/// Handles a connection-state notification for one channel.
///
/// When `disconnected` is zero it marks the channel disconnected and calls the
/// connect callback (`+0x8A4`). Otherwise, if the channel has a live Bluetooth
/// link (`+0x8BC != -1`), it fetches the six-byte link key through
/// `0x801F6160` and hands it to `0x80201CD8`.
///
/// # Original
/// - Ghidra: `FUN_801dfc40` at `0x801DFC40` (204 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801dfc40_FUN_801dfc40.c`
/// - Registered as a callback at `0x801DFE00` (`local_1d4`).
///
/// # Arguments
/// * `channel` - controller index.
/// * `connected` - zero means "link lost"; non-zero means "link up".
///
/// # Returns
/// `()`.
///
/// # Side effects
/// Writes `+0x8DC`, may invoke the connect callback with no arguments, and may
/// call `memset`/`memcpy` on a six-byte stack buffer plus `0x80201CD8`.
///
/// # Safety
/// The channel control block must be valid; callbacks and `0x801F6160` must be
/// callable.
///
/// # Confidence
/// low-medium - the branch logic is exact; the callback names are inferred from
/// where their pointers live (`+0x8A4` is the connect slot per `0x801E1060`).
pub unsafe fn fn_801dfc40(channel: u32, connected: u32) {
    let ctl = kpad_control(channel);
    if connected == 0 {
        platform::write_u32(ctl + 0x8DC, 1);
        let callback = platform::read_u32(ctl + 0x8A4);
        if callback != 0 {
            platform::call0(callback as usize);
        }
    } else {
        let token = disable_interrupts();
        let link = platform::read_i32(ctl + 0x8BC);
        restore_interrupts(token);

        if link != -1 {
            let ctl = kpad_control(channel);
            let token = disable_interrupts();
            let id = platform::read_u8(ctl + 0x8C3);
            restore_interrupts(token);

            let key_src = platform::call1(BT_GET_LINK_KEY, id as u32) as usize;
            let mut key = crate::platform::GuestLocal::new( [0u8; 6]);
            if key_src == 0 {
                platform::call3(MEMSET, key.as_mut_ptr() as u32, 0, 6);
            } else {
                platform::call3(MEMCPY, key.as_mut_ptr() as u32, key_src as u32, 6);
            }
            platform::call1(BT_STORE_LINK_KEY, key.as_ptr() as u32);
        }
    }
}

/// Clears a channel's queued reports and link key when `reset` is non-zero.
///
/// # Original
/// - Ghidra: `FUN_801dfd10` at `0x801DFD10` (232 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801dfd10_FUN_801dfd10.c`
/// - Passed to `0x801E4C50` as a completion callback at `0x801DFE00`.
///
/// # Arguments
/// * `channel` - controller index.
/// * `reset` - only non-zero runs the body.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// Under the lock: clears `+0x160`/`+0x161` and memsets the report ring at
/// `*(+0x164)` with `*(+0x168) * 0x30` bytes. Then repeats the link-key
/// fetch/`0x80201CD8` sequence from [`fn_801dfc40`].
///
/// # Safety
/// Same as [`fn_801dfc40`].
///
/// # Confidence
/// low-medium - exact stores; field semantics inferred from shared use with
/// [`wpad_control_init_801df570`].
pub unsafe fn fn_801dfd10(channel: u32, reset: u32) {
    let ctl = kpad_control(channel);
    if reset != 0 {
        let token = disable_interrupts();
        platform::write_u8(ctl + 0x160, 0);
        platform::write_u8(ctl + 0x161, 0);
        let base = platform::read_u32(ctl + 0x164);
        let count = platform::read_u32(ctl + 0x168);
        platform::call3(MEMSET, base, 0, count.wrapping_mul(0x30));
        restore_interrupts(token);

        let ctl = kpad_control(channel);
        let token = disable_interrupts();
        let link = platform::read_i32(ctl + 0x8BC);
        restore_interrupts(token);

        if link != -1 {
            let ctl = kpad_control(channel);
            let token = disable_interrupts();
            let id = platform::read_u8(ctl + 0x8C3);
            restore_interrupts(token);

            let key_src = platform::call1(BT_GET_LINK_KEY, id as u32) as usize;
            let mut key = crate::platform::GuestLocal::new( [0u8; 6]);
            if key_src == 0 {
                platform::call3(MEMSET, key.as_mut_ptr() as u32, 0, 6);
            } else {
                platform::call3(MEMCPY, key.as_mut_ptr() as u32, key_src as u32, 6);
            }
            platform::call1(BT_STORE_LINK_KEY, key.as_ptr() as u32);
        }
    }
}

/// Computes the movement delta of one accelerometer source for a channel.
///
/// `source == 0` subtracts the first triple (`+0x874`) from the current triple
/// (`+0x87A`); `source == 1` does the same for the second pair (`+0x88E` /
/// `+0x894`). The result is three signed 16-bit axis deltas.
///
/// # Original
/// - Ghidra: `FUN_801e0d30` at `0x801E0D30` (212 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801e0d30_FUN_801e0d30.c`
///
/// # Arguments
/// * `channel` - controller index.
/// * `source` - 0 or 1 selects the axis triple.
/// * `out` - writable pointer for three `i16` values; may be null.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// Writes six bytes to `out` (when non-null) under the interrupt lock.
///
/// # Safety
/// `out` must be writable for six bytes when non-null.
///
/// # Confidence
/// medium - the arithmetic is exact; the units/axes are inferred from the
/// accel-shaped six 16-bit fields it reads.
pub unsafe fn fn_801e0d30(channel: u32, source: u32, out: usize) {
    let ctl = kpad_control(channel);
    let token = disable_interrupts();
    if out != 0 {
        if source == 0 {
            let dx = (platform::read_u16(ctl + 0x87A) as i16)
                .wrapping_sub(platform::read_u16(ctl + 0x874) as i16);
            let dy = (platform::read_u16(ctl + 0x87C) as i16)
                .wrapping_sub(platform::read_u16(ctl + 0x876) as i16);
            let dz = (platform::read_u16(ctl + 0x87E) as i16)
                .wrapping_sub(platform::read_u16(ctl + 0x878) as i16);
            platform::write_u16(out, dx as u16);
            platform::write_u16(out + 2, dy as u16);
            platform::write_u16(out + 4, dz as u16);
        } else if source == 1 {
            let dx = (platform::read_u16(ctl + 0x894) as i16)
                .wrapping_sub(platform::read_u16(ctl + 0x88E) as i16);
            let dy = (platform::read_u16(ctl + 0x896) as i16)
                .wrapping_sub(platform::read_u16(ctl + 0x890) as i16);
            let dz = (platform::read_u16(ctl + 0x898) as i16)
                .wrapping_sub(platform::read_u16(ctl + 0x892) as i16);
            platform::write_u16(out, dx as u16);
            platform::write_u16(out + 2, dy as u16);
            platform::write_u16(out + 4, dz as u16);
        }
    }
    restore_interrupts(token);
}

