// ---------------------------------------------------------------------------
// Second pass: WPAD start/connection gate and KPAD extension accessors
// ---------------------------------------------------------------------------
//
// Appended from `0x801DFA50`-`0x801E1630`. Every function reads the channel
// control block through `kpad_control`; the new `r13` offsets are named below.

// --- r13-relative globals (second pass) -----------------------------------

/// `r13-0x4C00`: set to `1` once [`wpad_start_801dfa50`] has run.
const SDA_WPAD_4C00: usize = SDA_BASE - 0x4C00;
/// `r13-0x4C10`: one-shot latch for the idle-function registration.
const SDA_WPAD_4C10: usize = SDA_BASE - 0x4C10;
/// `r13-0x4BD4`: cleared when Bluetooth initialisation succeeds.
const SDA_WPAD_4BD4: usize = SDA_BASE - 0x4BD4;
/// `r13-0x5E8C`: set to `-1` when Bluetooth initialisation succeeds.
const SDA_WPAD_5E8C: usize = SDA_BASE - 0x5E8C;
/// `r13-0x4BFC`: set to `0x32` (50) when Bluetooth initialisation succeeds.
const SDA_WPAD_4BFC: usize = SDA_BASE - 0x4BFC;

// --- external call targets / tables (second pass) -------------------------

/// `0x801B32D0`: inserts one node into the sorted OS function list.
const OS_INSERT_FUNCTION: usize = 0x801B_32D0;
/// `0x80343B18`: node/function-pointer table entry registered by WPAD start.
const WPAD_IDLE_ENTRY: u32 = 0x8034_3B18;
/// `0x801F3190`: Bluetooth (`BTA`) initialisation; returns `1` on first call.
const BT_INIT: usize = 0x801F_3190;
/// `0x801F3530`: reads the Bluetooth connection state byte.
const BT_CONNECTION_STATE: usize = 0x801F_3530;
/// `0x801F51A0`: returns `0` when the Bluetooth host is ready.
const BT_LINK_READY: usize = 0x801F_51A0;
/// `0x801F3C50`: writes the two Bluetooth enable bytes and forwards them.
const BT_SET_ENABLE: usize = 0x801F_3C50;
/// `0x801F62D0`: clears (with `0`) or copies a six-byte link key.
const BT_CLEAR_LINK_KEY: usize = 0x801F_62D0;
/// `0x801E6BE0`: HID-report parser feed. Ghidra drops its register arguments.
const HID_PARSER_FEED: usize = 0x801E_6BE0;
/// `0x801E1630`: queues one KPAD event/report block for a channel.
const KPAD_QUEUE_EVENT: usize = 0x801E_1630;
/// `0x8039F340`: per-channel HID/init byte table (16 bytes used).
const WPAD_CHANNEL_FLAGS: usize = 0x8039_F340;
/// `0x801E0E10`: KPAD completion callback label passed to `0x801E1630`.
/// Ghidra did not export the fragment as a function.
const KPAD_EVENT_CALLBACK: u32 = 0x801E_0E10;
/// `"HID Parser reports %d"` diagnostic at `0x80343CC0`.
const MSG_HID_PARSER_REPORTS: u32 = 0x8034_3CC0;

/// Starts the WPAD layer: registers the idle hook, runs Bluetooth init once and
/// then brings up all four controller channels.
///
/// # Original
/// - Ghidra: `FUN_801dfa50` at `0x801DFA50` (112 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801dfa50_FUN_801dfa50.c`
/// - Calls [`wpad_init_801df7f0`] only after `0x801F3190` reports that
///   Bluetooth was initialised now.
///
/// # Arguments
/// None.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// Writes the `r13` start/ready fields, registers `0x80343B18` once, and seeds
/// the channel/retry fields before the driver bring-up.
///
/// # Safety
/// Must run after the OS, heap and Bluetooth stack are available.
///
/// # Confidence
/// medium - the call order and writes are exact; the public name is inferred
/// from the surrounding WPAD init.
pub unsafe fn wpad_start_801dfa50() {
    platform::write_u32(SDA_WPAD_4C00, 1);

    if platform::read_u8(SDA_WPAD_4C10) == 0 {
        platform::call1(OS_INSERT_FUNCTION, WPAD_IDLE_ENTRY);
        platform::write_u8(SDA_WPAD_4C10, 1);
    }

    if call0_ret(BT_INIT) != 0 {
        platform::write_u32(SDA_WPAD_4BD4, 0);
        platform::write_u32(SDA_WPAD_5E8C, 0xFFFF_FFFF);
        platform::write_u32(SDA_WPAD_4BFC, 0x32);
        wpad_init_801df7f0();
    }
}

/// Enables or disables the Bluetooth link when the host is connected and ready.
///
/// # Original
/// - Ghidra: `FUN_801dfbd0` at `0x801DFBD0` (104 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801dfbd0_FUN_801dfbd0.c`
///
/// # Arguments
/// * `enable` - zero disables, non-zero enables; normalised to `0`/`1`.
///
/// # Returns
/// `1` when the enable request was forwarded, `0` when the link was not in
/// state `3` or the host was not ready.
///
/// # Side effects
/// Calls `0x801F3C50(0, enable)` (two Bluetooth state bytes).
///
/// # Safety
/// The Bluetooth stack must be initialised.
///
/// # Confidence
/// low - body exact; the state value `3` and the public role are inferred.
pub unsafe fn fn_801dfbd0(enable: u32) -> u32 {
    if call0_ret(BT_CONNECTION_STATE) == 3
        && call0_ret(BT_LINK_READY) == 0
    {
        let normalized = enable.wrapping_neg() | enable;
        platform::call2(BT_SET_ENABLE, 0, normalized >> 31);
        1
    } else {
        0
    }
}

/// Reports a HID-parser failure for one channel.
///
/// # Original
/// - Ghidra: `FUN_801e0ce0` at `0x801E0CE0` (80 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801e0ce0_FUN_801e0ce0.c`
/// - String: `"HID Parser reports %d"` at `0x80343CC0`.
///
/// # Arguments
/// * `channel` - controller index used to read the per-channel byte table.
/// * `arg` - the callback's incoming `r4`, forwarded to the parser unchanged.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// Reads `0x8039F340[channel]`; when it is below `4`, feeds `0x801E6BE0` with
/// `(status, arg)` and reports its non-zero result through `0x801EA8F0`.
///
/// # Safety
/// `arg` must be the value the HID receive callback receives in `r4`; the parser
/// must accept `(status, arg)`.
///
/// # Confidence
/// high - both argument registers are literal in the instruction stream:
/// `lbzx r3,r5,r3` at `0x801E0CF4` overwrites `r3` with the table byte, and `r4`
/// is never written before `bl 0x801E6BE0` at `0x801E0D00`.
pub unsafe fn fn_801e0ce0(channel: u32, arg: u32) {
    let status = platform::read_u8(WPAD_CHANNEL_FLAGS + channel as usize) as u32;
    if status < 4 {
        // observed: `lbzx` result in `r3`; `r4` is the caller's, untouched.
        let result = platform::call2(HID_PARSER_FEED, status, arg);
        if result != 0 {
            platform::call2(OS_REPORT, MSG_HID_PARSER_REPORTS, result);
        }
    }
}

/// Drops a channel's Bluetooth link key and queues the next KPAD event.
///
/// # Original
/// - Ghidra: `FUN_801e0e40` at `0x801E0E40` (192 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801e0e40_FUN_801e0e40.c`
///
/// # Arguments
/// * `channel` - controller index.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// When `+0x8BC` is not `-1`, clears the key through `0x801F62D0(channel, 0)`,
/// rechecks the link, and under the lock sets `+0x986` before calling
/// `0x801E1630(channel, 0, 0x801E0E10)`.
///
/// # Safety
/// The channel control block and Bluetooth stack must be valid.
///
/// # Confidence
/// medium - branch logic and stores are exact; the event callback is a raw
/// label not exported by Ghidra.
pub unsafe fn fn_801e0e40(channel: u32) {
    let ctl = kpad_control(channel);

    let token = disable_interrupts();
    let link = platform::read_i32(ctl + 0x8BC);
    restore_interrupts(token);

    if link != -1 {
        platform::call2(BT_CLEAR_LINK_KEY, channel, 0);

        let ctl = kpad_control(channel);
        let token = disable_interrupts();
        let link = platform::read_i32(ctl + 0x8BC);
        restore_interrupts(token);

        if link != -1 {
            let token = disable_interrupts();
            if platform::read_u8(ctl + 0x986) == 0 {
                platform::write_u8(ctl + 0x986, 1);
                restore_interrupts(token);
                platform::call3(KPAD_QUEUE_EVENT, channel, 0, KPAD_EVENT_CALLBACK);
            } else {
                restore_interrupts(token);
            }
        }
    }
}

/// Reads one channel's link handle and connection byte.
///
/// # Original
/// - Ghidra: `FUN_801e0f40` at `0x801E0F40` (140 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801e0f40_FUN_801e0f40.c`
///
/// # Arguments
/// * `channel` - controller index.
/// * `out` - optional writable word receiving the byte at `+0x8C1`.
///
/// # Returns
/// The link word from `+0x8BC`, or `-1` when the byte at `+0x8C1` is `0xFD`,
/// or `-2` when `+0x8DC` is zero.
///
/// # Side effects
/// Writes `*out` under the interrupt lock when `out` is non-null.
///
/// # Safety
/// `out` must be writable for one word when non-null.
///
/// # Confidence
/// medium - arithmetic and return values are exact; the field meanings are
/// unknown.
pub unsafe fn fn_801e0f40(channel: u32, out: usize) -> i32 {
    let ctl = kpad_control(channel);
    let token = disable_interrupts();
    if out != 0 {
        platform::write_u32(out, platform::read_u8(ctl + 0x8C1) as u32);
    }
    let mut link = platform::read_i32(ctl + 0x8BC);
    if link != -1 {
        if platform::read_u8(ctl + 0x8C1) == 0xFD {
            link = -1;
        } else if platform::read_u32(ctl + 0x8DC) == 0 {
            link = -2;
        }
    }
    restore_interrupts(token);
    link
}

