///
/// # Side effects
/// Writes `control_block + 0x8A0` under the interrupt lock.
///
/// # Safety
/// WPAD/KPAD must be initialised and `channel` in range.
///
/// # Confidence
/// low - swap is exact; the callback's trigger is unknown.
pub unsafe fn fn_801e10f0(channel: u32, value: u32) -> u32 {
    let ctl = kpad_control(channel);
    let token = disable_interrupts();
    let previous = platform::read_u32(ctl + 0x8A0);
    platform::write_u32(ctl + 0x8A0, value);
    restore_interrupts(token);
    previous
}

/// Reads one channel's word at `+0x8B8` under the interrupt lock.
///
/// # Original
/// - Ghidra: `FUN_801e1150` at `0x801E1150` (68 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801e1150_FUN_801e1150.c`
///
/// # Arguments
/// * `channel` - controller index.
///
/// # Returns
/// The word at `control_block + 0x8B8`.
///
/// # Side effects
/// None beyond the lock/unlock pair.
///
/// # Safety
/// WPAD/KPAD must be initialised and `channel` in range.
///
/// # Confidence
/// low - read is exact; the field's meaning is unknown.
pub unsafe fn fn_801e1150(channel: u32) -> u32 {
    let ctl = kpad_control(channel);
    let token = disable_interrupts();
    let value = platform::read_u32(ctl + 0x8B8);
    restore_interrupts(token);
    value
}

/// Invokes and clears one channel's extension callback at `+0x988`.
///
/// # Original
/// - Ghidra: `FUN_801e1260` at `0x801E1260` (84 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801e1260_FUN_801e1260.c`
///
/// # Arguments
/// * `channel` - controller index.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// Calls the callback with no arguments (when non-null), then clears `+0x988`
/// and the byte at `+0x98C`.
///
/// # Safety
/// The callback must be callable; the control block must be valid.
///
/// # Confidence
/// medium - call and clears are exact; the callback's role is inferred.
pub unsafe fn fn_801e1260(channel: u32) {
    let ctl = kpad_control(channel);
    let callback = platform::read_u32(ctl + 0x988);
    if callback != 0 {
        platform::call0(callback as usize);
    }
    platform::write_u32(ctl + 0x988, 0);
    platform::write_u8(ctl + 0x98C, 0);
}

/// Updates a channel's `+0x8D4` mode when it differs from the requested value.
///
/// # Original
/// - Ghidra: `FUN_801e14e0` at `0x801E14E0` (204 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801e14e0_FUN_801e14e0.c`
///
/// # Arguments
/// * `channel` - controller index.
/// * `value` - requested mode (`0`/`1` are the observed values).
///
/// # Returns
/// `()`.
///
/// # Side effects
/// When the link is live, the global at [`SDA_WPAD_4BC8`] allows a change, and
/// the requested value differs from `+0x8D4`, writes the normalised boolean to
/// `+0x8D4` and sets `+0x8D0 = 1` under the interrupt lock.
///
/// # Safety
/// WPAD/KPAD must be initialised and `channel` in range.
///
/// # Confidence
/// medium - the gating conditions and boolean normalisation are exact.
pub unsafe fn fn_801e14e0(channel: u32, value: u32) {
    let ctl = kpad_control(channel);
    let token = disable_interrupts();

    if platform::read_i32(ctl + 0x8BC) == -1 {
        restore_interrupts(token);
        return;
    }
    if platform::read_u32(SDA_WPAD_4BC8) == 0
        && (value != 0 || platform::read_u32(ctl + 0x8D4) != 1)
    {
        restore_interrupts(token);
        return;
    }

    let current = platform::read_u32(ctl + 0x8D4);
    if (value == 0 && current == 0) || (value == 1 && current == 1) {
        restore_interrupts(token);
        return;
    }

    platform::write_u32(ctl + 0x8D4, (value.wrapping_neg() | value) >> 31);
    platform::write_u32(ctl + 0x8D0, 1);
    restore_interrupts(token);
}

/// Writes the global word at `r13-0x4BC8` under the interrupt lock.
///
/// # Original
/// - Ghidra: `FUN_801e15b0` at `0x801E15B0` (52 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801e15b0_FUN_801e15b0.c`
///
/// # Arguments
/// * `value` - new global value.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// Writes [`SDA_WPAD_4BC8`].
///
/// # Safety
/// None beyond a valid SDA.
///
/// # Confidence
/// medium - exact setter; the flag's meaning is inferred from its use in
/// [`fn_801e14e0`].
pub unsafe fn fn_801e15b0(value: u32) {
    let token = disable_interrupts();
    platform::write_u32(SDA_WPAD_4BC8, value);
    restore_interrupts(token);
}

/// Reads the global word at `r13-0x4BC8` under the interrupt lock.
///
/// # Original
/// - Ghidra: `FUN_801e15f0` at `0x801E15F0` (52 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801e15f0_FUN_801e15f0.c`
///
/// # Arguments
/// None.
///
/// # Returns
/// The word at [`SDA_WPAD_4BC8`].
///
/// # Side effects
/// None beyond the lock/unlock pair.
///
/// # Safety
/// None beyond a valid SDA.
///
/// # Confidence
/// medium - exact getter; the flag's meaning is inferred from its use in
/// [`fn_801e14e0`].
pub unsafe fn fn_801e15f0() -> u32 {
    let token = disable_interrupts();
    let value = platform::read_u32(SDA_WPAD_4BC8);
    restore_interrupts(token);
    value
}

// ---------------------------------------------------------------------------
// Third pass: device assignment, report-ring producers and report readers
// ---------------------------------------------------------------------------
//
// Appended from `0x801E0700`-`0x801E1DD0`. These functions sit between the
// Bluetooth transport and the public KPAD API: one assigns a connected device
// to a channel, two push command blocks into the per-channel ring, and the rest
// read or clear the double-buffered report state. The Ghidra bodies begin with
// `__savegprlr_*` artifacts (`0x802DCD6C`/`0x802DCD70`/`0x802DCD74`); the
// recovered register arguments are written as normal parameters below.

// --- external call targets (third pass) -----------------------------------

/// `0x801F6350`: non-zero when a Bluetooth link key is registered for a
/// channel.
const BT_HAS_LINK_KEY: usize = 0x801F_6350;
/// `0x802DF098`: compares `len` bytes of a Bluetooth device name.
const BT_NAME_MATCH: usize = 0x802D_F098;
/// `0x801DB8E0`: non-zero when the WPAD layer is not ready to sample.
const WPAD_NOT_READY: usize = 0x801D_B8E0;
/// `0x801DD6D0`: reads the extension type for the configured mode byte.
const WPAD_EXTENSION_TYPE: usize = 0x801D_D6D0;
/// `0x801DD600`: converts the sampling gate into a boolean.
const WPAD_SAMPLING_GATE: usize = 0x801D_D600;
/// `0x801DCC70`: starts sampling with a per-channel callback.
const WPAD_START_SAMPLING: usize = 0x801D_CC70;
/// `0x801E4C50`: appends one 0x30-byte block to the ring at `control+0x160`.
const KPAD_RING_PUSH: usize = 0x801E_4C50;
/// `0x801E1260`: extension callback installed in the `0x15` command block.
const KPAD_EXTENSION_CALLBACK: u32 = 0x801E_1260;

/// `"Nintendo RVL WBC"` at `0x80343C24`: the balance-board device name that
/// is pinned to channel 3.
const MSG_BT_NAME_WBC: u32 = 0x8034_3C24;

/// Returns the report length selected by the per-channel state word `+0x8B8`.
///
/// # Original
/// - Inlined in `0x801E18D0`, `0x801E19C0` and `0x801E1C90`.
/// - Evidence: `work/ghidra/main-gb/export/801e18d0_FUN_801e18d0.c` and the
///   sibling bodies.
///
/// # Arguments
/// * `state` - value read from `control_block + 0x8B8`.
///
/// # Returns
/// One of the observed lengths `0x2A`, `0x2E`, `0x32`, `0x34`, `0x36`, `0x4A`
/// or `0x5A`.
///
/// # Safety
/// None; pure lookup.
///
/// # Confidence
/// high - the switch table is identical in all three callers.
fn kpad_report_len(state: u32) -> u32 {
    match state {
        3 | 4 | 5 => 0x32,
        6 | 7 | 8 | 0x0B | 0x0F => 0x36,
        9 => 0x5A,
        10 => 0x2E,
        0x0C => 0x34,
        0x0D | 0x0E => 0x4A,
        _ => 0x2A,
    }
}

/// Returns the currently selected 0x60-byte report sub-block for a channel.
///
/// `control_block + 0x8C8` selects between the two sub-blocks at `+0xA0` and
/// `+0x100`; the Ghidra code computes this as `CLZ(byte) >> 5`, which is `1`
/// when the byte is zero and `0` otherwise.
///
/// # Original
/// - Inlined in `0x801E18D0`, `0x801E1B70` and `0x801E1C90`.
/// - Evidence: `work/ghidra/main-gb/export/801e18d0_FUN_801e18d0.c`.
///
/// # Arguments
/// * `control` - per-channel control block.
///
/// # Returns
/// `control + 0xA0` or `control + 0x100`.
///
/// # Safety
/// `control` must point at a 0x9C0-byte control block.
///
/// # Confidence
/// high - `CLZ`-based selector and stride are identical in all three bodies.
unsafe fn kpad_report_block(control: usize) -> usize {
    let selector = platform::read_u8(control + 0x8C8) as u32;
    let index = (selector.leading_zeros() >> 5) & 0xFF;
    control + index as usize * 0x60
}

/// Appends one 0x30-byte block to the per-channel report ring when it has
/// space.
///
/// The ring is described by `base = +0x164`, `capacity = +0x168`, a tail byte
/// at `+0x160` and a head byte at `+0x161`. The ring is full when the pending
/// count equals `capacity - 1`; otherwise the slot at `head` is cleared,
/// filled and `head` advances (wrapping to `0` at `capacity - 1`).
///
/// # Original
/// - Inlined in `0x801E12C0` and `0x801E1630`.
/// - Evidence: `work/ghidra/main-gb/export/801e12c0_FUN_801e12c0.c`,
///   `801e1630_FUN_801e1630.c`.
///
/// # Arguments
/// * `control` - per-channel control block.
/// * `block` - 0x30-byte block to copy.
///
/// # Returns
/// `true` when the block was appended, `false` when the ring was full.
///
/// # Safety
/// The ring base and capacity must be valid, and `block` readable for 0x30
/// bytes.
///
/// # Confidence
/// high - the count arithmetic, clear, copy and wrap are identical in both
/// callers.
unsafe fn kpad_ring_push(control: usize, block: &[u8; 0x30]) -> bool {
    // The game reads these through their addresses: guest copies.
    let block = crate::platform::GuestLocal::new(*block);
    let token = disable_interrupts();
    let base = platform::read_u32(control + 0x164) as usize;
    let capacity = platform::read_u32(control + 0x168);
    let head = platform::read_u8(control + 0x161);
    let tail = platform::read_u8(control + 0x160);

    let mut count = head.wrapping_sub(tail);
    if (count as i8) < 0 {
        // observed: negative byte difference wraps by the ring capacity.
        count = count.wrapping_add(capacity as u8);
    }
    let inserted = capacity.wrapping_sub(1) != count as u32;
    if inserted {
        let slot = base + head as usize * 0x30;
        platform::call3(MEMSET, slot as u32, 0, 0x30);
        platform::call3(MEMCPY, slot as u32, block.as_ptr() as u32, 0x30);
        let mut next = head.wrapping_add(1);
        if next as u32 == capacity.wrapping_sub(1) {
            next = 0;
        }
        platform::write_u8(control + 0x161, next);
    }
    restore_interrupts(token);
    inserted
}

/// Assigns a connected Bluetooth device to a KPAD channel.
///
/// The balance board (`"Nintendo RVL WBC"`) is always assigned to channel 3,
/// and the call fails with `-1` when that slot already has state at `+0x8D8`.
/// Other devices are matched against the registered link keys; the first free
/// channel with a matching key wins, otherwise channel 3 is used.
///
/// # Original
/// - Ghidra: `FUN_801e0700` at `0x801E0700` (288 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801e0700_FUN_801e0700.c`
/// - Strings: `"Nintendo RVL WBC"` at `0x80343C24`.
///
/// # Arguments
/// * `device` - Bluetooth device descriptor; its byte at `+0x56` identifies
///   the device to `0x801F6160`.
///
/// # Returns
/// The assigned channel (`0..=3`), or `-1` for a balance board whose slot is
/// already occupied.
///
/// # Side effects
/// May clear or forward a six-byte link key and sets the per-channel init byte
/// at `r13-0x4BD0`.
///
/// # Safety
/// `device` must be a readable descriptor; the Bluetooth link-key helpers and
/// the channel table must be initialised.
///
/// # Confidence
/// medium - body exact; the device-name comparison and channel-pinning role are
/// inferred from the string and the channel-3 slot check.
pub unsafe fn fn_801e0700(device: usize) -> i32 {
    let key = platform::call1(BT_GET_LINK_KEY, platform::read_u8(device + 0x56) as u32);
    let is_wbc = platform::call3(BT_NAME_MATCH, device as u32, MSG_BT_NAME_WBC, 0x10);

    let mut channel: i32;
    if is_wbc == 0 {
        channel = 3;
        let control = platform::read_u32(KPAD_CONTROL_TABLE + 12) as usize;
        if platform::read_u32(control + 0x8D8) != 0 {
            platform::call1(BT_STORE_LINK_KEY, key);
            return -1;
        }
    } else {
        channel = 0;
        loop {
            let has_key = platform::call2(BT_HAS_LINK_KEY, channel as u32, key);
            let free = platform::read_u8(SDA_WPAD_4BD0 + channel as usize) == 0;
            if has_key != 0 && free {
                break;
            }
            // observed: the original also tracks the first free channel in a
            // local that is overwritten before use (no observable effect).
            let next = channel + 1;
            if next >= 4 {
                break;
            }
            channel = next;
        }
    }

    if platform::call2(BT_HAS_LINK_KEY, channel as u32, key) == 0 {
        platform::call2(BT_CLEAR_LINK_KEY, channel as u32, key);
    }
    platform::write_u8(SDA_WPAD_4BD0 + channel as usize, 1);
    channel
}

/// Offers a report id to a channel and records it when it changed.
///
/// # Original
/// - Ghidra: `FUN_801e11a0` at `0x801E11A0` (184 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801e11a0_FUN_801e11a0.c`
/// - Caller: `0x801EE230` passes one register; the body reads the channel from
///   `r3` and the report id from `r4`.
///
/// # Arguments
/// * `channel` - controller index (`r3`).
/// * `value` - report id to store (`r4`).
///
/// # Returns
/// `0` on success or when the id is unchanged, `-1` when the link is gone,
/// `-2` when the channel is not connected or the ring is full.
///
/// # Side effects
/// Appends a 0x30-byte block through `0x801E4C50` and writes `+0x8B8` under the
/// interrupt lock.
///
/// # Safety
/// The channel control block and its ring must be initialised.
///
/// # Confidence
/// low - the body is exact, but `r4` is not visible at the only recovered
/// caller, so the second argument is inferred from the artifact return pair.
///
/// # Partial
/// `// partial:` the caller's `r4` value is unresolved; the signature exposes it
/// explicitly so a later pass can correct the call site without rewriting the
/// body.
pub unsafe fn fn_801e11a0(channel: u32, value: u32) -> i32 {
    let control = kpad_control(channel);

    let token = disable_interrupts();
    let connected = platform::read_u32(control + 0x8DC);
    let link = platform::read_i32(control + 0x8BC);
    let last = platform::read_u32(control + 0x8B8);
    restore_interrupts(token);

    if link == -1 {
        return -1;
    }
    if connected == 0 {
        return -2;
    }
    if last == value {
        return 0;
    }

    let queued = platform::call4(
        KPAD_RING_PUSH,
        (control + 0x160) as u32,
        value,
        platform::read_u8(control + 0x98E) as u32,
        0,
    );
    if queued == 0 {
        return -2;
    }

    let token = disable_interrupts();
    platform::write_u32(control + 0x8B8, value);
    restore_interrupts(token);
    0
}

/// Requests an extension report and queues the `0x15` command block.
///
/// # Original
/// - Ghidra: `FUN_801e12c0` at `0x801E12C0` (544 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801e12c0_FUN_801e12c0.c`
/// - Callers: `0x8016F5D0` and `0x80173920` pass `(channel, buffer, callback)`.
///
/// # Arguments
/// * `channel` - controller index.
/// * `buffer` - caller buffer recorded in the command block at `+0x28`.
/// * `callback` - function invoked with `(channel, result)` when the request
///   fails.
///
/// # Returns
/// `0` when the block was queued, `-1` when the link is gone, `-2` when the
/// channel is disconnected, busy or the ring is full.
///
/// # Side effects
/// Sets `+0x98C` and `+0x988` under the lock before queuing; on a full ring both
/// are cleared again. The queued block has kind `0x15`, `+0x1A` = 1,
/// `+0x28` = `buffer` and `+0x2C` = [`KPAD_EXTENSION_CALLBACK`].
///
/// # Safety
/// The control block, ring and callbacks must be valid.
///
/// # Confidence
/// medium - the ring/branch logic is exact; the command block's unassigned
/// stack bytes are zeroed (see the note in the body).
pub unsafe fn fn_801e12c0(channel: u32, buffer: u32, callback: u32) -> i32 {
    let control = kpad_control(channel);

    let token = disable_interrupts();
    let connected = platform::read_u32(control + 0x8DC);
    let link = platform::read_i32(control + 0x8BC);
    let active = platform::read_u8(control + 0x98C);
    restore_interrupts(token);

    let mut result: i32 = link;
    if link != -1 {
        if connected == 0 || active != 0 {
            result = -2;
        } else {
            let token = disable_interrupts();
            platform::write_u8(control + 0x98C, 1);
            platform::write_u32(control + 0x988, callback);
            restore_interrupts(token);

            let mut block = [0u8; 0x30];
            block[3] = 0x15;
            // unknown: `+4` is masked stack data in the Ghidra body; zeroed.
            block[0x1A] = 0;
            block[0x1B] = 1;
            block[0x28..0x2C].copy_from_slice(&buffer.to_be_bytes());
            block[0x2C..0x30]
                .copy_from_slice(&KPAD_EXTENSION_CALLBACK.to_be_bytes());

            if kpad_ring_push(control, &block) {
                result = 0;
            } else {
                // observed: a full ring clears the pending request.
                let token = disable_interrupts();
                platform::write_u8(control + 0x98C, 0);
                platform::write_u32(control + 0x988, 0);
                restore_interrupts(token);
                result = -2;
            }
        }
    }

    if result != 0 && callback != 0 {
        platform::call2(callback as usize, channel, result as u32);
    }
    result
}

/// Queues a `0x11` KPAD event block for a channel.
///
/// # Original
/// - Ghidra: `FUN_801e1630` at `0x801E1630` (488 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801e1630_FUN_801e1630.c`
/// - Caller: [`fn_801e0e40`] passes `(channel, 0, 0x801E0E10)`.
///
/// # Arguments
/// * `channel` - controller index.
/// * `value` - event value; its low byte is shifted into block byte `+4`.
/// * `callback` - function invoked with `(channel, result)` when the queue is
///   full or the channel is down.
///
/// # Returns
/// `0` when queued, `-1` when the link is gone, `-2` when the channel is
/// disconnected or the ring is full.
///
/// # Side effects
/// Copies a 0x30-byte block with kind `0x11`, `+0x1A` low half `1` and
/// `+0x2C` = `callback` into the ring at `+0x160`.
///
/// # Safety
/// The control block and ring must be valid.
///
/// # Confidence
/// medium - the ring logic is exact; the block's unassigned stack bytes are
/// zeroed (see the note in the body).
pub unsafe fn fn_801e1630(channel: u32, value: u32, callback: u32) -> i32 {
    let control = kpad_control(channel);

    let token = disable_interrupts();
    let link = platform::read_i32(control + 0x8BC);
    let connected = platform::read_u32(control + 0x8DC);
    restore_interrupts(token);

    let mut result: i32 = link;
    if link != -1 {
        if connected == 0 {
            result = -2;
        } else {
            let mut block = [0u8; 0x30];
            block[3] = 0x11;
            // observed: the low byte of `value << 4` is the only initialised
            // part of the `+4` word; the rest is stack data and is zeroed.
            block[4] = (value.wrapping_shl(4) & 0xFF) as u8;
            block[0x1A] = 0;
            block[0x1B] = 1;
            block[0x2C..0x30].copy_from_slice(&callback.to_be_bytes());

            result = if kpad_ring_push(control, &block) { 0 } else { -2 };
        }
    }

    if result != 0 && callback != 0 {
        platform::call2(callback as usize, channel, result as u32);
    }
    result
}

/// Starts sampling when the extension type and the global gate both allow it.
///
/// # Original
/// - Ghidra: `FUN_801e1820` at `0x801E1820` (172 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801e1820_FUN_801e1820.c`
///
/// # Arguments
/// * `callback` - optional completion callback. It receives `2` when sampling
///   is refused, otherwise it is forwarded to `0x801DCC70`.
///
/// # Returns
/// The observed boolean `(extension & 1) & gate` (`0` when refused).
///
/// # Side effects
/// Reads [`SDA_WPAD_4BC8`] and [`SDA_WPAD_4BC9`] under the interrupt lock and
/// may call `0x801DCC70`.
///
/// # Safety
/// The WPAD layer must be initialised and the callback callable.
///
/// # Confidence
/// medium - body exact; the extension/gate roles are inferred from the values
/// read by WPAD init.
pub unsafe fn fn_801e1820(callback: u32) -> u32 {
    let ready = call0_ret(WPAD_NOT_READY);
    if ready != 0 {
        return 0;
    }

    let token = disable_interrupts();
    let gate = platform::read_u32(SDA_WPAD_4BC8);
    let mode = platform::read_u8(SDA_WPAD_4BC9);
    restore_interrupts(token);

    let extension = platform::call1(WPAD_EXTENSION_TYPE, mode as u32);
    // observed: `(-gate | gate) >> 31` is the compact `gate != 0` test.
    let gate_bool = platform::call1(
        WPAD_SAMPLING_GATE,
        (gate.wrapping_neg() | gate) >> 31,
    );
    let allowed = (extension & 1) & gate_bool;

    if allowed == 0 {
        if callback != 0 {
            platform::call1(callback as usize, 2);
        }
    } else {
        platform::call1(WPAD_START_SAMPLING, callback);
    }
    allowed
}

/// Copies the currently selected report sub-block into a caller buffer.
///
/// # Original
/// - Ghidra: `FUN_801e18d0` at `0x801E18D0` (228 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801e18d0_FUN_801e18d0.c`
/// - Caller: `0x801EE230` passes `(channel, destination)`.
///
/// # Arguments
/// * `channel` - controller index.
/// * `out` - destination buffer.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// Copies [`kpad_report_len`] bytes from `control + 0xA0`/`+0x100` into `out`
/// under the interrupt lock; an overlong extension report is truncated to
/// `0x2A` bytes when byte `+0xC9` is non-zero.
///
/// # Safety
/// `out` must be writable for the selected report length (at most `0x5A`).
///
/// # Confidence
/// high - selector, table and copy are exact.
pub unsafe fn fn_801e18d0(channel: u32, out: usize) {
    let control = kpad_control(channel);
    let token = disable_interrupts();
    let report = kpad_report_block(control);
    let mut length = kpad_report_len(platform::read_u32(control + 0x8B8));
    if platform::read_u8(report + 0xC9) != 0 {
        length = 0x2A;
    }
    platform::call3(MEMCPY, out as u32, (report + 0xA0) as u32, length);
    restore_interrupts(token);
}

/// Fills a report ring with `count` slots of zeroed report data.
///
/// # Original
/// - Ghidra: `FUN_801e19c0` at `0x801E19C0` (428 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801e19c0_FUN_801e19c0.c`
/// - Caller: `0x801E0820` passes `(channel, buffer, count)`.
///
/// # Arguments
/// * `channel` - controller index.
/// * `buffer` - report ring base (may be null).
/// * `count` - number of slots.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// * `memset(buffer, 0, length * count)`.
/// * Writes the marker byte `0xFC` (or `0xFF` when the link is gone) at
///   `buffer + i * length + 0x29` for every slot.
/// * Stores `-1` in `+0x8B0`, `count` in `+0x8B4` and `buffer` in `+0x8AC`.
///
/// # Safety
/// `buffer` must be writable for `length * count` bytes when non-null.
///
/// # Confidence
/// high - every store and the unrolled fill reduce to the same loop.
pub unsafe fn fn_801e19c0(channel: u32, buffer: u32, count: u32) {
    let control = kpad_control(channel);
    let token = disable_interrupts();

    let mut marker = 0xFCu8;
    if platform::read_i32(control + 0x8BC) == -1 {
        marker = 0xFF;
    }
    let length = kpad_report_len(platform::read_u32(control + 0x8B8));

    if buffer != 0 {
        platform::call3(MEMSET, buffer, 0, length.wrapping_mul(count));
        for i in 0..count {
            platform::write_u8(
                buffer as usize + i as usize * length as usize + 0x29,
                marker,
            );
        }
        platform::write_u32(control + 0x8B0, 0xFFFF_FFFF);
        platform::write_u32(control + 0x8B4, count);
    }
    platform::write_u32(control + 0x8AC, buffer);

    restore_interrupts(token);
}

/// Clears the status bits of the selected report sub-block.
///
/// # Original
/// - Ghidra: `FUN_801e1b70` at `0x801E1B70` (276 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801e1b70_FUN_801e1b70.c`
/// - Caller: `0x801E6BE0` (HID parser) calls it after parsing.
///
/// # Arguments
/// * `channel` - controller index.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// Under the lock: clears bit 1 of `+0xA0` when both low bits are set, clears
/// bit 2 when bits 2-3 are both set, and for states `6,7,8,0xB,0xF,10` clears
/// bits 15/14 of `+0xCA` when the paired low bit is also set.
///
/// # Safety
/// The control block must be valid.
///
/// # Confidence
/// medium - the bit tests are exact; the field meanings are unknown.
pub unsafe fn fn_801e1b70(channel: u32) {
    let control = kpad_control(channel);
    let token = disable_interrupts();
    let report = kpad_report_block(control);

    let mut status = platform::read_u16(report + 0xA0);
    if status & 3 == 3 {
        status &= !2;
    }
    if status & 0x0C == 0x0C {
        status &= !4;
    }
    platform::write_u16(report + 0xA0, status);

    let state = platform::read_u32(control + 0x8B8);
    if matches!(state, 6 | 7 | 8 | 0x0B | 0x0F | 10) {
        let mut bits = platform::read_u16(report + 0xCA);
        if bits & 0x8002 == 0x8002 {
            bits &= !0x8000;
        }
        if bits & 0x4001 == 0x4001 {
            bits &= !0x4000;
        }
        platform::write_u16(report + 0xCA, bits);
    }

    restore_interrupts(token);
}

/// Copies the selected report into the next ring slot and dispatches the
/// sampling callback.
///
/// # Original
/// - Ghidra: `FUN_801e1c90` at `0x801E1C90` (320 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801e1c90_FUN_801e1c90.c`
/// - Caller: `0x801E6BE0` (HID parser) calls it after decoding a report.
///
/// # Arguments
/// * `channel` - controller index.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// Under the lock: advances the ring cursor `+0x8B0`, copies the report into
/// `buffer + cursor * length`, invokes the sampling callback at `+0x8A8` with
/// the channel, and increments the 16-bit counter at `+0x984`.
///
/// # Safety
/// The control block, report buffer and callback must be valid.
///
/// # Confidence
/// high - every store and both calls are transcribed; the callback slot is the
/// one installed by [`kpad_set_sampling_callback_801e0fd0`].
pub unsafe fn fn_801e1c90(channel: u32) {
    let control = kpad_control(channel);
    let token = disable_interrupts();
    let report = kpad_report_block(control);
    let mut length = kpad_report_len(platform::read_u32(control + 0x8B8));

    let buffer = platform::read_u32(control + 0x8AC);
    if buffer != 0 {
        let mut cursor = platform::read_u32(control + 0x8B0).wrapping_add(1);
        platform::write_u32(control + 0x8B0, cursor);
        if platform::read_u32(control + 0x8B4) <= cursor {
            cursor = 0;
            platform::write_u32(control + 0x8B0, 0);
        }
        if platform::read_u8(report + 0xC9) != 0 {
            length = 0x2A;
        }
        platform::call3(
            MEMCPY,
            buffer.wrapping_add(cursor.wrapping_mul(length)),
            (report + 0xA0) as u32,
            length,
        );
    }

    let callback = platform::read_u32(control + 0x8A8);
    if callback != 0 {
        platform::call1(callback as usize, channel);
    }
    let counter = platform::read_u16(control + 0x984).wrapping_add(1);
    platform::write_u16(control + 0x984, counter);

    restore_interrupts(token);
}

/// Reads the per-channel word at `control_block + 0x83C`.
///
/// # Original
/// - Ghidra: `FUN_801e1dd0` at `0x801E1DD0` (68 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801e1dd0_FUN_801e1dd0.c`
///
/// # Arguments
/// * `channel` - controller index.
///
/// # Returns
/// The word at `+0x83C`.
///
/// # Side effects
/// None beyond the interrupt lock pair.
///
/// # Safety
/// WPAD/KPAD must be initialised and `channel` in range.
///
/// # Confidence
/// low - read is exact; the field's meaning is unknown.
pub unsafe fn fn_801e1dd0(channel: u32) -> u32 {
    let control = kpad_control(channel);
    let token = disable_interrupts();
    let value = platform::read_u32(control + 0x83C);
    restore_interrupts(token);
    value
}

// ---------------------------------------------------------------------------
// Fourth pass: WPAD/KPAD report pipeline and extension decoders
// ---------------------------------------------------------------------------
//
// Appended from `0x801DE9D0`-`0x801E8DD0`. This is the path a Bluetooth report
// takes after the transport hands it to KPAD: `0x801E0820` assigns a device to
// a channel and queues the attach sequence, `0x801E6BE0` dispatches report ids
// `0x20`-`0x3F` through the table at `0x80343E90`, and the decoders below fill
// the 0x60-byte report block at `control + 0xA0` / `+0x100`.
//
// The extension calibration records live at `control + 0x974`. Their first
// seven bytes describe the extension and the remaining bytes are checked
// against a two-byte sum in `0x801E6A30`.

// --- r13-relative globals (fourth pass) -----------------------------------

/// `r13-0x4BA4`: one byte per channel holding the decoded extension kind
/// (`0` core remote, `1` nunchuk, `2` classic, `3` balance board, `0xFB`/`0xFC`
/// unavailable).
const SDA_WPAD_4BA4: usize = SDA_BASE - 0x4BA4;
/// `r13-0x4BA8`: one byte per channel holding the extension sub-mode.
const SDA_WPAD_4BA8: usize = SDA_BASE - 0x4BA8;
/// `r13-0x4BAC`: one byte per channel that makes `0x801E7BE0` clear the
/// extension axes after decoding (`0` keeps them).
const SDA_WPAD_4BAC: usize = SDA_BASE - 0x4BAC;
/// `r13-0x4BB0`: per-channel retry counter used by `0x801E5460`; the attach
/// sequence is retried while the old value is below `0x20`.
const SDA_WPAD_4BB0: usize = SDA_BASE - 0x4BB0;
/// `r13-0x5048`: global tested while decoding the balance-board sub-id.
const SDA_WPAD_5048: usize = SDA_BASE - 0x5048;
/// `r13-0x5E6C`: inline "connected" label passed to the report printer.
const SDA_WPAD_5E6C: usize = SDA_BASE - 0x5E6C;
/// `r13-0x5E74`: inline "disconnected" label passed to the report printer.
const SDA_WPAD_5E74: usize = SDA_BASE - 0x5E74;
/// `r13-0x5E78`: inline version label used by the attach error report.
const SDA_WPAD_5E78: usize = SDA_BASE - 0x5E78;

// --- external call targets / tables (fourth pass) -------------------------

/// `0x801F3570`: Bluetooth connection/queue state byte.
const BT_STATE_801F3570: usize = 0x801F_3570;
/// `0x801F61C0`: Bluetooth link-key bookkeeping for a device id.
const BT_KEY_HOOK_801F61C0: usize = 0x801F_61C0;
/// `0x801F6220`: returns a small link-quality/counter value for a device id.
const BT_KEY_VALUE_801F6220: usize = 0x801F_6220;
/// `0x801F6280`: returns the current Bluetooth retry/quality limit byte.
const BT_KEY_LIMIT_801F6280: usize = 0x801F_6280;
/// `0x801BE470`: flushes the WPAD/Bluetooth report path after a state change.
const BT_FLUSH_801BE470: usize = 0x801B_E470;
/// `0x801DE010`: compares a freshly decoded report with the previous one.
const WPAD_REPORT_CHANGED: usize = 0x801D_E010;
/// `0x801DE910`: per-extension sample counter used by the accept path.
const WPAD_SAMPLE_COUNTER: usize = 0x801D_E910;
/// `0x801E55C0`: balance-board calibration/weight filter (not translated).
const KPAD_CALIBRATION_FINALIZE: usize = 0x801E_55C0;
/// `0x801E53F0`: clears one 0x30-byte-slot command ring.
const KPAD_RING_CLEAR: usize = 0x801E_53F0;
/// `0x801E4EC0`: writes one short command into the extension ring.
