const KPAD_XOR_DECODE: usize = 0x801E_A520;
/// `0x801EFEF0`: non-zero when the balance board is allowed on this console.
const KPAD_BALANCE_BOARD_ALLOWED: usize = 0x801E_FEF0;
/// `0x801DDA50`: probe for the classic-controller sub-id `4`.
const KPAD_PROBE_CLASSIC_4: usize = 0x801D_DA50;
