/// Address of `fn_801dfc40`, used as a callback word in queued commands.
const FN_801DFC40: u32 = 0x801D_FC40;
/// Address of `fn_801dfd10`, used as a callback word in queued commands.
const FN_801DFD10: u32 = 0x801D_FD10;
/// Address of `fn_801dfe00`, queued as the attach-sequence completion.
const FN_801DFE00: u32 = 0x801D_FE00;
/// Address of `fn_801e5460`, queued as the extension-detach completion.
const FN_801E5460: u32 = 0x801E_5460;

/// Builds a zeroed 0x30-byte command block with its kind at byte `+3`.
///
/// The queue consumer `0x801DDD20` loads the first 32-bit word and tests
/// `word & 0xFF`. On the big-endian target that low byte is block byte `+3`,
/// which is where the original producers store the kind word (`0x12`, `0x15`,
/// `0x16`, `0x17`, `0x18`, `0x1A`).
///
/// # Original
/// - Inlined word stores in `FUN_801e4c50`, `FUN_801e4ec0`, `FUN_801e5240`
///   and the `0x801E1E20`/`0x801E39C0` producers.
/// - Evidence: `work/ghidra/main-gb/export/801ddd20_FUN_801ddd20.c` (consumer
///   mask) and `work/ghidra/main-gb/export/801e4ec0_FUN_801e4ec0.c` (word
///   store of `0x16` at block `+0`).
///
/// # Confidence
/// high - producer word stores and consumer mask agree.
fn kpad_cmd_block(kind: u8) -> [u8; 0x30] {
    let mut block = [0u8; 0x30];
    block[3] = kind;
    block
}

/// Reads a big-endian word from a 0x30-byte command block.
fn kpad_block_u32(block: &[u8; 0x30], offset: usize) -> u32 {
    u32::from_be_bytes([
        block[offset],
        block[offset + 1],
        block[offset + 2],
        block[offset + 3],
    ])
}

/// Writes a big-endian word into a 0x30-byte command block.
fn kpad_block_set_u32(block: &mut [u8; 0x30], offset: usize, value: u32) {
    block[offset..offset + 4].copy_from_slice(&value.to_be_bytes());
}

/// Writes a big-endian halfword into a 0x30-byte command block.
fn kpad_block_set_u16(block: &mut [u8; 0x30], offset: usize, value: u16) {
    block[offset..offset + 2].copy_from_slice(&value.to_be_bytes());
}

/// Counts the pending slots in a ring whose first four fields are
/// `tail u8`, `head u8`, `base u32`, `capacity u32`.
///
/// # Safety
/// `ring` must point at a live 0x0C-byte ring header.
unsafe fn kpad_ring_count(ring: usize) -> u32 {
    let head = platform::read_u8(ring + 1);
    let tail = platform::read_u8(ring);
    let capacity = platform::read_u32(ring + 8);
    let mut count = head.wrapping_sub(tail);
    if (count as i8) < 0 {
        count = count.wrapping_add(capacity as u8);
    }
    count as u32
}

/// Calls a PowerPC routine that takes and returns one double.
///
/// Used for the SDK sin/cos helpers `0x802E84C4` / `0x802E7FBC`, which have no
/// integer-only wrapper in [`crate::platform`].
///
/// # Safety
/// `addr` must be a function with the `f64`-in/`f64`-out ABI, and the caller
/// must run on the target (or an ABI-compatible host).
unsafe fn call_f64_1(addr: usize, value: f64) -> f64 {
    let f = crate::platform::guest_fn!(addr, fn(f64) -> f64);
    f(value)
}

/// Accepts a decoded sampling report, refreshes the previous-report snapshot,
/// and retries a stale Bluetooth link.
///
/// # Original
/// - Ghidra: `FUN_801de9d0` at `0x801DE9D0` (404 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801de9d0_FUN_801de9d0.c`
/// - Caller: the sampling alarm path reached from `0x801DF550`.
///
/// # Arguments
/// * `channel` - controller index.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// Calls the report comparator `0x801DE010`, the sample counter `0x801DE910`,
/// updates `+0x8F0` (64-bit time) and the previous-report copy at `+0x40`, and
/// may forward a fresh six-byte link key to `0x80201CD8`. Calls `0x801BE470`
/// when a report was accepted.
///
/// # Safety
/// The channel control block and the link-key helpers must be valid.
///
/// # Confidence
/// medium - the report accept/branch logic is exact; the time-based retry is
/// reconstructed from the 64-bit subtraction and the `bus_clock >> 2` divisor.
pub unsafe fn fn_801de9d0(channel: u32) {
    let control = kpad_control(channel);

    if platform::read_u8(SDA_WPAD_4C0C) != 5 {
        return;
    }

    let token = disable_interrupts();
    let selector = platform::read_u8(control + 0x8C8) as u32;
    let report = control + ((selector.leading_zeros() >> 5) & 0xFF) as usize * 0x60 + 0xA0;
    restore_interrupts(token);

    let changed = platform::call3(
        WPAD_REPORT_CHANGED,
        control as u32,
        report as u32,
        (control + 0x40) as u32,
    );
    platform::call2(WPAD_SAMPLE_COUNTER, channel, report as u32);

    let mut accepted = false;
    if changed == 0 {
        let mode = platform::read_u8(SDA_WPAD_4BC2);
        if mode != 0 {
            let now = get_time();
            let last = ((platform::read_u32(control + 0x8F0) as u64) << 32)
                | platform::read_u32(control + 0x8F4) as u64;
            let period = (platform::read_u32(LOW_MEM_BUS_CLOCK) >> 2) as u64;
            // inferred: the original 64-bit divide helper returns the elapsed
            // seconds; the decompiler only exposes the remainder register.
            let elapsed = if period == 0 {
                0
            } else {
                now.wrapping_sub(last) / period
            };
            if (mode as u32).wrapping_mul(0x3C) < elapsed as u32 {
                let token = disable_interrupts();
                let link = platform::read_i32(control + 0x8BC);
                restore_interrupts(token);
                if link != -1 {
                    let token = disable_interrupts();
                    let device = platform::read_u8(control + 0x8C3);
                    restore_interrupts(token);
                    let key_src = platform::call1(BT_GET_LINK_KEY, device as u32) as usize;
                    let mut key = crate::platform::GuestLocal::new( [0u8; 6]);
                    if key_src == 0 {
                        platform::call3(MEMSET, key.as_mut_ptr() as u32, 0, 6);
                    } else {
                        platform::call3(MEMCPY, key.as_mut_ptr() as u32, key_src as u32, 6);
                    }
                    platform::call1(BT_STORE_LINK_KEY, key.as_ptr() as u32);
                }
            }
        }
    } else {
        accepted = true;
        let now = get_time();
        platform::write_u32(control + 0x8F0, (now >> 32) as u32);
        platform::write_u32(control + 0x8F4, now as u32);
        platform::call3(MEMCPY, (control + 0x40) as u32, report as u32, 0x60);
    }

    let marker = platform::read_u8(control + 0x69);
    if marker != 0 && marker != 0xF9 {
        platform::call3(MEMCPY, (control + 0x40) as u32, report as u32, 0x60);
    }
    if accepted {
        platform::call0(BT_FLUSH_801BE470);
    }
}

/// Queues the command sequence that initialises a newly attached controller.
///
/// # Original
/// - Ghidra: `FUN_801dfe00` at `0x801DFE00` (2292 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801dfe00_FUN_801dfe00.c`
/// - Registered as the completion callback of the attach block in
///   [`fn_801e0820`]. It is the `local_1d4` callback noted by wave 4.
///
/// # Arguments
/// * `channel` - controller index.
/// * `result` - attach status; `-1` means the link failed and no command is
///   queued.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// Publishes `+0x8BC = 0`, records whether the link was already up in `+0x8E0`,
/// then appends seven 0x30-byte blocks to the `+0x160` ring: a `0x12` reset,
/// a `0x1A` LED/state block, a `0x11` sampling block, three `0x17` reads from
/// the extension registers `0x2A` / `0x62` / `0x176C`, and a `0x15` extension
/// report request.
///
/// # Safety
/// The channel control block and the ring must be initialised.
///
/// # Confidence
/// medium - the queue writes are exact; the meaning of each command kind is
/// not proven and is documented only by its observed byte values.
pub unsafe fn fn_801dfe00(channel: u32, result: i32) {
    let control = kpad_control(channel);
    if result == -1 {
        return;
    }

    let token = disable_interrupts();
    platform::write_u32(control + 0x8E0, (result == 0) as u32);
    platform::write_u32(control + 0x8BC, 0);
    restore_interrupts(token);

    let version = if platform::read_u32(control + 0x8E0) != 0 {
        SDA_WPAD_5E78 as u32
    } else {
        MSG_VERSION_21
    };
    platform::call2(OS_REPORT, MSG_INIT_ERROR, version);

    let mut mask = 1u32;
    if platform::read_u8(control + 0x8C1) != 3 {
        mask = 1u32 << channel;
    }

    let _ = fn_801e4c50(
        (control + 0x160) as usize,
        0,
        platform::read_u8(control + 0x98E) as u32,
        FN_801DFD10,
    );

    // observed: kind 0x1A, u16 +0x1A = 1, completion callback at +0x2C.
    let mut block = kpad_cmd_block(0x1A);
    block[0x1A] = 0;
    block[0x1B] = 1;
    kpad_block_set_u32(&mut block, 0x2C, FN_801DFD10);
    let _ = kpad_ring_push(control, &block);

    // observed: kind 0x11 with the channel mask shifted into byte +4.
    let mut block = kpad_cmd_block(0x11);
    block[4] = (mask.wrapping_shl(4) & 0xFF) as u8;
    block[0x1A] = 0;
    block[0x1B] = 1;
    kpad_block_set_u32(&mut block, 0x2C, FN_801DFD10);
    let _ = kpad_ring_push(control, &block);

    // observed: kind 0x17 read of register 0x2A into control+0x934.
    let mut block = kpad_cmd_block(0x17);
    kpad_block_set_u32(&mut block, 4, 0x2A);
    kpad_block_set_u16(&mut block, 8, 0x38);
    block[0x1A] = 0;
    block[0x1B] = 6;
    kpad_block_set_u32(&mut block, 0x1C, (control + 0x934) as u32);
    kpad_block_set_u16(&mut block, 0x20, 0x38);
    kpad_block_set_u32(&mut block, 0x24, 0x2A);
    kpad_block_set_u32(&mut block, 0x2C, FN_801DFD10);
    let _ = kpad_ring_push(control, &block);

    // observed: the same read for register 0x62.
    let mut block = kpad_cmd_block(0x17);
    kpad_block_set_u32(&mut block, 4, 0x62);
    kpad_block_set_u16(&mut block, 8, 0x38);
    block[0x1A] = 0;
    block[0x1B] = 6;
    kpad_block_set_u32(&mut block, 0x1C, (control + 0x934) as u32);
    kpad_block_set_u16(&mut block, 0x20, 0x38);
    kpad_block_set_u32(&mut block, 0x24, 0x62);
    kpad_block_set_u32(&mut block, 0x2C, FN_801DFD10);
    let _ = kpad_ring_push(control, &block);

    // observed: link/version handshake. `result == 0` selects register 0
    // with a 0x14-byte read, otherwise register 0x176C with 0x2A bytes.
    let register = if result == 0 { 0x176Cu32 } else { 0 };
    let length = if result == 0 { 0x14u32 } else { 0x2A };
    let mut block = kpad_cmd_block(0x17);
    kpad_block_set_u32(&mut block, 4, register);
    kpad_block_set_u16(&mut block, 8, length as u16);
    block[0x1A] = 0;
    block[0x1B] = 6;
    kpad_block_set_u32(&mut block, 0x1C, (control + 0x934) as u32);
    kpad_block_set_u16(&mut block, 0x20, length as u16);
    kpad_block_set_u32(&mut block, 0x24, register);
    kpad_block_set_u32(&mut block, 0x2C, FN_801DFC40);
    let _ = kpad_ring_push(control, &block);

    // observed: kind 0x15 extension-report request with no completion.
    let mut block = kpad_cmd_block(0x15);
    block[0x1A] = 0;
    block[0x1B] = 1;
    let _ = kpad_ring_push(control, &block);
}

/// Handles the Bluetooth connect/disconnect notification for one device.
///
/// On disconnect it marks the channel's link dead, drains the command queue
/// (invoking each block's `+0x2C` callback with `-1`), resets the report ring
/// and the channel, and calls the public connect callback with `-1`.
///
/// On connect it assigns a channel through [`fn_801e0700`], resets the channel
/// and queues the attach sequence whose completion is [`fn_801dfe00`]. The
/// device name `"Nintendo RVL CNT"` is the standard remote and
/// `"Nintendo RVL WBC"` is the balance board.
///
/// # Original
/// - Ghidra: `FUN_801e0820` at `0x801E0820` (1204 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801e0820_FUN_801e0820.c`
/// - Registered through `0x801F3BF0` by `0x801DEB70`.
///
/// # Arguments
/// * `device` - Bluetooth device descriptor; `+0x56` is the device id.
/// * `connected` - zero means disconnect, non-zero means connect.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// Writes `0x8039F340[device_id]`, the per-channel state fields `+0x8BC`,
/// `+0x8C1`, `+0x8C3`, `+0x8D8`, `+0x8BC`, `+0x983`, `+0x986`, `+0x98D` and
/// `+0x990`, and appends the attach block to the `+0x160` ring.
///
/// # Safety
/// `device` must be readable; the channel table and ring must be initialised.
///
/// # Confidence
/// high - both branches and the device-name comparisons are explicit in the
/// Ghidra body; only the official callback name is unresolved.
pub unsafe fn fn_801e0820(device: usize, connected: u32) {
    let device_id = platform::read_u8(device + 0x56);
    let label = if connected != 0 {
        SDA_WPAD_5E74
    } else {
        SDA_WPAD_5E6C
    };
    platform::call2(OS_REPORT, MSG_CONNECTION_IS, label as u32);

    if connected == 0 {
        let mut slot = platform::read_u8(WPAD_CHANNEL_FLAGS + device_id as usize) as i8;
        platform::write_u8(WPAD_CHANNEL_FLAGS + device_id as usize, 0xFF);
        if slot == -1 {
            platform::call1(OS_REPORT, MSG_DISCONNECT_WARNING);
            return;
        }
        let channel = slot as u32;
        let control = kpad_control(channel);

        platform::write_u32(control + 0x8BC, 0xFFFF_FFFF);
        let callback = platform::read_u32(control + 0x89C);
        if callback == 0 {
            let alternate = platform::read_u32(control + 0x9A8);
            if alternate != 0 {
                platform::call2(alternate as usize, channel, 0xFFFF_FFFF);
            }
        } else {
            platform::call2(callback as usize, channel, 0xFFFF_FFFF);
        }

        loop {
            let token = disable_interrupts();
            let count = kpad_ring_count(control + 0x160);
            restore_interrupts(token);
            if count == 0 {
                break;
            }

            let token = disable_interrupts();
            let base = platform::read_u32(control + 0x164) as usize;
            let tail = platform::read_u8(control + 0x160);
            let mut block = crate::platform::GuestLocal::new( [0u8; 0x30]);
            platform::call3(
                MEMCPY,
                block.as_mut_ptr() as u32,
                (base + tail as usize * 0x30) as u32,
                0x30,
            );
            restore_interrupts(token);

            let block_callback = kpad_block_u32(&block, 0x2C);
            if block_callback != 0 {
                platform::call2(block_callback as usize, channel, 0xFFFF_FFFF);
            }

            let token = disable_interrupts();
            let count = kpad_ring_count(control + 0x160);
            if count != 0 {
                let base = platform::read_u32(control + 0x164) as usize;
                let tail = platform::read_u8(control + 0x160);
                platform::call3(MEMSET, (base + tail as usize * 0x30) as u32, 0, 0x30);
                let mut next = tail.wrapping_add(1);
                let capacity = platform::read_u32(control + 0x168);
                if next as u32 == capacity.wrapping_sub(1) {
                    next = 0;
                }
                platform::write_u8(control + 0x160, next);
            }
            restore_interrupts(token);
        }

        platform::call1(OS_REPORT, MSG_CLEANUP_QUEUE);
        let report_buffer = platform::read_u32(control + 0x8AC);
        if report_buffer != 0 {
            fn_801e19c0(
                channel,
                report_buffer,
                platform::read_u32(control + 0x8B4),
            );
        }
        wpad_control_init_801df570(channel);
        platform::write_u8(SDA_WPAD_4BD0 + channel as usize, 0);
        let callback = platform::read_u32(control + 0x8A4);
        if callback != 0 {
            platform::call2(callback as usize, channel, 0xFFFF_FFFF);
        }
        return;
    }

    let assigned = fn_801e0700(device);
    if assigned < 0 {
        return;
    }
    let channel = assigned as u32;
    platform::write_u8(WPAD_CHANNEL_FLAGS + device_id as usize, channel as u8);
    wpad_control_init_801df570(channel);

    let control = kpad_control(channel);
    if platform::call3(BT_NAME_MATCH, device as u32, MSG_CNT_NAME, 0x10) == 0 {
        platform::write_u8(control + 0x8C1, 0);
        platform::write_u32(control + 0x8B8, 0);
    } else if platform::call3(BT_NAME_MATCH, device as u32, MSG_WBC_NAME, 0x10) == 0
        && call0_ret(KPAD_BALANCE_BOARD_ALLOWED) != 0
    {
        platform::write_u8(control + 0x8C1, 3);
        platform::write_u32(control + 0x8B8, 0xC);
    } else {
        platform::write_u8(control + 0x8C1, 0xFB);
        platform::write_u32(control + 0x8B8, 0);
    }

    platform::write_u8(control + 0x8C3, device_id);
    platform::write_u32(control + 0x8D8, 1);
    platform::write_u32(control + 0x8BC, 0);
    platform::write_u8(control + 0x983, 100);
    platform::write_u8(control + 0x986, 0);
    platform::write_u8(control + 0x98D, 0);
    platform::write_u8(control + 0x990, platform::read_u8(control + 0x8C1));

    // observed: kind 0x17, register 6000 / 1, 6-byte read into control+0x934.
    let mut block = kpad_cmd_block(0x17);
    kpad_block_set_u32(&mut block, 4, 6000);
    kpad_block_set_u16(&mut block, 8, 1);
    block[0x1A] = 0;
    block[0x1B] = 6;
    kpad_block_set_u32(&mut block, 0x1C, (control + 0x934) as u32);
    kpad_block_set_u16(&mut block, 0x20, 1);
    kpad_block_set_u32(&mut block, 0x24, 6000);
    kpad_block_set_u32(&mut block, 0x2C, FN_801DFE00);
    let _ = kpad_ring_push(control, &block);

    platform::call0(BT_FLUSH_801BE470);
}

/// Reads the global sampling-mode byte `r13-0x4BC9` under the interrupt lock.
///
/// # Original
/// - Ghidra: `FUN_801e3420` at `0x801E3420` (52 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801e3420_FUN_801e3420.c`
///
/// # Arguments
/// None.
///
/// # Returns
/// The current extension sampling mode (`0..=0x7F`).
///
/// # Side effects
/// None beyond the lock pair.
///
/// # Safety
/// None beyond a valid SDA.
///
/// # Confidence
/// high - exact getter paired with [`fn_801e3460`].
pub unsafe fn fn_801e3420() -> u8 {
    let token = disable_interrupts();
    let value = platform::read_u8(SDA_WPAD_4BC9);
    restore_interrupts(token);
    value
}

/// Writes the global sampling-mode byte `r13-0x4BC9`, clamped to `0..=0x7F`.
///
/// # Original
/// - Ghidra: `FUN_801e3460` at `0x801E3460` (80 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801e3460_FUN_801e3460.c`
///
/// # Arguments
/// * `value` - requested mode; `0` stays `0`, values above `0x7E` become
///   `0x7F`.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// Writes [`SDA_WPAD_4BC9`] under the interrupt lock.
///
/// # Safety
/// None beyond a valid SDA.
///
/// # Confidence
/// high - the clamp is explicit in the Ghidra body.
pub unsafe fn fn_801e3460(value: u32) {
    let clamped = if value == 0 {
        0
    } else if value > 0x7E {
        0x7F
    } else {
        value as u8
    };
    let token = disable_interrupts();
    platform::write_u8(SDA_WPAD_4BC9, clamped);
    restore_interrupts(token);
}

/// Decides whether one channel is currently allowed to sample.
///
/// The function combines the channel's disconnected bit, the Bluetooth state,
/// the link-quality limit, the command-ring depth and the extension state into
/// a single boolean. It also nudges the Bluetooth link when it is still up.
///
/// # Original
/// - Ghidra: `FUN_801e34b0` at `0x801E34B0` (312 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801e34b0_FUN_801e34b0.c`
/// - The channel argument is recovered from the `0x802DCD60` prologue artifact
///   and the result is returned through `0x802DCDAC`.
///
/// # Arguments
/// * `channel` - controller index.
///
/// # Returns
/// `0` when sampling is allowed, `1` when it must be refused.
///
/// # Side effects
/// Calls `0x801F61C0` when a link is present and reads the ring/SDA fields
/// under the interrupt lock.
///
/// # Safety
/// The channel control block and Bluetooth helpers must be valid.
///
/// # Confidence
/// medium - the gate is a direct transcription; the individual Bluetooth
/// counters are named by shape only.
pub unsafe fn fn_801e34b0(channel: u32) -> u32 {
    let control = kpad_control(channel);

    let token = disable_interrupts();
    let disconnected = platform::read_u8(control + 0x8CD);
    let link_state = platform::read_u8(control + 0x8C1);
    let bluetooth_state = call0_ret(BT_STATE_801F3570) & 0xFF;

    let token_inner = disable_interrupts();
    let pending = kpad_ring_count(control + 0x160) as i8;
    restore_interrupts(token_inner);

    let token_inner = disable_interrupts();
    let link = platform::read_i32(control + 0x8BC);
    let device = platform::read_u8(control + 0x8C3);
    restore_interrupts(token_inner);
    if link != -1 {
        platform::call1(BT_KEY_HOOK_801F61C0, device as i8 as i32 as u32);
    }

    let token_inner = disable_interrupts();
    let link = platform::read_i32(control + 0x8BC);
    let device = platform::read_u8(control + 0x8C3);
    restore_interrupts(token_inner);
    let link_value = if link == -1 {
        0
    } else {
        platform::call1(BT_KEY_VALUE_801F6220, device as i8 as i32 as u32) as u16
    };

    let extension_state = platform::read_u8(control + 0x8CF);
    let limit = call0_ret(BT_KEY_LIMIT_801F6280) & 0xFF;
    restore_interrupts(token);

    let allowed = disconnected == 0
        && (link_value as u32) < 4
        && bluetooth_state != 10
        && bluetooth_state < limit.wrapping_mul(2).wrapping_add(2)
        && link_state != 0xFF
        && pending < 0x15
        && extension_state == 0;
    if allowed {
        0
    } else {
        1
    }
}

/// Reports whether one channel has a live link and is ready to sample.
///
/// # Original
/// - Ghidra: `FUN_801e35f0` at `0x801E35F0` (132 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801e35f0_FUN_801e35f0.c`
///
/// # Arguments
/// * `channel` - controller index.
///
/// # Returns
/// `1` when the link exists, the channel is connected and
/// [`fn_801e34b0`] allows sampling; otherwise `0`.
///
/// # Side effects
/// None beyond the interrupt-lock reads.
///
/// # Safety
/// The channel control block must be valid.
///
/// # Confidence
/// high - the three-part condition is explicit.
pub unsafe fn fn_801e35f0(channel: u32) -> u32 {
    let control = kpad_control(channel);
    let token = disable_interrupts();
    let link = platform::read_i32(control + 0x8BC);
    let connected = platform::read_u32(control + 0x8DC);
    restore_interrupts(token);

    if link == -1 || connected == 0 || fn_801e34b0(channel) != 0 {
        0
    } else {
        1
    }
}

/// Sends one short command to the extension register ring.
///
/// The block has kind `0x18`; byte `+4` is the payload length shifted left by
/// three and bytes `+5..` are the caller buffer. On success the per-channel
/// command counter at `+0x8CF` is incremented.
///
/// # Original
/// - Ghidra: `FUN_801e3680` at `0x801E3680` (528 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801e3680_FUN_801e3680.c`
/// - Callers `0x80173A30` and `0x80270410` pass `(channel, buffer, 0x14)`.
///
/// # Arguments
/// * `channel` - controller index (recovered from the `0x802DCD70` artifact).
/// * `buffer` - payload bytes copied into block `+5`.
/// * `len` - payload length; the callers use `0x14`.
///
/// # Returns
/// `0` when queued, `-1` without a link, `-2` when the channel is down, the
/// sampling gate refuses, or the ring is full.
///
/// # Side effects
/// Appends one 0x30-byte block to the `+0x160` ring and increments `+0x8CF`.
///
/// # Safety
/// `buffer` must be readable for `len` bytes; the ring must be initialised.
///
/// # Confidence
/// medium - the queue shape and status values are exact; the command kind is
/// observed only.
pub unsafe fn fn_801e3680(channel: u32, buffer: usize, len: u32) -> i32 {
    let control = kpad_control(channel);

    let token = disable_interrupts();
    let link = platform::read_i32(control + 0x8BC);
    let connected = platform::read_u32(control + 0x8DC);
    restore_interrupts(token);

    if link == -1 {
        return -1;
    }
    if connected == 0 || fn_801e34b0(channel) != 0 {
        return -2;
    }

    let mut block = kpad_cmd_block(0x18);
    block[4] = (len.wrapping_shl(3) & 0xFF) as u8;
    for i in 0..len as usize {
        if 5 + i < 0x30 {
            block[5 + i] = platform::read_u8(buffer + i);
        }
    }
    block[0x1A] = 0;
    block[0x1B] = 0x15;

    if !kpad_ring_push(control, &block) {
        return -2;
    }

    let token = disable_interrupts();
    let counter = platform::read_u8(control + 0x8CF).wrapping_add(1);
    platform::write_u8(control + 0x8CF, counter);
    restore_interrupts(token);
    0
}

