// ---------------------------------------------------------------------------
// Wave 18: WPAD report-queue consumer and the GKI buffer-queue layer
// (`0x801DDD20`, `0x801EA8F0`, `0x801F3530`-`0x801F87C0`)
// ---------------------------------------------------------------------------
//
// The WPAD report path does not hand reports to the application directly: every
// decoded HID report is copied into a reference-counted buffer owned by the
// Bluetooth "GKI" buffer pool and then queued to the HID-host task. This
// section translates that transport:
//
// * `0x801DDD20` consumes one completed 0x30-byte report block from the WPAD
//   queue, updates the per-channel control block and posts a `0x1708`
//   HID-host message that carries the copied report.
// * `0x801F6FB0`/`0x801F7150` allocate a pool buffer (by size or by pool id),
//   `0x801F7240` frees one, and `0x801F7670`/`0x801F77B0`/`0x801F78F0`/
//   `0x801F7990` manage the per-owner/per-destination FIFOs.
// * `0x801F6AC0`/`0x801F6CE0` build and clear the five pools, `0x801F84F0`/
//   `0x801F8580` bring the whole GKI area up and down, and
//   `0x801F8730`/`0x801F8760` push/pop the nested critical-section masks.
//
// Pool records live at `0x803CDCA8`, one 0x10-byte record per pool:
// `{ head u32, tail u32, size u16, count u16, used u16, high u16 }`.
// Each buffer carries an 8-byte header *before* the pointer the caller sees:
// `{ next u32, pool id u8, owner/tag u8, state u8, pad u8 }`, and a
// `0xDDBADDBA` guard word sits directly after the payload. State `0` means
// free, `1` allocated and unlinked, `2` linked into a queue.

// --- GKI buffer-pool globals ----------------------------------------------

/// Stride between pool records: four 32-bit halves of the six fields.
const GKI_POOL_STRIDE: usize = 0x10;
/// `0x803CDCA8`: free-list head of pool `n` (`+ n * 0x10`).
const GKI_POOL_HEAD: usize = 0x803C_DCA8;
/// `0x803CDCAC`: free-list tail of pool `n` (`+ n * 0x10`).
const GKI_POOL_TAIL: usize = 0x803C_DCAC;
/// `0x803CDCB0`: block size in bytes (`u16`, `+ n * 0x10`).
const GKI_POOL_SIZE: usize = 0x803C_DCB0;
/// `0x803CDCB2`: block count (`u16`, `+ n * 0x10`).
const GKI_POOL_COUNT: usize = 0x803C_DCB2;
/// `0x803CDCB4`: blocks currently handed out (`u16`, `+ n * 0x10`).
const GKI_POOL_USED: usize = 0x803C_DCB4;
/// `0x803CDCB6`: high-water mark of [`GKI_POOL_USED`] (`u16`).
const GKI_POOL_HIGH: usize = 0x803C_DCB6;

/// `0x803CDD38`: arena base of pool `n` (`u32`, stride 4).
const GKI_POOL_ARENA: usize = 0x803C_DD38;
/// `0x803CDD5C`: first byte after pool `n`'s arena (`u32`, stride 4).
const GKI_POOL_ARENA_END: usize = 0x803C_DD5C;
/// `0x803CDD80`: block stride of pool `n` (`u16`, stride 2).
const GKI_POOL_BLOCK_STRIDE: usize = 0x803C_DD80;
/// `0x803CDD98`: 16-bit mask of pools that must not be handed out.
const GKI_POOL_EXCLUDE: usize = 0x803C_DD98;
/// `0x803CDD9A`: pool ids in ascending block size, searched by `getbuf`.
const GKI_POOL_ORDER: usize = 0x803C_DD9A;
/// `0x803CDDA3`: number of valid entries in [`GKI_POOL_ORDER`] (5 here).
const GKI_POOL_ORDER_COUNT: usize = 0x803C_DDA3;

/// `0x803CDAC8`: per-owner "queue registered" byte (8 owners).
const GKI_QUEUE_READY: usize = 0x803C_DAC8;
/// `0x803CDAD0`: per-owner pending-event mask. Ghidra indexes it as
/// `&DAT_803cdad0 + owner * 2` on a 16-bit datum, i.e. one 32-bit word per
/// owner with the mask in the low half (`0x803CDAD4` is owner 1).
// inferred: the 4-byte stride explains the separate `0x803CDAD4` writes in
// `0x801F84F0`; only the low 16 bits are ever used as a mask.
const GKI_QUEUE_EVENTS: usize = 0x803C_DAD0;
/// `0x803CDBA8`: per-(owner, destination) queue head; owner stride `0x10`,
/// destination stride 4.
const GKI_QUEUE_HEAD: usize = 0x803C_DBA8;
/// `0x803CDC28`: per-(owner, destination) queue tail.
const GKI_QUEUE_TAIL: usize = 0x803C_DC28;

/// `0x803A52C8`: nesting depth of the GKI critical-section stack (byte).
const GKI_CRITICAL_DEPTH: usize = 0x803A_52C8;
/// `0x803A52CC`: saved interrupt masks of the critical-section stack.
const GKI_CRITICAL_STACK: usize = 0x803A_52CC;
/// `0x803CDACA`: GKI initialised flag (byte).
const GKI_INITIALISED: usize = 0x803C_DACA;
/// `0x803CDAB0`: GKI queue-configuration word cleared by `0x801F84F0`.
const GKI_CONFIG_WORD: usize = 0x803C_DAB0;
/// `0x803CDAD4`: owner-1 pending-event word cleared by `0x801F84F0`.
const GKI_QUEUE_EVENTS_1: usize = 0x803C_DAD4;
/// `0x803CDB10`: GKI statistics word cleared by `0x801F84F0`.
const GKI_STATS_WORD: usize = 0x803C_DB10;

/// `0x803A3828`: Bluetooth link state shared with [`fn_801ddb50`].
const BT_LINK_STATE: usize = 0x803A_3828;
/// `0x803A312D`..`0x803A3130`: open-attempt state bytes. `0x803A312C` is
/// already [`BTA_HH_PENDING_MODE`]; these are the three bytes after it.
const BT_OPEN_STATE_312D: usize = 0x803A_312D;
const BT_OPEN_STATE_312F: usize = 0x803A_312F;
const BT_OPEN_STATE_3130: usize = 0x803A_3130;

// --- external call targets -------------------------------------------------

/// `0x801F87B0`: two-argument diagnostic stub (empty in this build).
const GKI_LOG: usize = 0x801F_87B0;
/// `0x801F8720`: returns the current GKI task/owner id (constant `2` here).
const GKI_CURRENT_TASK: usize = 0x801F_8720;
/// `0x801B1160`: snapshot of the interrupt level pushed by GKI init.
const GKI_CRITICAL_LEVEL: usize = 0x801B_1160;
/// `0x801EFF00`: application memory allocator wrapper; returns the pointer
/// produced by the app callback at `0x803A3814`.
const APP_MEM_ALLOC: usize = 0x801E_FF00;
/// `0x801F7F60`: clears the GKI per-owner statistic block.
const GKI_CLEAR_STATS: usize = 0x801F_7F60;
/// `0x801FF778`: queues a `0x1708` HID-host data message for `(handle, buf)`.
const HID_HOST_POST_DATA: usize = 0x801F_F778;

/// `"handle = %d, repid = %02x"` at `0x80343B28`.
const MSG_REPORT_TRACE: u32 = 0x8034_3B28;
/// `"getbuf: Size is zero"` at `0x803473F8`.
const MSG_GETBUF_ZERO: u32 = 0x8034_73F8;
/// `"getbuf: Size is too big"` at `0x80347410`.
const MSG_GETBUF_TOO_BIG: u32 = 0x8034_7410;
/// `"Free - Buf Corrupted"` at `0x80347428`.
const MSG_FREE_CORRUPTED: u32 = 0x8034_7428;
/// `"Freeing Linked Buf"` at `0x80347440`.
const MSG_FREE_LINKED: u32 = 0x8034_7440;
/// `"Bad Buf QId"` at `0x80347454`.
const MSG_FREE_BAD_QID: u32 = 0x8034_7454;
/// `"Sending to unknown dest"` at `0x80347460`.
const MSG_SEND_UNKNOWN_DEST: u32 = 0x8034_7460;
/// `"Send - Buffer corrupted"` at `0x80347478`.
const MSG_SEND_CORRUPTED: u32 = 0x8034_7478;
/// `"Send - buffer linked"` at `0x80347490`.
const MSG_SEND_LINKED: u32 = 0x8034_7490;
/// `"Enqueue - Buffer corrupted"` at `0x803474A8`.
const MSG_ENQUEUE_CORRUPTED: u32 = 0x8034_74A8;
/// `"Eneueue - buf already linked"` at `0x803474C4` (typo is in the image).
const MSG_ENQUEUE_LINKED: u32 = 0x8034_74C4;
/// `"Eneueue head - buf already linked"` at `0x803474E4`.
const MSG_ENQUEUE_HEAD_LINKED: u32 = 0x8034_74E4;

/// End-of-payload guard word written by the pool builder.
const GKI_BUF_MAGIC: u32 = 0xDDBADDBA;
/// Owner/tag byte of a free buffer (the pool builder writes it, `free` puts it
/// back).
const GKI_BUF_FREE_TAG: u8 = 0xF0;

/// Returns the pool record offset for `pool` (`pool * 0x10`).
///
/// # Original
/// - Inlined as `(&DAT_803cdca8)[pool * 4]`, `(&DAT_803cdcb0)[pool * 8]` and
///   `*(int *)((int)&DAT_803cdd38 + pool * 4)` in `0x801F6AC0`,
///   `0x801F6FB0` and `0x801F7150`.
///
/// # Confidence
/// high - all three field groups use the same 0x10-byte stride.
#[inline]
fn gki_pool_offset(pool: u32) -> usize {
    (pool & 0xFF) as usize * GKI_POOL_STRIDE
}

/// Returns the payload size of an allocated buffer, or `0` when the header is
/// unaligned or names an out-of-range pool.
///
/// # Original
/// - Inlined in `0x801F7240`, `0x801F7400`, `0x801F7670` and `0x801F77B0`.
/// - Ghidra: `FUN_801f73b0` at `0x801F73B0` is the same computation as a
///   standalone function; this helper delegates to that body.
///
/// # Safety
/// `buf` must be a buffer pointer returned by `getbuf` (payload start), or the
/// reads at `buf - 4` are out of range.
///
/// # Confidence
/// high - four identical inline copies plus the standalone body.
#[inline]
unsafe fn gki_buf_size(buf: usize) -> u32 {
    // canonical: fn_801f73b0 is the standalone 0x801F73B0 body.
    fn_801f73b0(buf) as u32
}

/// Returns non-zero when a buffer's guard word is not [`GKI_BUF_MAGIC`].
///
/// # Original
/// - Inlined in `0x801F7240`, `0x801F7400`, `0x801F7670` and `0x801F77B0` as
///   `(0xddbaddba - *guard | *guard + 0x22452246) >> 31`.
///
/// # Arguments
/// * `buf` - payload pointer; the guard word sits at `buf + size`.
///
/// # Returns
/// `0` when the guard matches, `1` otherwise (including misaligned buffers).
///
/// # Safety
/// `buf + size` must be readable.
///
/// # Confidence
/// high - the arithmetic is identical at all four call sites.
#[inline]
unsafe fn gki_buf_corrupted(buf: usize) -> u32 {
    let size = gki_buf_size(buf) as usize;
    if buf.wrapping_add(size) & 1 != 0 {
        return 1;
    }
    let guard = platform::read_u32(buf + size);
    ((GKI_BUF_MAGIC.wrapping_sub(guard) | guard.wrapping_add(0x2245_2246)) >> 31) & 1
}

/// Pushes the current interrupt mask onto the GKI critical-section stack.
///
/// # Original
/// - Ghidra: `FUN_801f8760` at `0x801F8760` (68 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801f8760_FUN_801f8760.c`
/// - Called by every queue operation before it touches a list.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// Reads the mask through `0x801B1140`, stores it at
/// `0x803A52CC + depth * 4`, and increments the depth byte `0x803A52C8`.
///
/// # Safety
/// The nesting depth must stay below 255 (the original stores only one byte).
///
/// # Confidence
/// high - the body is the mask push and nothing else.
pub unsafe fn fn_801f8760() {
    let mask = disable_interrupts();
    let depth = platform::read_u8(GKI_CRITICAL_DEPTH);
    platform::write_u32(GKI_CRITICAL_STACK + depth as usize * 4, mask);
    platform::write_u8(GKI_CRITICAL_DEPTH, depth.wrapping_add(1));
}

/// Pops the GKI critical-section stack and restores the saved interrupt mask.
///
/// # Original
/// - Ghidra: `FUN_801f8730` at `0x801F8730` (36 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801f8730_FUN_801f8730.c`
/// - Called by every queue operation after it has touched a list.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// Decrements `0x803A52C8`, restores the mask stored at
/// `0x803A52CC + (old_depth - 1) * 4` through `0x801B1180`, and therefore
/// re-enables interrupts at the outermost level.
///
/// # Safety
/// Must be called once per [`fn_801f8760`]; an unbalanced pop reads a stale
/// slot and restores an arbitrary mask.
///
/// # Confidence
/// high - the body is the mask pop and nothing else.
pub unsafe fn fn_801f8730() {
    let depth = platform::read_u8(GKI_CRITICAL_DEPTH);
    platform::write_u8(GKI_CRITICAL_DEPTH, depth.wrapping_sub(1));
    let slot = (depth.wrapping_sub(1) as usize * 4) & 0x3FC;
    restore_interrupts(platform::read_u32(GKI_CRITICAL_STACK + slot));
}

/// Consumes one completed WPAD report block and forwards it to the HID host.
///
/// The block is the 0x30-byte record the WPAD queue hands over: byte `+3` is
/// the report id, bytes `+4..` the payload and `+0x1A` the payload length. The
/// function first applies the channel-specific side effects (extension
/// read/write bookkeeping), then copies the report into a GKI buffer and posts
/// it to the HID host as a `0x1708` data message.
///
/// # Original
/// - Ghidra: `FUN_801ddd20` at `0x801DDD20` (468 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801ddd20_FUN_801ddd20.c`
/// - Called by the queue-drain worker `0x801DEB70` as
///   `FUN_801ddd20(channel, &block)`.
/// - Recovers `(channel, block)` from the `0x802DCD68` prologue artifact, which
///   returns the saved `r4` (block) and `r3` (channel) pair.
///
/// # Arguments
/// * `channel` - 0..=3; selects the 0x9C0-byte control block.
/// * `block` - 0x30-byte record: id at `+3`, payload at `+4`, length `u16` at
///   `+0x1A`.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// Under the interrupt lock: clears `+0x8BC` to `0xFFFFFFFE`, then applies the
/// per-id updates:
/// * `0x10` restores the saved `+0x8BC`;
/// * `0x18` restores it and decrements the retry byte `+0x8CF`;
/// * `0x17` stores the extension-read block (`+0x974`/`+0x978`/`+0x980`) and
///   clears `+0x97C`;
/// * `0x15` stores `block[+0x28]` at `+0x850` and sets `+0x8C0`;
/// * every other id sets bit 1 of `block[+4]` (the payload's first byte).
/// Then stores `block[+0x2C]` at `+0x89C`, the id at `+0x987`, a 64-bit
/// deadline at `+0x908` and clears `+0x910`. Outside the lock it logs the
/// handle/id, allocates a `(length + 0x12) & 0xFF` buffer, fills the
/// 4-byte message header, copies the payload and posts it; bit 0 of the copied
/// payload is set when `(+0x8D4 & r13-0x4BC8) != 0`.
///
/// # Safety
/// The control block must be published; `0x801F6FB0` may return `0`, which the
/// original does not check before writing the header.
///
/// # Confidence
/// medium - every branch and store is transcribed; the meaning of the
/// `+0x8BC`/`+0x8D4` words and of the id-specific fields is not named by any
/// string.
pub unsafe fn fn_801ddd20(channel: u32, block: usize) {
    let control = kpad_control(channel);
    let first_word = platform::read_u32(block);
    let length = platform::read_u16(block + 0x1A);
    let kind = (first_word & 0xFF) as u8; // observed: big-endian, so byte +3
    let payload = block + 4;

    let mask = disable_interrupts();
    let handle = platform::read_u8(control + 0x8C3) as i8;
    let saved_state = platform::read_u32(control + 0x8BC);

    if handle < 0 {
        // observed: a negative handle marks an inactive channel; nothing is
        // updated and no report is forwarded.
        restore_interrupts(mask);
    } else {
        platform::write_u32(control + 0x8BC, 0xFFFF_FFFE);
        let selector = platform::read_u32(control + 0x8D4);
        let selector_mask = platform::read_u32(SDA_WPAD_4BC8);

        if kind == 0x10 {
            platform::write_u32(control + 0x8BC, saved_state);
        } else if kind == 0x18 {
            platform::write_u32(control + 0x8BC, saved_state);
            let retries = platform::read_u8(control + 0x8CF);
            platform::write_u8(control + 0x8CF, retries.wrapping_sub(1));
        } else {
            if kind != 0x16 {
                if kind == 0x17 {
                    // Extension register read result.
                    platform::write_u32(control + 0x97C, 0);
                    platform::write_u32(control + 0x978, platform::read_u32(block + 0x24));
                    platform::write_u16(control + 0x980, platform::read_u16(block + 0x20));
                    platform::write_u32(control + 0x974, platform::read_u32(block + 0x1C));
                } else if kind == 0x15 {
                    platform::write_u32(control + 0x8BC, saved_state);
                    platform::write_u32(control + 0x850, platform::read_u32(block + 0x28));
                    platform::write_u8(control + 0x8C0, 1);
                } else {
                    // observed: mark the first payload byte with bit 1.
                    let byte = platform::read_u8(payload);
                    platform::write_u8(payload, byte | 2);
                }
            }

            platform::write_u32(control + 0x89C, platform::read_u32(block + 0x2C));
            platform::write_u8(control + 0x987, kind);
            let deadline = get_time().wrapping_add(
                (platform::read_u32(LOW_MEM_BUS_CLOCK) >> 1 & 0x7FFF_FFFE) as u64,
            );
            platform::write_u32(control + 0x908, (deadline >> 32) as u32);
            platform::write_u32(control + 0x90C, deadline as u32);
            platform::write_u8(control + 0x910, 0);
        }
        restore_interrupts(mask);

        platform::call3(
            OS_REPORT,
            MSG_REPORT_TRACE,
            handle as i32 as u32,
            kind as u32,
        );

        let buffer = platform::call1(
            BTA_HH_GETBUF,
            (length as u32).wrapping_add(0x12) & 0xFF,
        ) as usize;
        platform::write_u16(buffer + 2, length.wrapping_add(1) & 0xFF);
        platform::write_u16(buffer + 4, 10);
        platform::write_u8(buffer + 0x12, kind);
        platform::call3(MEMCPY, (buffer + 0x13) as u32, payload as u32, length as u32);

        let copied = platform::read_u8(buffer + 0x13);
        if selector & selector_mask == 0 {
            platform::write_u8(buffer + 0x13, copied & 0xFE);
        } else {
            platform::write_u8(buffer + 0x13, copied | 1);
        }
        platform::call2(HID_HOST_POST_DATA, handle as i32 as u32, buffer as u32);
    }
}

