/// high - the pool sizes/counts/arenas and the id table are literal.
pub unsafe fn fn_801f6ce0() {
    for i in 0..32 {
        platform::write_u32(GKI_QUEUE_HEAD + i * 4, 0);
        platform::write_u32(GKI_QUEUE_TAIL + i * 4, 0);
    }

    for pool in 0..9u32 {
        let record = gki_pool_offset(pool);
        platform::write_u32(GKI_POOL_HEAD + record, 0);
        platform::write_u32(GKI_POOL_TAIL + record, 0);
        platform::write_u16(GKI_POOL_SIZE + record, 0);
        platform::write_u16(GKI_POOL_COUNT + record, 0);
        platform::write_u16(GKI_POOL_USED + record, 0);
        platform::write_u16(GKI_POOL_HIGH + record, 0);
        platform::write_u32(GKI_POOL_ARENA + pool as usize * 4, 0);
        platform::write_u32(GKI_POOL_ARENA_END + pool as usize * 4, 0);
        platform::write_u16(GKI_POOL_BLOCK_STRIDE + pool as usize * 2, 0);
    }
    platform::write_u16(GKI_POOL_EXCLUDE, 0xFFF0);

    fn_801f6ac0(0, 0x40, 0x30, 0x803A_531C);
    fn_801f6ac0(1, 0x80, 0x1A, 0x803A_615C);
    fn_801f6ac0(2, 0x294, 0x2D, 0x803A_6F94);
    fn_801f6ac0(3, 0x708, 0x1E, 0x803A_E5B4);
    fn_801f6ac0(4, 0x2000, 9, 0x803B_BA0C);

    platform::write_u8(GKI_POOL_ORDER, 0);
    platform::write_u8(GKI_POOL_ORDER + 1, 1);
    platform::write_u8(GKI_POOL_ORDER + 2, 2);
    platform::write_u8(GKI_POOL_ORDER + 3, 3);
    platform::write_u8(GKI_POOL_ORDER + 4, 4);
    platform::write_u8(GKI_POOL_ORDER_COUNT, 5);
}

