            fn_801f8730();

            platform::write_u8(block + 5, call0_ret(GKI_CURRENT_TASK) as u8);
            platform::write_u8(block + 6, 1);
            platform::write_u32(block, 0);
            platform::write_u8(block + 7, 0);
            return block + 8;
