/// medium - the compare chain, table indexing and calls are literal;
/// `0x801FFEC4` recovers its argument and return value through a split
/// prologue, so its byte result is inferred from the ABI.
pub unsafe fn fn_801ffcc4(msg: usize) -> u32 {
    let mut handle: u8 = 0x10;
    let mut control: usize = 0;
    let event = platform::read_u16(msg);

    if event == 0x170E {
        platform::call0(0x801F_F024);
        return 1;
    }
    if event < 0x170E {
        if event == 0x170C {
            platform::call0(0x801F_DE58);
            return 1;
        }
        if event > 0x170B {
            platform::call0(0x801F_DFCC);
            return 1;
        }
    } else if event < 0x1710 {
        platform::call0(0x801F_E0D0);
        return 1;
    }

    let message_handle = platform::read_u16(msg + 6);
    if event == 0x1700 {
        handle = platform::call1(0x801F_FEC4, (msg + 8) as u32) as u8;
    } else if event == 0x170A {
        if platform::read_u16(msg + 0x10) == 0x0B {
            handle = platform::call1(0x801F_FEC4, (msg + 8) as u32) as u8;
        } else {
            handle = platform::read_u8(BTA_HH_DEVICE_BY_HANDLE + message_handle as usize);
        }
    } else if message_handle < 0x10 {
        handle = platform::read_u8(BTA_HH_DEVICE_BY_HANDLE + message_handle as usize);
    }

    if handle != 0x10 {
        control = BTA_HH_CB_BASE + handle as usize * BTA_HH_CB_STRIDE;
    }
    if bta_trace_level() > 4 {
        platform::call4(
            BTA_TRACE_2,
            0x504,
            0x8034_7D7C, // "bta_hh_hdl_event: handle: %d d"
            message_handle as u32,
            handle as u32,
        );
    }
    fn_801ff970(control, event as u32, msg);
    1
}

/// Maps a HID-host event id to its diagnostic name.
///
/// The 16 event ids `0x1700`..`0x170F` each return a fixed string address in
/// the `0x80347Dxx` block; anything else returns the
/// `"unknown HID Host event code"` string.
///
/// # Original
/// - Ghidra: `FUN_801ffe10` at `0x801FFE10` (180 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801ffe10_FUN_801ffe10.c`
///
/// # Arguments
/// * `event` - 32-bit event id.
///
/// # Returns
/// A pointer to the NUL-terminated name string.
///
/// # Side effects
/// None.
///
/// # Safety
/// The string must be read-only data (it is).
///
/// # Confidence
/// high - the switch and all sixteen string addresses are literal; the
/// addresses are taken from the `s_..._8034xxxx` symbols.
pub unsafe fn fn_801ffe10(event: u32) -> usize {
    match event {
        0x1700 => 0x8034_7DD8, // "BTA_HH_API_OPEN_EVT"
        0x1701 => 0x8034_7DEC, // "BTA_HH_API_CLOSE_EVT"
        0x1702 => 0x8034_7E04, // "BTA_HH_INT_OPEN_EVT"
        0x1703 => 0x8034_7E18, // "BTA_HH_INT_CLOSE_EVT"
        0x1704 => 0x8034_7E48, // "BTA_HH_INT_DATA_EVT"
        0x1705 => 0x8034_7E5C, // "BTA_HH_INT_CTRL_DATA"
        0x1706 => 0x8034_7E30, // "BTA_HH_INT_HANDSK_EVT"
        0x1707 => 0x8034_7E90, // "BTA_HH_SDP_CMPL_EVT"
        0x1708 => 0x8034_7E74, // "BTA_HH_API_WRITE_DEV_EVT"
        0x1709 => 0x8034_7ED8, // "BTA_HH_API_GET_DSCP_EVT"
        0x170A => 0x8034_7EBC, // "BTA_HH_API_MAINT_DEV_EVT"
        0x170B => 0x8034_7EF0, // "BTA_HH_OPEN_CMPL_EVT"
        0x170C => 0x8034_7DC0, // "BTA_HH_API_ENABLE_EVT"
        0x170D => 0x8034_7DA8, // "BTA_HH_API_DISABLE_EVT"
        0x170E => 0x8034_7F08, // "BTA_HH_API_GET_ACL_Q_EVT"
        0x170F => 0x8034_7EA4, // "BTA_HH_DISC_CMPL_EVT"
        _ => 0x8034_7F24,      // "unknown HID Host event code"
    }
}

// ---------------------------------------------------------------------------
// WUD device-manager state machine and the BTM connection glue it drives
// (wave 74)
// ---------------------------------------------------------------------------
//
// `0x801F1620`..`0x801F3CB0` is the layer that owns the Bluetooth link state
// byte `0x803A3828` and the 16 per-device records at `0x803A3204`. The three
// flush callbacks (`0x801F1620`, `0x801F1F20`, `0x801F2CC0`) are the only
// writers of the init/shutdown state bytes `0x803A3130` / `0x803A3131`; the
// four `WUDSet*Callback` setters (`0x801F3630`, `0x801F3690`, `0x801F3B90`,
// `0x801F3BF0`) share one shape: trace, take the OS interrupt lock, read the
// old callback, install the new one, release the lock, return the old value.
// The two poll helpers `0x801F3860` / `0x801F38F0` report whether the link is
// up (`state == 3`) and close a pending removal exactly once.
//
// The second half of the pass (`0x801F7F60` and `0x801F92C0`..`0x801FB040`)
// is the HID-host transmit path and the BTM device-manager event handlers.
// Both pump functions post one buffer from a GKI list and keep an in-flight
// count for the same list; the four `0x801FAE00`..`0x801FAF0C` handlers all
// resolve the peer `BD_ADDR` through `0x8020A68C` first and then hand an
// eight-byte key plus the event record to a BTM request builder.
//
// `0x801F6A70` (the trace printer) is a no-op in this build, so every `trace`
// call below drops its formatted arguments but records them in a comment.

