/// Calls a nine-argument PowerPC routine through an `extern "C"` pointer.
///
/// [`crate::platform`] provides `call0`..`call7`; the HID-host transmitter
/// `0x801EFE60` takes nine arguments, so its call is spelled out here in the
/// same way [`call_f64_1`] handles the FPU-only helpers.
///
/// # Safety
/// `addr` must point at a routine with nine integer arguments and an integer
/// result, and the caller must run on the target (or an ABI-compatible host).
unsafe fn call9(
    addr: usize,
    a: u32,
    b: u32,
    c: u32,
    d: u32,
    e: u32,
    f: u32,
    g: u32,
    h: u32,
    i: u32,
) -> u32 {
    let func = crate::platform::guest_fn!(addr, fn(u32, u32, u32, u32, u32, u32, u32, u32, u32) -> u32);
    func(a, b, c, d, e, f, g, h, i)
}

