    body[1] = (address >> 8) as u8;
    body[2] = (address >> 16) as u8;
    body[3] = (address >> 24) as u8;
    let mut offset = 0usize;
    while offset < chunk as usize {
        body[4 + offset] = platform::read_u8(WUD_PATCH_DATA + position as usize + offset);
        offset += 1;
    }
    platform::write_u32(
        SDA_WUD_PATCH_POS,
        position.wrapping_add(chunk as u32),
    );
