/// Brings the WUD device manager up and marks every stored device present.
///
/// Announces the local name and device class taken from the `r2` small-data
/// area, installs the status, device-event and power-management callbacks,
/// applies three BTM configuration values, and re-adds every device record
/// whose state byte is `1` (ten in the first table, six in the second). It then
/// sets the link state to `3`, arms the `r13-0x4B4C` feature word and enables
/// the two WUD mode bytes.
///
/// # Original
/// - Ghidra: `FUN_801f4350` at `0x801F4350` (368 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801f4350_FUN_801f4350.c`
/// - String: `"start __wudInitSub()"` at `0x8034691C`.
///
/// # Arguments
/// None.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// Calls [fn_801fcf68], [fn_801f44c0] up to sixteen times, six registration
/// helpers, the interrupt lock pair and [fn_801fcfcc].
///
/// # Safety
/// The device tables must be initialised and the BTM task must be running
/// before the registration helpers are called.
///
/// # Confidence
/// medium - every call, constant and store is literal; the three-field stack
/// block is read from the `r2` small-data area through a base register Ghidra
/// reports as unproven, and the field roles are inferred from the two callees.
pub unsafe fn fn_801f4350() {
    // Ghidra splits the block into a halfword, a byte and a word; the offsets
    // below keep the original relative layout so both callees see the same
    // bytes.
    let mut boot = crate::platform::GuestLocal::new( [0u8; 8]);
    let base = boot.as_mut_ptr() as usize;
    platform::write_u16(base, platform::read_u16(SDA2_WUD_BOOT_CLASS));
    platform::write_u8(base + 2, platform::read_u8(SDA2_WUD_BOOT_SUB));
    platform::write_u32(base + 4, platform::read_u32(SDA2_WUD_BOOT_NAME));
    // observed: "start __wudInitSub()".
    fn_801f6a70();
    // observed: the word field is handed over as a NUL-terminated name.
    fn_801fcf68(base + 4);
    platform::call1(BTA_DM_SET_CLASS, base as u32);
    // fn_801f59d0 and fn_801f5c80 are the two DM callbacks installed here.
    platform::call1(WUD_INSTALL_STATUS_CB, 0x801F_59D0);
    platform::call1(WUD_INSTALL_EVENT_CB, 0x801F_5C80);
    platform::call3(
        BTM_SERVICE_REGISTER,
        3,
        WUD_HCI_HANDLE as u32,
        0x801F_6030,
    );
    platform::call1(BTA_DM_CONFIG_SETTER_B, 0x8000);
    platform::call1(BTA_DM_CONFIG_SETTER_C, 5);
    platform::call1(BTA_DM_CONFIG_SETTER_A, 0xC80);
    for index in 0..10 {
        let record = BTA_HH_DEVICE_TABLE + index * 0x60;
        if platform::read_u8(record + 0x59) == 1 {
            fn_801f44c0((record + 0x40) as u32);
        }
    }
    for index in 0..6 {
        let record = BTA_HH_DEVICE_TABLE_2 + index * 0x60;
        if platform::read_u8(record + 0x59) == 1 {
            fn_801f44c0((record + 0x40) as u32);
        }
    }
    let token = disable_interrupts();
    platform::write_u8(BT_LINK_STATE, 3);
    platform::write_u32(SDA_WUD_4B4C, 1);
    restore_interrupts(token);
    let token = disable_interrupts();
    platform::write_u8(WUD_MODE_380B, 0);
    platform::write_u8(WUD_MODE_380A, 1);
    restore_interrupts(token);
    fn_801fcfcc(0, 1);
}

// --- device-database constants ---------------------------------------------

/// `0x803A313C`: first of the six 12-byte slot descriptors of the first bank.
/// A slot holds the node pointer at `+0`, one link at `+4` and one at `+8`; the
/// device records the slots point at are [`BTA_HH_DEVICE_TABLE`] (ten) and
/// [`BTA_HH_DEVICE_TABLE_2`] (six).
const WUD_SLOT_TABLE_A: usize = 0x803A_313C;
/// `0x803A3134` / `0x803A3138`: head and tail node of the six-slot bank.
const WUD_HEAD_A: usize = 0x803A_3134;
const WUD_TAIL_A: usize = 0x803A_3138;
/// `0x803A318C`: first of the ten 12-byte slot descriptors of the second bank.
const WUD_SLOT_TABLE_B: usize = 0x803A_318C;
/// `0x803A3184` / `0x803A3188`: head and tail node of the ten-slot bank.
const WUD_HEAD_B: usize = 0x803A_3184;
const WUD_TAIL_B: usize = 0x803A_3188;
/// `0x803A3132` / `0x803A3133`: incremented when a device joins the database
/// and decremented when one leaves; the two counters split the devices by the
/// `+0x5B` class byte.
const WUD_ADD_COUNT: usize = 0x803A_3132;
const WUD_REMOVE_COUNT: usize = 0x803A_3133;
/// `0x80345FB8`: device-parameter block passed in the `BTA_HhAddDev` request.
const WUD_DEVICE_PARAMS: usize = 0x8034_5FB8;
/// `0x80346220` / `0x80346234`: the two 0x10-byte name prefixes that mark a
/// record as a Wii Remote or a Wii Balance Board.
const WUD_NAME_RVL_CNT: usize = 0x8034_6220;
const WUD_NAME_RVL_WBC: usize = 0x8034_6234;

/// `r13-0x4B38`: non-zero accepts the Balance Board records in the add path.
/// // unknown: who writes it.
const SDA_WUD_4B38: usize = SDA_BASE - 0x4B38;

/// `0x801FD16C`: `BTA_DmAddDevice(bd_addr, link_key, 0, 0)`.
const WUD_DM_ADD_DEVICE: usize = 0x801F_D16C;
/// `0x801FF808`: `BTA_HhAddDev(bd_addr, attr, subclass, app_id, params)`.
const WUD_HH_ADD_DEVICE: usize = 0x801F_F808;


/// Returns the address of 12-byte slot descriptor `index` in `base`.
///
/// # Original
/// - Inlined address arithmetic in `0x801F4880`-`0x801F5000`; the slot
///   descriptor holds a node pointer and two links.
///
/// # Safety
/// `index` must be inside the bank `base` names.
///
/// # Confidence
/// high - every one of the six list routines spells the stride out.
#[inline]
unsafe fn wud_slot(base: usize, index: usize) -> usize {
    base + index * 12
}

/// Adds one device to the BTM and HID-host databases.
///
/// Resolves the record for `bd_addr`, registers it with `BTA_DmAddDevice` and
/// then, for a Wii Remote - or for a Balance Board when `r13-0x4B38` is set -
/// also with `BTA_HhAddDev`. The class byte at `+0x5B` decides which of the two
/// counters at `0x803A3132` / `0x803A3133` advances.
///
/// # Original
/// - Ghidra: `FUN_801f44c0` at `0x801F44C0` (340 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801f44c0_FUN_801f44c0.c`
/// - Strings: `"BTA_DmAddDevice(): %d"` at `0x80346934`, `"BTA_HhAddDev()"` at
///   `0x80346950`.
///
/// # Arguments
/// * `bd_addr` - address of the six-byte peer `BD_ADDR`.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// One `BTA_DmAddDevice`, an optional `BTA_HhAddDev`, and one counter
/// increment, all under the interrupt lock.
///
/// # Safety
/// The record lookup must succeed; [fn_801f47a0] always returns a record from
/// one of the two tables for a device the stack knows about.
///
/// # Confidence
/// medium - the layout, the two name compares and the counter split are
/// literal; the eight-byte `BTA_HhAddDev` parameter block starts with a
/// halfword `0x00D9` whose low half is uninitialised in the export, so the
/// body reproduces only the half the C writes.
pub unsafe fn fn_801f44c0(bd_addr: u32) {
    let token = disable_interrupts();
    let record = fn_801f47a0(bd_addr) as usize;
    let status = platform::call4(
        WUD_DM_ADD_DEVICE,
        (record + 0x40) as u32,
        (record + 0x46) as u32,
        0,
        0,
    );
    // observed: "BTA_DmAddDevice(): %d".
    fn_801f6a70();
    let _ = status;
    let is_remote = platform::call3(
        BTA_MEMCMP,
        record as u32,
        WUD_NAME_RVL_CNT as u32,
        0x10,
    ) == 0;
    let is_board = platform::call3(
        BTA_MEMCMP,
        record as u32,
        WUD_NAME_RVL_WBC as u32,
        0x10,
    ) == 0;
    if is_remote || (is_board && platform::read_u32(SDA_WUD_4B38) != 0) {
        // observed: a two-word parameter block: a class halfword `0x00D9`
        // (the low half is never written) followed by `0x80345FB8`.
        let mut params = crate::platform::GuestLocal::new( [0u8; 8]);
        let base = params.as_mut_ptr() as usize;
        platform::write_u16(base, 0x00D9);
        platform::write_u32(base + 4, WUD_DEVICE_PARAMS as u32);
        // observed: "BTA_HhAddDev()".
        fn_801f6a70();
        platform::call5(
            WUD_HH_ADD_DEVICE,
            (record + 0x40) as u32,
            platform::read_u16(record + 0x5E) as u32,
            platform::read_u8(record + 0x57) as u32,
            platform::read_u8(record + 0x58) as u32,
            base as u32,
        );
    }
    let class = platform::read_u8(record + 0x5B);
    if class == 0 || class == 4 || class == 2 || class == 5 {
        platform::write_u8(
            WUD_ADD_COUNT,
            platform::read_u8(WUD_ADD_COUNT).wrapping_add(1),
        );
    } else {
        platform::write_u8(
            WUD_REMOVE_COUNT,
            platform::read_u8(WUD_REMOVE_COUNT).wrapping_add(1),
        );
    }
    restore_interrupts(token);
}

/// Removes one device from the databases and clears its record.
///
/// Looks the record up, drops the HID-host handle for a Wii Remote (or a
