        // observed: "BTM_CB_EVT_READ_STORED_LINK_KEYS" and
        // "status = %d max_keys = %d num_keys = %d".
        fn_801f6a70();
        fn_801f6a70();
        platform::write_u8(WUD_KEY_REQUEST, 0);
