/// - Ghidra: `FUN_801fdfcc` at `0x801FDFCC` (260 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801fdfcc_FUN_801fdfcc.c`
///
/// # Arguments
/// None.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// Sixteen `0x801FAAF0` frees plus one for the SDP buffer, one application
/// call, a 0x230-byte `memset`, or one API request per open block.
///
/// # Safety
/// The application callback must be installed; every block must be a live
/// 0x20-byte record.
///
/// # Confidence
/// high - both branches, the `0x1C == 3` test and the `0x1701` request are
/// literal.
pub unsafe fn fn_801fdfcc() {
    if platform::read_u32(BTA_HH_APP_CALLBACK) == 0 {
        return;
    }
    let mut payload = crate::platform::GuestLocal::new( [0u8; 16]);
    let base = payload.as_mut_ptr() as usize;
    if platform::read_u8(BTA_HH_OPEN_COUNT) == 0 {
        platform::write_u8(base, 0);
        if call0_ret(BTA_HH_CONNECTED) != 0 {
            platform::write_u8(base, 6);
        }
        let mut index = 0u32;
        while index < 16 {
            fn_801faaf0(bta_hh_cb(index) + 4);
            index += 1;
        }
        fn_801faaf0(BTA_HH_SDP_BUFFER);
        let callback = platform::read_u32(BTA_HH_APP_CALLBACK) as usize;
        platform::call2(callback, 1, base as u32);
        platform::call3(MEMSET, BTA_HH_CLEAR_BASE as u32, 0, 0x230);
    } else {
        platform::write_u8(BTA_HH_SHUTDOWN_FLAG, 1);
        let mut index = 0u32;
        while index < 16 {
            let block = bta_hh_cb(index);
            if platform::read_u8(block + 0x1C) == 3 {
                platform::call3(BTA_HH_API, block as u32, 0x1701, 0);
            }
            index += 1;
        }
    }
}

