    let base = payload.as_mut_ptr() as usize;
    fn_801fa3a4(base, record + 2);
    platform::call3(MEMCPY, (base + 6) as u32, (record + 8) as u32, 3);
    platform::write_u8(base + 9, platform::read_u8(record + 0x0E));

    let inquiry = platform::call1(BTM_INQUIRY_LOOKUP, (record + 2) as u32) as usize;
    // observed: only the found record path initialises the trailing flag.
    if inquiry != 0 {
        platform::write_u8(base + 10, 0);
    }
    platform::call2(bta_dm_app_callback(), 0, base as u32);
    if inquiry != 0 {
        platform::write_u8(inquiry + 0x10, 0);
    }
