/// payload offsets `+0x26` and `+0xFE` come from the two overlapping stack
/// locals, whose roles are inferred as name terminator and stored PIN.
pub unsafe fn fn_801fc104(reply: usize) {
    let mut payload = crate::platform::GuestLocal::new( [0u8; 0x101]);
    let base = payload.as_mut_ptr() as usize;
    fn_801fa3a4(base, BTA_DM_PIN_BDADDR);
    platform::write_u8(base + 0xFE, platform::read_u8(BTA_DM_PIN_CODE));
    platform::write_u8(base + 0xFF, platform::read_u8(BTA_DM_PIN_CODE + 1));
    platform::write_u8(base + 0x100, platform::read_u8(BTA_DM_PIN_CODE + 2));

    if reply == 0 || platform::read_u16(reply) != 0 {
        platform::write_u8(base + 6, 0);
    } else {
        let length = platform::read_u16(reply + 2);
        let length = if length < 0x20 { length } else { 0x20 };
        platform::call3(MEMCPY, (base + 6) as u32, (reply + 4) as u32, length as u32);
        platform::write_u8(base + 0x26, 0);
    }
    platform::call2(
        platform::read_u32(BTA_DM_SEARCH_CALLBACK) as usize,
        2,
        base as u32,
    );
}

/// Starts a remote-name request for a PIN-code lookup, or reports it directly.
///
/// Answers `0x0B` when no BTM search callback is installed. For a non-empty
/// caller name it first stores the address and the three PIN bytes, asks the
/// BTM layer for the remote name and returns `1` when the request was accepted;
/// on a rejection it logs `"bta_dm_pin_cback(): > Failed ..."`. The fallback
/// path reports the address, PIN and name to the search callback as event `2`
/// and returns `1`.
