    if platform::read_u8(name) == 0 {
        fn_801fa3a4(BTA_DM_PIN_BDADDR, addr as usize);
        platform::write_u8(BTA_DM_PIN_CODE, platform::read_u8(code));
        platform::write_u8(BTA_DM_PIN_CODE + 1, platform::read_u8(code + 1));
        platform::write_u8(BTA_DM_PIN_CODE + 2, platform::read_u8(code + 2));
        if platform::call2(BTM_READ_REMOTE_NAME, addr, fn_801fc104 as *const () as usize as u32) == 1 {
            return 1;
        }
        if platform::read_u8(SDA_BTA_TRACE_LEVEL) > 1 {
            // observed: "bta_dm_pin_cback(): > Failed to s...".
            platform::call2(BTA_TRACE_0, 0x501, MSG_PIN_FAILED as u32);
        }
    }

    let mut payload = crate::platform::GuestLocal::new( [0u8; 0x101]);
    let base = payload.as_mut_ptr() as usize;
    fn_801fa3a4(base, addr as usize);
    platform::write_u8(base + 0xFE, platform::read_u8(code));
    platform::write_u8(base + 0xFF, platform::read_u8(code + 1));
    platform::write_u8(base + 0x100, platform::read_u8(code + 2));
    platform::call3(BTA_STRNCPY, (base + 6) as u32, name as u32, 0x20);
    platform::write_u8(base + 0x16, 0);
    platform::call2(
        platform::read_u32(BTA_DM_SEARCH_CALLBACK) as usize,
        2,
        base as u32,
    );
    1
