/// # Confidence
/// medium - the store, the zero test and the two value pairs are literal;
/// `0x80213058`'s role is inferred from its argument shape.
pub unsafe fn fn_801fcd7c(event: usize) {
    let mode = platform::read_u16(event + 6);
    platform::write_u8(BTA_DM_DISABLE_FORCE, mode as u8);
    if (mode & 0xFF) == 0 {
        platform::call2(BTA_DM_STATE_RESET, SDA2_BTA_STATE_4C70 as u32, 2);
        platform::call3(BTM_FLOW_CONTROL_13058, 0, 2, 1);
    } else {
        platform::call2(BTA_DM_STATE_RESET, SDA2_BTA_STATE_4C70 as u32, 0xFFFF);
        platform::call3(BTM_FLOW_CONTROL_13058, 0, 0xFFFF, 1);
    }
}

/// Posts a `0x109` event carrying one handle, one halfword and one flag.
///
/// # Original
