/// `0x803A3807`: link-mode flag read by [fn_801f57c0] and written by
/// [fn_801f36f0]. // inferred: values `0`/`1` select the inquiry scan window.
const WUD_LINK_MODE_3807: usize = 0x803A_3807;
/// `0x803A3870`: 0x108-byte inquiry-result record (`BD_ADDR` at `+0`, name at
/// `+6`, extra word at `+0x100`).
const WUD_SEARCH_RESULT: usize = 0x803A_3870;
/// `0x803A3970`: word copied from inquiry result `+0x100`.
const WUD_SEARCH_RESULT_EXTRA: usize = 0x803A_3970;
/// `0x803A3E40`: 0x80-byte device-class block whose last 16 bytes are part of
/// the checksum in [fn_801f1720].
const WUD_SEARCH_CLASS: usize = 0x803A_3E40;
/// `0x803A3EC0`: four-byte checksum written at the end of that block.
const WUD_CHECKSUM: usize = 0x803A_3EC0;
/// `0x803A312E`: search/security state byte (`1` = running, `3` = waiting for
/// the link-key callback, `0` = idle).
const BTA_HH_SEARCH_STATE_312E: usize = 0x803A_312E;
/// `r13-0x4B19`: number of inquiry results collected so far (byte).
const SDA_WUD_4B19: usize = SDA_BASE - 0x4B19;
/// `r13-0x4B1A`: last device-class byte from an inquiry result.
const SDA_WUD_4B1A: usize = SDA_BASE - 0x4B1A;
/// `r13-0x4B2C`: "target data load started" byte, written once per state.
const SDA_WUD_4B2C: usize = SDA_BASE - 0x4B2C;
/// `r13-0x4B34`: 32-bit checksum seed (high half = sum, low half = folded sum).
const SDA_WUD_4B34: usize = SDA_BASE - 0x4B34;
/// `0x801F2DD0`: alarm continuation run after the shutdown snapshot.
const WUD_ALARM_CONTINUATION: usize = 0x801F_2DD0;
/// `0x802037CC`: posts one runtime-patch/abort request `(opcode, size, ptr,
/// flag)`. Reused here with opcode `0xFC4C`.
const WUD_SEARCH_ABORT_REQUEST: usize = 0x8020_37CC;
/// `0x803461B8`: parameter block of that request. // unknown: four bytes of
/// data only.
const WUD_PATCH_PARAM: usize = 0x8034_61B8;
/// `0x802036C8`: fills the ten-byte local version block (`hci_version`,
/// `hci_revision`, `lmp_version`, `lmp_subversion`, `manufacturer`).
const BTM_LOCAL_VERSION_INFO: usize = 0x8020_36C8;
/// `0x80203AA4`: starts discovery with a completion callback.
const BTM_DISCOVERY_START_CB: usize = 0x8020_3AA4;
/// `0x801DD940`: non-zero once the Balance Board link is established.
/// // inferred: the same test guards the WBC checksum paths in [fn_801f02f0].
const WUD_BOARD_ACTIVE: usize = 0x801D_D940;
/// `0x80203C4C`: security grant for one address with a completion callback.
/// // inferred: the callback is the stored-link-key event handler
/// [fn_801f5cd0].
const BTM_SECURITY_REQUEST: usize = 0x8020_3C4C;
/// `0x803D1960`: sixteen 0x20-byte HID device blocks; `+0x0E` is the handle
/// and `+0x0F` the "unplugged" byte.
const HID_DEVICE_EVENT_SLOTS: usize = 0x803D_1960;
/// `0x803A3184` / `0x803A3134`: heads of the ten-slot and six-slot in-use
/// link lists (node `+0` = device, `+8` = next).
const WUD_LINK_LIST_10: usize = 0x803A_3184;
const WUD_LINK_LIST_6: usize = 0x803A_3134;
/// `0x803A5081`: second link-key table (six 0x56-byte records).
const WUD_KEY_TABLE_2: usize = 0x803A_5081;
/// The ten `HID_HDEV_EVT_*` trace strings printed by [fn_801ff308].
const MSG_HID_EVT_OPEN: usize = 0x8034_7B24;
const MSG_HID_EVT_CLOSE: usize = 0x8034_7B38;
const MSG_HID_EVT_RETRYING: usize = 0x8034_7B4C;
const MSG_HID_EVT_INTR_DATA: usize = 0x8034_7B64;
const MSG_HID_EVT_INTR_DATC: usize = 0x8034_7B7C;
const MSG_HID_EVT_CTRL_DATA: usize = 0x8034_7B94;
const MSG_HID_EVT_CTRL_DATC: usize = 0x8034_7BAC;
const MSG_HID_EVT_HANDSHAKE: usize = 0x8034_7BC4;
const MSG_HID_EVT_VC_UNPLUG: usize = 0x8034_7BDC;
const MSG_HID_EVT_UNKNOWN: usize = 0x8034_7BF4;
