/// `0x803A1FD4`: base of the four `0x578`-byte KPAD per-channel blocks.
const KPAD_CHANNEL_BASE: usize = 0x803A_1FD4;
/// One KPAD per-channel block; `0x803A254C` is the second block.
const KPAD_CHANNEL_STRIDE: usize = 0x578;
/// `0x803A1C04`: sixteen `0x38`-byte status records per channel (the block
/// begins `0x3D0` bytes later). The record status byte is at `+0x29`.
const KPAD_STATUS_SLOTS: usize = 0x803A_1C04;
const KPAD_STATUS_STRIDE: usize = 0x38;
/// `0x803A1F84` / `0x803A1F88`: per-channel pointer and count of the variable
/// status-record bank (`+0x29` of each record is the posted status byte).
const KPAD_EXTRA_SLOTS: usize = 0x803A_1F84;
const KPAD_EXTRA_COUNT: usize = 0x803A_1F88;
/// `0x803A30D8`..`0x803A3110`: eight 64-bit filter values shared by channel 3
/// and the classic-controller path. // unknown: what each filter stage holds.
const KPAD_FILTER_CH3: usize = 0x803A_30D8;

/// `r2-0x4D38`: the constant `0.0f`.
const SDA2_F32_4D38: usize = SDA2_BASE - 0x4D38;
/// `r2-0x4D2C`: the constant `1.0f`.
const SDA2_F32_4D2C: usize = SDA2_BASE - 0x4D2C;
const SDA2_F32_4D30: usize = SDA2_BASE - 0x4D30;
const SDA2_F32_4D28: usize = SDA2_BASE - 0x4D28;
const SDA2_F32_4D24: usize = SDA2_BASE - 0x4D24;
/// `r2-0x4D20`: upper magnitude bound used by the aim filters.
const SDA2_F32_4D20: usize = SDA2_BASE - 0x4D20;
/// `r2-0x4D00`: the 8-byte zero pattern copied into the channel-3 filters.
const SDA2_F64_4D00: usize = SDA2_BASE - 0x4D00;

const SDA_KPAD_4B64: usize = SDA_BASE - 0x4B64;
const SDA_KPAD_4B68: usize = SDA_BASE - 0x4B68;
const SDA_KPAD_4B7C: usize = SDA_BASE - 0x4B7C;
const SDA_KPAD_4B80: usize = SDA_BASE - 0x4B80;
const SDA_KPAD_5DF8: usize = SDA_BASE - 0x5DF8;
const SDA_KPAD_5DFC: usize = SDA_BASE - 0x5DFC;
const SDA_KPAD_5E18: usize = SDA_BASE - 0x5E18;
const SDA_KPAD_5E24: usize = SDA_BASE - 0x5E24;
const SDA_KPAD_5E28: usize = SDA_BASE - 0x5E28;
const SDA_KPAD_5E2C: usize = SDA_BASE - 0x5E2C;
const SDA_KPAD_5E30: usize = SDA_BASE - 0x5E30;
const SDA_KPAD_5E34: usize = SDA_BASE - 0x5E34;
const SDA_KPAD_5E38: usize = SDA_BASE - 0x5E38;
const SDA_KPAD_5E3C: usize = SDA_BASE - 0x5E3C;
const SDA_KPAD_5E40: usize = SDA_BASE - 0x5E40;
const SDA_KPAD_5E44: usize = SDA_BASE - 0x5E44;
/// `r13-0x4B6A`..`r13-0x4B70`: the five classic-controller extension check
/// bytes and the sixteen-bit repeat counter next to them.
const SDA_KPAD_4B6A: usize = SDA_BASE - 0x4B6A;
const SDA_KPAD_4B6B: usize = SDA_BASE - 0x4B6B;
const SDA_KPAD_4B6C: usize = SDA_BASE - 0x4B6C;
const SDA_KPAD_4B6D: usize = SDA_BASE - 0x4B6D;
const SDA_KPAD_4B6E: usize = SDA_BASE - 0x4B6E;
const SDA_KPAD_4B70: usize = SDA_BASE - 0x4B70;

/// `0x802E8620`: single-precision square root (`f64` in/out).
const KPAD_SQRT_802E8620: usize = 0x802E_8620;
/// `0x801AC440`: invalidates a data-cache range (`dcbi` loop).
const DC_INVALIDATE_RANGE: usize = 0x801A_C440;
/// `0x801AC470`: flushes and syncs a data-cache range (`dcbf` + `sync`).
const DC_FLUSH_RANGE: usize = 0x801A_C470;
/// `0x801C1160`: rotates the two classic-controller axes in place.
/// // inferred: three-pointer call shape and the `0x803A30A8` basis block.
const KPAD_ROTATE_2D: usize = 0x801C_1160;

/// Calls a PowerPC routine with eight integer arguments.
///
/// [`crate::platform`] stops at [`crate::platform::call7`]; the IOS control
/// message wrappers below forward eight values.
///
/// # Safety
/// `addr` must accept the eight-argument `u32` ABI.
unsafe fn call8(
    addr: usize,
    a: u32,
    b: u32,
    c: u32,
    d: u32,
    e: u32,
    f: u32,
    g: u32,
    h: u32,
) -> u32 {
    let func = crate::platform::guest_fn!(addr, fn(u32, u32, u32, u32, u32, u32, u32, u32) -> u32);
    func(a, b, c, d, e, f, g, h)
}

/// Writes a value into the KPAD "initialised" word.
///
/// # Original
/// - Ghidra: `FUN_801e5450` at `0x801E5450` (8 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801e5450_FUN_801e5450.c`
///
/// # Arguments
/// * `value` - word stored at `r13-0x4BD8` (the KPAD init/ready flag).
///
/// # Returns
/// `()`.
///
/// # Side effects
/// One word store.
///
/// # Safety
/// None; the target is a fixed small-data word.
///
/// # Confidence
/// high - the single store is the whole body.
pub unsafe fn fn_801e5450(value: u32) {
    platform::write_u32(SDA_KPAD_INITIALISED, value);
}

/// Resets the stick, trigger and pointer limits of one KPAD channel block.
///
/// Everything the filter stages read is re-seeded here: the four pointer
/// bounds (`+0x528`..`+0x534`), the two pointer scale/ratio words, the
/// magnitude limit and the per-sample gain. The three input axes, both
/// 16-bit timers (`+0x500`, `+0x508`), the press flags and the six status
/// records are then cleared or copied from their idle sources, and the
/// sixteen `+0x29` status bytes of the fixed record bank are set to `0xFF`.
///
/// # Original
/// - Ghidra: `FUN_801ea9c0` at `0x801EA9C0` (464 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801ea9c0_FUN_801ea9c0.c`
///
/// # Arguments
/// * `block` - one of the four `0x578`-byte channel blocks.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// About seventy word stores, two 16-bit stores, four `0xFF` status bytes in
/// the fixed bank and one `0xFF` status byte pair at `+0x128`/`+0x134`.
///
/// # Safety
/// `block` must be the base of a live channel block.
///
/// # Confidence
/// high - every store and both clear loops are literal; the `r2`/`r13` words
/// are read from their original small-data addresses, so their numeric values
/// stay in the image rather than in this file.
pub unsafe fn fn_801ea9c0(block: usize) {
    let c_4d30 = platform::read_f32(SDA2_F32_4D30);
    let c_4d2c = platform::read_f32(SDA2_F32_4D2C);
    let c_4d28 = platform::read_f32(SDA2_F32_4D28);
    let c_4d24 = platform::read_f32(SDA2_F32_4D24);
    let sample = platform::read_f32(block + 0xD0);
    let zero_word = platform::read_u32(SDA2_F32_4D38);
    let s_5e34 = platform::read_f32(SDA_KPAD_5E34);
    let s_5e2c = platform::read_f32(SDA_KPAD_5E2C);
    let s_5e40 = platform::read_f32(SDA_KPAD_5E40);

    platform::write_u8(block + 0x554, 0);
    platform::write_f32(block + 0x528, c_4d30 + s_5e34);
    platform::write_f32(block + 0x530, c_4d2c - s_5e34);
    platform::write_f32(block + 0x52C, c_4d28 + s_5e34);
    platform::write_f32(block + 0x534, c_4d24 - s_5e34);
    platform::write_f32(block + 0x538, c_4d2c / s_5e2c);
    platform::write_f32(block + 0x53C, c_4d30 / s_5e2c);
    platform::write_f32(block + 0x540, s_5e40 * s_5e40);
    platform::write_u32(block + 0x548, platform::read_u32(SDA_KPAD_4B64));
    let mut gain = platform::read_f32(SDA_KPAD_4B68);
    platform::write_f32(block + 0x544, gain);
    gain /= sample;

    platform::write_u32(block + 8, 0);
    platform::write_u32(block + 4, 0);
    platform::write_u32(block, 0);
    platform::write_u16(block + 0x500, 0);
    platform::write_u16(block + 0x502, platform::read_u16(block + 0x504));
    platform::write_u8(block + 0x5E, 0);
    platform::write_u8(block + 0x4FE, 0);

    let word_4b80 = platform::read_u32(SDA_KPAD_4B80);
    let word_4b7c = platform::read_u32(SDA_KPAD_4B7C);

    platform::write_u32(block + 0x2C, word_4b7c);
    platform::write_f32(block + 0x4EC, c_4d2c);
    platform::write_u32(block + 0x4F0, zero_word);
    platform::write_u32(block + 0x28, word_4b80);
    platform::write_u32(block + 0x20, word_4b80);
    platform::write_u32(block + 0x24, word_4b7c);
    platform::write_u32(block + 0x30, zero_word);
    platform::write_f32(block + 0x4E4, c_4d2c);
    platform::write_f32(block + 0x34, c_4d2c);
    platform::write_u32(block + 0x4E8, zero_word);
    platform::write_u32(block + 0x38, zero_word);
    platform::write_u32(block + 0x40, word_4b7c);
    platform::write_u32(block + 0x14, zero_word);
    platform::write_u32(block + 0xC, zero_word);
    platform::write_f32(block + 0x10, c_4d30);
    platform::write_u32(block + 0x3C, word_4b80);
    platform::write_u32(block + 0x44, zero_word);
    platform::write_f32(block + 0x54, c_4d2c);
    platform::write_u32(block + 0x58, zero_word);
    platform::write_f32(block + 0x48, sample);
    platform::write_u32(block + 0x50, zero_word);
    platform::write_u32(block + 0x4C, zero_word);
    platform::write_f32(block + 0x4D0, sample);
    platform::write_f32(block + 0x4D4, gain);
    platform::write_f32(block + 0x4C4, gain);
    platform::write_f32(block + 0x4C8, platform::read_f32(block + 0xDC));
    platform::write_f32(block + 0x4CC, platform::read_f32(block + 0xE0));
    platform::write_f32(block + 0x18, c_4d2c);
    platform::write_u32(block + 0x1C, zero_word);
    platform::write_f32(block + 0x4D8, platform::read_f32(block + 0xC));
    platform::write_f32(block + 0x4DC, platform::read_f32(block + 0x10));
    platform::write_f32(block + 0x4E0, platform::read_f32(block + 0x14));
    platform::write_u32(block + 0x4F4, platform::read_u32(block + 0x4EC));
    platform::write_u32(block + 0x4F8, platform::read_u32(block + 0x4F0));
    platform::write_u16(block + 0x4FC, platform::read_u16(SDA_KPAD_5E38));
    platform::write_u16(block + 0x138, 0);

    // observed: the four `pfVar7[2]` status bytes of the fixed bank.
    let mut cursor = block + 0x114;
    while cursor >= block + 0xF0 {
        platform::write_u8(cursor + 8, 0xFF);
        cursor -= 0xC;
    }
    // observed: the two `pfVar7[2]` status bytes of the two-point bank.
    cursor = block + 0x12C;
    while cursor >= block + 0x120 {
        platform::write_u8(cursor + 8, 0xFF);
        cursor -= 0xC;
    }

    platform::write_u8(block + 0x13B, 0);
    platform::write_u8(block + 0x555, 1);
}

/// Advances the two 16-bit press/repeat timers of one channel block.
///
/// Each half of the function drives one timer pair. The "active" flag word at
/// `+0`/`+0x60` accumulates `0x80000000` whenever the timer passes the next
/// threshold; the timer and its threshold are then advanced by one tick and
/// one period word respectively, wrapping modulo 40000 and 20000. When the
/// matching press flags are non-zero the counters are reset to `0` and to the
/// stored start values instead.
///
/// # Original
/// - Ghidra: `FUN_801eab90` at `0x801EAB90` (416 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801eab90_FUN_801eab90.c`
///
/// # Arguments
/// * `block` - one of the four `0x578`-byte channel blocks.
/// * `mode` - button-source selector; the second timer pair only runs for
///   `2`, `0x10` and `0x11`.
/// * `delta` - tick increment added to the active timer.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// Up to six 16-bit stores and two flag-word read/modify/writes.
///
/// # Safety
/// `block` must be a live channel block.
///
/// # Confidence
/// high - the two timer machines are literal; `0x63C0`/`0xB1E0` are the
/// 16-bit two's complements of 40000 and 20000.
pub unsafe fn fn_801eab90(block: usize, mode: i32, delta: i32) {
    if platform::read_u32(block + 4) == 0 && platform::read_u32(block + 8) == 0 {
        if platform::read_u32(block) != 0 {
            let mut value = platform::read_u16(block + 0x500)
                .wrapping_add(delta as i16 as u16);
            platform::write_u16(block + 0x500, value);
            if value > 39999 {
                value = value.wrapping_add(0x63C0);
                platform::write_u16(block + 0x500, value);
            }
            let value = platform::read_u16(block + 0x500);
            if platform::read_u16(block + 0x502) <= value {
                let flags = platform::read_u32(block);
                platform::write_u32(block, flags | 0x8000_0000);
                let next = platform::read_u16(block + 0x502)
                    .wrapping_add(platform::read_u16(block + 0x506));
                platform::write_u16(block + 0x502, next);
                if value > 19999 {
                    platform::write_u16(block + 0x500, value.wrapping_add(0xB1E0));
                    platform::write_u16(block + 0x502, next.wrapping_sub(20000));
                }
            }
        }
    } else {
        platform::write_u16(block + 0x500, 0);
        platform::write_u16(block + 0x502, platform::read_u16(block + 0x504));
        if platform::read_u32(block + 4) != 0 && platform::read_u16(block + 0x506) != 0 {
            let flags = platform::read_u32(block);
            platform::write_u32(block, flags | 0x8000_0000);
        }
    }

    if mode != 2 && (mode as u32).wrapping_sub(0x10) > 1 {
        return;
    }

    if platform::read_u32(block + 0x64) == 0 && platform::read_u32(block + 0x68) == 0 {
        if platform::read_u32(block + 0x60) == 0 {
            return;
        }
        let mut value = platform::read_u16(block + 0x508)
            .wrapping_add(delta as i16 as u16);
        platform::write_u16(block + 0x508, value);
        if value > 39999 {
            value = value.wrapping_add(0x63C0);
            platform::write_u16(block + 0x508, value);
        }
        let value = platform::read_u16(block + 0x508);
        if value < platform::read_u16(block + 0x50A) {
            return;
        }
        let flags = platform::read_u32(block + 0x60);
        platform::write_u32(block + 0x60, flags | 0x8000_0000);
        let next = platform::read_u16(block + 0x50A)
            .wrapping_add(platform::read_u16(block + 0x506));
        platform::write_u16(block + 0x50A, next);
        if value < 20000 {
            return;
        }
        platform::write_u16(block + 0x508, value.wrapping_add(0xB1E0));
        platform::write_u16(block + 0x50A, next.wrapping_sub(20000));
        return;
    }

    platform::write_u16(block + 0x508, 0);
    platform::write_u16(block + 0x50A, platform::read_u16(block + 0x504));
    if platform::read_u32(block + 0x64) == 0 {
        return;
    }
    if platform::read_u16(block + 0x506) == 0 {
        return;
    }
    let flags = platform::read_u32(block + 0x60);
    platform::write_u32(block + 0x60, flags | 0x8000_0000);
}

/// Stores one button word and derives the pressed/released edges.
///
/// The core word is `buttons & 0x9FFF`; for mode `1` the `0x6000` bits are
/// taken from `extra` only while the block's `+0x555` byte is clear. The two
/// edge words (`+4`, `+8`) are `changed & new` and `changed & old` over the
/// low sixteen bits. Modes `2`, `0x10` and `0x11` do the same for the
/// `+0x60` extension word from `buttons2`. The timer step is then called.
///
/// # Original
/// - Ghidra: `FUN_801ead30` at `0x801EAD30` (160 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801ead30_FUN_801ead30.c`
///
/// # Arguments
/// * `block` - one of the four `0x578`-byte channel blocks.
/// * `mode` - button-source selector.
/// * `delta` - tick increment forwarded to [`fn_801eab90`].
/// * `buttons` - core remote button bits.
/// * `extra` - `0x6000`-bit source used by mode `1`.
/// * `buttons2` - extension button bits.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// Six word stores and one [`fn_801eab90`] call.
///
/// # Safety
/// `block` must be a live channel block.
///
/// # Confidence
/// medium - the masks, the `+0x555` gate and the edge arithmetic are literal;
/// the timer call is passed `(block, mode, delta)`, which the export leaves
/// implicit because the callee prototype is unknown.
pub unsafe fn fn_801ead30(
    block: usize,
    mode: i32,
    delta: u32,
    buttons: u32,
    extra: u32,
    buttons2: u32,
) {
    let previous = platform::read_u32(block);
    // observed: `(b == 0) ? 0xFFFFFFFF : 0` fold of the `+0x555` byte.
    let gate = if platform::read_u8(block + 0x555) == 0 {
        0xFFFF_FFFF
    } else {
        0
    };

    let mut value = buttons & 0x9FFF;
    if mode == 1 {
        value |= extra & gate & 0x6000;
    }
    platform::write_u32(block, value);

    let changed = value ^ (previous & 0xFFFF);
    platform::write_u32(block + 4, changed & value);
    platform::write_u32(block + 8, changed & previous & 0xFFFF);

    if mode == 2 || (mode as u32).wrapping_sub(0x10) < 2 {
        let old = platform::read_u32(block + 0x60);
        let hidden = buttons2 & gate & 0xFFFF;
        platform::write_u32(block + 0x60, hidden);
        let diff = hidden ^ (old & 0xFFFF);
        platform::write_u32(block + 0x64, hidden & diff);
        platform::write_u32(block + 0x68, old & 0xFFFF & diff);
    }

    fn_801eab90(block, mode, delta as i32);
}

/// Pulls one filtered axis toward a new sample.
///
/// With `+0x56C` clear the gain follows a fourth-power curve below the
/// radius at `+0xC8` and is `1.0` outside it, so small movements are
/// smoothed and large ones pass through. With `+0x56C` set the sample is
/// simply clamped to `±radius` around the stored value.
///
/// # Original
/// - Ghidra: `FUN_801eadd0` at `0x801EADD0` (180 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801eadd0_FUN_801eadd0.c`
///
/// # Arguments
/// * `sample` - new axis value (arrives in `f1`).
/// * `block` - one of the four `0x578`-byte channel blocks.
/// * `value` - address of the filtered axis word.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// One word store at `*value`.
///
/// # Safety
/// `value` must be a writable `f32` inside `block`.
///
/// # Confidence
/// high - the curve, the clamp and the two gain words are literal.
pub unsafe fn fn_801eadd0(sample: f64, block: usize, value: usize) {
    let previous = platform::read_f32(value) as f64;
    let delta = (sample - previous) as f32;
    let radius = platform::read_f32(block + 0xC8);

    if platform::read_u32(block + 0x56C) == 0 {
        let mut magnitude = delta;
        if delta < platform::read_f32(SDA2_F32_4D38) {
            magnitude = -delta;
        }
        let gain = if magnitude < radius {
            let ratio = magnitude / radius;
            ratio * ratio * ratio * ratio
        } else {
            platform::read_f32(SDA2_F32_4D2C)
        };
        let current = platform::read_f32(value);
        platform::write_f32(
            value,
            current + gain * platform::read_f32(block + 0xCC) * delta,
        );
        return;
    }

    let gain = platform::read_f32(block + 0xCC);
    if -radius <= delta {
        if radius < delta {
            platform::write_f32(value, (previous + (gain * (delta - radius)) as f64) as f32);
        }
        return;
    }
    platform::write_f32(value, (previous + (gain * (delta + radius)) as f64) as f32);
}

/// Rotates the raw acceleration vector into the body frame.
///
/// Both the horizontal magnitude and the magnitude of the rotated vector are
/// normalised, then blended into the two stored direction words with a weight
/// that grows quadratically outside `1.0` and saturates at the `r2-0x4D20`
/// limit. The `+0x4F4`/`+0x4F8` smoothed copies are updated separately and the
/// residual decides whether the `+0x4FC` hold counter is reloaded or
/// decremented.
///
/// # Original
/// - Ghidra: `FUN_801eae90` at `0x801EAE90` (404 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801eae90_FUN_801eae90.c`
///
/// # Arguments
/// * `block` - one of the four `0x578`-byte channel blocks.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// Six float stores and one 16-bit counter update.
///
/// # Safety
/// `block` must be a live channel block.
///
/// # Confidence
/// medium - the two normalisations and the blend are literal; the two
/// `r13-0x5E44`/`r13-0x5E3C` gain words and the hold counter's unit are read
/// from the image and their meaning is not proven.
pub unsafe fn fn_801eae90(block: usize) {
    let x = platform::read_f32(block + 0x4D8);
    let y = platform::read_f32(block + 0x4DC);
    let length = call_f64_1(KPAD_SQRT_802E8620, (x * x + y * y) as f64) as f32;
    let zero = platform::read_f32(SDA2_F32_4D38);
    if length == zero || length >= platform::read_f32(SDA2_F32_4D20) {
        return;
    }

    let unit_x = x / length;
    let unit_y = y / length;
    let mut weight = length;
    if platform::read_f32(SDA2_F32_4D2C) < length {
        weight = platform::read_f32(SDA2_F32_4D20) - length;
    }
    weight = weight * weight * platform::read_f32(SDA_KPAD_5E44);

    let target_x = platform::read_f32(block + 0xD4) * unit_x
        + platform::read_f32(block + 0xD8) * unit_y;
    let target_y = platform::read_f32(block + 0xD8) * unit_x
        - platform::read_f32(block + 0xD4) * unit_y;
    let blended_x = platform::read_f32(block + 0x4EC)
        + weight * (target_x - platform::read_f32(block + 0x4EC));
    let blended_y = platform::read_f32(block + 0x4F0)
        + weight * (target_y - platform::read_f32(block + 0x4F0));

    let length2 = call_f64_1(
        KPAD_SQRT_802E8620,
        (blended_x * blended_x + blended_y * blended_y) as f64,
    ) as f32;
    if length2 == zero {
        return;
    }

    let dir_x = blended_x / length2;
    let dir_y = blended_y / length2;
    platform::write_f32(block + 0x4EC, dir_x);
    platform::write_f32(block + 0x4F0, dir_y);

    let smooth_x = platform::read_f32(block + 0x4F4)
        + platform::read_f32(SDA_KPAD_5E3C) * (dir_x - platform::read_f32(block + 0x4F4));
    platform::write_f32(block + 0x4F4, smooth_x);
    let smooth_y = platform::read_f32(block + 0x4F8)
        + platform::read_f32(SDA_KPAD_5E3C) * (dir_y - platform::read_f32(block + 0x4F8));
    platform::write_f32(block + 0x4F8, smooth_y);

    let residual_x = dir_x - smooth_x;
    let residual_y = dir_y - smooth_y;
    if platform::read_f32(block + 0x540) < residual_x * residual_x + residual_y * residual_y {
        platform::write_u16(block + 0x4FC, platform::read_u16(SDA_KPAD_5E38));
    } else if platform::read_u16(block + 0x4FC) != 0 {
        let hold = platform::read_u16(block + 0x4FC) - 1;
        platform::write_u16(block + 0x4FC, hold);
    }
}

/// Normalises the three-axis sample into the body-frame direction words.
///
/// The raw vector is normalised, blended toward the stored direction with the
/// same quadratic weight as [`fn_801eae90`], then normalised again before it is
/// written to `+0x54`/`+0x58`.
///
/// # Original
/// - Ghidra: `FUN_801eb030` at `0x801EB030` (292 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801eb030_FUN_801eb030.c`
///
/// # Arguments
/// * `block` - one of the four `0x578`-byte channel blocks.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// Two float stores.
///
/// # Safety
/// `block` must be a live channel block.
///
/// # Confidence
/// medium - the arithmetic is literal; the two gains come from the image.
pub unsafe fn fn_801eb030(block: usize) {
    let x = platform::read_f32(block + 0x4D8);
    let y = platform::read_f32(block + 0x4DC);
    let z = platform::read_f32(block + 0x4E0);
    let zero = platform::read_f32(SDA2_F32_4D38);
    let one = platform::read_f32(SDA2_F32_4D2C);
    let limit = platform::read_f32(SDA2_F32_4D20);

    let horizontal = (x * x + y * y) as f64;
    let flat = call_f64_1(KPAD_SQRT_802E8620, horizontal) as f32;
    let length = call_f64_1(KPAD_SQRT_802E8620, (horizontal + (z * z) as f64) as f32 as f64) as f32;
    if length == zero || length >= limit {
        return;
    }

    let unit_x = flat / length;
    let unit_y = -z / length;
    let mut weight = length;
    if one < length {
        weight = limit - length;
    }
    let weight = weight * (weight * platform::read_f32(SDA_KPAD_5E44));

    let blended_x =
        platform::read_f32(block + 0x54) + weight * (unit_x - platform::read_f32(block + 0x54));
    let blended_y =
        platform::read_f32(block + 0x58) + weight * (unit_y - platform::read_f32(block + 0x58));

    let length2 = call_f64_1(
        KPAD_SQRT_802E8620,
        (blended_x * blended_x + blended_y * blended_y) as f64,
    ) as f32;
    if length2 == zero {
        return;
    }
    platform::write_f32(block + 0x54, blended_x / length2);
    platform::write_f32(block + 0x58, blended_y / length2);
}

/// Decodes one extension sample into the three filtered axis words.
///
/// The sample kind selects which report fields are read: kinds `1`/`2`, `4`/`5`
/// and `7`/`8` use the `+2`/`+4`/`+6` halfwords with the `+0x510`/`+0x514`/
/// `+0x518` scales. The two horizontal axes are inverted and clamped to the
/// `r13-0x5DFC` limit before [`fn_801eadd0`] smooths them into `+0xC`/`+0x10`/
/// `+0x14`; the resulting magnitude and the magnitude of the change are stored
/// at `+0x18`/`+0x1C`. Kinds `4`/`5` then decode the `+0x2A`/`+0x2C`/`+0x2E`
/// control-stick triplet into `+0x68`/`+0x6C`/`+0x70`, optionally rotating it
/// through `0x801C1160`, and store the two magnitudes at `+0x74`/`+0x78`.
///
/// # Original
/// - Ghidra: `FUN_801eb160` at `0x801EB160` (1,120 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801eb160_FUN_801eb160.c`
///
/// # Arguments
/// * `block` - one of the four `0x578`-byte channel blocks.
/// * `report` - extension report whose `+0x36` byte selects the sample kind.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// Up to eight float stores and three smoothing calls; one `0x801C1160`
/// rotation when the block's `+0x55E` byte is set.
///
/// # Safety
/// `report` must be readable through `+0x36`; `block` must be live.
///
/// # Confidence
/// medium - every field offset and the kind gate are literal; the three scale
/// words and the `r13-0x5DF8`/`r13-0x5DFC` clamps are read from the image and
/// the `0x801C1160` rotation's meaning is inferred from its three pointers.
pub unsafe fn fn_801eb160(block: usize, report: usize) {
    let kind = platform::read_u8(report + 0x36) as u32;
    // observed: kinds 1, 2, 4, 5, 7, 8 and 0x0B carry a usable sample.
    if !(kind.wrapping_sub(1) <= 1
        || kind.wrapping_sub(4) <= 1
        || kind.wrapping_sub(7) <= 1
        || kind == 0xB)
    {
        return;
    }

    let zero = platform::read_f32(SDA2_F32_4D38);
    let clamp_1 = platform::read_f32(SDA_KPAD_5DFC);

    let mut axis_0 = -(platform::read_u16(report + 2) as i16 as i32) as f32
        * platform::read_f32(block + 0x510);
    let mut value = clamp_1;
    if zero <= axis_0 {
        if axis_0 <= value {
            value = axis_0;
        }
    } else {
        value = -value;
        if value <= axis_0 {
            value = axis_0;
        }
    }
    axis_0 = value;

    let mut axis_1 = -(platform::read_u16(report + 6) as i16 as i32) as f32
        * platform::read_f32(block + 0x518);
    value = clamp_1;
    if zero <= axis_1 {
        if axis_1 <= value {
            value = axis_1;
        }
    } else {
        value = -value;
        if value <= axis_1 {
            value = axis_1;
        }
    }
    axis_1 = value;

    let mut axis_2 = (platform::read_u16(report + 4) as i16 as i32) as f32
        * platform::read_f32(block + 0x514);
    value = clamp_1;
    if zero <= axis_2 {
        if axis_2 <= value {
            value = axis_2;
        }
    } else {
        value = -value;
        if value <= axis_2 {
            value = axis_2;
        }
    }
    axis_2 = value;

    platform::write_f32(block + 0x4D8, axis_0);
    platform::write_f32(block + 0x4DC, axis_1);
    platform::write_f32(block + 0x4E0, axis_2);

    let old_x = platform::read_f32(block + 0xC);
    let old_y = platform::read_f32(block + 0x10);
    let old_z = platform::read_f32(block + 0x14);
    fn_801eadd0(axis_0 as f64, block, block + 0xC);
    fn_801eadd0(axis_1 as f64, block, block + 0x10);
    fn_801eadd0(axis_2 as f64, block, block + 0x14);

    let magnitude = call_f64_1(
        KPAD_SQRT_802E8620,
        (platform::read_f32(block + 0x14) * platform::read_f32(block + 0x14)
            + platform::read_f32(block + 0xC) * platform::read_f32(block + 0xC)
            + platform::read_f32(block + 0x10) * platform::read_f32(block + 0x10)) as f64,
    ) as f32;
    let delta_x = old_x - platform::read_f32(block + 0xC);
    let delta_y = old_y - platform::read_f32(block + 0x10);
    let delta_z = old_z - platform::read_f32(block + 0x14);
    platform::write_f32(block + 0x18, magnitude);
    let change = call_f64_1(
        KPAD_SQRT_802E8620,
        (delta_z * delta_z + delta_x * delta_x + delta_y * delta_y) as f64,
    ) as f32;
    platform::write_f32(block + 0x1C, change);

    fn_801eae90(block);
    fn_801eb030(block);

    if platform::read_u8(report + 0x29) != 0 {
        return;
    }
    if platform::read_u8(report + 0x28) != 1 {
        return;
    }
    if kind != 4 && kind != 5 {
        return;
    }

    let clamp_2 = platform::read_f32(SDA_KPAD_5DF8);
    let mut stick_0 = crate::platform::GuestLocal::new( -(platform::read_u16(report + 0x2A) as i16 as i32) as f32
        * platform::read_f32(block + 0x51C));
    value = clamp_2;
    if zero <= *stick_0 {
        if *stick_0 <= value {
            value = *stick_0;
        }
    } else {
        value = -value;
        if value <= *stick_0 {
            value = *stick_0;
        }
    }
    *stick_0 = value;

    let mut stick_1 = -(platform::read_u16(report + 0x2E) as i16 as i32) as f32
        * platform::read_f32(block + 0x524);
    value = clamp_2;
    if zero <= stick_1 {
        if stick_1 <= value {
            value = stick_1;
        }
    } else {
        value = -value;
        if value <= stick_1 {
            value = stick_1;
        }
    }
    stick_1 = value;

    let mut stick_2 = (platform::read_u16(report + 0x2C) as i16 as i32) as f32
        * platform::read_f32(block + 0x520);
    value = clamp_2;
    if zero <= stick_2 {
        if value < stick_2 {
            stick_2 = value;
        }
    } else {
        value = -value;
        if stick_2 < value {
            stick_2 = value;
        }
    }

    if platform::read_u8(block + 0x55E) != 0 {
        platform::call3(
            KPAD_ROTATE_2D,
            0x803A_30A8,
            (stick_0.as_ptr() as *const f32) as usize as u32,
            (stick_0.as_ptr() as *const f32) as usize as u32,
        );
    }

    let old_stick_x = platform::read_f32(block + 0x68);
    let old_stick_y = platform::read_f32(block + 0x6C);
    let old_stick_z = platform::read_f32(block + 0x70);
    fn_801eadd0(*stick_0 as f64, block, block + 0x68);
    fn_801eadd0(stick_1 as f64, block, block + 0x6C);
    fn_801eadd0(stick_2 as f64, block, block + 0x70);

    let stick_length = call_f64_1(
        KPAD_SQRT_802E8620,
        (platform::read_f32(block + 0x70) * platform::read_f32(block + 0x70)
            + platform::read_f32(block + 0x68) * platform::read_f32(block + 0x68)
            + platform::read_f32(block + 0x6C) * platform::read_f32(block + 0x6C)) as f64,
    ) as f32;
    let stick_dx = old_stick_x - platform::read_f32(block + 0x68);
    let stick_dy = old_stick_y - platform::read_f32(block + 0x6C);
    let stick_dz = old_stick_z - platform::read_f32(block + 0x70);
    platform::write_f32(block + 0x74, stick_length);
    let stick_change = call_f64_1(
        KPAD_SQRT_802E8620,
        (stick_dz * stick_dz + stick_dx * stick_dx + stick_dy * stick_dy) as f64,
    ) as f32;
    platform::write_f32(block + 0x78, stick_change);
}

/// Pairs the four sensor-bar points and stores the best pair as the aim points.
///
/// Every valid pair of the four `0xF0`-based points is scored by the dot
/// product of the normalised pair direction with the stored pointer direction
/// (`+0x4EC`/`+0x4F0`), scaled by `+0x544` and gated by `+0x548` and the
/// `r13-0x5E30` limit. The pair with the largest absolute score is copied into
/// the two aim points at `+0x120` and `+0x12C`.
///
/// # Original
/// - Removed: the modelled `_savegpr_25` prologue call (`0x802DCD6C`) and the `_restgpr_25` epilogue call (`0x802DCDB8`).
///   The save `bl` returns no value; the value it appeared to return is the incoming `r3` (the channel block).
/// - Ghidra: `FUN_801eb5c0` at `0x801EB5C0` (488 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801eb5c0_FUN_801eb5c0.c`
///
/// # Arguments
/// * `block` - the channel block, incoming `r3`.
///
/// # Returns
/// `()`; the result `0`/`2` travels through the `0x802DCDB8` epilogue helper.
///
/// # Side effects
/// Six float stores in the aim-point bank.
///
/// # Safety
/// The block from `0x802DCD6C` must be live.
///
/// # Confidence
/// medium - the pair search, the two comparisons and the six stores are
/// literal; the `0x802DCD6C` word is the established split-return artifact and
/// is read once through [`call0_ret`].
pub unsafe fn fn_801eb5c0(block: usize) {
    let zero = platform::read_f32(SDA2_F32_4D38);
    let one = platform::read_f32(SDA2_F32_4D2C);
    let initial = platform::read_f32(SDA_KPAD_5E28);
    let limit = platform::read_f32(SDA_KPAD_5E30);

    let mut best = initial;
    let mut primary = 0usize;
    let mut secondary = 0usize;

    let mut first = block + 0xF0;
    while first < block + 0x114 {
        if platform::read_u8(first + 8) == 0 {
            let mut second = first + 0xC;
            while second <= block + 0x114 {
                if platform::read_u8(second + 8) == 0 {
                    let dx = platform::read_f32(second) - platform::read_f32(first);
                    let dy = platform::read_f32(second + 4) - platform::read_f32(first + 4);
                    let distance = call_f64_1(KPAD_SQRT_802E8620, (dx * dx + dy * dy) as f64) as f32;
                    let inverse = one / distance;
                    let score = platform::read_f32(block + 0x544) * inverse;
                    if platform::read_f32(block + 0x548) < score && score < limit {
                        let dot = platform::read_f32(block + 0x4EC)
                            * (platform::read_f32(block + 0xDC) * (dx * inverse)
                                + platform::read_f32(block + 0xE0) * (dy * inverse))
                            + platform::read_f32(block + 0x4F0)
                                * (platform::read_f32(block + 0xE0) * (dx * inverse)
                                    - platform::read_f32(block + 0xDC) * (dy * inverse));
                        if dot >= zero {
                            if best < dot {
                                best = dot;
                                primary = first;
                                secondary = second;
                            }
                        } else if best < -dot {
                            best = -dot;
                            primary = second;
                            secondary = first;
                        }
                    }
                }
                second += 0xC;
            }
        }
        first += 0xC;
    }

    let result = if best == initial {
        0
    } else {
        platform::write_f32(block + 0x120, platform::read_f32(primary));
        platform::write_f32(block + 0x124, platform::read_f32(primary + 4));
        platform::write_f32(block + 0x128, platform::read_f32(primary + 8));
        platform::write_f32(block + 0x12C, platform::read_f32(secondary));
        platform::write_f32(block + 0x130, platform::read_f32(secondary + 4));
        platform::write_f32(block + 0x134, platform::read_f32(secondary + 8));
        2
    };
}

/// Pairs the sensor-bar points with the weighted importance of each pair.
///
/// The pair search is the same as [`fn_801eb5c0`], but the score is reduced by
/// the `+0x4D0` bias, scaled by `+0x538` or `+0x53C` depending on the sign, and
/// combined with `(1 - |dot|) / (1 - r13-0x5E24)`. Pairs below that cosine
/// limit are ignored. The winning pair is written to `+0x120`/`+0x12C`.
///
/// # Original
/// - Removed: the modelled `_savegpr_25` prologue call (`0x802DCD6C`) and the `_restgpr_25` epilogue call (`0x802DCDB8`).
///   The save `bl` returns no value; the value it appeared to return is the incoming `r3` (the channel block).
/// - Ghidra: `FUN_801eb7b0` at `0x801EB7B0` (552 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801eb7b0_FUN_801eb7b0.c`
///
/// # Arguments
/// * `block` - the channel block, incoming `r3`.
///
/// # Returns
/// `()`; the result `0`/`2` travels through the `0x802DCDB8` epilogue helper.
///
/// # Side effects
/// Six float stores in the aim-point bank.
///
/// # Safety
/// The block from `0x802DCD6C` must be live.
///
/// # Confidence
/// medium - the search and the two comparison gates are literal; the compound
/// assignment that flips the pair order when the dot product is negative is
/// reconstructed from the `bVar7` flag the export carries through the test.
pub unsafe fn fn_801eb7b0(block: usize) {
    let zero = platform::read_f32(SDA2_F32_4D38);
    let one = platform::read_f32(SDA2_F32_4D2C);
    let limit = platform::read_f32(SDA2_F32_4D20);
    let cosine = platform::read_f32(SDA_KPAD_5E24);
    let window = platform::read_f32(SDA_KPAD_5E30);

    let mut best = limit;
    let mut primary = 0usize;
    let mut secondary = 0usize;

    let mut first = block + 0xF0;
    while first < block + 0x114 {
        if platform::read_u8(first + 8) == 0 {
            let mut second = first + 0xC;
            while second <= block + 0x114 {
                if platform::read_u8(second + 8) == 0 {
                    let dx = platform::read_f32(second) - platform::read_f32(first);
                    let dy = platform::read_f32(second + 4) - platform::read_f32(first + 4);
                    let distance = call_f64_1(KPAD_SQRT_802E8620, (dx * dx + dy * dy) as f64) as f32;
                    let inverse = one / distance;
                    let score = platform::read_f32(block + 0x544) * inverse;
                    if platform::read_f32(block + 0x548) < score && score < window {
                        let bias = score - platform::read_f32(block + 0x4D0);
                        let factor = if bias >= zero {
                            platform::read_f32(block + 0x538)
                        } else {
                            platform::read_f32(block + 0x53C)
                        };
                        let weighted = bias * factor;
                        if weighted < one {
                            let dot = platform::read_f32(block + 0x4C8) * (dx * inverse)
                                + platform::read_f32(block + 0x4CC) * (dy * inverse);
                            let negative = dot < zero;
                            let magnitude = if negative { -dot } else { dot };
                            let candidate = weighted + (one - magnitude) / (one - cosine);
                            if magnitude > cosine && candidate < best {
                                best = candidate;
                                primary = first;
                                secondary = second;
                                if negative {
                                    primary = second;
                                    secondary = first;
                                }
                            }
                        }
                    }
                }
                second += 0xC;
            }
        }
        first += 0xC;
    }

    let result = if best == limit {
        0
    } else {
        platform::write_f32(block + 0x120, platform::read_f32(primary));
        platform::write_f32(block + 0x124, platform::read_f32(primary + 4));
        platform::write_f32(block + 0x128, platform::read_f32(primary + 8));
        platform::write_f32(block + 0x12C, platform::read_f32(secondary));
        platform::write_f32(block + 0x130, platform::read_f32(secondary + 4));
        platform::write_f32(block + 0x134, platform::read_f32(secondary + 8));
        2
    };
}

/// Extrapolates each sensor-bar point and marks the first one on screen.
///
/// For every valid point at `+0xF0` the function builds the point displaced by
/// `(direction) * (+0x4D4)` in both senses and tests both against the screen
/// bounds (`+0x528`/`+0x52C`/`+0x530`/`+0x534`). A pair that straddles a
/// border is stored as the near/far aim points; both cases return `-1`.
///
/// # Original
/// - Ghidra: `FUN_801eb9e0` at `0x801EB9E0` (436 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801eb9e0_FUN_801eb9e0.c`
///
/// # Arguments
/// * `block` - one of the four `0x578`-byte channel blocks.
///
/// # Returns
/// `0xFFFFFFFF` when a border pair was found, `0` otherwise.
///
/// # Side effects
/// Up to eight float stores and four byte stores.
///
/// # Safety
/// `block` must be a live channel block.
///
/// # Confidence
/// medium - the four bounds, the two displacement tests and the stores are
/// literal; the meaning of the `+0x128`/`+0x129` byte pair is unknown.
pub unsafe fn fn_801eb9e0(block: usize) -> u32 {
    let cos = platform::read_f32(block + 0x4EC);
    let sin = platform::read_f32(block + 0x4F0);
    let scale = platform::read_f32(block + 0x4D4);
    let offset_x = (platform::read_f32(block + 0xDC) * cos
        + platform::read_f32(block + 0xE0) * sin)
        * scale;
    let offset_y = (platform::read_f32(block + 0xE0) * cos
        - platform::read_f32(block + 0xDC) * sin)
        * scale;
    let left = platform::read_f32(block + 0x528);
    let top = platform::read_f32(block + 0x52C);
    let right = platform::read_f32(block + 0x530);
    let bottom = platform::read_f32(block + 0x534);

    let mut point = block + 0xF0;
    loop {
        if platform::read_u8(point + 8) == 0 {
            let x_lo = platform::read_f32(point) - offset_x;
            let y_lo = platform::read_f32(point + 4) - offset_y;
            let x_hi = platform::read_f32(point) + offset_x;
            let y_hi = platform::read_f32(point + 4) + offset_y;
            if x_lo <= left || right <= x_lo || y_lo <= top || bottom <= y_lo {
                if left < x_hi && x_hi < right && top < y_hi && y_hi < bottom {
                    platform::write_f32(block + 0x12C, platform::read_f32(point));
                    platform::write_f32(block + 0x130, platform::read_f32(point + 4));
                    platform::write_f32(block + 0x134, platform::read_f32(point + 8));
                    platform::write_f32(block + 0x120, x_lo);
                    platform::write_f32(block + 0x124, y_lo);
                    platform::write_u8(block + 0x128, 0);
                    platform::write_u8(block + 0x129, 0xFF);
                    return 0xFFFF_FFFF;
                }
            } else if x_hi <= left || right <= x_hi || y_hi <= top || bottom <= y_hi {
                platform::write_f32(block + 0x120, platform::read_f32(point));
                platform::write_f32(block + 0x124, platform::read_f32(point + 4));
                platform::write_f32(block + 0x128, platform::read_f32(point + 8));
                platform::write_f32(block + 0x12C, x_hi);
                platform::write_f32(block + 0x130, y_hi);
                platform::write_u8(block + 0x134, 0);
                platform::write_u8(block + 0x135, 0xFF);
                return 0xFFFF_FFFF;
            }
        }
        point += 0xC;
        if point >= block + 0x120 {
            return 0;
        }
    }
}

/// Pairs each aim point with the nearest sensor-bar point.
///
/// For each of the two aim points at `+0x120` with a clear `+8` status byte,
/// the nearest valid point at `+0xF0` within the `r13-0x5E18` radius is copied
/// in, the pointer direction is recomputed into `+0x4C8`/`+0x4CC`, and the
/// partner point is displaced by `(+0x4C4) * direction`. Returns `-1` when the
/// block's `+0x5E` byte is negative, `1` when a pair was stored and `0` when
/// nothing matched.
///
/// # Original
/// - Ghidra: `FUN_801ebba0` at `0x801EBBA0` (372 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801ebba0_FUN_801ebba0.c`
///
/// # Arguments
/// * `block` - one of the four `0x578`-byte channel blocks.
///
/// # Returns
/// `-1`, `0` or `1`.
///
/// # Side effects
/// Up to ten float stores and four byte stores.
///
/// # Safety
/// `block` must be a live channel block.
///
/// # Confidence
/// medium - the nearest-point search and both displacement branches are
/// literal; the `+0x129`/`+0x135` `0xFF` marks have unknown meaning.
pub unsafe fn fn_801ebba0(block: usize) -> u32 {
    let radius = platform::read_f32(SDA_KPAD_5E18);
    let mut best = radius * radius;
    let mut matched_aim = 0usize;
    let mut matched_point = 0usize;

    let mut aim = block + 0x120;
    while aim < block + 0x138 {
        if platform::read_u8(aim + 8) == 0 && platform::read_u8(aim + 9) == 0 {
            let mut point = block + 0xF0;
            while point < block + 0x120 {
                if platform::read_u8(point + 8) == 0 {
                    let dx = platform::read_f32(aim) - platform::read_f32(point);
                    let dy = platform::read_f32(aim + 4) - platform::read_f32(point + 4);
                    let distance = dx * dx + dy * dy;
                    if distance < best {
                        best = distance;
                        matched_aim = aim;
                        matched_point = point;
                    }
                }
                point += 0xC;
            }
        }
        aim += 0xC;
    }

    if best == radius * radius {
        return 0;
    }

    platform::write_f32(matched_aim, platform::read_f32(matched_point));
    platform::write_f32(matched_aim + 4, platform::read_f32(matched_point + 4));
    platform::write_f32(matched_aim + 8, platform::read_f32(matched_point + 8));

    let cos = platform::read_f32(block + 0x4EC);
    let sin = platform::read_f32(block + 0x4F0);
    let dir_x = platform::read_f32(block + 0xDC) * cos + platform::read_f32(block + 0xE0) * sin;
    let dir_y = platform::read_f32(block + 0xE0) * cos - platform::read_f32(block + 0xDC) * sin;
    platform::write_f32(block + 0x4C8, dir_x);
    let offset_x = platform::read_f32(block + 0x4C4) * dir_x;
    let offset_y = platform::read_f32(block + 0x4C4) * dir_y;
    platform::write_f32(block + 0x4CC, dir_y);

    if matched_aim == block + 0x120 {
        platform::write_f32(block + 0x12C, platform::read_f32(matched_aim) + offset_x);
        platform::write_f32(block + 0x130, platform::read_f32(matched_aim + 4) + offset_y);
        platform::write_u8(block + 0x134, 0);
        platform::write_u8(block + 0x135, 0xFF);
    } else {
        platform::write_f32(block + 0x120, platform::read_f32(matched_aim) - offset_x);
        platform::write_f32(block + 0x124, platform::read_f32(matched_aim + 4) - offset_y);
        platform::write_u8(block + 0x128, 0);
        platform::write_u8(block + 0x129, 0xFF);
    }

    if (platform::read_u8(block + 0x5E) as i8) < 0 {
        return 0xFFFF_FFFF;
    }
    1
}

/// Maps one signed axis sample to `-1..=1` with a dead zone.
///
/// # Original
/// - Ghidra: inlined twice in `FUN_801ec8a0` at `0x801EC8A0`
/// - Evidence: `work/ghidra/main-gb/export/801ec8a0_FUN_801ec8a0.c`
///
/// # Arguments
/// * `value` - signed sample.
/// * `deadzone` - samples with `|value| <= deadzone` map to `0`.
/// * `limit` - samples with `|value| >= limit` map to `±1`.
///
/// # Returns
/// The normalised axis value.
///
/// # Safety
/// None; pure arithmetic.
///
/// # Confidence
/// medium - the two branches and the `limit - deadzone` divisor are literal;
/// the export spells the conversions as `0x43300000` bias folds.
fn kpad_axis_deadzone(value: i32, deadzone: i32, limit: i32) -> f32 {
    if value < 0 {
        let magnitude = -value;
        let mapped = if deadzone < magnitude {
            if magnitude < limit {
                (magnitude - deadzone) as f32 / (limit - deadzone) as f32
            } else {
                1.0
            }
        } else {
            0.0
        };
        -mapped
    } else {
        if deadzone < value {
            if value < limit {
                (value - deadzone) as f32 / (limit - deadzone) as f32
            } else {
                1.0
            }
        } else {
            0.0
        }
    }
}

/// Normalises the two control-stick axes and applies the radial clamp.
///
/// Each axis is passed through [`kpad_axis_deadzone`]; when the resulting
/// vector is longer than one, both components are divided by its length.
///
/// # Original
/// - Ghidra: `FUN_801ec8a0` at `0x801EC8A0` (548 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801ec8a0_FUN_801ec8a0.c`
///
/// # Arguments
/// * `out` - two-float destination.
/// * `x` - signed horizontal sample.
/// * `y` - signed vertical sample.
/// * `deadzone` - dead-zone half-width.
/// * `limit` - saturation point of the scale.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// Two float stores.
///
/// # Safety
/// `out` must be writable for two floats.
///
/// # Confidence
/// medium - both axis blocks and the final radial clamp are literal; the
/// square root call takes the magnitude computed by the guard, which the
/// export leaves implicit.
pub unsafe fn fn_801ec8a0(out: usize, x: i32, y: i32, deadzone: i32, limit: i32) {
    platform::write_f32(out, kpad_axis_deadzone(x, deadzone, limit));
    platform::write_f32(out + 4, kpad_axis_deadzone(y, deadzone, limit));

    let x_value = platform::read_f32(out);
    let y_value = platform::read_f32(out + 4);
    let magnitude = x_value * x_value + y_value * y_value;
    if platform::read_f32(SDA2_F32_4D2C) < magnitude {
        let length = call_f64_1(KPAD_SQRT_802E8620, magnitude as f64) as f32;
        platform::write_f32(out, x_value / length);
        platform::write_f32(out + 4, y_value / length);
    }
}

/// Resets or re-arms one KPAD channel after an asynchronous event.
///
/// The reset mode and channel are the two halves of the `0x802DCD74` split
/// return. Mode `0` (connect) clears the repeat word, arms the flag at `+0x68`,
/// brackets the sampling-callback registration with [`fn_801e5450`] calls, and
/// for channel `3` also clears the eight shared 64-bit filters and the five
/// extension check bytes. Any other mode posts `0xFF` into the sixteen fixed
/// status records and into every record of the variable bank. The per-channel
/// callback at `+0x44` is invoked last with `(channel, mode)`.
///
/// # Original
/// - Removed: the modelled `_savegpr_27` prologue call (`0x802DCD74`) and the `_restgpr_27` epilogue call (`0x802DCDC0`).
///   The save `bl` returns no value; the value it appeared to return is the incoming `r3`/`r4` argument pair (channel then mode).
/// - Ghidra: `FUN_801edf40` at `0x801EDF40` (356 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801edf40_FUN_801edf40.c`
///
/// # Arguments
/// * `channel`, `mode` - the reset channel and mode, incoming `r3`/`r4`.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// Two callback registrations, up to sixteen `0xFF` status stores or two,
/// eight 64-bit filter clears, six small-data clears and one `0x802DCDC0`
/// epilogue.
///
/// # Safety
/// The channel must be `0..=3`; the variable bank pointer must be readable.
///
/// # Confidence
/// medium - the two arms and the `0xFF` fills are literal; the
/// `0x802DCD74` halves are the established split-return artifact, and the
/// sampling callback it installs (`0x801EE230`) is still untranslated.
pub unsafe fn fn_801edf40(channel: u32, mode: u32) {
    let block = KPAD_CHANNEL_BASE + channel as usize * KPAD_CHANNEL_STRIDE;

    if mode == 0 {
        platform::write_u32(block + 0x64, 0);
        platform::write_u8(block + 0x68, 1);
        fn_801e5450(0);
        kpad_set_sampling_callback_801e0fd0(channel, 0x801E_E230);
        fn_801e5450(1);
        platform::write_u8(block + 0x4B, 0);
        platform::write_u8(block + 0x4D, 0);
        if channel == 3 {
            let low = platform::read_u32(SDA2_F64_4D00);
            let high = platform::read_u32(SDA2_F64_4D00 + 4);
            for index in 0..8usize {
                platform::write_u32(KPAD_FILTER_CH3 + index * 8, low);
                platform::write_u32(KPAD_FILTER_CH3 + index * 8 + 4, high);
            }
            platform::write_u8(SDA_KPAD_4B6A, 0);
            platform::write_u8(SDA_KPAD_4B6B, 0);
            platform::write_u8(SDA_KPAD_4B6C, 0);
            platform::write_u8(SDA_KPAD_4B6E, 0);
            platform::write_u16(SDA_KPAD_4B70, 0);
            platform::write_u8(SDA_KPAD_4B6D, 0);
        }
    } else {
        for index in 0..16usize {
            platform::write_u8(
                KPAD_STATUS_SLOTS
                    + channel as usize * KPAD_CHANNEL_STRIDE
                    + index * KPAD_STATUS_STRIDE
                    + 0x29,
                0xFF,
            );
        }
        let base = platform::read_u32(
            KPAD_EXTRA_SLOTS + channel as usize * KPAD_CHANNEL_STRIDE,
        ) as usize;
        let count = platform::read_u32(
            KPAD_EXTRA_COUNT + channel as usize * KPAD_CHANNEL_STRIDE,
        );
        for index in 0..count as usize {
            platform::write_u8(base + index * KPAD_STATUS_STRIDE + 0x29, 0xFF);
        }
    }

    let callback = platform::read_u32(block + 0x44);
    if callback != 0 {
        platform::call2(callback as usize, channel, mode);
    }
}

/// Exchanges one word in a KPAD channel block under the interrupt lock.
///
/// # Original
/// - Ghidra: `FUN_801ee0b0` at `0x801EE0B0` (88 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801ee0b0_FUN_801ee0b0.c`
///
/// # Arguments
/// * `channel` - block index (`0..=3`).
/// * `value` - new word for `block + 0x44`.
///
/// # Returns
/// The previous word.
///
/// # Side effects
/// One word store with the interrupt lock held.
///
/// # Safety
/// `channel` must be in range; the block must be live.
///
/// # Confidence
/// high - the lock bracket, the load and the store are literal.
pub unsafe fn fn_801ee0b0(channel: i32, value: u32) -> u32 {
    let token = disable_interrupts();
    let slot = KPAD_CHANNEL_BASE + channel as usize * KPAD_CHANNEL_STRIDE + 0x44;
    let previous = platform::read_u32(slot);
    platform::write_u32(slot, value);
    restore_interrupts(token);
    previous
}

