/// `0x803CDDF1`: IOS bulk tag of the transmit pump (`0x82` after init).
const HID_TX_TAG: usize = HID_STATE_BLOCK + 0x11;
/// `0x803CDDF2`: IOS bulk tag of the receive pump (`0x81` after init).
const HID_RX_TAG: usize = HID_STATE_BLOCK + 0x12;
