/// // unknown: not read anywhere in the band.
const HID_STATE_TAIL: usize = HID_STATE_BLOCK + 0x13;
/// `0x803CDDF4`: transmit buffer length (0x57E unless the caller supplied one).
const HID_TX_BUFFER_LENGTH: usize = HID_STATE_BLOCK + 0x14;
/// `0x803CDDF8`: receive buffer length (0x305 unless the caller supplied one).
const HID_RX_BUFFER_LENGTH: usize = HID_STATE_BLOCK + 0x18;
/// `0x803CDDFC`: first dynamic GKI pool id (used by the `0x1000` pump, which
/// is armed through [fn_801f8f70]).
const HID_POOL_A: usize = HID_STATE_BLOCK + 0x1C;
/// `0x803CDDFD`: second dynamic GKI pool id (used by the `0x1100` pump, which
/// is armed through [fn_801f9120]).
const HID_POOL_B: usize = HID_STATE_BLOCK + 0x1D;
/// `0x803CDE04`: word stored from the caller's argument by [fn_801f9490].
/// // unknown: the export only shows the copy.
const HID_STATE_PARAM: usize = HID_STATE_BLOCK + 0x24;
/// `0x803CDE0B`: set once [fn_801f8f70] has armed the receive pump.
const HID_RX_ARMED: usize = HID_STATE_BLOCK + 0x2B;

/// `0x803CDDC7`: GKI queue id the assembled reports are posted to.
const HID_REPORT_QUEUE_ID: usize = 0x803C_DDC7;
/// `0x803D16CC`: ACL fragment payload size used when re-chunking.
const HID_ACL_FRAGMENT: usize = 0x803D_16CC;
/// `0x803D16CE`: remaining-length threshold below which the next chunk is sent.
const HID_ACL_THRESHOLD: usize = 0x803D_16CE;

/// `0x803D1650`: two-entry HID-host timer table; each entry is a 32-bit key
/// followed by a handler pointer.
const HID_EVENT_TABLE: usize = 0x803D_1650;
/// `0x803D1660`: six-entry receive-frame handler table; each entry is a 16-bit
/// `0xNN00` type followed by a handler pointer.
const HID_EVENT_HANDLERS: usize = 0x803D_1660;
/// `r13-0x5DA8`: pointer to the three-byte-per-handle link-value table walked by
/// [fn_801fcc74]. Byte `+1` holds the entry count.
const SDA_DM_LINK_TABLE: usize = SDA_BASE - 0x5DA8;

/// `0x803A386A`: open-retry countdown written to 200 by [fn_801f36f0] and
/// decremented by the pairing state machine. // inferred: only ever `200` or
