const SDA_WUD_4B1B: usize = SDA_BASE - 0x4B1B;

/// `0x803A3830`: WUD connection alarm object (shared with the wave-89 cluster).
const WUD_CONNECT_ALARM: usize = 0x803A_3830;
/// `0x801F1600`: continuation armed on [`WUD_CONNECT_ALARM`] by [fn_801f36f0].
