const IOS_TX_CONTEXT: usize = 0x803C_FE40;
/// `0x801F9C10`: completion callback installed by both pumps.
const IOS_REPORT_CALLBACK: u32 = 0x801F_9C10;

/// `0x801FEF6F0`: IOS bulk sender behind the six-argument pump call. The
