/// `0x80215460`: HID parser open for one assembled report buffer.
const HID_PARSER_OPEN: usize = 0x8021_5460;
/// `0x80215630`: HID parser ready query.
const HID_PARSER_READY: usize = 0x8021_5630;

/// `r13-0x4B0C`: non-zero when the caller-supplied buffer lengths are used.
const SDA_HID_USB_LENGTHS: usize = SDA_BASE - 0x4B0C;
/// `r13-0x4B08` / `r13-0x4B04`: caller-supplied transmit/receive lengths.
const SDA_HID_USB_TX_LENGTH: usize = SDA_BASE - 0x4B08;
const SDA_HID_USB_RX_LENGTH: usize = SDA_BASE - 0x4B04;
