                        let links = platform::read_u8(BTA_HH_LINK_COUNT);
                        restore_interrupts(token);
                        platform::write_u16(
                            WUD_OPEN_TIMER_TICKS,
                            if links == 3 { 200 } else { 100 },
                        );
                        let token = disable_interrupts();
                        platform::write_u8(WUD_MODE_380B, 0);
                        platform::write_u8(WUD_MODE_380A, 1);
                        restore_interrupts(token);
                        fn_801fcfcc(0, 1);
                        chosen = 0x18;
