                                fn_801f6a70();
                                fn_801f6a70();
                                platform::write_u8(BTA_HH_SEARCH_STATE_312E, 2);
                                platform::call4(
                                    BTM_WRITE_STORED_KEY,
                                    1,
                                    (device + 0x40) as u32,
                                    (device + 0x46) as u32,
                                    0x801F_5CD0,
                                );
