// ---------------------------------------------------------------------------
// Wave 103: the IOS USB transfer helpers, the KPAD init and the aim step
// ---------------------------------------------------------------------------

/// `r13-0x5DE0`: the IOS heap id owned by the USB library. It holds `-1` until
/// [`fn_801eeb00`] creates the `0x4000`-byte heap.
const IUSB_HEAP: usize = SDA_BASE - 0x5DE0;
/// `r13-0x4B60` / `r13-0x4B5C`: the arena start and size captured once by
/// [`fn_801eeb00`] from the two `0x8022436x` queries.
const SDA_IUSB_ARENA_START: usize = SDA_BASE - 0x4B60;
const SDA_IUSB_ARENA_SIZE: usize = SDA_BASE - 0x4B5C;

/// `0x80225EB0`: `iosAllocAligned(heap, size, align)`.
const IOS_ALLOC_ALIGNED: usize = 0x8022_5EB0;
/// `0x802260C0`: `iosFree(heap, ptr)`; a negative result is a failure.
const IOS_FREE: usize = 0x8022_60C0;
/// `0x802259A0`: synchronous `iosIoctl(fd, request, num_in, num_out, vectors)`.
const IOS_IOCTL: usize = 0x8022_59A0;
/// `0x802258B0`: `iosIoctlvAsync(fd, request, num_in, num_out, vectors, cb, arg)`.
const IOS_IOCTLV_ASYNC: usize = 0x8022_58B0;
/// `0x80224C70`: `iosOpenDevice(name, mode)`.
const IOS_OPEN_DEVICE: usize = 0x8022_4C70;
/// `0x80224DA0`: `iosCloseAsync(fd, callback, argument)`.
const IOS_CLOSE_ASYNC: usize = 0x8022_4DA0;
/// `0x80224370` / `0x80224360` / `0x80224380`: arena start, arena size and the
/// arena commit call used while [`fn_801eeb00`] creates its heap.
const IOS_ARENA_START: usize = 0x8022_4370;
const IOS_ARENA_SIZE: usize = 0x8022_4360;
const IOS_ARENA_COMMIT: usize = 0x8022_4380;
/// `0x80225D80`: `iosCreateHeap(base, size)`; returns the heap id or a negative
/// error code.
const IOS_CREATE_HEAP: usize = 0x8022_5D80;
/// `0x802E16E8`: the formatted-string builder (six arguments in this body).
const SPRINTF: usize = 0x802E_16E8;
/// `0x801EEC10`: the completion callback shared by the three asynchronous
/// transfer helpers below (the body is [`fn_801eec10`]).
const IOS_USB_COMPLETION: u32 = 0x801E_EC10;
/// `0x80345924`: the `"/dev/usb/%s/%x/%x"` device-path format passed to
/// [`SPRINTF`]. The bytes are kept as an address because the export only
/// exposes the Ghidra label `s__dev_usb__s__x__x_80345924`.
const IOS_USB_DEVICE_PATH: u32 = 0x8034_5924;
/// The heap size requested by [`fn_801eeb00`]; the arena must hold at least
/// this much after the captured start pointer.
const IUSB_HEAP_BYTES: u32 = 0x4000;

/// Frees one IOS USB descriptor block and swallows the failure trace.
///
/// The original inlines `iosFree(heap, block)` followed by a
/// `"iosFree(%d, 0x%x) failed: %d"` report; the printer is a no-op in this
/// build, so only the free is reproduced.
///
/// # Safety
/// `block` must be a pointer returned by [`IOS_ALLOC_ALIGNED`] for
/// [`IUSB_HEAP`], or zero.
unsafe fn iusb_free(block: usize) {
    if block != 0
        && (platform::call2(IOS_FREE, platform::read_u32(IUSB_HEAP), block as u32) as i32) < 0
    {
        // observed: the free-failure trace; its printer is a no-op here.
    }
}

/// Creates the `0x4000`-byte IOS heap the USB library allocates from.
///
/// The first call captures the arena start and size, checks that the arena can
/// hold `0x4000` bytes after the start and then creates the heap. A second call
/// only reports that the library is already initialised. Both calls run under
/// the OS interrupt lock.
///
/// # Original
/// - Ghidra: `FUN_801eeb00` at `0x801EEB00` (248 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801eeb00_FUN_801eeb00.c`
///
/// # Arguments
/// None.
///
/// # Returns
/// `0` on success, `0xFFFFFFEA` (`-22`) when the arena is too small or the heap
/// cannot be created.
///
/// # Side effects
/// Two arena words, one heap-id word, one arena commit, one heap creation and
/// the interrupt lock.
///
/// # Safety
/// Must run before any other USB helper allocates; the heap id stays `-1` on a
/// failure.
///
/// # Confidence
/// high - the guard, the two captured words, the `0x4000` threshold, the heap
/// call and both stores are literal. The three trace calls are omitted because
/// their printer is a no-op in this build.
pub unsafe fn fn_801eeb00() -> u32 {
    let token = disable_interrupts();
    let mut result = 0u32;

    if platform::read_i32(IUSB_HEAP) == -1 {
        if platform::read_u32(SDA_IUSB_ARENA_START) == 0 {
            let start = call0_ret(IOS_ARENA_START);
            platform::write_u32(SDA_IUSB_ARENA_START, start);
            let size = call0_ret(IOS_ARENA_SIZE);
            platform::write_u32(SDA_IUSB_ARENA_SIZE, size);
            if platform::read_u32(SDA_IUSB_ARENA_SIZE)
                < platform::read_u32(SDA_IUSB_ARENA_START).wrapping_add(IUSB_HEAP_BYTES)
            {
                // observed: "Not enough IPC arena" (trace only).
                result = 0xFFFF_FFEA;
                restore_interrupts(token);
                return result;
            }
            platform::call0(IOS_ARENA_COMMIT);
        }
        let heap = platform::call2(
            IOS_CREATE_HEAP,
            platform::read_u32(SDA_IUSB_ARENA_START),
            IUSB_HEAP_BYTES,
        ) as i32;
        platform::write_i32(IUSB_HEAP, heap);
        if heap < 0 {
            // observed: "Not enough heaps" (trace only).
            result = 0xFFFF_FFEA;
        }
    } else {
        // observed: "Library is already initialized." (trace only).
    }

    restore_interrupts(token);
    result
}

/// Returns `0`.
///
/// # Original
/// - Ghidra: `FUN_801eec00` at `0x801EEC00` (8 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801eec00_FUN_801eec00.c`
///
/// # Arguments
/// None.
///
/// # Returns
/// Always `0`.
///
/// # Side effects
/// None.
///
/// # Safety
/// None; the body is `li r3,0; blr`.
///
/// # Confidence
/// high - the whole body is the constant return.
pub unsafe fn fn_801eec00() -> u32 {
    0
}

/// Completes one IOS USB interrupt/bulk transfer and releases its descriptors.
///
/// Called by IOS with the transfer's file descriptor and the `0x80`-byte record
/// built by [`fn_801ef030`] / [`fn_801ef390`] / [`fn_801ef8b0`]. The record
/// word `+0x34` counts the buffers at `+0x14`; the allowed completion counts are
/// `0`, `2`..`4` and `7`. Every non-null buffer is freed, the count is cleared,
/// and the user callback is invoked: a record with a non-zero `+0` word uses it
/// as the callback (two arguments), otherwise `+4` is used with three.
///
/// # Original
/// - Removed: the modelled `_savegpr_26` prologue call (`0x802DCD70`) and the `_restgpr_26` epilogue call (`0x802DCDBC`).
///   The save `bl` returns no value; the value it appeared to return is the incoming `r3`/`r4` argument pair (descriptor then record).
/// - Ghidra: `FUN_801eec10` at `0x801EEC10` (412 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801eec10_FUN_801eec10.c`
///
/// # Arguments
/// * `fd`, `record` - the descriptor and the completion record, incoming
///   `r3`/`r4` (descriptor first, record second).
///
/// # Returns
/// `()`; the record is always released.
///
/// # Side effects
/// Up to `+0x34` frees, two user-callback calls and one `0x802DCDBC` release.
///
/// # Safety
/// The record must be the block allocated by the transfer helper, with its
/// `+0x34` count and `+0x14`.. buffer array intact.
///
/// # Confidence
/// medium - the count test, the free loop, both callback shapes and the final
/// release are literal; the two values arrive through the established split
/// return and the trace calls are omitted (their printer is a no-op).
pub unsafe fn fn_801eec10(fd: u32, record: usize) {
    let heap = platform::read_u32(IUSB_HEAP);

    let count = platform::read_u32(record + 0x34);
    if count.wrapping_sub(2) < 3 || count == 7 || count == 0 {
        let mut index = 0u32;
        while index < platform::read_u32(record + 0x34) {
            let buffer = platform::read_u32(record + 0x14 + index as usize * 4);
            if buffer != 0
                && (platform::call2(IOS_FREE, heap, buffer) as i32) < 0
            {
                // observed: "iosFree(%d, 0x%x) failed: %d" (trace only).
            }
            index += 1;
        }
        platform::write_u32(record + 0x34, 0);
    } else {
        // observed: "_intrBlkCtrlIsoCb: got invalid n" (trace only).
    }

    let callback = platform::read_u32(record);
    if callback == 0 {
        let alternate = platform::read_u32(record + 4);
        if alternate != 0 {
            platform::call3(
                alternate as usize,
                fd,
                platform::read_u32(record + 0xC),
                platform::read_u32(record + 8),
            );
        }
    } else {
        platform::call2(callback as usize, fd, platform::read_u32(record + 8));
    }

    iusb_free(record);
}

/// Opens one USB device by name and returns its IOS descriptor.
///
/// Allocates a `0x80`-byte record, builds the `"/dev/usb/%s/%x/%x"` path into
/// its `+0x40` tail from the three arguments, opens it and copies the descriptor
/// to `*out`. The record is released on every path.
///
/// # Original
/// - Removed: the `_restgpr_26` epilogue call (`0x802DCDBC`).
///   The epilogue `bl` returns no value; the argument it was passed is the routine's `r3` return.
/// - Ghidra: `FUN_801eedb0` at `0x801EEDB0` (324 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801eedb0_FUN_801eedb0.c`
///
/// # Arguments
/// * `name` - device name inserted in the path (`r3`).
/// * `vendor` - first hexadecimal path field (`r4`).
/// * `product` - second hexadecimal path field (`r5`).
/// * `out` - receives the descriptor; must be non-null.
///
/// # Returns
/// `()`; the descriptor travels through `*out` and through the `0x802DCDBC`
/// epilogue helper.
///
/// # Side effects
/// One `0x80`-byte allocation, one zero fill, one formatted path, one
/// `iosOpenDevice` and one free.
///
/// # Safety
/// `out` must be writable for one word and `name` must be a NUL-terminated
/// string.
///
/// # Confidence
/// medium - the null test, the allocation size, the formatted path, the open
/// and the free are literal; the three path arguments are the `0x802DCD70`
/// split pair plus `r5`, which fixes their order.
#[allow(unused_assignments)] // observed: the final status stays in r3.
pub unsafe fn fn_801eedb0(name: u32, vendor: u32, product: u32, out: u32) {
    let heap = platform::read_u32(IUSB_HEAP);
    let mut record = 0usize;
    let mut result;

    if out == 0 {
        result = 0xFFFF_FFFC;
    } else {
        record = platform::call3(IOS_ALLOC_ALIGNED, heap, 0x80, 0x20) as usize;
        if record == 0 {
            // observed: "iosAllocAligned(%d, %u) failed" + "OpenDeviceIds:
            // Not enough memory" (trace only).
            result = 0xFFFF_FFEA;
        } else {
            platform::call3(MEMSET, record as u32, 0, 0x80);
            platform::call6(
                SPRINTF,
                (record + 0x40) as u32,
                0x40,
                IOS_USB_DEVICE_PATH,
                name,
                vendor,
                product,
            );
            result = platform::call2(IOS_OPEN_DEVICE, (record + 0x40) as u32, 0);
            // observed: "OpenDevice returned: %d" (trace only).
            platform::write_u32(out as usize, result);
        }
    }

    iusb_free(record);
}

/// Starts an asynchronous close of one IOS USB descriptor.
///
/// Allocates a `0x80`-byte record, stores the descriptor at `+0` (the callback
/// slot) and the caller's word at `+8`, and calls `iosCloseAsync` with
/// [`fn_801eec10`] as the completion. The record is released only when the
/// close call fails.
///
/// # Original
/// - Removed: the `_restgpr_27` epilogue call (`0x802DCDC0`).
///   The epilogue `bl` returns no value; the argument it was passed is the routine's `r3` return.
/// - Ghidra: `FUN_801eef00` at `0x801EEF00` (292 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801eef00_FUN_801eef00.c`
///
/// # Arguments
/// * `fd` - the descriptor to close (`r3`).
/// * `_callback` - the word at `r4`, stored at record `+0` and used as the
///   completion callback.
/// * `argument` - stored at record `+8` and passed to that callback.
///
/// # Returns
/// `()`; the close status travels through the `0x802DCDC0` epilogue helper.
///
/// # Side effects
/// One allocation, one zero fill, one `iosCloseAsync` and a conditional free.
///
/// # Safety
/// `fd` must be an open USB descriptor.
///
/// # Confidence
/// medium - the allocation, the two stores, the completion address and the
/// status test are literal; the callback/argument roles follow the two stores
/// and the completion body.
#[allow(unused_assignments)] // observed: the final status stays in r3.
pub unsafe fn fn_801eef00(fd: u32, completion: u32, argument: u32) {
    let heap = platform::read_u32(IUSB_HEAP);
    let result;

    // observed: "CloseDevice" (trace only).
    let record = platform::call3(IOS_ALLOC_ALIGNED, heap, 0x80, 0x20) as usize;
    if record == 0 {
        result = 0xFFFF_FFEA_u32;
    } else {
        platform::call3(MEMSET, record as u32, 0, 0x80);
        platform::write_u32(record, completion);
        platform::write_u32(record + 8, argument);
        platform::write_u32(record + 0x34, 0);
        result = platform::call3(IOS_CLOSE_ASYNC, fd, IOS_USB_COMPLETION, record as u32);
        // observed: "CloseDevice returned: %d" (trace only).
        if (result as i32) < 0 {
            iusb_free(record);
        }
    }
}

/// Sends one long bulk request (IOS request `10`) over the USB descriptor.
///
/// Builds three ioctl vectors - the one-byte tag from `r4`, the four-byte
/// length word at `r5`, and the caller's buffer at `r6` with length `r5` -
/// flushes them, and either issues the synchronous ioctl or allocates a
/// completion record and calls the asynchronous form. Records are freed on
/// every failure path.
///
/// # Original
/// - Removed: the `_restgpr_21` epilogue call (`0x802DCDA8`).
///   The epilogue `bl` returns no value; the argument it was passed is the routine's `r3` return.
/// - Ghidra: `FUN_801ef030` at `0x801EF030` (852 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801ef030_FUN_801ef030.c`
///
/// # Arguments
/// * `fd` - the open USB descriptor (`r3`).
/// * `tag` - value whose low byte is the first descriptor byte (`r4`).
/// * `length` - payload length, also placed in the four-byte descriptor (`r5`).
/// * `buffer` - payload address (`r6`).
/// * `callback`, `callback_argument` - async completion (`r7`, `r8`).
/// * `async_flag` - non-zero selects the asynchronous form (`r9`).
///
/// # Returns
/// `()`; the ioctl status travels through the `0x802DCDA8` epilogue helper.
///
/// # Side effects
/// Up to four allocations, seven cache flushes, one ioctl and up to four frees.
///
/// # Safety
/// `buffer` must be readable and writable for `length` bytes.
///
/// # Confidence
/// medium - the three vector pairs, the flush sequence, both ioctl forms and the
/// free ladder are literal; the tag/length roles come from the vector layout
/// and from the two callers that pass the message length at `r5`.
#[allow(unused_assignments)] // observed: the final status stays in r3.
pub unsafe fn fn_801ef030(
    fd: u32,
    tag: u32,
    length: u32,
    buffer: u32,
    callback: u32,
    callback_argument: u32,
    async_flag: u32,
) {
    let heap = platform::read_u32(IUSB_HEAP);
    let context = platform::call3(IOS_ALLOC_ALIGNED, heap, 0x60, 0x20) as usize;
    let tag_block = platform::call3(IOS_ALLOC_ALIGNED, heap, 0x20, 0x20) as usize;
    let length_block = platform::call3(IOS_ALLOC_ALIGNED, heap, 0x20, 0x20) as usize;
    let mut result;

    if context == 0 || tag_block == 0 || length_block == 0 {
        // observed: "_LongBlkMsgInt: Not enough memory" (trace only).
        result = 0xFFFF_FFEA_u32;
    } else {
        platform::write_u8(tag_block, tag as u8);
        platform::write_u32(length_block, length);
        platform::write_u32(context, tag_block as u32);
        platform::write_u32(context + 4, 1);
        platform::write_u32(context + 8, length_block as u32);
        platform::write_u32(context + 0xC, 4);
        platform::write_u32(context + 0x10, buffer);
        platform::write_u32(context + 0x14, length);

        platform::call2(DC_FLUSH_RANGE, tag_block as u32, 0x20);
        platform::call2(DC_FLUSH_RANGE, length_block as u32, 0x20);
        platform::call2(DC_FLUSH_RANGE, context as u32, 0x60);

        if async_flag == 0 {
            result = platform::call5(IOS_IOCTL, fd, 10, 2, 1, context as u32);
            // observed: "Long bulk ioctl returned: %d" (trace only).
        } else {
            let record = platform::call3(IOS_ALLOC_ALIGNED, heap, 0x80, 0x20) as usize;
            if record == 0 {
                // observed: "LongBlkMsgInt: async - Not enough memory"
                // (trace only).
                result = 0xFFFF_FFEA_u32;
            } else {
                platform::call3(MEMSET, record as u32, 0, 0x80);
                platform::write_u32(record, callback);
                platform::write_u32(record + 8, callback_argument);
                platform::write_u32(record + 0x34, 3);
                platform::write_u32(record + 0x14, tag_block as u32);
                platform::write_u32(record + 0x18, length_block as u32);
                platform::write_u32(record + 0x1C, context as u32);
                platform::write_u32(record + 0x40, buffer);
                platform::write_u16(record + 0x44, length as u16);
                result = platform::call7(
                    IOS_IOCTLV_ASYNC,
                    fd,
                    10,
                    2,
                    1,
                    context as u32,
                    IOS_USB_COMPLETION,
                    record as u32,
                );
                if (result as i32) < 0 {
                    if result == 0xFFFF_FFEA {
                        // observed: "%s: IoctlvAsync returned error %d"
                        // (trace only).
                    }
                    iusb_free(record);
                } else {
                    return;
                }
            }
        }
    }

    iusb_free(tag_block);
    iusb_free(length_block);
    iusb_free(context);
}

