/// Sends a USB control transfer with a six-field setup packet.
///
/// The six descriptor fields are built into `0x20`-byte blocks and published as
/// six `(buffer, length)` vectors, followed by the caller's data buffer and
/// length. All seven buffers are flushed, then either the synchronous control
/// ioctl or the asynchronous form runs. The data buffer stays owned by the
/// caller; only the descriptor blocks are freed here.
///
/// # Original
/// - Removed: the `_restgpr_14` epilogue call (`0x802DCD8C`).
///   The epilogue `bl` returns no value; the argument it was passed is the routine's `r3` return.
/// - Ghidra: `FUN_801ef8b0` at `0x801EF8B0` (1,444 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801ef8b0_FUN_801ef8b0.c`
///
/// # Arguments
/// * `fd` - the open USB descriptor (`r3`).
/// * `request_type` - first setup byte, `bmRequestType` (`r4`).
/// * `request` - second setup byte, `bRequest` (`r5`).
/// * `value` - third setup field, `wValue`, stored big-endian (`r6`).
/// * `index` - fourth setup field, `wIndex`, stored big-endian (`r7`).
/// * `length` - fifth setup field `wLength` and the data-buffer length (`r8`).
/// * `buffer` - data buffer (`r9`).
/// * `callback`, `callback_argument` - async completion (`r10`, `r11`).
/// * `async_flag` - non-zero selects the asynchronous form (stack word).
///
/// # Returns
/// `()`; the ioctl status travels through the `0x802DCD8C` epilogue helper.
///
/// # Side effects
/// Seven allocations, seven cache flushes, one ioctl and up to seven frees.
///
/// # Safety
/// `buffer` must be readable for `length` bytes (writable for an IN transfer),
/// and every other argument must be a plain value.
///
/// # Confidence
/// medium - the vector table, the byte-swaps, the flush ladder, both ioctl
/// forms and the cleanup path are literal; the setup-field roles follow the
/// vector lengths (`1,1,2,2,2,1`) and the two translated callers.
#[allow(unused_assignments)] // observed: the final status stays in r3.
pub unsafe fn fn_801ef8b0(
    fd: u32,
    request_type: u32,
    request: u32,
    value: u32,
    index: u32,
    length: u32,
    buffer: u32,
    callback: u32,
    callback_argument: u32,
    async_flag: u32,
) {
    let heap = platform::read_u32(IUSB_HEAP);
    let mut result;

    if (buffer == 0 && length != 0) || (buffer & 0x1F) != 0 {
        // observed: "ctrlmsg: bad data buffer" (trace only).
        result = 0xFFFF_FFFC_u32;
        return;
    }

    let context = platform::call3(IOS_ALLOC_ALIGNED, heap, 0xE0, 0x20) as usize;
    let request_type_block = platform::call3(IOS_ALLOC_ALIGNED, heap, 0x20, 0x20) as usize;
    let request_block = platform::call3(IOS_ALLOC_ALIGNED, heap, 0x20, 0x20) as usize;
    let unused_block = platform::call3(IOS_ALLOC_ALIGNED, heap, 0x20, 0x20) as usize;
    let value_block = platform::call3(IOS_ALLOC_ALIGNED, heap, 0x20, 0x20) as usize;
    let index_block = platform::call3(IOS_ALLOC_ALIGNED, heap, 0x20, 0x20) as usize;
    let length_block = platform::call3(IOS_ALLOC_ALIGNED, heap, 0x20, 0x20) as usize;

    if request_type_block == 0
        || request_block == 0
        || unused_block == 0
        || value_block == 0
        || index_block == 0
        || length_block == 0
        || context == 0
    {
        // observed: "Ctrl Msg: Not enough memory" (trace only).
        result = 0xFFFF_FFEA_u32;
    } else {
        platform::write_u8(request_type_block, request_type as u8);
        platform::write_u8(request_block, request as u8);
        platform::write_u16(value_block, (value as u16).swap_bytes());
        platform::write_u16(index_block, (index as u16).swap_bytes());
        platform::write_u16(length_block, (length as u16).swap_bytes());
        platform::write_u8(unused_block, 0);

        platform::write_u32(context, request_type_block as u32);
        platform::write_u32(context + 4, 1);
        platform::write_u32(context + 8, request_block as u32);
        platform::write_u32(context + 0xC, 1);
        platform::write_u32(context + 0x10, value_block as u32);
        platform::write_u32(context + 0x14, 2);
        platform::write_u32(context + 0x18, index_block as u32);
        platform::write_u32(context + 0x1C, 2);
        platform::write_u32(context + 0x20, length_block as u32);
        platform::write_u32(context + 0x24, 2);
        platform::write_u32(context + 0x28, unused_block as u32);
        platform::write_u32(context + 0x2C, 1);
        platform::write_u32(context + 0x30, buffer);
        platform::write_u32(context + 0x34, length);

        platform::call2(DC_FLUSH_RANGE, request_type_block as u32, 0x20);
        platform::call2(DC_FLUSH_RANGE, request_block as u32, 0x20);
        platform::call2(DC_FLUSH_RANGE, unused_block as u32, 0x20);
        platform::call2(DC_FLUSH_RANGE, value_block as u32, 0x20);
        platform::call2(DC_FLUSH_RANGE, index_block as u32, 0x20);
        platform::call2(DC_FLUSH_RANGE, length_block as u32, 0x20);
        platform::call2(DC_FLUSH_RANGE, context as u32, 0xE0);

        if async_flag == 0 {
            result = platform::call5(IOS_IOCTL, fd, 0, 6, 1, context as u32);
        } else {
            let record = platform::call3(IOS_ALLOC_ALIGNED, heap, 0x80, 0x20) as usize;
            if record == 0 {
                // observed: "CtrlMsgInt: async - Not enough memory"
                // (trace only).
                result = 0xFFFF_FFEA_u32;
            } else {
                platform::call3(MEMSET, record as u32, 0, 0x80);
                platform::write_u32(record, callback);
                platform::write_u32(record + 8, callback_argument);
                platform::write_u32(record + 0x34, 7);
                platform::write_u32(record + 0x14, request_type_block as u32);
                platform::write_u32(record + 0x18, request_block as u32);
                platform::write_u32(record + 0x1C, value_block as u32);
                platform::write_u32(record + 0x20, index_block as u32);
                platform::write_u32(record + 0x24, length_block as u32);
                platform::write_u32(record + 0x28, unused_block as u32);
                platform::write_u32(record + 0x2C, context as u32);
                platform::write_u32(record + 0x40, buffer);
                platform::write_u16(record + 0x44, length as u16);
                result = platform::call7(
                    IOS_IOCTLV_ASYNC,
                    fd,
                    0,
                    6,
                    1,
                    context as u32,
                    IOS_USB_COMPLETION,
                    record as u32,
                );
                // observed: "Ctrl Msg async returned: %d" (trace only).
                if (result as i32) >= 0 {
                    return;
                }
                iusb_free(record);
            }
        }
    }

    iusb_free(request_type_block);
    iusb_free(request_block);
    iusb_free(value_block);
    iusb_free(index_block);
    iusb_free(length_block);
    iusb_free(unused_block);
    iusb_free(context);
}

/// Forwards a nine-argument control transfer with the asynchronous flag set.
///
/// The export shows a bare forwarder: the two leading words are read back
/// through the `0x802DCD64` split and the body calls [`fn_801ef8b0`] with the
/// same nine arguments plus `1`. It is the async entry point used by the HID
/// report sender at `0x801F9840`.
///
/// # Original
/// - Ghidra: `FUN_801efe60` at `0x801EFE60` (140 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801efe60_FUN_801efe60.c`
///
/// # Arguments
/// Same nine words as [`fn_801ef8b0`]: descriptor, `bmRequestType`, `bRequest`,
/// `wValue`, `wIndex`, length, buffer, callback and callback argument.
///
/// # Returns
/// `()`; the callee's status travels through its own epilogue helper.
///
/// # Side effects
/// Exactly those of [`fn_801ef8b0`] on its asynchronous path.
///
/// # Safety
/// See [`fn_801ef8b0`].
///
/// # Confidence
/// medium - the forward and the trailing `1` are literal; the two leading
/// arguments are reassembled from the `0x802DCD64` split, which is the
/// established way this export loses its first register pair.
pub unsafe fn fn_801efe60(
    fd: u32,
    request_type: u32,
    request: u32,
    value: u32,
    index: u32,
    length: u32,
    buffer: u32,
    callback: u32,
    callback_argument: u32,
) {
    fn_801ef8b0(
        fd,
        request_type,
        request,
        value,
        index,
        length,
        buffer,
        callback,
        callback_argument,
        1,
    );
}

/// `0x803A1AC8`: the base of the four `0x578`-byte KPAD channel records this
/// pass uses. It is `0x50C` bytes below [`KPAD_CHANNEL_BASE`] (the two names
/// describe the same record at different offsets).
const KPAD_BLOCK_BASE: usize = 0x803A_1AC8;
/// One KPAD channel record (`0x803A2040` is the second one).
const KPAD_BLOCK_STRIDE: usize = 0x578;
/// `0x803A30A8`..`0x803A30D4`: the shared 2-D basis written once by the KPAD
/// init and rotated by `0x801C1160`. // inferred: cos/-sin/sin/cos layout from
/// the four helper calls that fill it.
const KPAD_BASIS_30A8: usize = 0x803A_30A8;

/// `r2-0x4D18`: the `2^52` magic double of the integer-to-double sequence.
const SDA2_F64_4D18: usize = SDA2_BASE - 0x4D18;
/// `r2-0x4D34`: the half scale applied to the two aim-point coordinates.
/// // unknown: exact value (the export only reads it).
const SDA2_F32_4D34: usize = SDA2_BASE - 0x4D34;
/// `r2-0x4D10`/`-0x4D0C`/`-0x4D08`: scale and the two offsets of the sensor
/// point conversion.
const SDA2_F32_4D10: usize = SDA2_BASE - 0x4D10;
const SDA2_F32_4D0C: usize = SDA2_BASE - 0x4D0C;
const SDA2_F32_4D08: usize = SDA2_BASE - 0x4D08;
/// `r2-0x4CE8`: the clock divisor used to turn the init tick count into the
/// pointer scale.
const SDA2_F32_4CE8: usize = SDA2_BASE - 0x4CE8;
/// `r2-0x4CE4`: the angle constant multiplied by the `r13-0x5DE4` clock scale
/// to build the shared basis.
const SDA2_F32_4CE4: usize = SDA2_BASE - 0x4CE4;

/// `r13-0x5E5C`..`r13-0x5E4C`: five default orientation words copied into every
/// channel record at `+0xD0`..`+0xE0` by the KPAD init.
const SDA_KPAD_5E5C: usize = SDA_BASE - 0x5E5C;
const SDA_KPAD_5E58: usize = SDA_BASE - 0x5E58;
const SDA_KPAD_5E54: usize = SDA_BASE - 0x5E54;
const SDA_KPAD_5E50: usize = SDA_BASE - 0x5E50;
const SDA_KPAD_5E4C: usize = SDA_BASE - 0x5E4C;
/// `r13-0x4B98`/`-0x4B94`: the two horizontal-aim offsets copied into every
/// record at `+0xE4`/`+0xE8`.
const SDA_KPAD_4B98: usize = SDA_BASE - 0x4B98;
const SDA_KPAD_4B94: usize = SDA_BASE - 0x4B94;
/// `r13-0x5E48`: the raw pointer scale the init converts through
/// [`SDA2_F32_4CE8`] into `r13-0x4B64`/`r13-0x4B68`.
const SDA_KPAD_5E48: usize = SDA_BASE - 0x5E48;
/// `r13-0x5E60`: argument handed to the WPAD hook at the end of the KPAD init.
const SDA_KPAD_5E60: usize = SDA_BASE - 0x5E60;
/// `r13-0x4B84`: set to `1` once the KPAD init has run; a second call returns
/// immediately.
const SDA_KPAD_4B84: usize = SDA_BASE - 0x4B84;
/// `r13-0x5DE4`: the CPU-clock scale used by the shared basis angle.
const SDA_KPAD_5DE4: usize = SDA_BASE - 0x5DE4;
/// `r13-0x5E1C`: trigger-level threshold of the pointer matcher.
const SDA_KPAD_5E1C: usize = SDA_BASE - 0x5E1C;
/// `r13-0x5E20`: dot-product limit of the "pointer too far" test.
const SDA_KPAD_5E20: usize = SDA_BASE - 0x5E20;

/// Advances one channel's pointer-aim filter by one sample.
///
/// The stick vector at `+0xDC`/`+0xE0` is rotated by the sensor-bar basis
/// (`+0x4C8`/`+0x4CC`) into camera space. On the first sample (enable byte
/// `+0x5E` zero) the result is latched together with a zero delta. Afterwards
/// the delta from the previous point is measured, shaped by the dead zone
/// `+0xB8` and gain `+0xBC` when `+0x564` is zero, or clamped by the same pair
/// when it is set, and the difference of the new unit vector is stored at
/// `+0x3C`/`+0x40`/`+0x44`.
///
/// The scroll value (`+0x544` divided by `+0x4C4`) gets the same treatment into
/// `+0x48`/`+0x4C`/`+0x50` with the `+0xC0`/`+0xC4` pair and the `+0x568`
/// switch. The second half re-projects the two aim points (`+0x120`/`+0x124`
/// and `+0x12C`/`+0x130`) through the rotation and the `+0xD4`/`+0xD8` basis
/// into the camera point `+0x20`/`+0x24`, filtered with `+0xB0`/`+0xB4` and
/// the `+0x560` switch. The supplied mode byte is stored last.
///
/// # Original
/// - Ghidra: `FUN_801ebd20` at `0x801EBD20` (1,484 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801ebd20_FUN_801ebd20.c`
///
/// # Arguments
/// * `block` - one `0x578`-byte KPAD channel record.
/// * `enable` - non-zero runs the filter; zero only clears `+0x5E`.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// The aim point, scroll and camera point banks, their deltas and magnitudes,
/// and the mode byte `+0x5E`.
///
/// # Safety
/// `block` must be a live KPAD channel record and `+0x4C4` must be non-zero
/// after the first calibration sample.
///
/// # Confidence
/// medium - every offset, branch and store is literal; the three field groups
/// are named after their use (aim point, scroll, camera point) and the two
/// `r13-0x4B80`/`-0x4B7C` words are reused from the wave-97 constants.
pub unsafe fn fn_801ebd20(block: usize, enable: i32) {
    if enable == 0 {
        platform::write_u8(block + 0x5E, 0);
        return;
    }

    let zero = platform::read_f32(SDA2_F32_4D38);
    let one = platform::read_f32(SDA2_F32_4D2C);
    let half = platform::read_f32(SDA2_F32_4D34);

    let stick_x = platform::read_f32(block + 0xDC);
    let stick_y = platform::read_f32(block + 0xE0);
    let basis_x = platform::read_f32(block + 0x4C8);
    let basis_y = platform::read_f32(block + 0x4CC);

    let mut aim_x = stick_x * basis_x + stick_y * basis_y;
    let mut aim_y = stick_y * basis_x - stick_x * basis_y;

    if platform::read_u8(block + 0x5E) == 0 {
        platform::write_f32(block + 0x34, aim_x);
        platform::write_u32(block + 0x3C, platform::read_u32(SDA_KPAD_4B80));
        platform::write_f32(block + 0x38, aim_y);
        platform::write_u32(block + 0x40, platform::read_u32(SDA_KPAD_4B7C));
        platform::write_f32(block + 0x44, zero);
    } else {
        aim_x -= platform::read_f32(block + 0x34);
        aim_y -= platform::read_f32(block + 0x38);
        let distance =
            call_f64_1(KPAD_SQRT_802E8620, (aim_x * aim_x + aim_y * aim_y) as f64) as f32;
        let dead_zone = platform::read_f32(block + 0xB8);

        if platform::read_i32(block + 0x564) == 0 {
            let gain = if distance < dead_zone {
                let ratio = distance / dead_zone;
                let squared = ratio * ratio;
                squared * squared
            } else {
                one
            } * platform::read_f32(block + 0xBC);
            aim_x = platform::read_f32(block + 0x34) + gain * aim_x;
            aim_y = platform::read_f32(block + 0x38) + gain * aim_y;
            let length =
                call_f64_1(KPAD_SQRT_802E8620, (aim_x * aim_x + aim_y * aim_y) as f64) as f32;
            aim_x /= length;
            aim_y /= length;
            let delta_y = aim_y - platform::read_f32(block + 0x38);
            let delta_x = aim_x - platform::read_f32(block + 0x34);
            platform::write_f32(block + 0x40, delta_y);
            platform::write_f32(block + 0x3C, delta_x);
            let magnitude =
                call_f64_1(KPAD_SQRT_802E8620, (delta_x * delta_x + delta_y * delta_y) as f64)
                    as f32;
            platform::write_f32(block + 0x44, magnitude);
            platform::write_f32(block + 0x34, aim_x);
            platform::write_f32(block + 0x38, aim_y);
        } else if distance <= dead_zone {
            platform::write_u32(block + 0x3C, platform::read_u32(SDA_KPAD_4B80));
            platform::write_u32(block + 0x40, platform::read_u32(SDA_KPAD_4B7C));
            platform::write_f32(block + 0x44, zero);
        } else {
            let gain = platform::read_f32(block + 0xBC) * ((distance - dead_zone) / distance);
            aim_x = platform::read_f32(block + 0x34) + aim_x * gain;
            aim_y = platform::read_f32(block + 0x38) + aim_y * gain;
            let length =
                call_f64_1(KPAD_SQRT_802E8620, (aim_x * aim_x + aim_y * aim_y) as f64) as f32;
            aim_x /= length;
            aim_y /= length;
            let delta_y = aim_y - platform::read_f32(block + 0x38);
            let delta_x = aim_x - platform::read_f32(block + 0x34);
            platform::write_f32(block + 0x40, delta_y);
            platform::write_f32(block + 0x3C, delta_x);
            let magnitude =
                call_f64_1(KPAD_SQRT_802E8620, (delta_x * delta_x + delta_y * delta_y) as f64)
                    as f32;
            platform::write_f32(block + 0x44, magnitude);
            platform::write_f32(block + 0x34, aim_x);
            platform::write_f32(block + 0x38, aim_y);
        }
    }

    let mut scroll = platform::read_f32(block + 0x544) / platform::read_f32(block + 0x4C4);
    if platform::read_u8(block + 0x5E) == 0 {
        platform::write_f32(block + 0x48, scroll);
        platform::write_f32(block + 0x4C, zero);
        platform::write_f32(block + 0x50, zero);
    } else {
        scroll -= platform::read_f32(block + 0x48);
        let magnitude = if scroll < zero { -scroll } else { scroll };
        let scroll_zone = platform::read_f32(block + 0xC0);

        if platform::read_i32(block + 0x568) == 0 {
            let gain = if magnitude < scroll_zone {
                let ratio = magnitude / scroll_zone;
                let squared = ratio * ratio;
                squared * squared
            } else {
                one
            } * platform::read_f32(block + 0xC4)
                * scroll;
            platform::write_f32(block + 0x4C, gain);
            platform::write_f32(block + 0x50, if zero <= gain { gain } else { -gain });
            platform::write_f32(
                block + 0x48,
                platform::read_f32(block + 0x48) + platform::read_f32(block + 0x4C),
            );
        } else if magnitude <= scroll_zone {
            platform::write_f32(block + 0x4C, zero);
            platform::write_f32(block + 0x50, zero);
        } else {
            let gain = platform::read_f32(block + 0xC4)
                * ((magnitude - scroll_zone) / magnitude)
                * scroll;
            platform::write_f32(block + 0x4C, gain);
            platform::write_f32(block + 0x50, if zero <= gain { gain } else { -gain });
            platform::write_f32(
                block + 0x48,
                platform::read_f32(block + 0x48) + platform::read_f32(block + 0x4C),
            );
        }
    }

    let dot = basis_x * stick_x + basis_y * stick_y;
    let offset_x = half * (platform::read_f32(block + 0x120) + platform::read_f32(block + 0x12C));
    let cross = -basis_y * stick_x + basis_x * stick_y;
    let offset_y = half * (platform::read_f32(block + 0x124) + platform::read_f32(block + 0x130));
    let scale = platform::read_f32(block + 0xEC);
    let projected_y = scale * (platform::read_f32(block + 0xE4) - (dot * offset_x - cross * offset_y));
    let projected_x = scale * (platform::read_f32(block + 0xE8) - (cross * offset_x + dot * offset_y));
    let cos = platform::read_f32(block + 0xD4);
    let sin = platform::read_f32(block + 0xD8);
    let mut point_y = -sin * projected_y + cos * projected_x;
    let mut point_x = -cos * projected_y - sin * projected_x;

    if platform::read_u8(block + 0x5E) == 0 {
        platform::write_f32(block + 0x20, point_y);
        platform::write_f32(block + 0x24, point_x);
        platform::write_u32(block + 0x28, platform::read_u32(SDA_KPAD_4B80));
        platform::write_u32(block + 0x2C, platform::read_u32(SDA_KPAD_4B7C));
        platform::write_f32(block + 0x30, zero);
    } else {
        point_y -= platform::read_f32(block + 0x20);
        point_x -= platform::read_f32(block + 0x24);
        let distance =
            call_f64_1(KPAD_SQRT_802E8620, (point_y * point_y + point_x * point_x) as f64) as f32;
        let point_zone = platform::read_f32(block + 0xB0);

        if platform::read_i32(block + 0x560) == 0 {
            let gain = if distance < point_zone {
                let ratio = distance / point_zone;
                let squared = ratio * ratio;
                squared * squared
            } else {
                one
            } * platform::read_f32(block + 0xB4);
            let delta_y = gain * point_y;
            let delta_x = gain * point_x;
            platform::write_f32(block + 0x28, delta_y);
            platform::write_f32(block + 0x2C, delta_x);
            let magnitude =
                call_f64_1(KPAD_SQRT_802E8620, (delta_y * delta_y + delta_x * delta_x) as f64)
                    as f32;
            platform::write_f32(block + 0x30, magnitude);
            platform::write_f32(
                block + 0x20,
                platform::read_f32(block + 0x20) + platform::read_f32(block + 0x28),
            );
            platform::write_f32(
                block + 0x24,
                platform::read_f32(block + 0x24) + platform::read_f32(block + 0x2C),
            );
        } else if distance <= point_zone {
            platform::write_u32(block + 0x28, platform::read_u32(SDA_KPAD_4B80));
            platform::write_u32(block + 0x2C, platform::read_u32(SDA_KPAD_4B7C));
            platform::write_f32(block + 0x30, zero);
        } else {
            let gain = platform::read_f32(block + 0xB4) * ((distance - point_zone) / distance);
            let delta_y = gain * point_y;
            let delta_x = gain * point_x;
            platform::write_f32(block + 0x28, delta_y);
            platform::write_f32(block + 0x2C, delta_x);
            let magnitude =
                call_f64_1(KPAD_SQRT_802E8620, (delta_y * delta_y + delta_x * delta_x) as f64)
                    as f32;
            platform::write_f32(block + 0x30, magnitude);
            platform::write_f32(
                block + 0x20,
                platform::read_f32(block + 0x20) + platform::read_f32(block + 0x28),
            );
            platform::write_f32(
                block + 0x24,
                platform::read_f32(block + 0x24) + platform::read_f32(block + 0x2C),
            );
        }
    }

    platform::write_u8(block + 0x5E, enable as u8);
}

/// Initialises the four KPAD channel records and their status banks.
///
/// The body runs once (byte `r13-0x4B84`): it starts WPAD, clears the four
/// `0x578`-byte records, installs the connect and sampling callbacks, seeds
/// every limit (dead zones, gains, timers, flags), publishes the caller's
/// status-slot bank into `+0x4BC`/`+0x4C0`, clears sixteen `0x38`-byte status
/// records per channel, converts the clock count into the pointer scale, resets
/// the three extension channels and finally builds the shared cos/sin basis at
/// `0x803A30A8`.
///
/// # Original
/// - Ghidra: `FUN_801edaf0` at `0x801EDAF0` (1,092 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801edaf0_FUN_801edaf0.c`
///
/// # Arguments
/// * `status_bank` - the caller's status-slot area (`r3`, `0x802BD4A0` passes
///   its record `+0x20`).
/// * `size` - the area size word (`r4`, `0x40`); its quarter is the slot count.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// Clears `0x15E0` bytes, writes the four records, two callback installs, one
/// `0x801C1160`-style basis block, the KPAD init flag and the WPAD hook call.
///
/// # Safety
/// `status_bank` must be readable/writable for `(size / 4) * 4 * 0x38` bytes
/// when both arguments are non-zero; the WPAD layer must not be running yet.
///
/// # Confidence
/// medium - every offset, constant and call is literal; the two-argument
/// signature is recovered from the sole caller (`0x802BD4A0`), because the
/// export declares the body `void` and reads both words through the
/// `0x802DCD40` split. The trace calls are omitted (their printer is a no-op).
pub unsafe fn fn_801edaf0(status_bank: u32, size: u32) {
    if platform::read_u8(SDA_KPAD_4B84) != 0 {
        return;
    }

    wpad_start_801dfa50();
    platform::call3(MEMSET, KPAD_BLOCK_BASE as u32, 0, 0x15E0);

    let period = fn_801e3890();
    let zero = platform::read_f32(SDA2_F32_4D38);
    let one = platform::read_f32(SDA2_F32_4D2C);
    let diagonal = platform::read_f32(SDA2_F32_4D24);
    let count = size >> 2;
    let zero64_lo = platform::read_u32(SDA2_F64_4D00);
    let zero64_hi = platform::read_u32(SDA2_F64_4D00 + 4);

    platform::write_f32(SDA_KPAD_5E30, one + (period as u32) as f32);

    let mut channel = 0u32;
    while channel < 4 {
        let block = KPAD_BLOCK_BASE + channel as usize * KPAD_BLOCK_STRIDE;

        platform::write_u32(
            block + 0x550,
            kpad_set_connect_callback_801e1060(channel, 0x801E_DF40),
        );
        platform::write_u32(
            block + 0x54C,
            kpad_set_sampling_callback_801e0fd0(channel, 0x801E_EE30),
        );
        platform::write_u8(block + 0x557, 0);
        platform::write_u8(SDA_KPAD_4B6A, 0);
        platform::write_u8(SDA_KPAD_4B6B, 0);
        platform::write_u8(SDA_KPAD_4B6C, 0);
        platform::write_u8(SDA_KPAD_4B6E, 0);
        platform::write_u16(SDA_KPAD_4B70, 0);
        platform::write_u8(SDA_KPAD_4B6D, 0);

        let mut filter = 0usize;
        while filter < 8 {
            platform::write_u32(KPAD_FILTER_CH3 + filter * 8, zero64_lo);
            platform::write_u32(KPAD_FILTER_CH3 + filter * 8 + 4, zero64_hi);
            filter += 1;
        }

        platform::write_u8(block + 0x556, 1);
        platform::write_u32(block + 0x559, fn_801e3920(channel) as u32);
        platform::write_u8(block + 0x5C, 0xFD);
        platform::write_u8(block + 0x5F, 0);
        platform::write_u32(block + 0xD0, platform::read_u32(SDA_KPAD_5E5C));
        platform::write_u32(block + 0xD4, platform::read_u32(SDA_KPAD_5E58));
        platform::write_u32(block + 0xD8, platform::read_u32(SDA_KPAD_5E54));
        platform::write_u32(block + 0xDC, platform::read_u32(SDA_KPAD_5E50));
        platform::write_u32(block + 0xE0, platform::read_u32(SDA_KPAD_5E4C));
        platform::write_u32(block + 0xE4, platform::read_u32(SDA_KPAD_4B98));
        platform::write_u32(block + 0xE8, platform::read_u32(SDA_KPAD_4B94));

        let length = call_f64_1(
            KPAD_SQRT_802E8620,
            ((one * one) + (diagonal * diagonal)) as f64,
        ) as f32;
        let offset_x = platform::read_f32(block + 0xE4);
        let offset_y = platform::read_f32(block + 0xE8);
        let mut horizontal = one;
        let mut vertical = diagonal;
        if zero <= offset_x {
            horizontal -= offset_x;
        } else {
            horizontal += offset_x;
        }
        if zero <= offset_y {
            vertical -= offset_y;
        } else {
            vertical += offset_y;
        }
        let smaller = if horizontal < vertical {
            horizontal
        } else {
            vertical
        };
        platform::write_f32(block + 0xEC, length / smaller);

        platform::write_f32(block + 0xC8, zero);
        platform::write_f32(block + 0xC0, zero);
        platform::write_f32(block + 0xB8, zero);
        platform::write_f32(block + 0xB0, zero);
        platform::write_f32(block + 0xCC, one);
        platform::write_f32(block + 0xC4, one);
        platform::write_f32(block + 0xBC, one);
        platform::write_f32(block + 0xB4, one);
        platform::write_u32(block + 0x56C, 0);
        platform::write_u32(block + 0x568, 0);
        platform::write_u32(block + 0x564, 0);
        platform::write_u32(block + 0x560, 0);
        platform::write_u16(block + 0x504, 40000);
        platform::write_u16(block + 0x506, 0);
        platform::write_u16(block + 0x500, 0);
        platform::write_u16(block + 0x502, 40000);
        platform::write_u16(block + 0x508, 0);
        platform::write_u16(block + 0x50A, 40000);
        platform::write_u8(block + 0x55F, 0);
        platform::write_u8(block + 0x55C, 1);
        platform::write_u8(block + 0x55D, 1);
        platform::write_u8(block + 0x574, 1);
        platform::write_u8(block + 0x55E, 0);

        if size == 0 || status_bank == 0 {
            platform::write_u32(block + 0x4C0, 0);
            platform::write_u32(block + 0x4BC, 0);
        } else {
            platform::write_u32(block + 0x4C0, count);
            platform::write_u32(
                block + 0x4BC,
                status_bank
                    .wrapping_add(count.wrapping_mul(channel).wrapping_mul(0x38)),
            );
        }

        let mut status = 0usize;
        while status < 16 {
            platform::write_u8(block + 0x165 + status * 0x38, 0xFF);
            status += 1;
        }

        let base = platform::read_u32(block + 0x4BC) as usize;
        let mut slot = 0u32;
        while slot < platform::read_u32(block + 0x4C0) {
            platform::write_u8(base + slot as usize * 0x38 + 0x29, 0xFF);
            slot += 1;
        }

        channel += 1;
    }

    fn_801e5450(1);

    let raw_scale = platform::read_f32(SDA_KPAD_5E48);
    let divisor = platform::read_f32(SDA2_F32_4CE8);
    let token = disable_interrupts();
    platform::write_f32(SDA_KPAD_5E48, raw_scale);
    let scale = (raw_scale as f64 / divisor as f64) as f32;
    platform::write_f32(SDA_KPAD_4B64, scale);
    platform::write_f32(SDA_KPAD_4B68, scale);
    restore_interrupts(token);

    let mut channel = 3i32;
    let mut block = 0x803A_2B30usize;
    loop {
        if fn_801f3530() == 3 {
            fn_801e14e0(channel as u32, 0);
        }
        platform::write_u8(block + 0x554, 1);
        channel -= 1;
        if channel < 0 {
            break;
        }
        block -= KPAD_BLOCK_STRIDE;
    }

    platform::write_f32(KPAD_BASIS_30A8, one);
    platform::write_f32(KPAD_BASIS_30A8 + 4, zero);
    platform::write_f32(KPAD_BASIS_30A8 + 8, zero);
    platform::write_f32(KPAD_BASIS_30A8 + 0xC, zero);
    platform::write_f32(KPAD_BASIS_30A8 + 0x10, zero);

    let angle =
        platform::read_f32(SDA2_F32_4CE4) * platform::read_f32(SDA_KPAD_5DE4);
    let cosine = call_f64_1(KPAD_COS_802E7FBC, angle as f64) as f32;
    let sine = call_f64_1(KPAD_SIN_802E84C4, angle as f64) as f32;
    platform::write_f32(KPAD_BASIS_30A8 + 0x14, cosine);
    platform::write_f32(KPAD_BASIS_30A8 + 0x18, -sine);
    platform::write_f32(KPAD_BASIS_30A8 + 0x1C, zero);
    platform::write_f32(KPAD_BASIS_30A8 + 0x20, zero);
    platform::write_f32(KPAD_BASIS_30A8 + 0x24, sine);
    platform::write_f32(KPAD_BASIS_30A8 + 0x28, cosine);
    platform::write_f32(KPAD_BASIS_30A8 + 0x2C, zero);

    platform::write_u8(SDA_KPAD_4B84, 1);
    platform::call1(WPAD_ARG_HOOK, platform::read_u32(SDA_KPAD_5E60));
}

/// Forwards to the long WPAD command writer at `0x801ED3C0`.
///
/// The 8-byte body is `bl 0x801ED3C0; blr`, so every argument register reaches
/// the callee unchanged. `0x801ED3C0` is still untranslated (see
/// `docs/COVERAGE_WAVE103_INPUT.md`), so the five words are forwarded by
/// address.
///
/// # Original
/// - Ghidra: `FUN_801ed3b0` at `0x801ED3B0` (8 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801ed3b0_FUN_801ed3b0.c`
///
/// # Arguments
/// * `channel`, `record`, `mode` - the three words every caller supplies.
/// * `arg3`, `arg4` - the remaining two words `0x801ED3C0` declares.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// Exactly those of `0x801ED3C0` (it queues `0x30`-byte command records).
///
/// # Safety
/// `record` must be the structure `0x801ED3C0` expects for `channel`.
///
/// # Confidence
/// medium - the single call and the return are literal; the argument list is
/// the callee's five-word signature, which the only caller
/// (`0x802D71F0`, passing three words) fills.
pub unsafe fn fn_801ed3b0(channel: u32, record: u32, mode: u32, arg3: u32, arg4: u32) {
    platform::call5(0x801E_D3C0, channel, record, mode, arg3, arg4);
}

/// Refreshes one channel's sensor-bar samples and runs the pointer matcher.
///
/// For report types `2`, `5`, `8` (and `0x0B` when `+0x557` is set) the four
/// packed 16-bit sensor pairs at `sample+8`..`sample+0x20` are converted into
/// the four `0xF0`-based points, scaled by the `r2-0x4D10` constant. Points
/// outside the `+0x528`..`+0x534` window are flagged, coincident points are
/// marked with status `2`, and the surviving points are counted at `+0x138`.
/// Above the `r13-0x5E1C` trigger level the matcher picks a pair with
/// `0x801EB5C0`/`0x801EB7B0`/`0x801EB9E0`/`0x801EBBA0`, recomputes the
/// sensor-bar direction, and hands the verdict to [`fn_801ebd20`]. Any other
/// report type marks all four points invalid.
///
/// # Original
/// - Ghidra: `FUN_801ec2f0` at `0x801EC2F0` (1,148 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801ec2f0_FUN_801ec2f0.c`
///
/// # Arguments
/// * `block` - one `0x578`-byte KPAD channel record.
/// * `sample` - the raw report; the sensor pairs start at `+0x20` and the type
///   byte is `+0x36`.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// The four point slots, their status bytes, the hit count `+0x138`, the
/// direction/scale words `+0x4C4`..`+0x4F0`, the press flag `+0x128` and the
/// aim filter banks through [`fn_801ebd20`].
///
/// # Safety
/// `block` must be a live channel record and `sample` readable through
/// `+0x36`.
///
/// # Confidence
/// medium - the conversion loop, both status passes, the pair count and every
/// matcher call are literal; the four matcher results are read back through
/// `0x802DCDB8` because the translated bodies return `()`.
pub unsafe fn fn_801ec2f0(block: usize, sample: usize) {
    let one = platform::read_f32(SDA2_F32_4D2C);
    let report_type = platform::read_u8(sample + 0x36) as i8;

    let active = report_type == 2
        || report_type == 5
        || report_type == 8
        || (report_type == 0x0B && platform::read_u8(block + 0x557) != 0);

    if active {
        let scale = platform::read_f32(SDA2_F32_4D10);
        let offset_x = platform::read_f32(SDA2_F32_4D0C);
        let offset_y = platform::read_f32(SDA2_F32_4D08);

        let mut point = block + 0x114;
        let mut pair = sample + 0x20;
        loop {
            if platform::read_u16(pair + 4) == 0 {
                platform::write_u8(point + 8, 0xFF);
            } else {
                let x = platform::read_u16(pair) as i16 as i32 as f64 as f32;
                let y = platform::read_u16(pair + 2) as i16 as i32 as f64 as f32;
                platform::write_f32(point, scale * x - offset_x);
                platform::write_f32(point + 4, scale * y - offset_y);
                platform::write_u8(point + 8, 0);
                platform::write_u8(point + 9, 0);
            }
            point -= 0xC;
            pair -= 8;
            if point < block + 0xF0 {
                break;
            }
        }
    } else {
        let mut point = block + 0x114;
        loop {
            platform::write_u8(point + 8, 0xFF);
            point -= 0xC;
            if point < block + 0xF0 {
                break;
            }
        }
    }

    let mut point = block + 0x114;
    loop {
        let status = platform::read_u8(point + 8);
        if (status as i8) >= 0
            && (platform::read_f32(point) <= platform::read_f32(block + 0x528)
                || platform::read_f32(block + 0x530) <= platform::read_f32(point)
                || platform::read_f32(point + 4) <= platform::read_f32(block + 0x52C)
                || platform::read_f32(block + 0x534) <= platform::read_f32(point + 4))
        {
            platform::write_u8(point + 8, status | 1);
        }
        point -= 0xC;
        if point < block + 0xF0 {
            break;
        }
    }

    let mut first = block + 0xF0;
    while first < block + 0x114 {
        if platform::read_u8(first + 8) == 0 {
            let mut second = first + 0xC;
            while second <= block + 0x114 {
                if platform::read_u8(second + 8) == 0
                    && platform::read_f32(first) == platform::read_f32(second)
                    && platform::read_f32(first + 4) == platform::read_f32(second + 4)
                {
                    platform::write_u8(second + 8, 2);
                }
                second += 0xC;
            }
        }
        first += 0xC;
    }

    platform::write_u16(block + 0x138, 0);
    let mut point = block + 0x114;
    loop {
        if platform::read_u8(point + 8) == 0 {
            let count = platform::read_u16(block + 0x138).wrapping_add(1);
            platform::write_u16(block + 0x138, count);
        }
        point -= 0xC;
        if point < block + 0xF0 {
            break;
        }
    }

    let mut verdict = 0u32;
    if platform::read_f32(SDA_KPAD_5E1C) < platform::read_f32(block + 0x54) {
        let mode = platform::read_u8(block + 0x5E) as i8;
        let count = platform::read_u16(block + 0x138) as i16;
        if mode == 2 || mode == -2 {
            if count > 1 && call0_ret(0x801E_B7B0) != 0 {
                verdict = 2;
            } else if count > 0 {
                verdict = call0_ret(0x801E_BBA0);
            }
        } else if mode == 1 || mode == -1 {
            if count > 1 && call0_ret(0x801E_B5C0) != 0 {
                verdict = 2;
            } else if count > 0 {
                verdict = call0_ret(0x801E_BBA0);
            }
        } else {
            if count > 1 && call0_ret(0x801E_B5C0) != 0 {
                verdict = 2;
            } else if count == 1 {
                verdict = call0_ret(0x801E_B9E0);
            }
        }
    }

    if verdict == 0 {
        platform::write_u8(block + 0x4FE, 0);
    } else {
        let dx = platform::read_f32(block + 0x12C) - platform::read_f32(block + 0x120);
        let dy = platform::read_f32(block + 0x130) - platform::read_f32(block + 0x124);
        let length = call_f64_1(KPAD_SQRT_802E8620, (dx * dx + dy * dy) as f64) as f32;
        let inverse = (one / length) as f64;
        platform::write_f32(block + 0x4C4, length);
        let unit_x = (dx as f64 * inverse) as f32;
        let unit_y = (dy as f64 * inverse) as f32;
        platform::write_f32(block + 0x4C8, unit_x);
        platform::write_f32(block + 0x4CC, unit_y);
        platform::write_f32(
            block + 0x4D0,
            (platform::read_f32(block + 0x544) as f64 * inverse) as f32,
        );
        let rotated_x = platform::read_f32(block + 0xDC) * unit_x
            + platform::read_f32(block + 0xE0) * unit_y;
        let rotated_y = platform::read_f32(block + 0xE0) * unit_x
            - platform::read_f32(block + 0xDC) * unit_y;
        platform::write_f32(block + 0x4E4, rotated_x);
        platform::write_f32(block + 0x4E8, rotated_y);

        if platform::read_u16(block + 0x4FC) == 0
            && rotated_x * platform::read_f32(block + 0x4EC)
                + rotated_y * platform::read_f32(block + 0x4F0)
                <= platform::read_f32(SDA_KPAD_5E20)
        {
            platform::write_u8(block + 0x134, 1);
            verdict = 0;
            platform::write_u8(block + 0x128, 1);
        }

        if platform::read_u8(block + 0x5E) == 2 && verdict == 2 {
            if platform::read_u8(block + 0x4FE) == 0xC8 {
                platform::write_f32(block + 0x4D4, platform::read_f32(block + 0x4C4));
            } else {
                let pressed = platform::read_u8(block + 0x4FE).wrapping_add(1);
                platform::write_u8(block + 0x4FE, pressed);
            }
        } else {
            platform::write_u8(block + 0x4FE, 0);
        }
    }

    fn_801ebd20(block, verdict as i32);
}

/// `r13-0x4B90`: selects the alternate axis mapper `0x801EC8A0` instead of
/// `0x801EC770` in [`fn_801ecad0`]. // unknown: what sets it.
const SDA_KPAD_4B90: usize = SDA_BASE - 0x4B90;
/// `r13-0x4B88`: lower bound of the two stick axes of the `0x0B` report.
const SDA_KPAD_4B88: usize = SDA_BASE - 0x4B88;
/// `r13-0x5DF0`: upper bound of the two stick axes of the `0x0B` report.
const SDA_KPAD_5DF0: usize = SDA_BASE - 0x5DF0;
/// `r13-0x4B8C` / `r13-0x5DF4`: bounds of the four trigger bytes.
const SDA_KPAD_4B8C: usize = SDA_BASE - 0x4B8C;
const SDA_KPAD_5DF4: usize = SDA_BASE - 0x5DF4;
/// `r13-0x5E04` / `r13-0x5E00`: bounds of the two stick bytes of the `0x06`
/// report.
const SDA_KPAD_5E04: usize = SDA_BASE - 0x5E04;
const SDA_KPAD_5E00: usize = SDA_BASE - 0x5E00;
/// `r13-0x5E0C` / `r13-0x5E08`: dead-zone half-width and limit handed to the
/// axis mapper for the two `0x06` axes.
const SDA_KPAD_5E0C: usize = SDA_BASE - 0x5E0C;
const SDA_KPAD_5E08: usize = SDA_BASE - 0x5E08;
/// `r13-0x5E14` / `r13-0x5E10`: the same pair for the type-1 axes.
const SDA_KPAD_5E14: usize = SDA_BASE - 0x5E14;
const SDA_KPAD_5E10: usize = SDA_BASE - 0x5E10;
/// `r13-0x5DE8`: the filter weight of the balance-board running average.
const SDA_KPAD_5DE8: usize = SDA_BASE - 0x5DE8;
/// `r13-0x4B78`: the balance-board result place-holder (a double) and the
/// address the TGC query writes.
const SDA_KPAD_4B78: usize = SDA_BASE - 0x4B78;
/// `r2-0x4CF8`: the weight below which the TGC result is rejected.
const SDA2_F64_4CF8: usize = SDA2_BASE - 0x4CF8;

/// Reads a big-endian `f64` from two 32-bit words.
///
/// # Safety
/// `addr` must be readable for eight bytes.
unsafe fn kpad_read_f64(addr: usize) -> f64 {
    f64::from_bits(
        ((platform::read_u32(addr) as u64) << 32) | platform::read_u32(addr + 4) as u64,
    )
}

/// Writes a big-endian `f64` as two 32-bit words.
///
/// # Safety
/// `addr` must be writable for eight bytes.
unsafe fn kpad_write_f64(addr: usize, value: f64) {
    let bits = value.to_bits();
    platform::write_u32(addr, (bits >> 32) as u32);
    platform::write_u32(addr + 4, bits as u32);
}

/// Maps one axis value into `0.0..=1.0` between two bounds.
///
/// Below or at `low` the result is `0.0`, at or above `high` it is `1.0`, and
/// in between it is the linear ratio. This is the clamp the export spells with
/// the integer-to-double magic sequence in each of the four report branches of
/// [`fn_801ecad0`].
///
/// # Safety
/// None; all three values are plain integers.
unsafe fn kpad_axis_ratio(value: i32, low: i32, high: i32) -> f32 {
    if low < value {
        if value < high {
            ((value - low) as f64 / (high - low) as f64) as f32
        } else {
            1.0
        }
    } else {
        0.0
    }
}

/// Calls a routine with one `f64` and two integer arguments.
///
/// [`crate::platform`] has no floating-point call helper with this shape; the
/// balance-board query `0x801DDB20` takes its weight in `f1` and two pointers
/// in `r4`/`r5`.
///
/// # Safety
/// `addr` must accept the `(f64, u32, u32)` ABI and return a word.
unsafe fn call_f64_2ptr(addr: usize, value: f64, a: u32, b: u32) -> u32 {
    let func = crate::platform::guest_fn!(addr, fn(f64, u32, u32) -> u32);
    func(value, a, b)
}

/// Applies one extension report to a KPAD channel record.
///
/// Five report families are handled, keyed by the extension type byte at
/// `sample+0x28` and the report id at `sample+0x36`:
///
/// * type `1`, reports `3`..`5` - two signed bytes at `+0x30`/`+0x31` are fed
///   to the axis mapper selected by `r13-0x4B90` and written to the point at
///   `+0x60`.
/// * type `2`, reports `6`..`8` - two signed pairs (`+0x2C`/`+0x2E` and
///   `+0x30`/`+0x32`) go to `+0x6C`/`+0x74`, and the two trigger bytes
///   `+0x34`/`+0x35` become linear ratios at `+0x7C`/`+0x80`.
/// * type `0x11`, report `0x0B` - one stick pair plus the four trigger bytes.
/// * type `0x10`, report `0x0A` - the trigger bytes only; the axes are
///   zeroed.
/// * type `3`, report `0x0C` - the balance-board ladder: a status gate, the
///   four-point query, two weighted averages (fast and slow) and the TGC
///   weight query.
///
/// Each family first clears the "new extension" byte `+0x555` and resets its
/// state when that byte was set.
///
/// # Original
/// - Ghidra: `FUN_801ecad0` at `0x801ECAD0` (2,256 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801ecad0_FUN_801ecad0.c`
///
/// # Arguments
/// * `block` - one `0x578`-byte KPAD channel record.
/// * `sample` - the extension report.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// The point/tilt/trigger words `+0x60`..`+0x80`, the balance-board status
/// `+0xA8`, its averages `+0x88`..`+0xA0`, the shared accumulators at
/// `0x803A30D8`, and the `r13-0x4B6D`..`-0x4B70` counters.
///
/// # Safety
/// `block` must be a live channel record and `sample` readable through
/// `+0x36`.
///
/// # Confidence
/// medium - every branch, bound and store is literal; the extension-type roles
/// are inferred from the report ids (only type `3` is proven by the
/// balance-board calls), and the balance-board ladder is unreachable in this
/// build because `0x801DDAB0` always returns `0`.
pub unsafe fn fn_801ecad0(block: usize, sample: usize) {
    let zero = platform::read_f32(SDA2_F32_4D38);
    let one = platform::read_f32(SDA2_F32_4D2C);
    let extension_type = platform::read_u8(sample + 0x28) as i8;
    let report = platform::read_u8(sample + 0x36) as i8;

    let mut transform = 0x801E_C770usize;
    if platform::read_i32(SDA_KPAD_4B90) != 0 {
        transform = 0x801E_C8A0;
    }

    if extension_type == 1 && (report as u8).wrapping_sub(3) < 3 {
        if platform::read_u8(block + 0x555) != 0 {
            platform::write_u8(block + 0x555, 0);
            platform::write_u32(block + 0x60, platform::read_u32(SDA_KPAD_4B80));
            platform::write_u32(block + 0x64, platform::read_u32(SDA_KPAD_4B7C));
            platform::write_f32(block + 0x68, zero);
            platform::write_f32(block + 0x6C, platform::read_f32(SDA2_F32_4D30));
            platform::write_f32(block + 0x70, zero);
            platform::write_f32(block + 0x74, one);
            platform::write_f32(block + 0x78, zero);
        }
        platform::call5(
            transform,
            (block + 0x60) as u32,
            platform::read_u8(sample + 0x30) as i8 as i32 as u32,
            platform::read_u8(sample + 0x31) as i8 as i32 as u32,
            platform::read_u32(SDA_KPAD_5E14),
            platform::read_u32(SDA_KPAD_5E10),
        );
    } else if extension_type == 2 && (report as u8).wrapping_sub(6) < 3 {
        if platform::read_u8(block + 0x555) != 0 {
            platform::write_u8(block + 0x555, 0);
            platform::write_u32(block + 0x70, platform::read_u32(SDA_KPAD_4B7C));
            platform::write_u32(block + 0x6C, platform::read_u32(SDA_KPAD_4B80));
            platform::write_u32(block + 0x78, platform::read_u32(SDA_KPAD_4B7C));
            platform::write_u32(block + 0x74, platform::read_u32(SDA_KPAD_4B80));
            platform::write_f32(block + 0x80, zero);
            platform::write_f32(block + 0x7C, zero);
            platform::write_u32(block + 0x68, 0);
            platform::write_u32(block + 0x64, 0);
            platform::write_u32(block + 0x60, 0);
            platform::write_u16(block + 0x508, 0);
            platform::write_u16(block + 0x50A, platform::read_u16(block + 0x504));
        }
        platform::call5(
            transform,
            (block + 0x6C) as u32,
            platform::read_u16(sample + 0x2C) as i16 as i32 as u32,
            platform::read_u16(sample + 0x2E) as i16 as i32 as u32,
            platform::read_u32(SDA_KPAD_5E0C),
            platform::read_u32(SDA_KPAD_5E08),
        );
        platform::call5(
            transform,
            (block + 0x74) as u32,
            platform::read_u16(sample + 0x30) as i16 as i32 as u32,
            platform::read_u16(sample + 0x32) as i16 as i32 as u32,
            platform::read_u32(SDA_KPAD_5E0C),
            platform::read_u32(SDA_KPAD_5E08),
        );
        platform::write_f32(
            block + 0x7C,
            kpad_axis_ratio(
                platform::read_u8(sample + 0x34) as i32,
                platform::read_i32(SDA_KPAD_5E04),
                platform::read_i32(SDA_KPAD_5E00),
            ),
        );
        platform::write_f32(
            block + 0x80,
            kpad_axis_ratio(
                platform::read_u8(sample + 0x35) as i32,
                platform::read_i32(SDA_KPAD_5E04),
                platform::read_i32(SDA_KPAD_5E00),
            ),
        );
    } else if extension_type == 0x11 && report == 0x0B {
        if platform::read_u8(block + 0x555) != 0 {
            platform::write_u8(block + 0x555, 0);
            platform::write_u32(block + 0x70, platform::read_u32(SDA_KPAD_4B7C));
            platform::write_u32(block + 0x6C, platform::read_u32(SDA_KPAD_4B80));
            platform::write_u32(block + 0x78, platform::read_u32(SDA_KPAD_4B7C));
            platform::write_u32(block + 0x74, platform::read_u32(SDA_KPAD_4B80));
            platform::write_f32(block + 0x80, zero);
            platform::write_f32(block + 0x7C, zero);
            platform::write_u32(block + 0x68, 0);
            platform::write_u32(block + 0x64, 0);
            platform::write_u32(block + 0x60, 0);
            platform::write_u16(block + 0x508, 0);
            platform::write_u16(block + 0x50A, platform::read_u16(block + 0x504));
        }
        platform::call5(
            transform,
            (block + 0x6C) as u32,
            platform::read_u16(sample + 0x2C) as i16 as i32 as u32,
            platform::read_u16(sample + 0x2E) as i16 as i32 as u32,
            platform::read_u32(SDA_KPAD_5E0C),
            platform::read_u32(SDA_KPAD_5E08),
        );
        platform::write_f32(
            block + 0x74,
            kpad_axis_ratio(
                platform::read_u16(sample + 0x30) as i16 as i32,
                platform::read_i32(SDA_KPAD_4B88),
                platform::read_i32(SDA_KPAD_5DF0),
            ),
        );
        platform::write_f32(
            block + 0x78,
            kpad_axis_ratio(
                platform::read_u16(sample + 0x32) as i16 as i32,
                platform::read_i32(SDA_KPAD_4B88),
                platform::read_i32(SDA_KPAD_5DF0),
            ),
        );
        platform::write_f32(
            block + 0x7C,
            kpad_axis_ratio(
                platform::read_u8(sample + 0x34) as i32,
                platform::read_i32(SDA_KPAD_4B8C),
                platform::read_i32(SDA_KPAD_5DF4),
            ),
        );
        platform::write_f32(
            block + 0x80,
            kpad_axis_ratio(
                platform::read_u8(sample + 0x35) as i32,
                platform::read_i32(SDA_KPAD_4B8C),
                platform::read_i32(SDA_KPAD_5DF4),
            ),
        );
    } else if extension_type == 0x10 && report == 0x0A {
        if platform::read_u8(block + 0x555) != 0 {
            platform::write_u8(block + 0x555, 0);
            platform::write_u32(block + 0x70, platform::read_u32(SDA_KPAD_4B7C));
            platform::write_u32(block + 0x6C, platform::read_u32(SDA_KPAD_4B80));
            platform::write_u32(block + 0x78, platform::read_u32(SDA_KPAD_4B7C));
            platform::write_u32(block + 0x74, platform::read_u32(SDA_KPAD_4B80));
            platform::write_f32(block + 0x80, zero);
            platform::write_f32(block + 0x7C, zero);
            platform::write_u32(block + 0x68, 0);
            platform::write_u32(block + 0x64, 0);
            platform::write_u32(block + 0x60, 0);
            platform::write_u16(block + 0x508, 0);
            platform::write_u16(block + 0x50A, platform::read_u16(block + 0x504));
        }
        platform::write_f32(block + 0x70, zero);
        platform::write_f32(block + 0x6C, zero);
        platform::write_f32(block + 0x78, zero);
        platform::write_f32(block + 0x74, zero);
        platform::write_f32(
            block + 0x7C,
            kpad_axis_ratio(
                platform::read_u8(sample + 0x2C) as i32,
                platform::read_i32(SDA_KPAD_4B8C),
                platform::read_i32(SDA_KPAD_5DF4),
            ),
        );
        platform::write_f32(
            block + 0x80,
            kpad_axis_ratio(
                platform::read_u8(sample + 0x2D) as i32,
                platform::read_i32(SDA_KPAD_4B8C),
                platform::read_i32(SDA_KPAD_5DF4),
            ),
        );
    } else if extension_type == 3 && report == 0x0C {
        if platform::read_u8(block + 0x555) != 0 {
            platform::write_u8(block + 0x555, 0);
            let reset = kpad_read_f64(SDA2_F64_4D00);
            let mut accumulator = 0usize;
            while accumulator < 8 {
                kpad_write_f64(KPAD_FILTER_CH3 + accumulator * 8, reset);
                accumulator += 1;
            }
            platform::write_u8(SDA_KPAD_4B6E, 0);
            platform::write_u16(SDA_KPAD_4B70, 0);
            platform::write_u8(SDA_KPAD_4B6D, 0);
        }

        let status = platform::call1(0x801D_DAB0, platform::read_u8(sample + 0x33) as u32) as i32;
        if status == 0 {
            platform::write_i32(block + 0xA8, -1);
        } else if platform::read_u8(SDA_KPAD_4B6E) < 3 {
            platform::write_i32(block + 0xA8, -2);
        } else if platform::read_u8(sample + 0x32) as i8 == 0x7F
            || platform::read_u8(sample + 0x32) as i8 == -0x80
        {
            platform::write_i32(block + 0xA8, -3);
        } else {
            let result = platform::call3(
                0x801D_DAC0,
                sample as u32,
                (block + 0x68) as u32,
                4,
            ) as i32;
            platform::write_i32(block + 0xA8, result);

            let mut fast = [
                kpad_read_f64(KPAD_FILTER_CH3 + 0x20),
                kpad_read_f64(KPAD_FILTER_CH3 + 0x28),
                kpad_read_f64(KPAD_FILTER_CH3 + 0x30),
                kpad_read_f64(KPAD_FILTER_CH3 + 0x38),
            ];

            if result >= 0 {
                let weight = platform::read_f32(SDA_KPAD_5DE8) as f64;
                let first = kpad_read_f64(block + 0x68);
                let divisor = ((one as f64) + weight) as f32 as f64;

                fast[0] = (weight * fast[0] + first) / divisor;
                fast[1] = (weight * fast[1] + kpad_read_f64(block + 0x70)) / divisor;
                fast[2] = (weight * fast[2] + kpad_read_f64(block + 0x78)) / divisor;
                fast[3] = (weight * fast[3] + kpad_read_f64(block + 0x80)) / divisor;
                kpad_write_f64(KPAD_FILTER_CH3 + 0x20, fast[0]);
                kpad_write_f64(KPAD_FILTER_CH3 + 0x28, fast[1]);
                kpad_write_f64(KPAD_FILTER_CH3 + 0x30, fast[2]);
                kpad_write_f64(KPAD_FILTER_CH3 + 0x38, fast[3]);

                if platform::read_u8(SDA_KPAD_4B6D) != 0 {
                    let samples = platform::read_u16(SDA_KPAD_4B70).wrapping_add(1);
                    platform::write_u16(SDA_KPAD_4B70, samples);
                    let previous = (samples as i32 - 1) as f64;
                    let count = samples as f64;

                    let slow_1 = (previous * kpad_read_f64(KPAD_FILTER_CH3) + first) / count;
                    let slow_2 = (previous * kpad_read_f64(KPAD_FILTER_CH3 + 8)
                        + kpad_read_f64(block + 0x70))
                        / count;
                    let slow_3 = (previous * kpad_read_f64(KPAD_FILTER_CH3 + 0x10)
                        + kpad_read_f64(block + 0x78))
                        / count;
                    let slow_4 = (previous * kpad_read_f64(KPAD_FILTER_CH3 + 0x18)
                        + kpad_read_f64(block + 0x80))
                        / count;
                    kpad_write_f64(KPAD_FILTER_CH3, slow_1);
                    kpad_write_f64(KPAD_FILTER_CH3 + 8, slow_2);
                    kpad_write_f64(KPAD_FILTER_CH3 + 0x10, slow_3);
                    kpad_write_f64(KPAD_FILTER_CH3 + 0x18, slow_4);

                    if (count as f32) as f64 == weight {
                        let total = slow_1 + slow_2;
                        platform::write_u8(SDA_KPAD_4B6D, 0);
                        let query = call_f64_2ptr(
                            0x801D_DB20,
                            slow_4 + slow_3 + total,
                            SDA_KPAD_4B78 as u32,
                            sample as u32,
                        );
                        platform::write_i32(block + 0xA8, query as i32);
                        if kpad_read_f64(SDA_KPAD_4B78) < kpad_read_f64(SDA2_F64_4CF8) {
                            platform::write_i32(block + 0xA8, -4);
                        }
                    }
                }
            }

            kpad_write_f64(block + 0x88, fast[0]);
            kpad_write_f64(block + 0x90, fast[1]);
            kpad_write_f64(block + 0x98, fast[2]);
            kpad_write_f64(block + 0xA0, fast[3]);
            kpad_write_f64(block + 0x60, kpad_read_f64(SDA_KPAD_4B78));
            platform::write_u32(
                block + 0xAC,
                platform::read_u8(SDA_KPAD_4B6D) as u32,
            );
        }
    }
}

// ===========================================================================
// Seventeenth pass (wave 106): the two KPAD random self-test report builders
// and the ring/flush path they feed.
// ===========================================================================

/// Forwards to the ring-flush routine at `0x801ED3C0`.
///
/// The export is a bare tail call with no visible arguments; the three callers
/// (for example the console loop at `0x802D71F0`) pass `(channel, buffer,
/// length)` and expect the buffer to be filled, so the five words are forwarded
/// unchanged exactly like the sibling [`fn_801ed3b0`].
///
/// # Original
/// - Ghidra: `FUN_801ed3a0` at `0x801ED3A0` (12 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801ed3a0_FUN_801ed3a0.c`
///
/// # Arguments
/// * `channel` - the `0..=3` KPAD channel.
/// * `buffer` - destination for the flushed `0xB0`-byte status records.
/// * `length` - maximum number of records to flush.
/// * `status_out` - optional word that receives the result code.
/// * `keep` - non-zero preserves the caller's leading record.
///
/// # Returns
/// `()`; the status travels through `0x802DCDA4` inside the callee.
///
/// # Side effects
/// Everything [`fn_801ed3c0`] does.
///
/// # Safety
/// Same contract as [`fn_801ed3c0`].
///
/// # Confidence
/// high - the single call is the whole body; the five-word signature is the
/// same recovery the sibling forwarder already uses.
pub unsafe fn fn_801ed3a0(channel: u32, buffer: u32, length: u32, status_out: u32, keep: u32) {
    platform::call5(0x801E_D3C0, channel, buffer, length, status_out, keep);
}

/// Returns the ring slot for `index`, wrapping the `0x10`-slot inline bank and
/// the caller-provided overflow bank.
///
/// Slots `0..=0xF` live inline at `block + 0x13C`; the rest live in the bank
/// whose pointer the init published at `block + 0x4BC`. Every slot is `0x38`
/// bytes and the status byte is `+0x29`.
unsafe fn kpad_ring_slot(block: usize, index: i32) -> usize {
    if index < 0x10 {
        block + 0x13C + index as usize * 0x38
    } else {
        platform::read_u32(block + 0x4BC) as usize + (index as usize - 0x10) * 0x38
    }
}

/// Flushes the channel's pending status ring into the caller's record buffer.
///
/// This is the worker behind `0x801ED3A0`/`0x801ED3B0`, i.e. the KPAD read
/// path. It validates the layer (`r13-0x4B84`), the link state (`0x801F3530`
/// must be `3`) and a per-channel busy byte (`+0x4FF`) before touching the
/// ring. On a probe failure (`0x801E0F40` returns `-1`) it resets the block and
/// reports `-2`; while another reader owns the channel it reports `-4`.
///
/// Otherwise it copies the caller's leading `0xB0`-byte record to a stack
/// image, marks the newest ring run (`0xF9` start, `0xFE` end, `0xFC` for a
/// stale report type), then copies up to `length` slots back into the caller's
/// buffer as `0xB0`-byte records. Two layouts are supported: flag `+0x55F`
/// set processes each record on its own through `0x801EAD30` with mode `1`,
/// the other path first folds the oldest record's axis words into one
/// `0x801EAD30(block, type, count, ...)` call and then runs the decode chain.
/// Every processed record ends with a fresh copy of the block's leading `0xB0`
/// bytes, and the caller's leading record is restored when `keep` is non-zero.
///
/// # Original
/// - Removed: the `_restgpr_20` epilogue call (`0x802DCDA4`).
///   The epilogue `bl` returns no value; the argument it was passed is the routine's `r3` return.
/// - Ghidra: `FUN_801ed3c0` at `0x801ED3C0` (1,836 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801ed3c0_FUN_801ed3c0.c`
///
/// # Arguments
/// * `channel` - the `0..=3` KPAD channel (the high half of the `0x802DCD58`
///   split).
/// * `buffer` - the caller's `0xB0`-byte record area (the low half).
/// * `length` - maximum number of slots to flush; clamped to the ring fill.
/// * `status_out` - optional pointer that receives the result code.
/// * `keep` - non-zero restores the caller's leading record and suppresses the
///   `+0x5E` clear for non-sample records.
///
/// # Returns
/// `()`; the code is `0` (flushed), `-1` (nothing pending), `-2` (probe
/// failed), `-3` (link down), `-4` (busy) or `-5` (layer not initialised), and
/// travels back through `0x802DCDA4`.
///
/// # Side effects
/// The caller's buffer, the ring status bytes, the block bytes
/// `+0x5C`..`+0x60`/`+0x554`..`+0x55F`, the connect callback when the probe
/// fails, two interrupt-lock pairs and the three KPAD filter steps.
///
/// # Safety
/// The channel must be `0..=3`; `buffer` must be writable for `length` records
/// of `0xB0` bytes and `status_out` for one word when non-zero. The ring banks
/// must be the ones the KPAD init published.
///
/// # Confidence
/// medium - every offset, ring index, status marker and call is literal; the
/// `0xB0`-record layout is `// inferred:` from the two symmetric copies, the
/// first ring pass leaves its two sentinel words undefined for report kinds
/// other than `0`, `-2` and `-7` (the export's only consistent reading is the
/// `0xFFFF` default), and the inner lock pair discards its token in the export.
pub unsafe fn fn_801ed3c0(
    channel: u32,
    buffer: u32,
    length: u32,
    status_out: u32,
    keep: u32,
) {
    let block = KPAD_BLOCK_BASE + channel as usize * KPAD_BLOCK_STRIDE;
    let buffer = buffer as usize;
    let mut status: i32 = 0;
    let mut copied: i32 = 0;
    let mut image = crate::platform::GuestLocal::new( [0u8; 0xB0]);

    if platform::read_u8(SDA_KPAD_4B84) == 0 {
        status = -5;
    } else if fn_801f3530() != 3 {
        status = -3;
    } else {
        let token = disable_interrupts();
        if platform::read_u8(block + 0x4FF) == 0 {
            platform::write_u8(block + 0x4FF, 1);
            if fn_801e0f40(channel, 0) == -1 {
                fn_801ea9c0(block);
                if platform::read_u32(block + 0x50C) != 0
                    && platform::read_u8(block + 0x55A) != 0
                    && platform::read_u8(block + 0x55B) == 0
                {
                    platform::write_u8(block + 0x55B, 1);
                    platform::call2(platform::read_u32(block + 0x50C) as usize, channel, 1);
                    platform::write_u8(block + 0x55A, 0);
                    platform::write_u8(block + 0x557, fn_801e38d0(channel) as u8);
                    platform::write_u8(block + 0x558, 0);
                }
                platform::write_u8(block + 0x4FF, 0);
                restore_interrupts(token);
                status = -2;
            } else {
                restore_interrupts(token);
                if platform::read_u8(block + 0x554) != 0 {
                    platform::write_u8(block + 0x5D, 0xFC);
                    fn_801ea9c0(block);
                }

                // observed: 44 words from the caller's record into the stack
                // image, and the same 0xB0 bytes back at the end.
                platform::call3(MEMCPY, image.as_mut_ptr() as u32, buffer as u32, 0xB0);

                if platform::read_u8(block + 0x13B) > 1 && buffer != 0 && length != 0 {
                    // observed: the inner pair discards both the token and the
                    // restore value, so it is called by address.
                    platform::call0(0x801B_1140);
                    let ring = platform::read_u8(block + 0x13B) as u32;
                    let count = if length < ring { length } else { ring };
                    let total = platform::read_u32(block + 0x4C0) as i32 + 0x10;

                    let mut started = false;
                    let mut stale = false;
                    let mut index = platform::read_u8(block + 0x13A) as i32 - 1;
                    if index < 0 {
                        index += total;
                    }
                    let mut left = count;
                    while left > 0 {
                        let slot = kpad_ring_slot(block, index);
                        if started {
                            if platform::read_u8(slot + 0x29) == 0 {
                                platform::write_u8(slot + 0x29, 0xF9);
                                started = false;
                            } else if platform::read_u8(slot + 0x29) == 0xFE {
                                started = false;
                            }
                        } else if platform::read_u8(slot + 0x29) == 0xF9 {
                            started = true;
                        }
                        if platform::read_u8(block + 0x5C) != platform::read_u8(slot + 0x28) {
                            stale = true;
                        }
                        if stale {
                            platform::write_u8(slot + 0x29, 0xFC);
                        }
                        index -= 1;
                        if index < 0 {
                            index += total;
                        }
                        left -= 1;
                    }

                    copied = 1;
                    platform::write_u8(block + 0x13B, 1);
                    if count > 1 {
                        copied = count as i32 - 1;
                    }
                    let mut slot_index = (platform::read_u8(block + 0x13A) as i32 - copied) - 1;
                    if slot_index < 0 {
                        slot_index += total;
                    }
                    let mut cursor = buffer + copied as usize * 0xB0;
                    let mut left = copied;
                    while left > 0 {
                        let slot = kpad_ring_slot(block, slot_index);
                        platform::call3(MEMCPY, (cursor - 0xB0) as u32, slot as u32, 0x38);
                        slot_index += 1;
                        if total <= slot_index {
                            slot_index = 0;
                        }
                        cursor -= 0xB0;
                        left -= 1;
                    }
                    platform::call0(0x801B_1180);

                    if platform::read_u8(block + 0x55F) == 1 {
                        // observed: newest record first, each one decoded on
                        // its own with mode 1.
                        let mut end = buffer + copied as usize * 0xB0;
                        let mut left = copied;
                        while left > 0 {
                            let sample = end - 0xB0;
                            if platform::read_u8(block + 0x5C) != platform::read_u8(sample + 0x28) {
                                let kind = platform::read_u8(sample + 0x28);
                                platform::write_u8(block + 0x5C, kind);
                                platform::write_u8(block + 0x555, 1);
                            }
                            let kind = platform::read_u8(sample + 0x29) as i8;
                            let report_type = platform::read_u8(block + 0x5C) as u32;
                            platform::write_u8(block + 0x5D, kind as u8);
                            platform::write_u8(block + 0x5F, platform::read_u8(sample + 0x36));

                            let (buttons, extra, buttons2) = if kind == 0 {
                                if report_type == 1 {
                                    (
                                        platform::read_u32(sample) & 0x9F1F,
                                        platform::read_u32(sample),
                                        0,
                                    )
                                } else if report_type == 2
                                    || report_type.wrapping_sub(0x10) < 2
                                {
                                    (
                                        platform::read_u32(sample) & 0x9F1F,
                                        0,
                                        platform::read_u16(sample + 0x2A) as u32,
                                    )
                                } else {
                                    (platform::read_u32(sample) & 0x9F1F, 0, 0)
                                }
                            } else if kind == -7 {
                                (platform::read_u32(sample) & 0x9F1F, 0, 0)
                            } else if kind == -2 {
                                (platform::read_u32(sample) & 0x9F1F, 0xFFFF, 0xFFFF)
                            } else {
                                // inferred: the export reads these two words
                                // uninitialised; 0xFFFF is the only value that
                                // triggers the block defaults below.
                                (0xFFFF, 0xFFFF, 0xFFFF)
                            };

                            let buttons = if buttons == 0xFFFF {
                                platform::read_u32(block) & 0x9F1F
                            } else {
                                buttons
                            };
                            let extra = if extra == 0xFFFF {
                                platform::read_u32(block)
                            } else {
                                extra
                            };
                            let buttons2 = if buttons2 == 0xFFFF {
                                platform::read_u32(block + 0x60)
                            } else {
                                buttons2
                            };
                            fn_801ead30(block, report_type as i32, 1, buttons, extra, buttons2);

                            let sample_kind = platform::read_u8(sample + 0x29);
                            if sample_kind == 0 || sample_kind == 0xF9 {
                                fn_801ecad0(block, sample);
                                fn_801eb160(block, sample);
                                fn_801ec2f0(block, sample);
                            } else if keep == 0 {
                                platform::write_u8(block + 0x5E, 0);
                            }

                            platform::call3(MEMCPY, sample as u32, block as u32, 0xB0);
                            end -= 0xB0;
                            left -= 1;
                        }
                    } else {
                        // observed: the older layout folds the axis words of
                        // every record into one call, then decodes each record.
                        let mut end = buffer + copied as usize * 0xB0;
                        let mut buttons = 0xFFFFu32;
                        let mut extra = 0xFFFFu32;
                        let mut buttons2 = 0xFFFFu32;
                        let mut report_type = 0u32;
                        let mut left = copied;
                        while left > 0 {
                            let sample = end - 0xB0;
                            if platform::read_u8(block + 0x5C) != platform::read_u8(sample + 0x28) {
                                let kind = platform::read_u8(sample + 0x28);
                                platform::write_u8(block + 0x5C, kind);
                                platform::write_u8(block + 0x555, 1);
                            }
                            let kind = platform::read_u8(sample + 0x29) as i8;
                            report_type = platform::read_u8(sample + 0x28) as u32;
                            if kind == 0 {
                                if report_type == 1 {
                                    extra = platform::read_u32(sample);
                                    buttons2 = 0;
                                } else if report_type == 2
                                    || report_type.wrapping_sub(0x10) < 2
                                {
                                    buttons2 = platform::read_u16(sample + 0x2A) as u32;
                                    extra = 0;
                                } else {
                                    buttons2 = 0;
                                    extra = 0;
                                }
                                buttons = platform::read_u32(sample) & 0x9F1F;
                            } else if kind == -7 || kind == -2 {
                                buttons = platform::read_u32(sample) & 0x9F1F;
                            }
                            end -= 0xB0;
                            left -= 1;
                        }

                        let buttons = if buttons == 0xFFFF {
                            platform::read_u32(block) & 0x9F1F
                        } else {
                            buttons
                        };
                        let extra = if extra == 0xFFFF {
                            platform::read_u32(block)
                        } else {
                            extra
                        };
                        let buttons2 = if buttons2 == 0xFFFF {
                            platform::read_u32(block + 0x60)
                        } else {
                            buttons2
                        };
                        fn_801ead30(
                            block,
                            report_type as i32,
                            copied as u32,
                            buttons,
                            extra,
                            buttons2,
                        );

                        let mut end = buffer + copied as usize * 0xB0;
                        let mut left = copied;
                        while left > 0 {
                            let sample = end - 0xB0;
                            let kind = platform::read_u8(sample + 0x29);
                            platform::write_u8(block + 0x5D, kind);
                            platform::write_u8(block + 0x5F, platform::read_u8(sample + 0x36));
                            if kind == 0 || kind == 0xF9 {
                                fn_801ecad0(block, sample);
                                fn_801eb160(block, sample);
                                fn_801ec2f0(block, sample);
                            } else if keep == 0 {
                                platform::write_u8(block + 0x5E, 0);
                            }
                            platform::call3(MEMCPY, sample as u32, block as u32, 0xB0);
                            end -= 0xB0;
                            left -= 1;
                        }
                    }
                }

                platform::write_u8(block + 0x4FF, 0);
            }
        } else {
            restore_interrupts(token);
            status = -4;
        }
    }

    if copied == 0 {
        if status == 0 {
            if keep != 0 {
                platform::call3(MEMCPY, buffer as u32, image.as_ptr() as u32, 0xB0);
            }
            status = -1;
        } else if status == -2 && keep != 0 {
            platform::write_u8(buffer + 0x5C, 0xFD);
            platform::write_u8(buffer + 0x5F, 0);
            platform::write_u8(buffer + 0x5D, 0xFF);
        }
    }
    if status_out != 0 {
        platform::write_i32(status_out as usize, status);
    }
}

/// Forwards the IOS USB error trace when its gate byte is clear.
///
/// The original is a sixteen-argument trampoline: it saves the eight register
/// words (`r3..r10`) and eight stack words into a Metrowerks `va_list` frame,
/// prints the fixed banner at `r13-0x5DD8` through `0x8015F730`, and then runs
/// the caller's format with `0x802E1560`. The gate byte is `r13-0x4B58`.
///
/// The `va_list` is now reproduced exactly: the descriptor is
/// `{0x01000000, &stack_args, &save_area}`, the save area holds `r3..r10`
/// followed by `f1..f8`, and the overflow area holds arguments nine to sixteen.
/// `crate::engine::main_loop::fn_802e1560` is already translated, so the
/// formatted line is no longer dropped.
///
/// # Original
/// - Ghidra: `FUN_801ee9a0` at `0x801EE9A0` (168 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801ee9a0_FUN_801ee9a0.c`
///
/// # Arguments
/// * `fmt` - `r3`; the caller's format string (the first vararg).
/// * `gpr` - `r4..r10`; the remaining seven register words.
/// * `fpr` - `f1..f8`; the floating-point save area.
/// * `stack` - the eight caller stack words, arguments nine to sixteen.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// One banner print and one formatted print when the gate is set.
///
/// # Safety
/// The trace gate must be readable and `fmt` must match the supplied words.
///
/// # Confidence
/// high - the store offsets (`+8..+0x24`), the `0x01000000` tag, the overflow
/// pointer `r1+136`, the save-area pointer `r1+8`, the banner call and the
/// `0x802E1560(fmt, &va_list)` call are literal; the `$cr1` guard only skips
/// the FPR save when no float argument was passed, and always storing the eight
/// doubles cannot change a format that never reads them.
pub unsafe fn fn_801ee9a0(fmt: u32, gpr: [u32; 7], fpr: [f64; 8], stack: [u32; 8]) {
    kpad_trace_forward(SDA_KPAD_4B58, SDA_KPAD_5DD8 as u32, fmt, gpr, fpr, stack);
}

/// Forwards the IOS USB error trace of the second sender when its gate is clear.
///
/// Same trampoline shape as [`fn_801ee9a0`]: eight register words and eight
/// stack words are saved into a `va_list` frame, the fixed text
/// `s_USB_ERR__80345787 + 1` is printed through `0x8015F730`, and the caller's
/// format runs through `0x802E1560`. The gate byte is `r13-0x5DDC`.
///
/// # Original
/// - Ghidra: `FUN_801eea50` at `0x801EEA50` (172 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801eea50_FUN_801eea50.c`
///
/// # Arguments
/// * `fmt` - `r3`; the caller's format string.
/// * `gpr` - `r4..r10`; the remaining seven register words.
/// * `fpr` - `f1..f8`; the floating-point save area.
/// * `stack` - the eight caller stack words, arguments nine to sixteen.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// One banner print and one formatted print when the gate is set.
///
/// # Safety
/// The trace gate must be readable and `fmt` must match the supplied words.
///
/// # Confidence
/// high - identical body to [`fn_801ee9a0`] with the `r13-0x5DDC` gate and the
/// `"USB_ERR_"` text, both read from the shipped words.
pub unsafe fn fn_801eea50(fmt: u32, gpr: [u32; 7], fpr: [f64; 8], stack: [u32; 8]) {
    kpad_trace_forward(
        SDA_KPAD_5DDC,
        (KPAD_STRING_USB_80345787 + 1) as u32,
        fmt,
        gpr,
        fpr,
        stack,
    );
}

/// Shared sixteen-argument `va_list` trampoline of the two USB trace
/// forwarders.
///
/// # Safety
/// `gate` must be readable and `fmt` must match the supplied words.
unsafe fn kpad_trace_forward(
    gate: usize,
    banner: u32,
    fmt: u32,
    gpr: [u32; 7],
    fpr: [f64; 8],
    stack: [u32; 8],
) {
    if platform::read_u8(gate) == 0 {
        return;
    }
    platform::call1(OS_REPORT_KPAD, banner);

    // The save area is `r3..r10` (eight words) followed by `f1..f8` (eight
    // doubles); the descriptor's register word starts at GPR index 1.
    let mut save_area = crate::platform::GuestLocal::new( [0u8; 0x60]);
    let save = save_area.as_mut_ptr() as usize;
    platform::write_u32(save, fmt);
    for (i, word) in gpr.iter().enumerate() {
        platform::write_u32(save + 4 + i * 4, *word);
    }
    for (i, value) in fpr.iter().enumerate() {
        kpad_write_f64(save + 0x20 + i * 8, *value);
    }

    let mut overflow = crate::platform::GuestLocal::new( stack);
    let mut descriptor = crate::platform::GuestLocal::new( [
        0x0100_0000u32,
        overflow.as_mut_ptr() as u32,
        save as u32,
    ]);
    crate::engine::main_loop::fn_802e1560(fmt, descriptor.as_mut_ptr() as u32);
}

/// `0x801B5FA0`: the 32-bit tick read used to seed both self-test builders.
const TICK_801B5FA0: usize = 0x801B_5FA0;
/// `0x802E1560`: the `printf`-shaped entry the two trace forwarders use.
const KPAD_PRINTF_802E1560: usize = 0x802E_1560;
/// `0x80345787`: `"USB_ERR_"`; the forwarder at `0x801EEA50` passes `+1`.
const KPAD_STRING_USB_80345787: usize = 0x8034_5787;

/// `0x80344400`: the six expected answer bytes per selector of
/// [`fn_801e9730`]; its `0x80344430` neighbour is the 0x900-byte byte table it
/// indexes.
const KPAD_SELFTEST_ANS_80344400: usize = 0x8034_4400;
const KPAD_SELFTEST_T0_80344430: usize = 0x8034_4430;
/// `0x80344D30`/`0x80344D60`: the same pair for [`fn_801e9e20`].
const KPAD_SELFTEST_ANS_80344D30: usize = 0x8034_4D30;
const KPAD_SELFTEST_T0_80344D60: usize = 0x8034_4D60;

/// `r13-0x4B9D`..`-0x4BA0`: the four generator bytes. `-0x4B9D` is the state
/// written back at the end, `-0x4B9E` the masked step multiplier, `-0x4B9F` the
/// additive constant and `-0x4BA0` the constant `0xFF`.
const SDA_KPAD_4B9D: usize = SDA_BASE - 0x4B9D;
const SDA_KPAD_4B9E: usize = SDA_BASE - 0x4B9E;
const SDA_KPAD_4B9F: usize = SDA_BASE - 0x4B9F;
const SDA_KPAD_4BA0: usize = SDA_BASE - 0x4BA0;
/// `r13-0x4B58`: gate byte of the `0x801EE9A0` trace forwarder.
const SDA_KPAD_4B58: usize = SDA_BASE - 0x4B58;
/// `r13-0x5DD8`: fixed banner text handed to the print helper by
/// [`fn_801ee9a0`].
const SDA_KPAD_5DD8: usize = SDA_BASE - 0x5DD8;
/// `r13-0x5DDC`: gate byte of the `0x801EEA50` trace forwarder.
const SDA_KPAD_5DDC: usize = SDA_BASE - 0x5DDC;

/// Rotates the low byte of `value` right by `n` (`0..=7`), as Ghidra spells the
/// `x >> n | x << (8 - n)` pair in [`fn_801e9730`].
fn rot_right8(value: u32, n: u32) -> u32 {
    ((value >> n) | (value << (8 - n))) & 0xFF
}

/// Rotates the low byte of `value` left by `n` (`0..=7`), the spelling the same
/// instruction gets in [`fn_801e9e20`].
fn rot_left8(value: u32, n: u32) -> u32 {
    ((value << n) | (value >> (8 - n))) & 0xFF
}

/// Builds the `ft`/`sb` byte pairs both self-test builders store in the channel
/// block.
///
/// `table` is the 0x900-byte byte table (`0x80344430` or `0x80344D60`), `rnd`
/// the ten generator bytes, `keys` the six mixed key bytes and `selector` the
/// `0..6` table page. Both exports compute the same sixteen XOR pairs, so the
/// two bodies share this helper rather than duplicating the index arithmetic.
unsafe fn kpad_self_test_frames(
    table: usize,
    rnd: &[u8; 10],
    keys: &[u8; 6],
    selector: u32,
) -> ([u8; 8], [u8; 8]) {
    let base1 = (selector as usize + 1) * 0x100;
    let base2 = (selector as usize + 2) * 0x100;
    let t = |index: usize| platform::read_u8(table + index);
    let r = |index: usize| rnd[index] as usize;
    let k = |index: usize| keys[index] as usize;

    let ft = [
        t(k(4) + base1) ^ t(r(3) + base2),
        t(k(2) + base1) ^ t(r(5) + base2),
        t(k(5) + base1) ^ t(r(7) + base2),
        t(k(0) + base1) ^ t(r(2) + base2),
        t(k(1) + base1) ^ t(r(4) + base2),
        t(k(3) + base1) ^ t(r(9) + base2),
        t(r(0) + base1) ^ t(r(6) + base2),
        t(r(1) + base1) ^ t(r(8) + base2),
    ];
    let sb = [
        t(k(0) + base1) ^ t(r(1) + base2),
        t(k(5) + base1) ^ t(r(4) + base2),
        t(k(3) + base1) ^ t(r(0) + base2),
        t(k(2) + base1) ^ t(r(9) + base2),
        t(k(4) + base1) ^ t(r(7) + base2),
        t(k(1) + base1) ^ t(r(8) + base2),
        t(r(3) + base1) ^ t(r(5) + base2),
        t(r(2) + base1) ^ t(r(6) + base2),
    ];
    (ft, sb)
}

/// Runs the extension self-test generator and publishes its report block.
///
/// Three tick reads seed a byte generator (`state = (c + state * b) % 255`) that
/// draws ten bytes from the `0x80344430` table and picks the six-byte answer
/// row `state % 7` of `0x80344400`. The ten random bytes, six mixed key bytes
/// and the two eight-byte `ft`/`sb` XOR pairs are then written into the channel
/// block at `+0x914`..`+0x933`, which is the block the extension handshake
/// reads back. The four `0x801EA8F0` report lines (`"ans"`, `"rand"`, `"t0"`,
/// `"key"`, `"ft"`, `"sb"`) are diagnostic only and are dropped, like every
/// other trace call in this module.
///
/// # Original
/// - Removed: the modelled `_savegpr_14` prologue call (`0x802DCD40`) and the `_restgpr_14` epilogue call (`0x802DCD8C`).
///   The save `bl` returns no value; the value it appeared to return is the incoming `r3` (the channel index).
/// - Ghidra: `FUN_801e9730` at `0x801E9730` (1,776 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801e9730_FUN_801e9730.c`
///
/// # Arguments
/// * `channel` - the current KPAD channel index, incoming `r3`; the block comes
///   from the `0x8039E330` pointer table.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// Three tick reads, four small-data byte writes, the interrupt lock, the
/// report block `+0x914`..`+0x933` and the `0x802DCD8C` epilogue.
///
/// # Safety
/// The channel index must be `0..=3` and the `0x8039E330` entry a live WPAD
/// control block; the two tables must be readable for `0x900` bytes.
///
/// # Confidence
/// medium - the generator, the table indexing and every store are literal; the
/// three seeds arrive as Ghidra's `extraout_var`/`extraout_var_00` because it
/// declares `0x801B5FA0` as returning nothing, so they are read as the low
/// bytes of the repo's tick call, and the two `ft`/`sb` index maps are shared
/// with [`fn_801e9e20`] on the evidence that the export is identical.
pub unsafe fn fn_801e9730(channel: u32) {
    let block = platform::read_u32(KPAD_CONTROL_TABLE + channel as usize * 4) as usize;

    // observed: the first two seeds are stored from `extraout_var_00` and
    // `extraout_var`; the third read is used directly.
    let seed_a = call0_ret(TICK_801B5FA0) as u8;
    platform::write_u8(SDA_KPAD_4B9D, seed_a);
    let seed_b = (call0_ret(TICK_801B5FA0) as u8) & 0x3F;
    platform::write_u8(SDA_KPAD_4B9E, seed_b);
    let constant = (call0_ret(TICK_801B5FA0) >> 24) & 0x4C;
    platform::write_u8(SDA_KPAD_4B9F, constant as u8);
    platform::write_u8(SDA_KPAD_4BA0, 0xFF);

    let step = seed_b as u32;
    let mut state = (constant + seed_a as u32 * step) % 0xFF;
    let selector = state % 7;

    let mut rnd = [0u8; 10];
    let mut position = 0u32;
    let mut pass = 0;
    while pass < 2 {
        let base = (position & 0xFF) as usize;
        position = position.wrapping_add(5);
        let mut draw = 0;
        while draw < 5 {
            state = (constant + state * step) % 0xFF;
            rnd[base + draw] = platform::read_u8(KPAD_SELFTEST_T0_80344430 + state as usize);
            draw += 1;
        }
        pass += 1;
    }
    platform::write_u8(SDA_KPAD_4B9D, state as u8);

    let answer_base = KPAD_SELFTEST_ANS_80344400 + selector as usize * 6;
    let answer = |index: usize| platform::read_u8(answer_base + index) as u32;
    let t = |index: u32| platform::read_u8(KPAD_SELFTEST_T0_80344430 + index as usize) as u32;
    let r = |index: usize| rnd[index] as u32;

    let token = disable_interrupts();
    let b1 = t(r(5));
    let b2 = t(r(7));
    let n0 = t(r(0)) & 7;
    let n7 = b2 & 7;
    let n8 = t(r(8)) & 7;

    let key0 = (t(r(4)) ^ rot_right8(answer(0) ^ b1, t(r(2)) & 7).wrapping_sub(t(r(9)))) & 0xFF;
    let key1 = (b2 ^ rot_right8(t(r(1)) ^ answer(1), n0).wrapping_sub(b1)) & 0xFF;
    let key2 = (t(r(0)) ^ rot_right8(t(r(6)) ^ answer(2), n8).wrapping_sub(t(r(2)))) & 0xFF;
    let key3 = (t(r(2)) ^ rot_right8(answer(3) ^ t(r(4)), n7).wrapping_sub(t(r(3)))) & 0xFF;
    let key4 = (t(r(4)) ^ rot_right8(answer(4) ^ t(r(1)), t(r(6)) & 7).wrapping_sub(t(r(3)))) & 0xFF;
    let key5 = (t(r(9)) ^ rot_right8(answer(5) ^ b2, n8).wrapping_sub(b1)) & 0xFF;

    let keys = [
        key0 as u8, key1 as u8, key2 as u8, key3 as u8, key4 as u8, key5 as u8,
    ];
    let (ft, sb) = kpad_self_test_frames(KPAD_SELFTEST_T0_80344430, &rnd, &keys, selector);
    // MEMCPY reads both through their addresses: guest copies.
    let (ft, sb) = (crate::platform::GuestLocal::new(ft), crate::platform::GuestLocal::new(sb));

    let mut index = 0;
    while index < 10 {
        platform::write_u8(block + 0x914 + index, rnd[9 - index]);
        index += 1;
    }
    let mut index = 0;
    while index < 6 {
        platform::write_u8(block + 0x91E + index, keys[5 - index]);
        index += 1;
    }
    platform::call3(MEMCPY, (block + 0x924) as u32, ft.as_ptr() as u32, 8);
    platform::call3(MEMCPY, (block + 0x92C) as u32, sb.as_ptr() as u32, 8);

    restore_interrupts(token);
}

/// Runs the second extension self-test generator and publishes its report block.
///
/// The same generator and report layout as [`fn_801e9730`], but drawing from
/// the `0x80344D60` byte table with the `0x80344D30` answer rows, and mixing the
/// key bytes with additions instead of subtractions. The output lands in the
/// same channel-block span `+0x914`..`+0x933`.
///
/// # Original
/// - Removed: the modelled `_savegpr_14` prologue call (`0x802DCD40`) and the `_restgpr_14` epilogue call (`0x802DCD8C`).
///   The save `bl` returns no value; the value it appeared to return is the incoming `r3` (the channel index).
/// - Ghidra: `FUN_801e9e20` at `0x801E9E20` (1,784 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801e9e20_FUN_801e9e20.c`
///
/// # Arguments
/// * `channel` - the current KPAD channel index, incoming `r3`.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// Three tick reads, four small-data byte writes, the interrupt lock, the
/// report block `+0x914`..`+0x933` and the `0x802DCD8C` epilogue.
///
/// # Safety
/// The channel index must be `0..=3`; both tables must be readable for `0x900`
/// bytes.
///
/// # Confidence
/// medium - as [`fn_801e9730`]: the body is literal, the seeds come from the
/// tick read that Ghidra prints as `extraout_var`, and the byte rotation is the
/// left-rotate spelling of the same instruction.
pub unsafe fn fn_801e9e20(channel: u32) {
    let block = platform::read_u32(KPAD_CONTROL_TABLE + channel as usize * 4) as usize;

    let seed_a = call0_ret(TICK_801B5FA0) as u8;
    platform::write_u8(SDA_KPAD_4B9D, seed_a);
    let seed_b = (call0_ret(TICK_801B5FA0) as u8) & 0x3F;
    platform::write_u8(SDA_KPAD_4B9E, seed_b);
    let constant = (call0_ret(TICK_801B5FA0) >> 24) & 0x4C;
    platform::write_u8(SDA_KPAD_4B9F, constant as u8);
    platform::write_u8(SDA_KPAD_4BA0, 0xFF);

    let step = seed_b as u32;
    let mut state = (constant + seed_a as u32 * step) % 0xFF;
    let selector = state % 7;

    let mut rnd = [0u8; 10];
    let mut position = 0u32;
    let mut pass = 0;
    while pass < 2 {
        let base = (position & 0xFF) as usize;
        position = position.wrapping_add(5);
        let mut draw = 0;
        while draw < 5 {
            state = (constant + state * step) % 0xFF;
            rnd[base + draw] = platform::read_u8(KPAD_SELFTEST_T0_80344D60 + state as usize);
            draw += 1;
        }
        pass += 1;
    }
    platform::write_u8(SDA_KPAD_4B9D, state as u8);

    let answer_base = KPAD_SELFTEST_ANS_80344D30 + selector as usize * 6;
    let answer = |index: usize| platform::read_u8(answer_base + index) as u32;
    let t = |index: u32| platform::read_u8(KPAD_SELFTEST_T0_80344D60 + index as usize) as u32;
    let r = |index: usize| rnd[index] as u32;

    let token = disable_interrupts();
    let b0 = t(r(1));
    let b1 = t(r(4));
    let raised = t(r(8));
    let n2 = t(r(2)) & 7;
    let n9 = t(r(9)) & 7;

    let key0 = (t(r(7)) ^ (t(r(6)) + rot_left8(answer(0) ^ t(r(0)), b0 & 7))) & 0xFF;
    let key1 = (b0 ^ (t(r(3)) + rot_left8(answer(1) ^ b1, n2))) & 0xFF;
    let key2 = (t(r(5)) ^ (b1 + rot_left8(answer(2) ^ t(r(2)), raised & 7))) & 0xFF;
    let key3 = (t(r(0)) ^ (t(r(7)) + rot_left8(answer(3) ^ t(r(6)), n9))) & 0xFF;
    let key4 = (b0 ^ (raised + rot_left8(answer(4) ^ t(r(5)), b1 & 7))) & 0xFF;
    let key5 = (t(r(5)) ^ (raised + rot_left8(answer(5) ^ t(r(9)), t(r(3)) & 7))) & 0xFF;

    let keys = [
        key0 as u8, key1 as u8, key2 as u8, key3 as u8, key4 as u8, key5 as u8,
    ];
    let (ft, sb) = kpad_self_test_frames(KPAD_SELFTEST_T0_80344D60, &rnd, &keys, selector);
    // MEMCPY reads both through their addresses: guest copies.
    let (ft, sb) = (crate::platform::GuestLocal::new(ft), crate::platform::GuestLocal::new(sb));

    let mut index = 0;
    while index < 10 {
        platform::write_u8(block + 0x914 + index, rnd[9 - index]);
        index += 1;
    }
    let mut index = 0;
    while index < 6 {
        platform::write_u8(block + 0x91E + index, keys[5 - index]);
        index += 1;
    }
    platform::call3(MEMCPY, (block + 0x924) as u32, ft.as_ptr() as u32, 8);
    platform::call3(MEMCPY, (block + 0x92C) as u32, sb.as_ptr() as u32, 8);

    restore_interrupts(token);
}

// ---------------------------------------------------------------------------
// Wave 110: the KPAD sampling callback and the DPD/accelerometer calibration
// ---------------------------------------------------------------------------

/// `0x803A1C02`: produce index of each channel's fixed sixteen-slot status ring.
/// [`KPAD_STATUS_SLOTS`] follows two bytes later and the fill count sits at
/// `+0x803A1C03`.
const KPAD_STATUS_HEAD: usize = 0x803A_1C02;
const KPAD_STATUS_COUNT: usize = 0x803A_1C03;
/// `0x803A1BAC`: three per-channel floats written by the sampling callback
/// (`0.0`, `-offset`, `scale`). // unknown: what consumes the triple.
const KPAD_ACCEL_CAL_803A1BAC: usize = 0x803A_1BAC;
/// `0x80345770`: pairs of `{format-status id, expected report id}` selected by
/// `extension-format * 2`. // inferred: the roles come from the two comparisons
/// in [`fn_801ee230`] (the status id against `+0x4D`, the report id against the
/// ring slot's `+0x36`) and from the `+0x8B8` write of [`fn_801e11a0`].
const KPAD_FORMAT_TABLE: usize = 0x8034_5770;
/// `0x801E39C0`: the extension command-record writer (still untranslated; its
/// `0x30`-byte record payload cannot be recovered from the export).
const KPAD_COMMAND_WRITER_801E39C0: usize = 0x801E_39C0;
/// `0x801EE190`: completion callback handed to [`KPAD_COMMAND_WRITER_801E39C0`]
/// (see [`fn_801ee190`]); its address is passed as data.
const KPAD_COMMAND_DONE_801EE190: u32 = 0x801E_E190;
/// `0x801EE110` / `0x801EE130`: the two 32-byte completion callbacks handed to
/// `0x801E4A40` for the classic-controller handshake. // unknown: Ghidra created
/// no functions at these addresses, so their bodies are not in the export set.
const KPAD_CLASSIC_DETECT_801EE110: u32 = 0x801E_E110;
const KPAD_CLASSIC_INIT_801EE130: u32 = 0x801E_E130;
/// `0x801DDA90` / `0x801DDAA0`: the two zero-returning probes of the classic
/// controller path (translated as `runtime::dvd::fn_801dda90`/`fn_801ddaa0`).
const KPAD_PROBE_801DDA90: usize = 0x801D_DA90;
const KPAD_PROBE_801DDAA0: usize = 0x801D_DAA0;

/// `r2-0x4CD8`: word copied into the three accelerometer scale slots when one
/// of the three deltas is zero (the zero-g placeholder).
const SDA2_ACCEL_ZERO_WORD: usize = SDA2_BASE - 0x4CD8;
/// `r2-0x4CD0` / `r2-0x4CCC`: the two accelerometer offset candidates picked by
/// the classic-controller link state.
const SDA2_F32_4CD0: usize = SDA2_BASE - 0x4CD0;
const SDA2_F32_4CCC: usize = SDA2_BASE - 0x4CCC;
/// `r13-0x5DEC`: number of neutral classic-controller samples to average.
/// (`r13-0x5DE8`, the count threshold, is [`SDA_KPAD_5DE8`] from wave 103.)
const SDA_KPAD_5DEC: usize = SDA_BASE - 0x5DEC;

/// Reads one big-endian `f64` from `addr`.
///
/// # Safety
/// `addr` must be the address of eight readable bytes.
unsafe fn read_f64(addr: usize) -> f64 {
    let bits = ((platform::read_u32(addr) as u64) << 32) | platform::read_u32(addr + 4) as u64;
    f64::from_bits(bits)
}

/// Writes one big-endian `f64` to `addr`.
///
/// # Safety
/// `addr` must be the address of eight writable bytes.
unsafe fn write_f64(addr: usize, value: f64) {
    let bits = value.to_bits();
    platform::write_u32(addr, (bits >> 32) as u32);
    platform::write_u32(addr + 4, bits as u32);
}

/// Stores the three `1/delta` accelerometer scale factors for one sample pair.
///
/// A zero delta on any axis (the product is tested, exactly as the original
/// does) writes the zero-g placeholder word into all three slots instead of
/// dividing.
///
/// # Arguments
/// * `dst` - first of the three `f32` slots (`+0x04` or `+0x10` of the block).
/// * `sample` - the three signed deltas [`fn_801e0d30`] produced.
///
/// # Safety
/// `dst` must be twelve writable bytes inside a KPAD channel block.
unsafe fn kpad_accel_scale(dst: usize, sample: &[u16; 3]) {
    let x = sample[0] as u32;
    let y = sample[1] as u32;
    let z = sample[2] as u32;
    if z.wrapping_mul(x).wrapping_mul(y) == 0 {
        let placeholder = platform::read_u32(SDA2_ACCEL_ZERO_WORD);
        platform::write_u32(dst, placeholder);
        platform::write_u32(dst + 4, placeholder);
        platform::write_u32(dst + 8, placeholder);
    } else {
        let one = platform::read_f32(SDA2_F32_4D2C);
        platform::write_f32(dst, one / x as f32);
        platform::write_f32(dst + 4, one / y as f32);
        platform::write_f32(dst + 8, one / z as f32);
    }
}

/// Per-report KPAD sampling callback: files the report, refreshes the
/// accelerometer scales and drives the extension-format handshake.
///
/// In plain English, once per accepted report on one channel:
///
/// 1. Reads the channel's extension/report byte through [`fn_801e0f40`] and
///    stops early when the Bluetooth link is gone (`-1`).
/// 2. Copies the newest report into the next slot of the fixed sixteen-entry
///    status ring (or into the variable bank past slot `0x10`), stores the
///    current report id at `+0x36`, bumps the produce index and - while the
///    ring is not full - the fill count.
/// 3. When the report id becomes the accelerometer id `1`, arms `+0x68`; the
///    armed block then re-reads both 1G/0G delta vectors and stores
///    `1/delta` per axis at `+0x04`..`+0x18`.
/// 4. When `+0x50` is armed, rewrites the three floats at `0x803A1BAC`
///    (zero, `-offset`, and `sqrt(1 + tilt^2) / min(1, tilt)`).
/// 5. Maps the report id to an extension-format index, compares its
///    `0x80345770` status/id pair with the channel state, and either re-queues
///    the expected report id through [`fn_801e11a0`] or starts the
///    `0x801E39C0` format command after firing the `+0x00` callback.
/// 6. For the classic-controller id `3`, walks the neutral-point state machine
///    (`r13-0x4B6E`) and folds the four stick samples into the running means at
///    `0x803A30D8`..`0x803A3108`.
///
/// The per-channel `+0x40` callback then always runs with the channel index.
///
/// # Original
/// - Removed: the `_restgpr_27` epilogue call (`0x802DCDC0`).
///   The epilogue `bl` returns no value; the argument it was passed is the routine's `r3` return.
/// - Ghidra: `FUN_801ee230` at `0x801EE230` (1,896 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801ee230_FUN_801ee230.c`
/// - Installed at `+0x54C` by [`kpad_set_sampling_callback_801e0fd0`] from
///   [`fn_801edf40`] and [`fn_801edaf0`].
///
/// # Arguments
/// * `channel` - controller index. The export prints it as the 32-bit value the
///   `0x802DCD74` register-save fold hands back, i.e. the callback's incoming
///   `r3`.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// One status-ring slot (`0x38` bytes), `+0x36`, the ring head and count, the
/// six accelerometer scales, three floats at `0x803A1BAC`, the format state
/// bytes `+0x4A`..`+0x4F`, the `0x803A30D8`..`0x803A3110` means, the five
/// `r13-0x4B6A`..`-0x4B70` handshake bytes, the `+0x00`/`+0x40` callbacks, the
/// `0x801E39C0` command writer and the `0x802DCDC0` epilogue.
///
/// # Safety
/// `channel` must be `0..=3`; the channel block, both ring banks and the
/// `0x80345770` table must be readable, and the two callbacks must be live.
///
/// # Confidence
/// medium - every offset, branch, store and call is literal. Two inferences:
/// the class of the dead paired-single prologue (it spills `f30`/`f31` into
/// slots that are never read, exactly like [`fn_801e74c0`]) and the second
/// argument of the `0x801E11A0` call, which the export drops; the expected
/// report id from the same table entry is the only in-scope value that matches
/// that function's `+0x8B8` write.
pub unsafe fn fn_801ee230(channel: u32) {
    let block = KPAD_CHANNEL_BASE + channel as usize * KPAD_CHANNEL_STRIDE;
    let head_addr = KPAD_STATUS_HEAD + channel as usize * KPAD_CHANNEL_STRIDE;
    let count_addr = KPAD_STATUS_COUNT + channel as usize * KPAD_CHANNEL_STRIDE;

    let mut kind = crate::platform::GuestLocal::<u32>::new( 0);
    let link = fn_801e0f40(channel, (kind.as_mut_ptr() as *mut u32) as usize);
    let kind = *kind as i32;

    if link != -1 {
        // --- 1. file the newest report in the status ring -------------------
        let mut index = platform::read_u8(head_addr) as u32;
        let capacity =
            platform::read_u32(KPAD_EXTRA_COUNT + channel as usize * KPAD_CHANNEL_STRIDE);
        if capacity.wrapping_add(0x10) <= index {
            index = 0;
        }
        let slot = if index < 0x10 {
            KPAD_STATUS_SLOTS
                + channel as usize * KPAD_CHANNEL_STRIDE
                + index as usize * KPAD_STATUS_STRIDE
        } else {
            platform::read_u32(KPAD_EXTRA_SLOTS + channel as usize * KPAD_CHANNEL_STRIDE) as usize
                + (index as usize - 0x10) * KPAD_STATUS_STRIDE
        };
        fn_801e18d0(channel, slot);
        // observed: the report id byte is stored from the 32-bit `+0x8B8` word.
        platform::write_u8(slot + 0x36, fn_801e1150(channel) as u8);
        platform::write_u8(head_addr, index.wrapping_add(1) as u8);
        if (platform::read_u8(count_addr) as u32) < capacity.wrapping_add(0x10) {
            platform::write_u8(count_addr, platform::read_u8(count_addr).wrapping_add(1));
        }

        // --- 2. accelerometer scale factors ---------------------------------
        if kind != platform::read_i32(block + 0x64) && kind == 1 {
            platform::write_u8(block + 0x68, 1);
        }
        if platform::read_u8(block + 0x68) != 0 {
            let mut sample = crate::platform::GuestLocal::new( [0u16; 3]);
            fn_801e0d30(channel, 0, sample.as_mut_ptr() as usize);
            kpad_accel_scale(block + 0x04, &sample);
            fn_801e0d30(channel, 1, sample.as_mut_ptr() as usize);
            kpad_accel_scale(block + 0x10, &sample);
            platform::write_u8(block + 0x68, 0);
        }

        // --- 3. the 0x803A1BAC calibration triple ---------------------------
        if platform::read_u8(block + 0x50) != 0 {
            let offset = if platform::read_u8(block + 0x51) == 0 {
                platform::read_f32(SDA2_F32_4D38)
            } else if fn_801dfb90() == 1 {
                platform::read_f32(SDA2_F32_4CD0)
            } else {
                platform::read_f32(SDA2_F32_4CCC)
            };
            let one = platform::read_f32(SDA2_F32_4D2C) as f64;
            let tilt = platform::read_f32(SDA2_F32_4D24) as f64;
            let zero = platform::read_f32(SDA2_F32_4D38) as f64;
            let cal = KPAD_ACCEL_CAL_803A1BAC + channel as usize * KPAD_CHANNEL_STRIDE;
            platform::write_u32(cal, platform::read_u32(SDA2_F32_4D38));
            platform::write_f32(cal + 4, -offset);
            let hypot = call_f64_1(
                KPAD_SQRT_802E8620,
                (((one * one) as f32) + ((tilt * tilt) as f32)) as f64,
            );
            let stored_x = platform::read_f32(cal) as f64;
            let x_scale = if zero <= stored_x {
                one - stored_x
            } else {
                one + stored_x
            };
            let stored_y = platform::read_f32(cal + 4) as f64;
            let y_scale = if zero <= stored_y {
                tilt - stored_y
            } else {
                tilt + stored_y
            };
            let mut denominator = y_scale as f32;
            if (x_scale as f32) < denominator {
                denominator = x_scale as f32;
            }
            platform::write_f32(cal + 8, hypot as f32 / denominator);
            platform::write_u8(block + 0x50, 0);
        }

        // --- 4. extension-format handshake ----------------------------------
        'exit: {
            let format: u32 = if kind == 0x10 {
                10
            } else if kind < 0x10 {
                if kind == 2 {
                    4
                } else if kind < 2 {
                    if kind == 0 {
                        0
                    } else if kind < 0 {
                        break 'exit;
                    } else {
                        2
                    }
                } else if 3 < kind {
                    break 'exit;
                } else {
                    8
                }
            } else if kind < 0xFD {
                if kind < 0xFB {
                    if 0x11 < kind {
                        break 'exit;
                    }
                    6
                } else {
                    0
                }
            } else if kind != 0xFF {
                break 'exit;
            } else {
                0
            };

            // observed: `+0x4A` folds in one extra format step (the extension
            // port state) before the table index is doubled.
            let format = if platform::read_u8(block + 0x4A) != 0 {
                format.wrapping_add(1)
            } else {
                format
            };
            let index = format as usize * 2;
            let expected_status = platform::read_u8(KPAD_FORMAT_TABLE + index);
            let expected_id = platform::read_u8(KPAD_FORMAT_TABLE + index + 1);
            let current = if fn_801e38d0(channel) == 0 {
                0
            } else {
                platform::read_u8(block + 0x4D)
            };

            if current == expected_status {
                if platform::read_u8(slot + 0x36) != expected_id {
                    // inferred: the export prints only the channel; the
                    // expected id is the value `0x801E11A0` re-queues.
                    fn_801e11a0(channel, expected_id as u32);
                }
            } else {
                let pending = platform::read_u32(block);
                if pending != 0 && platform::read_u8(block + 0x4E) == 0 {
                    platform::write_u8(block + 0x4E, 1);
                    platform::call2(pending as usize, channel, 0);
                    platform::write_u8(block + 0x4F, 0);
                }
                if platform::read_u8(block + 0x4C) == 0 {
                    platform::write_u8(block + 0x4C, 1);
                    if platform::call3(
                        KPAD_COMMAND_WRITER_801E39C0,
                        channel,
                        expected_status as u32,
                        KPAD_COMMAND_DONE_801EE190,
                    ) == 0
                    {
                        platform::write_u8(block + 0x4D, expected_status);
                    }
                }
            }
        }

        // --- 5. classic-controller neutral-point handshake -------------------
        if kind == 3 {
            let armed = platform::read_u8(SDA_KPAD_4B6A);
            if armed == 0 && platform::read_u8(SDA_KPAD_4B6B) == 0 {
                if fn_801e4a40(channel, 0xAA, KPAD_CLASSIC_DETECT_801EE110) == 0 {
                    platform::write_u8(SDA_KPAD_4B6A, 1);
                }
            } else if platform::read_u8(SDA_KPAD_4B6B) == 0
                || platform::read_u8(SDA_KPAD_4B6C) != 0
            {
                if armed == 0 && platform::read_u8(SDA_KPAD_4B6C) != 0 {
                    let state = platform::read_u8(SDA_KPAD_4B6E);
                    if state < 3 {
                        if state == 0 {
                            if fn_801e4a40(channel, 0, KPAD_CLASSIC_INIT_801EE130) == 0 {
                                platform::write_u8(SDA_KPAD_4B6A, 1);
                            }
                        } else if state == 1 {
                            let centre = platform::read_u8(slot + 0x32);
                            if centre == 0x7F || centre == 0x80 {
                                let low = platform::read_u32(SDA2_F64_4D00);
                                let high = platform::read_u32(SDA2_F64_4D00 + 4);
                                for filter in 0..8usize {
                                    platform::write_u32(KPAD_FILTER_CH3 + filter * 8, low);
                                    platform::write_u32(KPAD_FILTER_CH3 + filter * 8 + 4, high);
                                }
                                platform::write_u8(SDA_KPAD_4B6E, 0);
                                platform::write_u16(SDA_KPAD_4B70, 0);
                                platform::write_u8(SDA_KPAD_4B6D, 0);
                            } else {
                                let count = platform::read_u16(SDA_KPAD_4B70).wrapping_add(1);
                                platform::write_u16(SDA_KPAD_4B70, count);
                                if (platform::read_u8(SDA_KPAD_5DEC) as u16) < count {
                                    platform::write_u8(SDA_KPAD_4B6E, 2);
                                    platform::write_u16(SDA_KPAD_4B70, 0);
                                }
                            }
                        } else if state == 2 && platform::read_u8(slot + 0x29) == 0 {
                            let count = platform::read_u16(SDA_KPAD_4B70).wrapping_add(1);
                            platform::write_u16(SDA_KPAD_4B70, count);
                            let previous = count.wrapping_sub(1) as i32 as f64;
                            let divisor = count as f64;
                            for axis in 0..4usize {
                                let sample = platform::read_u16(slot + 0x2A + axis * 2) as f64;
                                let mean = KPAD_FILTER_CH3 + axis * 8;
                                let updated = (previous * read_f64(mean) + sample) / divisor;
                                write_f64(mean, updated);
                            }
                            if (platform::read_f32(SDA_KPAD_5DE8) as f64) < divisor {
                                platform::write_u8(SDA_KPAD_4B6E, 3);
                                // observed: the original passes the filter block
                                // and `4`; the translated stub takes no arguments.
                                let _ = wbc_set_zero_point_dummy_801ddaf0();
                            }
                        }
                    }
                }
            } else if armed == 0 {
                if call0_ret(KPAD_PROBE_801DDA90) == 0 {
                    platform::write_u8(SDA_KPAD_4B6A, 1);
                }
            } else {
                let value = call0_ret(KPAD_PROBE_801DDAA0) as u8;
                platform::write_u8(SDA_KPAD_4B6C, value);
                // observed: `cntlzw(value) >> 5` - one when the value is zero.
                platform::write_u8(SDA_KPAD_4B6A, if value == 0 { 1 } else { 0 });
            }
        }
    }

    let callback = platform::read_u32(block + 0x40);
    if callback != 0 {
        platform::call1(callback as usize, channel);
    }
    // observed: `0x802DCDC0` is the register-restore epilogue of the entry
    // `0x802DCD74`.
}

/// `0x802E7C14` (`atan`) and `0x802E8590` (`tan`), both `f64`-in/`f64`-out;
/// translated in [`crate::engine::main_loop`] as `fn_802e7c14` /
/// `fn_802e8590`.
const KPAD_ATAN_802E7C14: usize = 0x802E_7C14;
const KPAD_TAN_802E8590: usize = 0x802E_8590;

/// `r2-0x4D88`: the corner-sum seed and centre base (also copied verbatim into
/// the angle slot). `r2-0x4D84`: the `1/4` corner average scale.
const SDA2_F32_4D88: usize = SDA2_BASE - 0x4D88;
const SDA2_F32_4D84: usize = SDA2_BASE - 0x4D84;
/// `r2-0x4D80` / `r2-0x4D7C`: the X angle bias and the X tangent scale.
const SDA2_F32_4D80: usize = SDA2_BASE - 0x4D80;
const SDA2_F32_4D7C: usize = SDA2_BASE - 0x4D7C;
/// `r2-0x4D78` / `r2-0x4D68`: the two `atan` reference angles (`f64`).
const SDA2_F64_4D78: usize = SDA2_BASE - 0x4D78;
const SDA2_F64_4D68: usize = SDA2_BASE - 0x4D68;
/// `r2-0x4D70` / `r2-0x4D6C`: the Y angle bias and the Y tangent scale.
const SDA2_F32_4D70: usize = SDA2_BASE - 0x4D70;
const SDA2_F32_4D6C: usize = SDA2_BASE - 0x4D6C;
/// `r2-0x4D60`: the angle-table gain applied to both tangents.
const SDA2_F32_4D60: usize = SDA2_BASE - 0x4D60;
/// `r2-0x4D5C` / `r2-0x4D58`: the rotation-reference bias and divisor.
const SDA2_F32_4D5C: usize = SDA2_BASE - 0x4D5C;
const SDA2_F32_4D58: usize = SDA2_BASE - 0x4D58;
/// `r2-0x4D98`..`r2-0x4D8C`: the four packed default DPD corner words. The X
/// candidates are `{hi, lo}` of the first and third word, the Y candidates
/// `{hi, lo}` of the second and fourth.
const SDA2_DPD_CORNERS: usize = SDA2_BASE - 0x4D98;
const SDA2_DPD_CORNERS_Y: usize = SDA2_BASE - 0x4D90;

/// `0x80343F3C`: `"Dpd_Setting_is_ok_"` diagnostic (Ghidra string symbol),
/// printed with the record's checksum offset.
const MSG_DPD_OK: u32 = 0x8034_3F3C;
/// `0x80343F50`: `"Dpd_Setting_is_broken_"`.
const MSG_DPD_BROKEN: u32 = 0x8034_3F50;
/// `0x80343F68`: `"Old_Firmware_uses_default_values_"`.
const MSG_OLD_FIRMWARE: u32 = 0x8034_3F68;
/// `0x80343FAC`: `"x=%lf, y=%lf"`.
const MSG_CORNER_XY: u32 = 0x8034_3FAC;
/// `0x80343FC0`: `"difaveX=%lf, difaveY=%lf"`.
const MSG_DIFAVE: u32 = 0x8034_3FC0;
/// `0x80343FE0`: `"deltaX=%lf, deltaY=%lf"`.
const MSG_DELTA: u32 = 0x8034_3FE0;
/// `0x80344000`: `" wpadCalibrationX=%lf, wpadCalibrationY=%lf"`.
const MSG_CALIBRATION: u32 = 0x8034_4000;
/// `0x80344034`: `"centX=%lf, centY=%lf"`.
const MSG_CENTRE: u32 = 0x8034_4034;
/// `0x80344050`: `" wpadRolag=%lf"`.
const MSG_ROLL: u32 = 0x8034_4050;
/// `0x80344064` / `0x80344070`: `"Acc_is_ok_"` / `"Acc_is_broken_"`.
const MSG_ACC_OK: u32 = 0x8034_4064;
const MSG_ACC_BROKEN: u32 = 0x8034_4070;
/// `0x80344080` / `0x803440A8`: `"0G: accX=%d, accY=%d, accZ=%d"` and the `1G`
/// twin.
const MSG_ACC_0G: u32 = 0x8034_4080;
const MSG_ACC_1G: u32 = 0x8034_40A8;
/// `0x803440D0`: `"Volume=%d, Motor=%d"`.
const MSG_VOLUME: u32 = 0x8034_40D0;

/// Calls the diagnostic printer with one `f64` payload.
///
/// The original is variadic; the fixed-arity trampoline keeps the same
/// argument order (`format`, then the double).
///
/// # Safety
/// `addr` must be `0x801EA8F0`-shaped and `format` must take one `%lf`.
unsafe fn report_f64_1(addr: usize, format: u32, a: f64) {
    let f = crate::platform::guest_fn!(addr, fn(u32, f64));
    f(format, a);
}

/// Calls the diagnostic printer with two `f64` payloads.
///
/// # Safety
/// `addr` must be `0x801EA8F0`-shaped and `format` must take two `%lf`.
unsafe fn report_f64_2(addr: usize, format: u32, a: f64, b: f64) {
    let f = crate::platform::guest_fn!(addr, fn(u32, f64, f64));
    f(format, a, b);
}

/// Sums `len` bytes at `addr` and applies the factory-data `0x55` bias.
///
/// The export spells this as an eight-byte unrolled block plus a remainder
/// loop; both add signed bytes into one `char`, so the wrapped byte sum is the
/// same value.
///
/// # Safety
/// `addr` must be readable for `len` bytes.
unsafe fn kpad_checksum_55(addr: usize, len: usize) -> u8 {
    let mut sum = 0u8;
    let mut index = 0;
    while index < len {
        sum = sum.wrapping_add(platform::read_u8(addr + index));
        index += 1;
    }
    sum.wrapping_add(0x55)
}

/// Rebuilds one channel's DPD and accelerometer calibration from the factory
/// data the extension read left at `+0x974`.
///
/// In plain English:
///
/// 1. Seeds the four DPD corner records at `+0x854`..`+0x872` with the packed
///    default words from `r2-0x4D98`..`-0x4D8C` and the accelerometer
///    references at `+0x874`..`+0x87E` with `0x212`/`0x27C`.
/// 2. On a successful read (`result == 0`) and current firmware
///    (`+0x8E0 == 0`), walks the two eleven-byte DPD records, validating each
///    with the `0x55` checksum, and files the four unpacked points into the
///    corner record that matches their half of the sensor area. Old firmware
///    keeps the defaults and says so.
/// 3. Averages the four corners (`sum / 4`), derives the X/Y rotation deltas
///    from two `atan` reference angles, writes the two tangent offsets to
///    `0x803A1A60`/`0x803A1A70`, accumulates the four corner centres into
///    `0x803A1A80`/`0x803A1A90` and the four corner-to-reference angles into
///    `0x803A1AA0`.
/// 4. Walks the two ten-byte accelerometer records (at `0x16` for current
///    firmware, `0` otherwise), validating the `0x55` checksum, and stores the
///    two 10-bit triples plus the volume/motor bytes.
///
/// # Original
/// - Removed: the modelled `_savegpr_15` prologue call (`0x802DCD44`) and the `_restgpr_15` epilogue call (`0x802DCD90`).
///   The save `bl` returns no value; the value it appeared to return is the incoming `r3`/`r4` argument pair (channel then result).
/// - Ghidra: `FUN_801e55c0` at `0x801E55C0` (2,792 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801e55c0_FUN_801e55c0.c`
/// - Called by [`fn_801e7050`] for the `0x0` / `0x176C` calibration reads with
///   `(channel, result)`.
///
/// # Arguments
/// * `channel`, `result` - the channel and the pending result, incoming `r3`/`r4`.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// The corner and accelerometer halfwords in the channel block, the five
/// `0x803A1A60`..`0x803A1AA0` tables for this channel, seventeen diagnostic
/// call sites and the `0x802DCD90` epilogue.
///
/// # Safety
/// The channel must be `0..=3`; `+0x974` must point at the factory-data buffer
/// (at least `0x30` bytes for current firmware) and the control block must be
/// writable through `+0x881`.
///
/// # Confidence
/// medium - every offset, store and branch is literal; the four default corner
/// words are read as packed halfword pairs, `atan`/`tan` are identified through
/// the [`crate::engine::main_loop`] translations, the dead paired-single
/// prologue/epilogue is not reproduced, and the `centX` report drops its second
/// value in the export (the Rust prints both centres).
pub unsafe fn fn_801e55c0(channel: u32, result: u32) {
    // observed: the caller at 0x801E7050 passes `(channel, result)`; the fold
    // hands them back as the high and low halves.

    let control = kpad_control(channel);
    let data = platform::read_u32(control + 0x974) as usize;
    let points = platform::read_u8(control + 0x8CA) as u16;

    // --- the default corner table -------------------------------------------
    let x_pair = platform::read_u32(SDA2_DPD_CORNERS);
    let x_pair2 = platform::read_u32(SDA2_DPD_CORNERS + 4);
    let y_pair = platform::read_u32(SDA2_DPD_CORNERS_Y);
    let y_pair2 = platform::read_u32(SDA2_DPD_CORNERS_Y + 4);
    let default_x = [
        (x_pair >> 16) as u16,
        x_pair as u16,
        (x_pair2 >> 16) as u16,
        x_pair2 as u16,
    ];
    let default_y = [
        (y_pair >> 16) as u16,
        y_pair as u16,
        (y_pair2 >> 16) as u16,
        y_pair2 as u16,
    ];
    for corner in 0..4usize {
        platform::write_u16(control + 0x854 + corner * 8, default_x[corner]);
        platform::write_u16(control + 0x856 + corner * 8, default_y[corner]);
        platform::write_u16(control + 0x858 + corner * 8, points);
        platform::write_u8(control + 0x85A + corner * 8, corner as u8);
    }
    for axis in 0..3usize {
        platform::write_u16(control + 0x874 + axis * 2, 0x212);
        platform::write_u16(control + 0x87A + axis * 2, 0x27C);
    }
    platform::write_u8(control + 0x880, 0);
    platform::write_u8(control + 0x881, 0);

    if result == 0 {
        // --- the eleven-byte DPD records ------------------------------------
        if platform::read_u32(control + 0x8E0) == 0 {
            for attempt in 0..2usize {
                let start = attempt * 0x0B;
                if kpad_checksum_55(data + start, 10)
                    != platform::read_u8(data + start + 10)
                {
                    platform::call2(OS_REPORT, MSG_DPD_BROKEN, (start + 10) as u32);
                    continue;
                }
                platform::call2(OS_REPORT, MSG_DPD_OK, (start + 10) as u32);

                let source = data + start;
                let b0 = platform::read_u8(source) as u16;
                let b1 = platform::read_u8(source + 1) as u16;
                let b2 = platform::read_u8(source + 2) as u16;
                let b3 = platform::read_u8(source + 3) as u16;
                let b4 = platform::read_u8(source + 4) as u16;
                let b5 = platform::read_u8(source + 5) as u16;
                let b6 = platform::read_u8(source + 6) as u16;
                let b7 = platform::read_u8(source + 7) as u16;
                let b8 = platform::read_u8(source + 8) as u16;
                let b9 = platform::read_u8(source + 9) as u16;

                // observed: four 10-bit points packed two per three bytes; the
                // high bits of each pair live in byte 2 and byte 7.
                let mut corner = [0u16; 16];
                corner[0] = b0 | (b2 & 0x30) << 4;
                corner[1] = 0x2FFu16.wrapping_sub(b1 | (b2 & 0xC0) << 2);
                corner[2] = points;
                corner[3] = 0;
                corner[4] = b3 | (b2 & 0x03) << 8;
                corner[5] = 0x2FFu16.wrapping_sub(b4 | (b2 & 0x0C) << 6);
                corner[6] = points;
                corner[7] = 1;
                corner[8] = b5 | (b7 & 0x30) << 4;
                corner[9] = 0x2FFu16.wrapping_sub(b6 | (b7 & 0xC0) << 2);
                corner[10] = points;
                corner[11] = 2;
                corner[12] = b8 | (b7 & 0x03) << 8;
                corner[13] = 0x2FFu16.wrapping_sub(b9 | (b7 & 0x0C) << 6);
                corner[14] = points;
                corner[15] = 3;

                for index in 0..4usize {
                    let x = corner[index * 4] as i16;
                    let y = corner[index * 4 + 1] as i16;
                    let target = if x < 0x200 && y < 0x180 {
                        control + 0x854
                    } else if 0x200 < x && y < 0x180 {
                        control + 0x85C
                    } else if 0x200 < x && 0x180 < y {
                        control + 0x864
                    } else if x < 0x200 && 0x180 < y {
                        control + 0x86C
                    } else {
                        continue;
                    };
                    platform::write_u16(target, corner[index * 4]);
                    platform::write_u16(target + 2, corner[index * 4 + 1]);
                    platform::write_u16(target + 4, corner[index * 4 + 2]);
                    platform::write_u8(target + 6, corner[index * 4 + 3] as u8);
                }
                break;
            }
        } else {
            platform::call1(OS_REPORT, MSG_OLD_FIRMWARE);
        }

        // --- corner averages, centres and angles ----------------------------
        let mut measured_x = [0f32; 4];
        let mut measured_y = [0f32; 4];
        let seed = platform::read_f32(SDA2_F32_4D88) as f64;
        let mut sum_x = seed;
        let mut sum_y = seed;
        for corner in 0..4usize {
            let x = platform::read_u16(control + 0x854 + corner * 8) as i16;
            let y = platform::read_u16(control + 0x856 + corner * 8) as i16;
            let delta_x = x as i32 as f64 - default_x[corner] as i16 as i32 as f64;
            let delta_y = y as i32 as f64 - default_y[corner] as i16 as i32 as f64;
            measured_x[corner] = x as f32;
            measured_y[corner] = y as f32;
            // observed: the running sums are rounded back to `f32` every step.
            sum_x = ((sum_x + delta_x) as f32) as f64;
            sum_y = ((sum_y + delta_y) as f32) as f64;
            report_f64_2(
                OS_REPORT,
                MSG_CORNER_XY,
                measured_x[corner] as f64,
                measured_y[corner] as f64,
            );
        }

        let average_scale = platform::read_f32(SDA2_F32_4D84) as f64;
        let difave_x = ((sum_x * average_scale) as f32) as f64;
        let difave_y = ((sum_y * average_scale) as f32) as f64;

        let reference_x =
            call_f64_1(KPAD_ATAN_802E7C14, read_f64(SDA2_F64_4D78)) as f32 as f64;
        let angle_x = call_f64_1(
            KPAD_ATAN_802E7C14,
            (((platform::read_f32(SDA2_F32_4D80) as f64 + difave_x) as f32)
                / platform::read_f32(SDA2_F32_4D7C)) as f64,
        ) as f32 as f64;
        let delta_x = (angle_x as f32 - reference_x as f32) as f64;

        let reference_y =
            call_f64_1(KPAD_ATAN_802E7C14, read_f64(SDA2_F64_4D68)) as f32 as f64;
        let angle_y = call_f64_1(
            KPAD_ATAN_802E7C14,
            (((platform::read_f32(SDA2_F32_4D70) as f64 + difave_y) as f32)
                / platform::read_f32(SDA2_F32_4D6C)) as f64,
        ) as f32 as f64;
        let delta_y = (angle_y as f32 - reference_y as f32) as f64;

        let gain = platform::read_f32(SDA2_F32_4D60);
        let table = channel as usize * 4;
        platform::write_f32(
            KPAD_LOADCELL_X_OFFSET + table,
            platform::read_f32(SDA2_F32_4D7C)
                * gain
                * (call_f64_1(KPAD_TAN_802E8590, delta_x) as f32),
        );
        platform::write_f32(
            KPAD_LOADCELL_Y_OFFSET + table,
            platform::read_f32(SDA2_F32_4D6C)
                * gain
                * (call_f64_1(KPAD_TAN_802E8590, delta_y) as f32),
        );

        report_f64_2(OS_REPORT, MSG_DIFAVE, difave_x, difave_y);
        report_f64_2(OS_REPORT, MSG_DELTA, delta_x, delta_y);
        report_f64_2(
            OS_REPORT,
            MSG_CALIBRATION,
            platform::read_f32(KPAD_LOADCELL_X_OFFSET + table) as f64,
            platform::read_f32(KPAD_LOADCELL_Y_OFFSET + table) as f64,
        );

        // observed: the four corner centres are accumulated into the two centre
        // words one corner at a time, each intermediate value stored.
        let centre_base = platform::read_f32(SDA2_F32_4D88);
        let offset_x = platform::read_f32(KPAD_LOADCELL_X_OFFSET + table);
        platform::write_f32(KPAD_LOADCELL_Y_CENTRE + table, centre_base);
        measured_x[0] += offset_x;
        platform::write_f32(KPAD_LOADCELL_X_CENTRE + table, centre_base);
        let offset_y = platform::read_f32(KPAD_LOADCELL_Y_OFFSET + table);
        measured_y[0] += offset_y;
        let mut running_y = platform::read_f32(KPAD_LOADCELL_Y_CENTRE + table);
        measured_y[1] += offset_y;
        platform::write_f32(
            KPAD_LOADCELL_X_CENTRE + table,
            centre_base + measured_x[0],
        );
        measured_x[1] += offset_x;
        measured_x[2] += offset_x;
        platform::write_f32(
            KPAD_LOADCELL_Y_CENTRE + table,
            running_y + measured_y[0],
        );
        running_y += measured_y[0] + measured_y[1];
        measured_y[2] += offset_y;
        measured_x[3] += offset_x;
        platform::write_f32(
            KPAD_LOADCELL_X_CENTRE + table,
            platform::read_f32(KPAD_LOADCELL_X_CENTRE + table) + measured_x[1],
        );
        platform::write_f32(KPAD_LOADCELL_Y_CENTRE + table, running_y);
        running_y += measured_y[2];
        let centre_scale = platform::read_f32(SDA2_F32_4D84);
        measured_y[3] += offset_y;
        platform::write_f32(
            KPAD_LOADCELL_X_CENTRE + table,
            platform::read_f32(KPAD_LOADCELL_X_CENTRE + table) + measured_x[2],
        );
        platform::write_f32(KPAD_LOADCELL_Y_CENTRE + table, running_y);
        running_y += measured_y[3];
        platform::write_f32(
            KPAD_LOADCELL_X_CENTRE + table,
            platform::read_f32(KPAD_LOADCELL_X_CENTRE + table) + measured_x[3],
        );
        platform::write_f32(KPAD_LOADCELL_Y_CENTRE + table, running_y);
        platform::write_f32(
            KPAD_LOADCELL_X_CENTRE + table,
            platform::read_f32(KPAD_LOADCELL_X_CENTRE + table) * centre_scale,
        );
        platform::write_f32(
            KPAD_LOADCELL_Y_CENTRE + table,
            running_y * centre_scale,
        );
        // inferred: the export recovers only the X centre for this line, but the
        // format string carries two `%lf`, so both centres are printed.
        report_f64_2(
            OS_REPORT,
            MSG_CENTRE,
            platform::read_f32(KPAD_LOADCELL_X_CENTRE + table) as f64,
            platform::read_f32(KPAD_LOADCELL_Y_CENTRE + table) as f64,
        );

        // --- the corner-to-centre angles ------------------------------------
        platform::write_u32(
            KPAD_LOADCELL_ANGLE + table,
            platform::read_u32(SDA2_F32_4D88),
        );
        let angle_bias = platform::read_f32(SDA2_F32_4D5C);
        let angle_divisor = platform::read_f32(SDA2_F32_4D58);
        for corner in 0..4usize {
            let centre_x = platform::read_f32(KPAD_LOADCELL_X_CENTRE + table);
            let centre_y = platform::read_f32(KPAD_LOADCELL_Y_CENTRE + table);
            let measured = call_f64_1(
                KPAD_ATAN_802E7C14,
                ((measured_y[corner] - centre_y) / (measured_x[corner] - centre_x)) as f64,
            ) as f32;
            // observed: the reference term is computed in f64 and rounded back
            // to f32, which is exactly the two `f32` subtractions below.
            let numerator = default_y[corner] as i16 as f32 - angle_bias;
            let denominator = default_x[corner] as i16 as f32 - angle_divisor;
            let reference = call_f64_1(
                KPAD_ATAN_802E7C14,
                (numerator / denominator) as f64,
            ) as f32;
            let current = platform::read_f32(KPAD_LOADCELL_ANGLE + table);
            platform::write_f32(
                KPAD_LOADCELL_ANGLE + table,
                current + (measured - reference),
            );
        }
        platform::write_f32(
            KPAD_LOADCELL_ANGLE + table,
            platform::read_f32(KPAD_LOADCELL_ANGLE + table) * centre_scale,
        );
        report_f64_1(
            OS_REPORT,
            MSG_ROLL,
            platform::read_f32(KPAD_LOADCELL_ANGLE + table) as f64,
        );

        // --- the ten-byte accelerometer records -----------------------------
        for attempt in 0..2usize {
            let start = if platform::read_u32(control + 0x8E0) == 0 {
                0x16 + attempt * 10
            } else {
                attempt * 10
            };
            if kpad_checksum_55(data + start, 9) != platform::read_u8(data + start + 9) {
                platform::call2(OS_REPORT, MSG_ACC_BROKEN, (start + 9) as u32);
                continue;
            }
            platform::call2(OS_REPORT, MSG_ACC_OK, (start + 9) as u32);

            let source = data + start;
            let b0 = platform::read_u8(source) as u16;
            let b1 = platform::read_u8(source + 1) as u16;
            let b2 = platform::read_u8(source + 2) as u16;
            let b3 = platform::read_u8(source + 3) as u16;
            let b4 = platform::read_u8(source + 4) as u16;
            let b5 = platform::read_u8(source + 5) as u16;
            let b6 = platform::read_u8(source + 6) as u16;
            let b7 = platform::read_u8(source + 7) as u16;
            let b8 = platform::read_u8(source + 8) as u16;

            platform::write_u16(control + 0x874, b0 << 2 | ((b3 >> 4) & 3));
            platform::write_u16(control + 0x876, b1 << 2 | ((b3 >> 2) & 3));
            platform::write_u16(control + 0x878, b2 << 2 | (b3 & 3));
            platform::write_u16(control + 0x87A, b4 << 2 | ((b7 >> 4) & 3));
            platform::write_u16(control + 0x87C, b5 << 2 | ((b7 >> 2) & 3));
            platform::write_u16(control + 0x87E, b6 << 2 | (b7 & 3));
            platform::write_u8(control + 0x881, (b8 & 0x7F) as u8);
            platform::write_u8(control + 0x880, (b8 & 0x80) as u8);
            break;
        }

        platform::call4(
            OS_REPORT,
            MSG_ACC_0G,
            platform::read_u16(control + 0x874) as i16 as i32 as u32,
            platform::read_u16(control + 0x876) as i16 as i32 as u32,
            platform::read_u16(control + 0x878) as i16 as i32 as u32,
        );
        platform::call4(
            OS_REPORT,
            MSG_ACC_1G,
            platform::read_u16(control + 0x87A) as i16 as i32 as u32,
            platform::read_u16(control + 0x87C) as i16 as i32 as u32,
            platform::read_u16(control + 0x87E) as i16 as i32 as u32,
        );
        platform::call3(
            OS_REPORT,
            MSG_VOLUME,
            platform::read_u8(control + 0x881) as u32,
            platform::read_u8(control + 0x880) as u32,
        );
    }

    // observed: the four `ldexpf` calls in the epilogue are the exit halves of
    // the paired-single GQR conversions; their results are unused.
}

// ---------------------------------------------------------------------------
// WPAD command-record writers (0x801E1E20 / 0x801E39C0)
// ---------------------------------------------------------------------------

/// `r2-0x4DA0`..`r2-0x4D9A`: the seven-byte register template the enable
/// sequence writes to `0x04A20001` (four bytes, two bytes, then one byte).
const SDA2_KPAD_TEMPLATE_4DA0: usize = SDA2_BASE - 0x4DA0;


/// `0x802F6CD8`: nine payload bytes per extension kind (`1`..=`5`, nine-byte
/// stride) written to register `0x4B00000`.
const KPAD_WBC_TABLE_802F6CD8: usize = 0x802F_6CD8;
/// `0x802F6D08`: two payload bytes per extension kind (two-byte stride) written
/// to register `0x4B0001A`.
const KPAD_WBC_TABLE_802F6D08: usize = 0x802F_6D08;

/// `0x801E3980`: `&LAB_801e3980`, the completion label inside the preceding
/// `0x801E3680` body. Ghidra emitted it as a code label, not as a function, so
/// it is passed by address exactly as the export does.
const KPAD_WBC_STEP_801E3980: u32 = 0x801E_3980;

/// Tests whether a control block's `+0x160` command ring has room for `blocks`
/// more records: the export spells it `count + blocks <= capacity - 1`.
///
/// # Original
/// - Inlined in both record writers: `count + 5 <= capacity - 1` in
///   `FUN_801e1e20`, `+ 3` and `+ 8` in `FUN_801e39c0`.
/// - Evidence: `work/ghidra/main-gb/export/801e1e20_FUN_801e1e20.c`,
///   `work/ghidra/main-gb/export/801e39c0_FUN_801e39c0.c`.
///
/// # Safety
/// `control` must point at a live control block with a valid 0x0C-byte ring
/// header at `+0x160`.
unsafe fn kpad_ring_has_room(control: usize, blocks: u32) -> bool {
    let count = kpad_ring_count(control + 0x160);
    count.wrapping_add(blocks) <= platform::read_u32(control + 0x168).wrapping_sub(1)
}

/// Builds one `0x16` extension register write.
///
/// The record is `id 0x16`, the four-byte register address at `+4`, the payload
/// size at `+8`, the payload from `+9`, the record length `0x15` at `+0x1A` and
/// the completion at `+0x2C`. The length is 21 because the extension driver
/// reads the four address bytes, the size byte and a sixteen-byte data window;
/// only `size` of the window bytes are data.
///
/// # Original
/// - Inlined in `FUN_801e1e20` (six call sites) and `FUN_801e39c0` (five).
/// - Evidence: `work/ghidra/main-gb/export/801e1e20_FUN_801e1e20.c`
///   (`B4 = 0x4A20001`, `B0 = 1`, `B0+1 = 1`).
///
/// # Confidence
/// high - the field offsets and the `0x15` length are literal at every site.
fn kpad_register_write(register: u32, data: &[u8], callback: u32) -> [u8; 0x30] {
    let mut block = kpad_cmd_block(0x16);
    kpad_block_set_u32(&mut block, 4, register);
    block[8] = data.len() as u8;
    for (index, byte) in data.iter().enumerate() {
        block[9 + index] = *byte;
    }
    kpad_block_set_u16(&mut block, 0x1A, 0x15);
    kpad_block_set_u32(&mut block, 0x2C, callback);
    block
}

/// Builds a one-byte record: the id at `+3`, the data byte at `+4`, the record
/// length `1` at `+0x1A` and the completion at `+0x2C`.
///
/// The `0x15` form also carries a value word at `+0x28` (the consumer stores it
/// at `+0x850`); every producer here leaves it zero, which the zeroed block
/// already provides.
///
/// # Original
/// - Inlined in `FUN_801e1e20` (nine call sites) and `FUN_801e39c0` (six).
/// - Evidence: `work/ghidra/main-gb/export/801e1e20_FUN_801e1e20.c`
///   (`local_58 = 0x19`, `local_70` low half `1`, `local_2c = 0`).
///
/// # Confidence
/// high - id, one-byte length and completion offsets are literal.
fn kpad_single_byte_block(kind: u8, data: u8, callback: u32) -> [u8; 0x30] {
    let mut block = kpad_cmd_block(kind);
    block[4] = data;
    kpad_block_set_u16(&mut block, 0x1A, 1);
    kpad_block_set_u32(&mut block, 0x2C, callback);
    block
}

/// Queues the WPAD extension register sequence for a channel mode change.
///
/// This is the first of the two command-record writers. It maps a mode word
/// onto a fixed set of 0x30-byte records and appends them to the channel's
/// command ring (`+0x160`); the records are the extension enable/disable
/// writes the Bluetooth HID host later feeds to the extension registers.
///
/// | mode | records queued (id → payload) |
/// |---:|---|
/// | `0`, `+0x83C == 0` | none; the callback still receives `(channel, 0)` |
/// | `0`, `+0x83C != 0` | `0x19`→`04`, `0x16`→`0x04A20001`←`01`, `0x16`→`0x04A20009`←`00`, `0x14`→`00`, `0x15`→`00` + callback |
/// | `1` or `5` | `0x14`→`04`, `0x19`→`04`, `0x16`→`0x04A20009`←`01`, `0x16`→`0x04A20001`←`80`, `0x16`→`0x04A20001`←template(7), `0x19`→`00`, `0x15`→`00` + callback |
/// | `2` | `0x19`→`04` + callback |
/// | `3` | `0x19`→`00` + callback |
/// | `4` | `0x16`→`0x04A20008`←`01` + callback |
///
/// The multi-record modes test for room up front (`count + n <= capacity - 1`)
/// and fail with `-2` without queueing anything; the single-record modes let
/// [`kpad_ring_push`] reject the record instead. The seven-byte template is the
/// static `r2-0x4DA0` block with its fifth byte replaced by the global sampling
/// mode `r13-0x4BC9`.
///
/// # Original
/// - Removed: the `_restgpr_25` epilogue call (`0x802DCDB8`).
///   The epilogue `bl` returns no value; the argument it was passed is the routine's `r3` return.
/// - Ghidra: `FUN_801e1e20` at `0x801E1E20` (5,628 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801e1e20_FUN_801e1e20.c`
/// - Call sites in the game code: `src/game/player.rs` treats it as
///   `(handle, mode, completion)`; `src/ui/menu.rs` passes
///   `(manager, 1, 0x80173FB0)`, `(manager, 4, 0x801740C0)` and `(player, 0, 0)`.
///
/// # Arguments
/// * `channel` - controller index `0..=3` (the high word of the `0x802DCD6C`
///   register-save fold, i.e. `r3`).
/// * `mode` - the low word of that fold: `0` clears, `1`/`5` enable, `2`/`3`/`4`
///   queue one record each; any other value only reports the link state.
/// * `callback` - optional completion, invoked as `(channel, result)` when no
///   record was queued.
///
/// # Returns
/// `()`; the result word travels through the `0x802DCDB8` epilogue.
///
/// # Side effects
/// Appends up to seven 0x30-byte records to `+0x160`, advancing its head byte
/// (wrapping at `capacity - 1`) under the interrupt lock, and calls the
/// callback on every path that did not queue.
///
/// # Safety
/// The channel must be `0..=3`; the control block, its command ring and the
/// callback must be valid, and `r2`/`r13` must hold the SDA2/SDA bases on the
/// target (the template and sampling-mode bytes are read through them).
///
/// # Confidence
/// medium - every branch, record id, length, register, size and payload byte is
/// literal; the block field roles come from the consumer [`fn_801ddd20`]. The
/// bytes of a `0x16` record beyond `9 + size` (and beyond `+4` for the
/// one-byte records) are never written by the export, are not data for the
/// declared size, and are left zero here (see the coverage doc).
pub unsafe fn fn_801e1e20(channel: u32, mode: u32, callback: u32) {
    let control = kpad_control(channel);

    // observed: seven bytes are copied from r2-0x4DA0 before the lock; the
    // fifth byte is patched with the sampling-mode byte r13-0x4BC9 only when
    // the enable sequence is actually built.
    let mut template = [0u8; 7];
    for (index, byte) in template.iter_mut().enumerate() {
        *byte = platform::read_u8(SDA2_KPAD_TEMPLATE_4DA0 + index);
    }

    let token = disable_interrupts();
    let state = platform::read_u32(control + 0x83C);
    let link = platform::read_i32(control + 0x8BC);
    let connected = platform::read_u32(control + 0x8DC);
    restore_interrupts(token);

    let mut result = link;
    let mut queued = false;

    if link != -1 {
        if connected == 0 {
            result = -2;
        } else if mode == 0 {
            if state == 0 {
                // observed: nothing is queued but the callback still runs.
                result = 0;
            } else {
                let token = disable_interrupts();
                if kpad_ring_has_room(control, 5) {
                    // observed: five records, queued in this order.
                    kpad_ring_push(control, &kpad_single_byte_block(0x19, 0x04, 0));
                    kpad_ring_push(control, &kpad_register_write(0x04A2_0001, &[0x01], 0));
                    kpad_ring_push(control, &kpad_register_write(0x04A2_0009, &[0x00], 0));
                    kpad_ring_push(control, &kpad_single_byte_block(0x14, 0x00, 0));
                    // observed: only the trailing 0x15 record carries the
                    // caller's completion.
                    kpad_ring_push(
                        control,
                        &kpad_single_byte_block(0x15, 0x00, callback),
                    );
                    queued = true;
                    result = 0;
                } else {
                    result = -2;
                }
                restore_interrupts(token);
            }
        } else if mode == 1 || mode == 5 {
            let token = disable_interrupts();
            if kpad_ring_has_room(control, 7) {
                // observed: seven records, queued in this order.
                kpad_ring_push(control, &kpad_single_byte_block(0x14, 0x04, 0));
                kpad_ring_push(control, &kpad_single_byte_block(0x19, 0x04, 0));
                kpad_ring_push(control, &kpad_register_write(0x04A2_0009, &[0x01], 0));
                kpad_ring_push(control, &kpad_register_write(0x04A2_0001, &[0x80], 0));
                // observed: the template's fifth byte is the sampling mode at
                // the point the enable record is built.
                template[4] = platform::read_u8(SDA_WPAD_4BC9);
                kpad_ring_push(
                    control,
                    &kpad_register_write(0x04A2_0001, &template, 0),
                );
                kpad_ring_push(control, &kpad_single_byte_block(0x19, 0x00, 0));
                kpad_ring_push(
                    control,
                    &kpad_single_byte_block(0x15, 0x00, callback),
                );
                queued = true;
                result = 0;
            } else {
                result = -2;
            }
            restore_interrupts(token);
        } else if mode == 2 {
            let block = kpad_single_byte_block(0x19, 0x04, callback);
            if kpad_ring_push(control, &block) {
                queued = true;
                result = 0;
            } else {
                result = -2;
            }
        } else if mode == 3 {
            let block = kpad_single_byte_block(0x19, 0x00, callback);
            if kpad_ring_push(control, &block) {
                queued = true;
                result = 0;
            } else {
                result = -2;
            }
        } else if mode == 4 {
            let block = kpad_register_write(0x04A2_0008, &[0x01], callback);
            if kpad_ring_push(control, &block) {
                queued = true;
                result = 0;
            } else {
                result = -2;
            }
        }
    }

    // observed: the shared tail calls the completion only when nothing was
    // queued, then hands the result to the register-restore epilogue.
    if !queued && callback != 0 {
        platform::call2(callback as usize, channel, result as u32);
    }
}

/// Writes the per-extension-kind activation sequence for a channel mode change.
///
/// This is the second command-record writer; [`fn_801ee230`] queues it for the
/// extension-format change and [`fn_801e5460`]'s retry path re-queues it. A
/// mode of `0` disables the extension (`+0x838` non-zero) by clearing the mode
/// latch `+0x8CC` and queueing `0x13`→`00`, `0x1A`→`00` (completion
/// `0x801E3980`) and `0x15`→`00` (the caller's completion). Any other mode that
/// differs from the latched `+0x8CC` stores the new latch, sets the configured
/// byte `+0x994` and queues eight records:
///
/// 1. `0x13`→`04`;
/// 2. `0x1A`→`04`;
/// 3. `0x16` `0x4B00030`←`01`;
/// 4. `0x16` `0x4B00000`← nine bytes from `0x802F6CD8 + (kind-1)*9`;
/// 5. `0x16` `0x4B0001A`← two bytes from `0x802F6D08 + (kind-1)*2`;
/// 6. `0x16` `0x4B00033`← the mode byte;
/// 7. `0x16` `0x4B00030`←`08`, completion `0x801E3980`;
/// 8. `0x15`→`00` with the caller's completion.
///
/// `kind` is the global extension kind `r13-0x4BC3` (clamped to `1..=5` by
/// `0x801DD530`), which selects one nine-byte and one two-byte record from the
/// two read-only tables. A mode equal to the latched `+0x8CC` queues nothing
/// and reports the link word unchanged.
///
/// # Original
/// - Removed: the `_restgpr_24` epilogue call (`0x802DCDB4`).
///   The epilogue `bl` returns no value; the argument it was passed is the routine's `r3` return.
/// - Ghidra: `FUN_801e39c0` at `0x801E39C0` (4,224 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801e39c0_FUN_801e39c0.c`
/// - Completers: `0x801E3980` (a code label inside `FUN_801e3680`) and the
///   caller's `param_3`.
///
/// # Arguments
/// * `channel` - controller index `0..=3` (the high word of the `0x802DCD68`
///   register-save fold, i.e. `r3`).
/// * `mode` - the low word of that fold; `0` disables, anything else enables.
/// * `callback` - optional completion, invoked as `(channel, result)` when no
///   record was queued.
///
/// # Returns
/// `()`; the result word travels through the `0x802DCDB4` epilogue. A channel
/// already in the requested mode reports the link word (`+0x8BC`) unchanged.
///
/// # Side effects
/// Stores `+0x8CC` (and `+0x994` when enabling), appends three or eight
/// 0x30-byte records to the `+0x160` ring under the interrupt lock, and calls
/// the callback on every path that did not queue.
///
/// # Safety
/// The channel must be `0..=3`; the control block, its command ring and the
/// callback must be valid, and `r13` must hold [`SDA_BASE`] on the target (the
/// extension kind and the two payload tables are read through it).
///
/// # Confidence
/// medium - the gate, the latch stores, all eight records and the two table
/// strides are literal; `0x801E3980` is a code label rather than a Ghidra
/// function, and the record bytes beyond the declared size are left zero (see
/// the coverage doc). The `0x4B000xx` register roles are `// unknown:`.
pub unsafe fn fn_801e39c0(channel: u32, mode: u32, callback: u32) {
    let control = kpad_control(channel);

    let token = disable_interrupts();
    let state = platform::read_u32(control + 0x838);
    let current = platform::read_u8(control + 0x8CC);
    let link = platform::read_i32(control + 0x8BC);
    let connected = platform::read_u32(control + 0x8DC);
    restore_interrupts(token);

    let mut result = link;
    let mut queued = false;

    if link != -1 {
        if connected == 0 {
            result = -2;
        } else if mode == 0 {
            if state == 0 {
                result = 0;
            } else {
                let token = disable_interrupts();
                if kpad_ring_has_room(control, 3) {
                    // observed: the mode latch is cleared before the records go
                    // out, so the disable sequence cannot be replayed.
                    platform::write_u8(control + 0x8CC, 0);
                    kpad_ring_push(control, &kpad_single_byte_block(0x13, 0x00, 0));
                    kpad_ring_push(
                        control,
                        &kpad_single_byte_block(0x1A, 0x00, KPAD_WBC_STEP_801E3980),
                    );
                    kpad_ring_push(
                        control,
                        &kpad_single_byte_block(0x15, 0x00, callback),
                    );
                    queued = true;
                    result = 0;
                } else {
                    result = -2;
                }
                restore_interrupts(token);
            }
        } else if mode != current as u32 {
            let token = disable_interrupts();
            if kpad_ring_has_room(control, 8) {
                platform::write_u8(control + 0x8CC, mode as u8);
                platform::write_u8(control + 0x994, 1);

                // observed: the extension kind `r13-0x4BC3` selects the payload
                // rows of the two read-only tables.
                let kind = platform::read_u8(SDA_WPAD_4BC3);
                let row = kind.wrapping_sub(1) as usize;

                kpad_ring_push(control, &kpad_single_byte_block(0x13, 0x04, 0));
                kpad_ring_push(control, &kpad_single_byte_block(0x1A, 0x04, 0));
                kpad_ring_push(control, &kpad_register_write(0x4B00_0030, &[0x01], 0));

                let mut nine = [0u8; 9];
                for (offset, byte) in nine.iter_mut().enumerate() {
                    *byte = platform::read_u8(KPAD_WBC_TABLE_802F6CD8 + row * 9 + offset);
                }
                // unknown: the `0x4B000xx` register bank has no name in the
                // export; only the addresses and the payload strides are literal.
                kpad_ring_push(control, &kpad_register_write(0x4B00_0000, &nine, 0));

                let mut two = [0u8; 2];
                for (offset, byte) in two.iter_mut().enumerate() {
                    *byte = platform::read_u8(KPAD_WBC_TABLE_802F6D08 + row * 2 + offset);
                }
                kpad_ring_push(control, &kpad_register_write(0x4B00_001A, &two, 0));

                kpad_ring_push(
                    control,
                    &kpad_register_write(0x4B00_0033, &[mode as u8], 0),
                );
                kpad_ring_push(
                    control,
                    &kpad_register_write(0x4B00_0030, &[0x08], KPAD_WBC_STEP_801E3980),
                );
                kpad_ring_push(
                    control,
                    &kpad_single_byte_block(0x15, 0x00, callback),
                );

                queued = true;
                result = 0;
            } else {
                result = -2;
            }
            restore_interrupts(token);
        }
    }

    // observed: the shared tail calls the completion only when nothing was
    // queued, then hands the result to the register-restore epilogue.
    if !queued && callback != 0 {
        platform::call2(callback as usize, channel, result as u32);
    }
}

// ---------------------------------------------------------------------------
// HCI receive dispatch and the variadic trace forwarder
// (0x801F8820 / 0x801F9C50)
// ---------------------------------------------------------------------------

/// `0x803CDDA8`: three-slot HCI receive reassembly block, immediately below the
/// `0x803CDDE0` HID-host state block. Slot `n` owns the buffer pointer at
/// `+n*4`, the remaining-byte count at `+0x0C+n*2`, the packet type at
/// `+0x14+n`, the saved length byte at `+0x17+n` and the receive state at
/// `+0x1A+n`. `+0x12` is a separate halfword (the "bias" that `0x801F8E80`
/// subtracts before calling here, never written by this body), `+0x1E` is the
/// gate byte (the machine only runs while it is `2`) and `+0x1F` the report
/// queue id, which is the existing [`HID_REPORT_QUEUE_ID`].
const HID_RX_BLOCK: usize = 0x803C_DDA8;

/// `r2-0x4CC0`: header size per packet type, read at `type - 1`. Types `1`..`4`
/// hold `3`, `4`, `3` and `2` bytes.
const HID_RX_HEADER_SIZE: usize = SDA2_BASE - 0x4CC0;
/// `r2-0x4CBA`: packet id written at the head of every reassembled report, read
/// at `type * 2`. Types `1`..`4` hold `0x0013`, `0x0011`, `0x0012` and `0x0010`.
const HID_RX_PACKET_ID: usize = SDA2_BASE - 0x4CBA;

/// `0x801F9830`: single-byte read from one receive pipe. Its shipped body is
/// the 8-byte `return 0` stub ([`fn_801f9830`]), so the receive loop below never
/// runs in the original image; the call is kept with all three arguments.
const HID_BYTE_READ: usize = 0x801F_9830;

/// `0x803CFE40`: trace buffer the variadic forwarder formats into. It is the
/// same address the receive path passes as its IOS transmit context.
const HID_TRACE_BUFFER: usize = 0x803C_FE40;
/// `0x802E1664`: `vsprintf`-shaped formatter `(buffer, format, va_list)`; it
/// stores the terminating NUL at `buffer[result]`.
const HID_TRACE_FORMAT: usize = 0x802E_1664;
/// `0x802E17DC`: appends one more formatted line to the trace buffer.
const HID_TRACE_APPEND: usize = 0x802E_17DC;
/// `0x8015F730`: flushes the trace buffer.
const HID_TRACE_FLUSH: usize = 0x8015_F730;
/// `r13-0x5D78`: `"%s\n"`, the format the append step inserts.
const SDA_HID_TRACE_LINE_5D78: usize = SDA_BASE - 0x5D78;

/// Reassembles one HCI receive packet byte by byte out of a channel pipe.
///
/// Each of the three slots of the block at `0x803CDDA8` owns a GKI buffer, a
/// remaining-byte count and a receive state. The function pulls one byte per
/// iteration for the requested slot and walks the state machine:
///
/// | state | action |
/// |---:|---|
/// | `0` | allocate the buffer for the slot's channel (`1`→pool `2`, `2`→pool `3`, `3`→pool `1`), stamp the packet id from the `r2-0x4CBA` table and the header size from `r2-0x4CC0`, move to `1` |
/// | `1` | append the byte, decrement the count; on zero, a type-`2` packet first combines its two length bytes and re-opens the buffer through `0x80215460`, then either accepts the length (state `3`), delivers an empty packet (state `0`) or frees it as invalid (state `4`) |
/// | `2` | discard the remaining length bytes of a type-`2` packet, then move to `4` |
/// | `3` | stream the payload into the buffer with one bulk read; when the count reaches zero, deliver unless a type-`2` packet still has a parser that is not ready |
/// | `4` | discard one byte per iteration and return to state `0` when the count expires |
///
/// A delivered packet is posted to the queue byte at `0x803CDDC7` and its slot
/// pointer cleared. The state-`0` allocation and the state-`1` length checks are
/// the two `"HCIS: ..."` trace sites.
///
/// # Original
/// - Removed: the `_restgpr_14` epilogue call (`0x802DCD8C`).
///   The epilogue `bl` returns no value; the argument it was passed is the routine's `r3` return.
/// - Ghidra: `FUN_801f8820` at `0x801F8820` (920 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801f8820_FUN_801f8820.c`
/// - Both arguments arrive through the `0x802DCD40` register-save fold: the
///   high word of the recovered pair is `r3` (the slot index) and the low word
///   is `r4` (the `0x803CDDA8` block). The only branch caller, `0x801F8E80`
///   (method-table slot `+0x10` of `0x802F6D30`), loads that address into `r4`
///   before the call, which is what fixes the pairing that made wave 102 skip
///   this body.
///
/// # Arguments
/// * `index` - receive slot `0..=2`. The pipe channel is `index + 1` and the
///   allocation pool is `2`, `3` or `1` for channels `1`, `2`, `3`.
///   // inferred: the slot numbering and its `0..=2` bound, from that three-way
///   pool choice, the three branches and the three-entry layout of the block.
/// * `control` - the `0x803CDDA8` receive block.
///
/// # Returns
/// The number of bytes read in the loop, handed back through the `0x802DCD8C`
/// epilogue's `r3`.
///
/// # Side effects
/// Reads from the pipe, rewrites the slot's buffer, count, type, saved byte and
/// state, prints the two `"HCIS: ..."` diagnostics through [`fn_801f9d10`], and
/// either posts a finished packet with [`fn_801f7400`] or frees it with
/// [`fn_801f7240`].
///
/// # Safety
/// `control` must be the live block and `index` must be below `3`, so that the
/// buffer, count and field slots stay inside it; a slot buffer must be live
/// while state `1` or `3` runs. The allocation-failure path falls into the byte
/// handler with a zero slot pointer exactly as the export does, so the original
/// faults there if the pool is exhausted.
///
/// # Confidence
/// medium - every offset, table index, mask, state value and call is literal,
/// and the argument pairing is proven from the caller's disassembly; the slot
/// roles and the `0..=2` bound are inferred from the layout, the packet-id and
/// header-size tables have no name in the export, and the read callee is an
/// 8-byte stub that makes the loop dead in the shipped image.
pub unsafe fn fn_801f8820(index: u32, control: usize) -> u32 {
    if platform::read_u8(control + 0x1E) != 2 {
        return 0;
    }

    let slot = (index & 0xFFFF) as usize;
    let buffer_slot = control + slot * 4;
    let count_slot = control + slot * 2 + 0x0C;
    let fields = control + index as usize;

    let mut byte = crate::platform::GuestLocal::<u8>::new( 0u8);
    let mut processed = 0u32;

    loop {
        let read = platform::call3(
            HID_BYTE_READ,
            index.wrapping_add(1) & 0xFF,
            (byte.as_mut_ptr() as *mut u8) as u32,
            1,
        ) as i16;
        if read == 0 {
            break;
        }

        let state = platform::read_u8(fields + 0x1A);
        let mut deliver = false;
        processed = processed.wrapping_add(1);

        'step: {
            let mut run_state_one = state == 1;

            if state == 0 {
                // observed: the channel picks both the pool and the type byte.
                let channel = index.wrapping_add(1) & 0xFFFF;
                let (pool, packet_type) = if channel == 1 {
                    (2u32, 4u8)
                } else if channel == 2 {
                    (3, 2)
                } else if channel == 3 {
                    (1, 3)
                } else {
                    break 'step;
                };

                let buffer = fn_801f7150(pool);
                platform::write_u32(buffer_slot, buffer as u32);
                platform::write_u8(fields + 0x14, packet_type);

                if platform::read_u32(buffer_slot) == 0 {
                    fn_801f9d10();
                    platform::write_u8(fields + 0x1A, 2);
                } else {
                    let buffer = platform::read_u32(buffer_slot) as usize;
                    let packet_type = platform::read_u8(fields + 0x14) as usize;
                    platform::write_u16(buffer + 2, 0);
                    platform::write_u16(
                        buffer,
                        platform::read_u16(HID_RX_PACKET_ID + packet_type * 2),
                    );
                    platform::write_u16(buffer + 4, 0);
                    platform::write_u8(fields + 0x1A, 1);
                }

                let packet_type = platform::read_u8(fields + 0x14) as usize;
                platform::write_u16(
                    count_slot,
                    platform::read_u8(HID_RX_HEADER_SIZE + packet_type - 1) as u16,
                );
                run_state_one = true;
            }

            if run_state_one {
                // State 0 falls through here: append the byte just read.
                let buffer = platform::read_u32(buffer_slot) as usize;
                let offset = platform::read_u16(buffer + 2) as usize;
                platform::write_u8(buffer + offset + 8, *byte);
                platform::write_u16(buffer + 2, (offset + 1) as u16);

                let remaining = platform::read_u16(count_slot).wrapping_sub(1);
                platform::write_u16(count_slot, remaining);

                if remaining != 0 {
                    platform::write_u8(fields + 0x17, *byte);
                } else {
                    let mut length = *byte as u32;
                    if platform::read_u8(fields + 0x14) == 2 {
                        length =
                            *byte as u32 * 0x100 + platform::read_u8(fields + 0x17) as u32;
                        let opened = platform::call1(HID_PARSER_OPEN, buffer as u32) as usize;
                        platform::write_u32(buffer_slot, opened as u32);
                        if opened == 0 {
                            platform::write_u16(count_slot, length as u16);
                            platform::write_u8(fields + 0x1A, if length == 0 { 0 } else { 4 });
                            break 'step;
                        }
                    }

                    platform::write_u16(count_slot, length as u16);
                    let capacity =
                        fn_801f73b0(platform::read_u32(buffer_slot) as usize) as u32;
                    let packet_type = platform::read_u8(fields + 0x14) as usize;
                    let header = platform::read_u8(HID_RX_HEADER_SIZE + packet_type - 1) as u32;
                    if (capacity & 0xFFFF) < length + header + 8 {
                        fn_801f7240(platform::read_u32(buffer_slot) as usize);
                        platform::write_u32(buffer_slot, 0);
                        platform::write_u8(fields + 0x1A, 4);
                        fn_801f9d10();
                    } else if length == 0 {
                        platform::write_u8(fields + 0x1A, 0);
                        deliver = true;
                    } else {
                        platform::write_u8(fields + 0x1A, 3);
                    }
                }
            } else if state == 2 {
                let remaining = platform::read_u16(count_slot).wrapping_sub(1);
                platform::write_u16(count_slot, remaining);
                if remaining == 0 {
                    let mut length = *byte as u16;
                    if platform::read_u8(fields + 0x14) == 2 {
                        length =
                            (*byte as u16) * 0x100 + platform::read_u8(fields + 0x17) as u16;
                    }
                    platform::write_u16(count_slot, length);
                    platform::write_u8(fields + 0x1A, 4);
                } else {
                    platform::write_u8(fields + 0x17, *byte);
                }
            } else if state == 3 {
                let buffer = platform::read_u32(buffer_slot) as usize;
                let offset = platform::read_u16(buffer + 2) as usize;
                platform::write_u8(buffer + offset + 8, *byte);
                platform::write_u16(buffer + 2, (offset + 1) as u16);

                let remaining = platform::read_u16(count_slot).wrapping_sub(1);
                platform::write_u16(count_slot, remaining);

                let received = platform::call3(
                    HID_BYTE_READ,
                    index.wrapping_add(1) & 0xFF,
                    (buffer + platform::read_u16(buffer + 2) as usize + 8) as u32,
                    remaining as u32,
                ) as i16;
                processed = processed.wrapping_add(received as i32 as u32);
                platform::write_u16(
                    buffer + 2,
                    platform::read_u16(buffer + 2).wrapping_add(received as u16),
                );

                let left = platform::read_u16(count_slot).wrapping_sub(received as u16);
                platform::write_u16(count_slot, left);
                if left == 0 {
                    platform::write_u8(fields + 0x1A, 0);
                    // observed: a type-2 packet whose parser is not ready yet is
                    // not delivered; every other finished packet is.
                    if platform::read_u8(fields + 0x14) != 2
                        || call0_ret(HID_PARSER_READY) as u8 != 0
                    {
                        deliver = true;
                    }
                }
            } else if state == 4 {
                let remaining = platform::read_u16(count_slot).wrapping_sub(1);
                platform::write_u16(count_slot, remaining);
                if remaining == 0 {
                    platform::write_u8(fields + 0x1A, 0);
                }
            }
        }

        if deliver {
            fn_801f7400(
                platform::read_u8(HID_REPORT_QUEUE_ID) as u32,
                0,
                platform::read_u32(buffer_slot) as usize,
            );
            platform::write_u32(buffer_slot, 0);
        }
    }

    // observed: the `0x802DCD8C` epilogue returns its argument in `r3`.
    processed
}

/// Formats one variadic trace line into the HID trace buffer, appends it and
/// flushes it.
///
/// The body is the CodeWarrior varargs frame itself: it saves `r3`..`r10` into
/// the frame's GPR area, saves `f1`..`f8` only when the `CR1` flag says a
/// floating-point argument was passed, builds the three-word `va_list`
/// `{ (GPR area) | 0x02000000, caller stack area, GPR area }`, formats the
/// caller's arguments with `0x802E1664`, appends the `"%s\n"` line at
/// `r13-0x5D78` with `0x802E17DC`, and flushes with `0x8015F730`. All three
/// calls use `0x803CFE40` as their buffer.
///
/// # Original
/// - Ghidra: `FUN_801f9c50` at `0x801F9C50` (180 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801f9c50_FUN_801f9c50.c`
///
/// # Arguments
/// * `gpr` - the eight integer argument registers in order `r3`..`r10`.
///   `gpr[1]` (`r4`) is the format string handed to `0x802E1664` and `gpr[0]`
///   (`r3`) the first variadic value.
/// * `fpr` - the eight floating-point argument registers `f1`..`f8`; they are
///   saved unconditionally (the `CR1` guard only skips a store that no format
///   in this path reads).
/// * `stack` - the caller's stack-argument words, which the `va_list`
///   overflow pointer addresses.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// Rewrites the trace buffer `0x803CFE40` and hands it to the formatter, the
/// append step and the flush.
///
/// # Safety
/// `gpr`, `fpr` and `stack` must carry the caller's argument words; the trace
/// buffer and the three callees must be live.
///
/// # Confidence
/// high - the save offsets (`r1+8..+0x24` GPR, `+0x28..+0x60` FPR), the
/// `0x02000000` tag, the overflow pointer `r1+136`, `"%s\n"` and all three
/// call targets are literal. The `CR1` guard only skips the FPR save when no
/// float argument was passed, and always storing the eight doubles cannot
/// change a format that never reads them (same argument as
/// [`fn_801ee9a0`]).
pub unsafe fn fn_801f9c50(gpr: [u32; 8], fpr: [f64; 8], stack: [u32; 8]) {
    // The save area is `r3..r10` followed after 0x20 bytes by `f1..f8`; the
    // descriptor's register word points at the GPR half.
    let mut save_area = crate::platform::GuestLocal::new( [0u8; 0x60]);
    let save = save_area.as_mut_ptr() as usize;
    for (i, word) in gpr.iter().enumerate() {
        platform::write_u32(save + i * 4, *word);
    }
    for (i, value) in fpr.iter().enumerate() {
        kpad_write_f64(save + 0x20 + i * 8, *value);
    }

    let mut overflow = crate::platform::GuestLocal::new( stack);
    let mut va_list = crate::platform::GuestLocal::new( [
        (save as u32) | 0x0200_0000,
        overflow.as_mut_ptr() as u32,
        save as u32,
    ]);

    platform::call3(
        HID_TRACE_FORMAT,
        HID_TRACE_BUFFER as u32,
        gpr[1],
        va_list.as_mut_ptr() as u32,
    );
    platform::call3(
        HID_TRACE_APPEND,
        HID_TRACE_BUFFER as u32,
        SDA_HID_TRACE_LINE_5D78 as u32,
        HID_TRACE_BUFFER as u32,
    );
    platform::call1(HID_TRACE_FLUSH, HID_TRACE_BUFFER as u32);
}

// ---------------------------------------------------------------------------
// Wave 228 - lane A. The untabled slots of the HID-host method table
// `0x802F6D30` (the wave-61 plumbing, receive path from wave 102).
// ---------------------------------------------------------------------------
//
// `0x802F6D30` is a 5-word run (20 B, `0x802F6D30..0x802F6D44`, then one zero
// word) that [`fn_801f9e10`] installs into the SDA word [`SDA_HID_METHOD_TABLE`]
// (`r13 - 0x4B00`). The image shows which slot is which:
//
// | slot | word | body | role |
// |---:|---|---|---|
// | `0` | `0x802F6D30` | `0x801F8D70` | untabled 44 B, [`fn_801f8d70`]: reset the RX block, latch queue id / bias |
// | `1` | `0x802F6D34` | `0x801F8DA0` | untabled 104 B, [`fn_801f8da0`]: open the transport and register the receive callback |
// | `2` | `0x802F6D38` | `0x801F8E10` | untabled 52 B, [`fn_801f8e10`]: stop, drain both queues, return to idle |
// | `3` | `0x802F6D3C` | `0x801F8E50` | untabled 48 B, [`fn_801f8e50`]: feed one ACL event into the reassembler |
// | `4` | `0x802F6D40` | `0x801F8E80` | tabled 60 B, [`fn_801f8e80`]: report-length trampoline |
//
// The three callers are the wrappers `0x801F9B50`..`0x801F9BE0`, all already
// translated: [`fn_801f9b50`] calls slot `+0xC` as `(event, value)`,
// [`fn_801f9b70`] calls slot `+0` as `(2, 1, 0x800)` and slot `+4` as
// `(context)`, and [`fn_801f9be0`] calls slot `+8` with no arguments. No direct
// branch to any of the four bodies exists in the image (`laneA_refs.mjs`).
//
// Measured from `work/dol/main.elf`: the three slots of this lane are 104 B
// (`0x801F8DA0`, `blr` at `0x801F8E04`), 52 B (`0x801F8E10`, `blr` at
// `0x801F8E40`) and 48 B (`0x801F8E50`, `blr` at `0x801F8E7C`) - 204 B, as the
// table doc predicted - plus the 44 B slot-0 leaf `0x801F8D70` (`blr` at
// `0x801F8D98`) that the prologue scan missed because it opens with `lis` and
// has no frame. None of the four is a `functions.tsv` row.
//
// The block they all use is [`HID_RX_BLOCK`] (`0x803CDDA8`): byte `+0x1E` gates
// the reassembler (it only runs while the byte is `2`), byte `+0x1F` is the
// report queue id, halfword `+0x12` is the length bias that [`fn_801f8e80`]
// subtracts, and `+0x1A..+0x1C` are the three slots' receive states.

// ---------------------------------------------------------------------------
// Wave-228 lane-A RX-block fields and the one callback constant.
// ---------------------------------------------------------------------------

/// `0x803CDDC6` (`0x803CDDA8 + 0x1E`): the reassembler gate byte.
const HID_RX_GATE_A228: usize = HID_RX_BLOCK + 0x1E;
/// `0x803CDDC7` (`+0x1F`): the report queue id; the same address the wave-61
/// pass names [`HID_REPORT_QUEUE_ID`].
const HID_RX_QUEUE_ID_A228: usize = HID_RX_BLOCK + 0x1F;
/// `0x803CDDC8` (`+0x20`): byte stored from slot `+0`'s second argument.
/// `// unknown:` no reader of this byte has been found in the image.
const HID_RX_BYTE_20_A228: usize = HID_RX_BLOCK + 0x20;
/// `0x803CDDC2` (`+0x1A`): first of the three per-slot receive states.
const HID_RX_STATE_BASE_A228: usize = HID_RX_BLOCK + 0x1A;

/// `0x801F8800`: the 20-byte event thunk slot `+4` registers as the transport's
/// receive callback. It returns immediately for event `4` and otherwise
/// sign-extends `r3` and tail-branches to `0x801F9F30`; it is not in
/// `functions.tsv` and is outside this lane's body list.
const HID_RX_EVENT_THUNK_A228: usize = 0x801F_8800;

// ---------------------------------------------------------------------------
// 0x801F8D70 - method-table slot +0: reset the RX block and latch its fields
// ---------------------------------------------------------------------------

/// Resets the receive block and latches the three configuration values.
///
/// Writes `0` to the gate byte and to the three per-slot states, then stores the
/// first argument in the queue-id byte, the second in `+0x20` and the third
/// (16-bit) as the length bias at `+0x12`. Called by [`fn_801f9b70`] as
/// `(2, 1, 0x800)` before the transport is opened, so the shipped configuration
/// is "queue id 2, byte `+0x20` = 1, bias `0x800`".
///
/// # Original (untabled)
/// - Address: `0x801F8D70`, 44 B (11 instructions, `blr` at `0x801F8D98`; the
///   next entry `0x801F8DA0` is [`fn_801f8da0`])
/// - Table: slot 0 of `0x802F6D30` (`0x802F6D30`)
/// - Reach: installed into [`SDA_HID_METHOD_TABLE`] by [`fn_801f9e10`] and
///   called from [`fn_801f9b70`]
/// - Not in `functions.tsv`: it has no stack frame, so the prologue scan in
///   `docs/UNTABLED_POINTER_TABLES.md` did not see it
///
/// # Arguments
/// - `queue_id`: stored at the queue-id byte (`r3 & 0xFF`).
/// - `extra`: stored at `+0x20` (`r4 & 0xFF`); meaning unknown.
/// - `bias`: stored as the `+0x12` halfword (`r5 & 0xFFFF`), the value
///   [`fn_801f8e80`] later subtracts from every report length.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Seven stores into [`HID_RX_BLOCK`].
///
/// # Safety
/// The block is BSS and always writable.
///
/// # Confidence
/// high - every offset and store is literal; only `+0x20`'s role is unknown.
pub unsafe fn fn_801f8d70(queue_id: u8, extra: u8, bias: u16) {
    platform::write_u8(HID_RX_GATE_A228, 0);
    platform::write_u8(HID_RX_STATE_BASE_A228, 0);
    platform::write_u8(HID_RX_STATE_BASE_A228 + 1, 0);
    platform::write_u8(HID_RX_STATE_BASE_A228 + 2, 0);
    platform::write_u8(HID_RX_QUEUE_ID_A228, queue_id);
    platform::write_u8(HID_RX_BYTE_20_A228, extra);
    platform::write_u16(HID_LENGTH_BIAS, bias);
}

// ---------------------------------------------------------------------------
// 0x801F8DA0 - method-table slot +4: open the transport and register the
// receive callback
// ---------------------------------------------------------------------------

/// Opens the HID-host transport and arms the receive gate.
///
/// Builds a 12-byte descriptor on the stack from the context object's first two
/// halfwords plus the queue-id byte, sets the gate byte to `2` (the value the
/// reassembler needs), then calls `0x801F9490` with the descriptor - which is
/// what stores the pointer at the state block's `+0x24` - and `0x801F96A0` with
/// the same descriptor and the [`HID_RX_EVENT_THUNK_A228`] callback, which
/// stores the callback at the state block's `+0x20` and moves the host to its
/// state `2`.
///
/// `// observed:` the descriptor's `+0..+4` and `+0xA` bytes are never written;
/// only `+4` (context halfword 0), `+6` (context halfword 1) and `+8` (the queue
/// id) carry values, and `+0xB` is the explicit zero (`stb r0,0x13(r1)`). The
/// untouched bytes are uninitialised stack in the original and are modelled as
/// zero here.
///
/// # Original (untabled)
/// - Address: `0x801F8DA0`, 104 B (26 instructions, `blr` at `0x801F8E04`; the
///   next entry `0x801F8E10` is [`fn_801f8e10`])
/// - Table: slot 1 of `0x802F6D30` (`0x802F6D34`)
/// - Reach: installed into [`SDA_HID_METHOD_TABLE`] by [`fn_801f9e10`] and
///   called from [`fn_801f9b70`] with the context object at `r13 - 0x4AFC`
/// - Not in `functions.tsv`; no Ghidra export
///
/// # Arguments
/// - `context`: the transport context object; its `+0`/`+2` halfwords become
///   descriptor fields `+4`/`+6`.
///
/// # Returns
/// The literal `1` - the "opened" answer [`fn_801f9b70`] ignores.
///
/// # Side effects
/// One 12-byte stack descriptor, the gate store, and the two transport calls
/// with their state-block writes.
///
/// # Safety
/// `context` must be readable at `+0..+4`; the state block must be initialised
/// and the transport callees must accept the descriptor.
///
/// # Confidence
/// medium - the descriptor fields, the gate value and both calls are literal;
/// that the descriptor is a transport configuration and the callback is the
/// receive-entry thunk is inferred from the callee stores.
pub unsafe fn fn_801f8da0(context: usize) -> u32 {
    let mut descriptor = crate::platform::GuestLocal::new( [0u8; 12]);
    let base = descriptor.as_mut_ptr() as usize;
    platform::write_u16(base + 4, platform::read_u16(context));
    platform::write_u16(base + 6, platform::read_u16(context + 2));
    platform::write_u16(
        base + 8,
        u16::from(platform::read_u8(HID_RX_QUEUE_ID_A228)),
    );
    platform::write_u8(HID_RX_GATE_A228, 2);
    fn_801f9490(base as u32);
    fn_801f96a0(base as u32, HID_RX_EVENT_THUNK_A228 as u32);
    1
}

// ---------------------------------------------------------------------------
// 0x801F8E10 - method-table slot +8: stop the transport
// ---------------------------------------------------------------------------

/// Stops the HID-host receive path.
///
/// Clears the gate byte so the reassembler stops taking packets, then runs the
/// two shutdown steps: [`fn_801f9a50`] (drain both GKI queues and unregister the
/// reset callback) and [`fn_801f9b00`] (restart the transport and put the state
/// block back to idle `5`).
///
/// # Original (untabled)
/// - Address: `0x801F8E10`, 52 B (13 instructions, `blr` at `0x801F8E40`; the
///   next entry `0x801F8E50` is [`fn_801f8e50`])
/// - Table: slot 2 of `0x802F6D30` (`0x802F6D38`)
/// - Reach: installed into [`SDA_HID_METHOD_TABLE`] by [`fn_801f9e10`] and
///   called from [`fn_801f9be0`]
/// - Not in `functions.tsv`; no Ghidra export
///
/// # Arguments
/// None.
///
/// # Returns
/// `0`. `// observed:` the body never loads `r3`, so the exported function would
/// hand back whatever [`fn_801f9b00`] left there; the sole caller
/// ([`fn_801f9be0`]) ignores the value, and `0` is the trampoline convention the
/// neighbouring slots use.
///
/// # Side effects
/// One store plus the full queue drain and idle reset of the two callees.
///
/// # Safety
/// Queued buffers must be live GKI payloads and the state block initialised.
///
/// # Confidence
/// high - the gate store and both calls are literal.
pub unsafe fn fn_801f8e10() -> u32 {
    platform::write_u8(HID_RX_GATE_A228, 0);
    fn_801f9a50();
    fn_801f9b00();
    0
}

// ---------------------------------------------------------------------------
// 0x801F8E50 - method-table slot +0xC: feed one ACL event to the reassembler
// ---------------------------------------------------------------------------

/// Hands one received event object to the ACL reassembler and reports success.
///
/// [`fn_801f9b50`] stores the 16-bit HCI opcode at `event + 0` and then calls
/// this slot with `(event, value)`. The body drops `r4` (the value is already in
/// the object) and calls `0x801F8BC0` with the receive block in `r3` and the
/// event in `r4`, which is exactly the `(_arg0, packet)` shape of
/// [`fn_801f8bc0`].
///
/// # Original (untabled)
/// - Address: `0x801F8E50`, 48 B (12 instructions, `blr` at `0x801F8E7C`; the
///   next entry `0x801F8E80` is the tabled [`fn_801f8e80`])
/// - Table: slot 3 of `0x802F6D30` (`0x802F6D3C`)
/// - Reach: installed into [`SDA_HID_METHOD_TABLE`] by [`fn_801f9e10`] and
///   called from [`fn_801f9b50`] as `(event, value)`
/// - Not in `functions.tsv`; no Ghidra export
///
/// # Arguments
/// - `event`: the queued message object read by [`fn_801f8bc0`] (`u16` opcode at
///   `+0`, `u16` remaining length at `+2`, `u16` payload cursor at `+4`); it is
///   forwarded as the callee's `packet`.
///
/// # Returns
/// The literal `1`.
///
/// # Side effects
/// Whatever the reassembler does: it may consume the event, re-post it to the
/// report queue or free it.
///
/// # Safety
/// `event` must be a live GKI payload laid out for [`fn_801f8bc0`].
///
/// # Confidence
/// high - the register shuffle and the constant return are literal, and the
/// callee's translated signature fixes the argument order.
pub unsafe fn fn_801f8e50(event: usize) -> u32 {
    fn_801f8bc0(HID_RX_BLOCK as u32, event);
    1
}

// ===========================================================================
// WPAD/KPAD extension-callback table, `0x80343E90` (wave 228, lane E)
// ===========================================================================
//
// `0x80343E90` is a 32-word table of report decoders indexed by the low byte of
// a Bluetooth input report id: `0x80343E90 + (id - 0x20) * 4` for ids
// `0x20..=0x3F`. It is installed nowhere - it is a static `const` array - and
// reached only through [`fn_801e6be0`], which validates the id and calls
// `entry(channel, report, out)` with the decoded 0x60-byte report block.
//
// | slot | id | target | role |
// |---:|---|---|---|
// | 0 | `0x20` | `0x801E6D10` | status/extension handshake report (this pass) |
// | 1 | `0x21` | `0x801E7050` | extension-register reply ([`fn_801e7050`]) |
// | 2 | `0x22` | `0x801E7380` | ack report (this pass) |
// | 3..15 | `0x23`..`0x2F` | `0x801E9720` | no-op ([`fn_801e9720`]) |
// | 16 | `0x30` | `0x801E8270` | buttons + stale marker only (this pass) |
// | 17 | `0x31` | `0x801E82D0` | 6-byte accelerometer report (this pass) |
// | 18 | `0x32` | `0x801E83E0` | 8-byte core/extension report (this pass) |
// | 19 | `0x33` | `0x801E8700` | accelerometer + load-cell report (this pass) |
// | 20 | `0x34` | `0x801E8850` | 19-byte classic-controller report (this pass) |
// | 21 | `0x35` | `0x801E8A30` | core report ([`fn_801e8a30`]) |
// | 22 | `0x36` | `0x801E8DD0` | balance-board report ([`fn_801e8dd0`]) |
// | 23 | `0x37` | `0x801E8EE0` | 10-byte balance-board + accel report (this pass) |
// | 24..28 | `0x38`..`0x3C` | `0x801E9720` | no-op ([`fn_801e9720`]) |
// | 29 | `0x3D` | `0x801E9290` | 21-byte classic/Nunchuk report (this pass) |
// | 30 | `0x3E` | `0x801E93B0` | load-cell half (updates in place) (this pass) |
// | 31 | `0x3F` | `0x801E9570` | load-cell half (updates in place) (this pass) |
//
// The nine prologue-bearing slots plus the three leaf/no-op targets that the
// prologue scan in `docs/UNTABLED_POINTER_TABLES.md` could not see (`0x801E8270`,
// `0x801E82D0` and the 16-times repeated `0x801E9720`) are translated below; the
// three tabled slots 1, 21 and 22 were already translated in wave 5.
//
// **Shared report-block layout** (the `out` argument, 0x60 bytes): `+0` button
// word (only the `0x9F1F` bits are decoded; bits `0x6000` are preserved from the
// previous sample), `+2`/`+4`/`+6` accelerometer deltas, `+0x28` extension kind,
// `+0x29` stale marker (`0` valid, `0xFC` no data, `0xF9` untouched), `+0x2A`..
// `+0x35` extension payload, `+8..+0x28` the four balance-board samples.

/// `r13-0x4BB4`: per-channel handshake flag of the `0x3E`/`0x3F` load-cell pair.
/// The `0x3F` decoder raises it and the `0x3E` decoder consumes it; both clear
/// both flags when the pair completes.
const SDA_WPAD_4BB4_E228: usize = SDA_BASE - 0x4BB4;
/// `r13-0x4BB8`: the other half of the [`SDA_WPAD_4BB4_E228`] pair.
const SDA_WPAD_4BB8_E228: usize = SDA_BASE - 0x4BB8;

/// `"Received report 20\n"` at `0x803442C8` (`r31 + 0x438` in the original).
const MSG_REPORT_20_E228: u32 = 0x8034_42C8;
/// `"initialize attachment\n"` at `0x803442DC`.
const MSG_INIT_ATTACHMENT_E228: u32 = 0x8034_42DC;
/// `"Received ack!\n"` at `0x803443B0`.
const MSG_RECEIVED_ACK_E228: u32 = 0x8034_43B0;
/// `"ack --> report ID = %02x, error code = %d\n"` at `0x803443C0`.
const MSG_ACK_REPORT_ID_E228: u32 = 0x8034_43C0;
/// `"invalid ack!\n"` at `0x803443EC`.
const MSG_INVALID_ACK_E228: u32 = 0x8034_43EC;

// ---------------------------------------------------------------------------
// 0x801E6D10 - table slot 0 (report id 0x20): status / attachment handshake
// ---------------------------------------------------------------------------

/// Decodes the report-`0x20` status word and drives the extension handshake.
///
/// The report carries the controller status in `+3`, an extension code in `+6`
/// and the two extension registers in `+5`. The decoder latches the status bits
/// into `control + 0x838`..`+0x84F`, derives the extension kind (`0` core, `1`
/// nunchuk, `2` classic, `3` balance board, `4` other) and then, when the
/// attachment bit (`control + 0x840`) is set, either queues the whole extension
/// bring-up sequence (read `0x4A400FA`, write `0x4A400F0`, write `0x4A400FB`)
/// on a fresh ring - the "initialize attachment" path, taken only on the rising
/// edge of `+0x840` - or, when it is clear, tears the ring down and arms the
/// 300-tick retry. The tail copies the previously selected report block into
/// `out`, refreshes the button word and runs the two "report changed" hooks.
///
/// # Original (untabled)
/// - Address: `0x801E6D10`, 832 B (`blr` at `0x801E704C`; the previous entry
///   `0x801E6BE0` is the tabled [`fn_801e6be0`])
/// - Table: slot 0 of `0x80343E90` (`0x80343E90`), selected by report id `0x20`
/// - Reach: [`fn_801e6be0`] indexes the table with `id - 0x20` and calls
///   `(channel, report, out)`
/// - Not in `functions.tsv`; no Ghidra export
///
/// # Arguments
/// - `channel`: controller index, used for the control block and the ring.
/// - `report`: raw report; `+1` carries the extension/status bit `6`, `+2` the
///   button low byte, `+3` the status byte, `+5` the extension register and `+6`
///   the extension code.
/// - `out`: the 0x60-byte KPAD report block.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes the status block `control + 0x838`..`+0x850`, the extension kind at
/// `+0x84C`, the extension byte `+0x8C1`/`+0x8C2`, and queues up to three
/// extension commands. Copies the selected report block into `out` and may call
/// the `+0x89C` and `+0x8A0` callbacks with `(channel, 0)` / `(channel, 0xFF)`.
///
/// # Safety
/// WPAD/KPAD must be initialised, `channel` in `0..=3`, and `report` readable
/// for seven bytes; the control block's ring must be live.
///
/// # Confidence
/// high - every field, queue command and callback site is a literal
/// transcription of the 208-instruction body.
pub unsafe fn fn_801e6d10(channel: u32, report: usize, out: usize) {
    let control = kpad_control(channel);
    let previous = platform::read_u32(control + 0x840);
    platform::call1(OS_REPORT, MSG_REPORT_20_E228);

    let token = disable_interrupts();
    if platform::read_u32(control + 0x8DC) == 0 {
        restore_interrupts(token);
        return;
    }

    let status = platform::read_u8(report + 3);
    platform::write_u32(control + 0x840, ((status >> 1) & 1) as u32);
    platform::write_u32(control + 0x844, (status & 1) as u32);
    platform::write_u8(control + 0x84D, status >> 4);
    platform::write_u8(control + 0x84E, 0);
    platform::write_u8(
        control + 0x84F,
        (platform::read_u8(report + 5) >> 4) & 0x0F,
    );
    platform::write_u32(
        control + 0x848,
        ((platform::read_u8(report + 1) >> 6) & 1) as u32,
    );
    platform::write_u32(control + 0x838, ((status >> 2) & 1) as u32);
    platform::write_u32(control + 0x83C, ((status >> 1) & 1) as u32);

    // observed: with extension kind `3` already latched the code byte is
    // ignored and the previously classified kind is copied through.
    let extension_kind = if platform::read_u8(control + 0x8C1) == 3 {
        platform::read_u8(control + 0x98F)
    } else {
        let code = platform::read_u8(report + 6);
        if code >= 0x55 {
            4
        } else if code >= 0x44 {
            3
        } else if code >= 0x33 {
            2
        } else if code >= 0x03 {
            1
        } else {
            0
        }
    };
    platform::write_u8(control + 0x84C, extension_kind);

    let ring = control + 0x5EC;
    if platform::read_u32(control + 0x840) != 0 {
        if previous == 0 {
            platform::call1(OS_REPORT, MSG_INIT_ATTACHMENT_E228);
            platform::write_u8(SDA_WPAD_4BB0 + channel as usize, 0);
            let callback = platform::read_u32(control + 0x8A0);
            fn_801e53f0(ring);
            fn_801e4c50(
                ring,
                platform::read_u32(control + 0x8B8),
                platform::read_u8(control + 0x98E) as u32,
                FN_801E5460,
            );
            platform::write_u8(control + 0x98D, 1);
            // observed: `lis r27,0x4A4` + `addi`, i.e. the extension register
            // addresses below `0x4A40000`.
            fn_801e4ec0(ring, 0x55, 0x4A40_00F0, FN_801E5460);
            fn_801e4ec0(ring, 0x00, 0x4A40_00FB, FN_801E5460);
            fn_801e5240(ring, (control + 0x934) as u32, 6, 0x4A40_00FA, FN_801E5460);
            platform::write_u8(control + 0x8C1, 0xFF);
            platform::write_u8(control + 0x8C2, 0);
            if callback != 0 {
                platform::call2(callback as usize, channel, 0xFF);
            }
        }
    } else {
        platform::write_u8(control + 0x8C1, 0);
        platform::write_u8(control + 0x8C2, 0);
        fn_801e53f0(ring);
        fn_801e4c50(
            ring,
            platform::read_u32(control + 0x8B8),
            platform::read_u8(control + 0x98E) as u32,
            0,
        );
        if previous != 0 {
            platform::write_u8(control + 0x991, 1);
            platform::write_u16(control + 0x992, 300);
            let callback = platform::read_u32(control + 0x8A0);
            if callback != 0 {
                platform::call2(callback as usize, channel, 0);
            }
        }
    }

    // observed: `+0x850` is a caller-supplied snapshot buffer that receives the
    // 24 status bytes just decoded, then the pointer is released.
    let snapshot = platform::read_u32(control + 0x850) as usize;
    if snapshot != 0 {
        platform::call3(MEMCPY, snapshot as u32, (control + 0x838) as u32, 24);
        platform::write_u32(control + 0x850, 0);
    }

    let selector = platform::read_u8(control + 0x8C8) as usize;
    platform::call3(
        MEMCPY,
        out as u32,
        (control + selector * 0x60 + 0xA0) as u32,
        0x60,
    );

    let buttons = ((platform::read_u8(report + 2) as u16) << 8)
        | platform::read_u8(report + 1) as u16;
    platform::write_u16(out, (buttons & 0x9F1F) | (platform::read_u16(out) & 0x6000));

    if platform::read_u8(out + 0x28) != platform::read_u8(control + 0x8C1) {
        platform::write_u8(out + 0x28, platform::read_u8(control + 0x8C1));
        platform::write_u8(out + 0x29, 0xFC);
    }

    let changed = platform::read_u32(control + 0x89C) as usize;
    if changed != 0 && platform::read_u8(control + 0x8C0) != 0 {
        platform::call2(changed, channel, 0);
        platform::write_u32(control + 0x89C, 0);
    }
    platform::write_u8(control + 0x8C0, 0);

    restore_interrupts(token);
}

// ---------------------------------------------------------------------------
// 0x801E7380 - table slot 2 (report id 0x22): extension ack
// ---------------------------------------------------------------------------

/// Decodes the extension acknowledgement report.
///
/// The decoder republishes the previously selected report block, refreshes the
/// button word and the extension kind, prints the ack (`report[3]` is the acked
/// report id, `report[4]` the error code) and then answers the ack: when
/// `control + 0x987` still equals the acked id the `+0x89C` completion is called
/// and cleared together with `+0x8BC`; otherwise the "invalid ack" diagnostic is
/// printed and the pending state is left untouched.
///
/// # Original (untabled)
/// - Address: `0x801E7380`, 320 B (`blr` at `0x801E74BC`; the next entry
///   `0x801E74C0` is the tabled [`fn_801e74c0`])
/// - Table: slot 2 of `0x80343E90` (`0x80343E98`), selected by report id `0x22`
/// - Reach: [`fn_801e6be0`] as `(channel, report, out)`
/// - Not in `functions.tsv`; the `0x801E7390` operand load is the only
///   untabled-code reference to the table base
///
/// # Arguments
/// - `channel`: controller index.
/// - `report`: raw report; `+3` acked report id, `+4` error code.
/// - `out`: the 0x60-byte KPAD report block.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Copies 0x60 bytes into `out`, updates `out + 0`/`+0x28`/`+0x29`, prints two
/// diagnostics and may call `control + 0x89C`.
///
/// # Safety
/// WPAD/KPAD must be initialised and `out` writable for 0x60 bytes.
///
/// # Confidence
/// high - the block copy, the ack compare and both diagnostics are literal.
/// medium for the second callback argument: the original passes the control
/// table base `0x8039E330` in `r4`, which is transcribed as observed.
pub unsafe fn fn_801e7380(channel: u32, report: usize, out: usize) {
    let control = kpad_control(channel);
    let token = disable_interrupts();
    platform::call1(OS_REPORT, MSG_RECEIVED_ACK_E228);

    let selector = platform::read_u8(control + 0x8C8) as usize;
    platform::call3(
        MEMCPY,
        out as u32,
        (control + selector * 0x60 + 0xA0) as u32,
        0x60,
    );

    let buttons = ((platform::read_u8(report + 2) as u16) << 8)
        | platform::read_u8(report + 1) as u16;
    platform::write_u16(out, (buttons & 0x9F1F) | (platform::read_u16(out) & 0x6000));

    if platform::read_u8(out + 0x28) != platform::read_u8(control + 0x8C1) {
        platform::write_u8(out + 0x28, platform::read_u8(control + 0x8C1));
        platform::write_u8(out + 0x29, 0xFC);
    }

    let report_id = platform::read_u8(report + 3);
    platform::call3(
        OS_REPORT,
        MSG_ACK_REPORT_ID_E228,
        report_id as u32,
        platform::read_u8(report + 4) as u32,
    );

    if platform::read_u8(control + 0x987) == report_id {
        let completion = platform::read_u32(control + 0x89C) as usize;
        if completion != 0 {
            // observed: `mr r4,r25` where `r25` still holds `0x8039E330`.
            platform::call2(completion, channel, KPAD_CONTROL_TABLE as u32);
            platform::write_u32(control + 0x89C, 0);
        }
        platform::write_u32(control + 0x8BC, 0);
    } else {
        platform::call1(OS_REPORT, MSG_INVALID_ACK_E228);
    }

    restore_interrupts(token);
}

// ---------------------------------------------------------------------------
// 0x801E9720 - table slots 3..15 and 24..28 (report ids 0x23..0x2F, 0x38..0x3C)
// ---------------------------------------------------------------------------

/// The shared no-op decoder.
///
/// Sixteen ids (`0x23`..`0x2F` and `0x38`..`0x3C`) have no payload the pad layer
/// models; they all point at a bare `bclr 20,0`. The report block is therefore
/// left exactly as [`fn_801e6be0`] handed it over (cleared, for these ids).
///
/// # Original (untabled)
/// - Address: `0x801E9720`, 4 B - the single instruction `blr` at `0x801E9720`
