// ---------------------------------------------------------------------------
// 0x801E8270 - table slot 16 (report id 0x30): buttons + stale marker
// ---------------------------------------------------------------------------

/// Publishes only the button word and the stale marker.
///
/// Unlike the other core decoders this one replaces the button word outright -
/// it does not preserve the `0x6000` bits - and treats `control + 0x8B8 == 0` as
/// "no data". It has no stack frame and no calls.
///
/// # Original (untabled)
/// - Address: `0x801E8270`, 92 B (`blr` at `0x801E82C8`)
/// - Table: slot 16 of `0x80343E90` (`0x80343ED0`), report id `0x30`
/// - Reach: [`fn_801e6be0`]
/// - Not in `functions.tsv`: no stack frame
///
/// # Arguments
/// - `channel`: controller index.
/// - `report`: raw report; `+1`/`+2` button bytes.
/// - `out`: the 0x60-byte KPAD report block.
///
/// # Side effects
/// Writes `out + 0`, `out + 0x28`, `out + 0x29` and `control + 0x848`.
///
/// # Safety
/// WPAD/KPAD must be initialised.
///
/// # Confidence
/// high - seven stores and one compare.
pub unsafe fn fn_801e8270(channel: u32, report: usize, out: usize) {
    let control = kpad_control(channel);
    let buttons = ((platform::read_u8(report + 2) as u16) << 8)
        | platform::read_u8(report + 1) as u16;
    platform::write_u16(out, buttons & 0x9F1F);
    platform::write_u8(out + 0x28, platform::read_u8(control + 0x8C1));
    platform::write_u8(
        out + 0x29,
        if platform::read_u32(control + 0x8B8) == 0 {
            0
        } else {
            0xFC
        },
    );
    platform::write_u32(
        control + 0x848,
        ((platform::read_u8(report + 1) >> 6) & 1) as u32,
    );
}

// ---------------------------------------------------------------------------
// 0x801E82D0 - table slot 17 (report id 0x31): six-byte accelerometer report
// ---------------------------------------------------------------------------

/// Decodes the short accelerometer report.
///
/// The three axes are rebuilt from `report[3..6]` plus the spare low bits in
/// `report[1]`/`report[2]` and each is biased by the per-channel centre stored
/// at `control + 0x874`/`+0x876`/`+0x878`. The stale marker is `0` only while
/// `control + 0x8B8` is zero.
///
/// # Original (untabled)
/// - Address: `0x801E82D0`, 260 B (`blr` at `0x801E83D0`; the next entry
///   `0x801E83E0` is [`fn_801e83e0`])
/// - Table: slot 17 of `0x80343E90` (`0x80343ED4`), report id `0x31`
/// - Reach: [`fn_801e6be0`]
/// - Not in `functions.tsv`: no stack frame
///
/// # Arguments
/// - `channel`: controller index.
/// - `report`: raw report; `+2` spare low bits, `+3`/`+4`/`+5` the axis bytes.
/// - `out`: the 0x60-byte KPAD report block.
///
/// # Side effects
/// Writes `out + 0`, `+2`, `+4`, `+6`, `+0x28`, `+0x29` and `control + 0x848`.
///
/// # Safety
/// WPAD/KPAD must be initialised.
///
/// # Confidence
/// high - the packing shifts and the `extsh` truncation were reduced to exact
/// 16-bit arithmetic.
pub unsafe fn fn_801e82d0(channel: u32, report: usize, out: usize) {
    let control = kpad_control(channel);
    let b1 = platform::read_u8(report + 1);
    let b2 = platform::read_u8(report + 2);

    let buttons = ((platform::read_u8(report + 2) as u16) << 8) | b1 as u16;
    platform::write_u16(out, buttons & 0x9F1F);
    platform::write_u8(out + 0x28, platform::read_u8(control + 0x8C1));
    platform::write_u8(
        out + 0x29,
        if platform::read_u32(control + 0x8B8) < 1 {
            0
        } else {
            0xFC
        },
    );
    platform::write_u32(control + 0x848, ((b1 >> 6) & 1) as u32);

    let axis = |high: u8, low: u16, centre: usize| -> u16 {
        ((((high as u16) << 2) | low) as i16)
            .wrapping_sub(platform::read_u16(control + centre) as i16) as u16
    };

    platform::write_u16(
        out + 2,
        axis(platform::read_u8(report + 3), ((b1 >> 5) & 3) as u16, 0x874),
    );
    platform::write_u16(
        out + 4,
        axis(
            platform::read_u8(report + 4),
            (((b2 >> 4) & 1) as u16) << 1,
            0x876,
        ),
    );
    platform::write_u16(
        out + 6,
        axis(
            platform::read_u8(report + 5),
            (((b2 >> 5) & 1) as u16) << 1,
            0x878,
        ),
    );
}

// ---------------------------------------------------------------------------
// 0x801E83E0 - table slot 18 (report id 0x32): eight-byte core/extension report
// ---------------------------------------------------------------------------

/// Decodes the eight-byte report that carries the accelerometer and one
/// extension block.
///
/// The core part is the button word, the stale marker and the three axes built
/// from `report[3..6]`; the eight extension bytes at `control + 3` are copied to
/// `0x803A1AB0` and XOR-decoded. The extension is then dispatched on
/// `control + 0x8C1`: kind `1` is unpacked inline (two signed bytes plus the
/// three 10-bit axes at `out + 0x2A`..`+0x2E`, biased by `+0x88E`/`+0x890`/
/// `+0x892`), kind `2` is delegated to [`fn_801e7be0`] with the sub-mode from
/// `+0x8C2`, and kind `0x10` copies the two trigger bytes and the inverted
/// 16-bit checksum. A final compare with the extension identity upgrades a clean
/// marker to `0xF9`.
///
/// `// observed:` the marker table is `{0, 3, 6, 0xA}`, narrower than the core
/// decoder's `{0, 1, 3, 4, 6, 7, 0xD}`.
///
/// # Original (untabled)
/// - Address: `0x801E83E0`, 792 B (`blr` at `0x801E86F4`; the next entry
///   `0x801E8700` is [`fn_801e8700`])
/// - Table: slot 18 of `0x80343E90` (`0x80343ED8`), report id `0x32`
/// - Reach: [`fn_801e6be0`] as `(channel, report, out)`
/// - Not in `functions.tsv`; no Ghidra export
///
/// # Arguments
/// - `channel`: controller index.
/// - `report`: raw report; `+3..+0x0A` the extension bytes.
/// - `out`: the 0x60-byte KPAD report block.
///
/// # Side effects
/// Writes `out + 0`..`+0x35`, `control + 0x848`, `control + 0x882`/`+0x888`
/// (first sample) and the `0x803A1AB0` scratch block.
///
/// # Safety
/// `report` must be readable for at least 0x0B bytes and `out` writable for
/// 0x60 bytes.
///
/// # Confidence
/// high - all three extension arms, the clamp pair and the identity compare are
/// literal; medium only for the physical meaning of the two signed bytes at
/// `out + 0x30`/`+0x31`.
pub unsafe fn fn_801e83e0(channel: u32, report: usize, out: usize) {
    let control = kpad_control(channel);
    let b1 = platform::read_u8(report + 1);
    let b2 = platform::read_u8(report + 2);

    let buttons = ((b2 as u16) << 8) | b1 as u16;
    platform::write_u16(out, buttons & 0x9F1F);

    let state = platform::read_u32(control + 0x8B8);
    platform::write_u8(
        out + 0x29,
        if matches!(state, 0 | 3 | 6 | 0x0A) {
            0
        } else {
            0xFC
        },
    );
    platform::write_u8(out + 0x28, platform::read_u8(control + 0x8C1));
    platform::write_u32(control + 0x848, ((b1 >> 6) & 1) as u32);

    platform::call3(
        MEMCPY,
        KPAD_EXTENSION_SCRATCH as u32,
        (report + 3) as u32,
        8,
    );
    platform::call4(KPAD_XOR_DECODE, channel, (report + 3) as u32, 8, 0);

    if platform::read_u32(control + 0x840) != 0 {
        let extension = platform::read_u8(control + 0x8C1);
        if extension == 1 {
            platform::write_u8(out + 0x30, platform::read_u8(report + 3));
            platform::write_u8(out + 0x31, platform::read_u8(report + 4));

            let spare = platform::read_u8(report + 8);
            let axis = |high: u8, low: u16, centre: usize| -> u16 {
                ((((high as u16) << 2) | low) as i16)
                    .wrapping_sub(platform::read_u16(control + centre) as i16) as u16
            };
            platform::write_u16(
                out + 0x2A,
                axis(platform::read_u8(report + 5), ((spare >> 2) & 3) as u16, 0x88E),
            );
            platform::write_u16(
                out + 0x2C,
                axis(platform::read_u8(report + 6), ((spare >> 4) & 3) as u16, 0x890),
            );
            platform::write_u16(
                out + 0x2E,
                axis(platform::read_u8(report + 7), (spare >> 6) as u16, 0x892),
            );
            platform::write_u16(
                out,
                platform::read_u16(out) | (((spare ^ 0xFF) & 3) as u16) << 13,
            );

            if platform::read_u8(control + 0x911) == 0 {
                platform::write_u8(control + 0x911, 1);
                platform::write_u16(
                    control + 0x882,
                    platform::read_u8(out + 0x30) as i8 as i16 as u16,
                );
                platform::write_u16(
                    control + 0x888,
                    platform::read_u8(out + 0x31) as i8 as i16 as u16,
                );
            }

            let dx = platform::read_u8(out + 0x30) as i32
                - (platform::read_u16(control + 0x882) & 0xFF) as i32;
            platform::write_u8(out + 0x30, clamp_i32(dx, -0x80, 0x7F) as i8 as u8);

            let dy = platform::read_u8(out + 0x31) as i32
                - (platform::read_u16(control + 0x888) & 0xFF) as i32;
            platform::write_u8(out + 0x31, clamp_i32(dy, -0x80, 0x7F) as i8 as u8);
        } else if extension == 2 {
            fn_801e7be0(
                channel,
                out,
                platform::read_u8(control + 0x8C2) as u32,
                report + 3,
                8,
            );
        } else if extension == 0x10 {
            platform::write_u8(out + 0x2C, platform::read_u8(report + 5));
            platform::write_u8(out + 0x2D, platform::read_u8(report + 6));
            platform::write_u16(
                out + 0x2A,
                (((platform::read_u8(report + 9) as u16) << 8)
                    | platform::read_u8(report + 0x0A) as u16)
                    ^ 0xFFFF,
            );
        }

        let same = platform::call3(
            BT_NAME_MATCH,
            KPAD_EXTENSION_SCRATCH as u32,
            KPAD_EXTENSION_IDENTITY as u32,
            8,
        );
        if same == 0 && platform::read_u8(out + 0x29) == 0 {
            platform::write_u8(out + 0x29, 0xF9);
        }
    }
}

