// ---------------------------------------------------------------------------
// 0x801E8850 - table slot 20 (report id 0x34): 19-byte classic report
// ---------------------------------------------------------------------------

/// Decodes the nineteen-byte classic-controller report.
///
/// The four 16-bit axes at `report[3..0x0B]` are copied verbatim (they are
/// already packed), the two extra bytes land at `out + 0x32`/`+0x33`, and the
/// extension code byte `report[0x0D]` is classified into the pad-layer kind
/// (`>= 0x82` other, `0x7D`..`0x81` balance board, `0x78`..`0x79` classic,
/// `0x6A`..`0x77` nunchuk) stored at `control + 0x98F`. The whole block is
/// XOR-decoded in place and compared with the extension identity.
///
/// `// observed:` the thresholds are applied to `report[0x0D] << 1`, so the byte
/// values above are the shifted ones.
///
/// # Original (untabled)
/// - Address: `0x801E8850`, 480 B (`blr` at `0x801E8A2C`; the next entry
///   `0x801E8A30` is the tabled [`fn_801e8a30`])
/// - Table: slot 20 of `0x80343E90` (`0x80343EE0`), report id `0x34`
/// - Reach: [`fn_801e6be0`] as `(channel, report, out)`
/// - Not in `functions.tsv`; no Ghidra export
///
/// # Arguments
/// - `channel`: controller index.
/// - `report`: raw report; `+3`..`+0x0D` payload.
/// - `out`: the 0x60-byte KPAD report block.
///
/// # Side effects
/// Writes `out + 0`, `+0x28`, `+0x29`, `+0x2A`..`+0x33`, `control + 0x848`,
/// `+0x8C1`-kinded `+0x98F`, `+0x911` and the `0x803A1AB0` scratch block.
///
/// # Safety
/// `report` must be readable for 0x1C bytes.
///
/// # Confidence
/// high - the field copies and all four thresholds are literal.
pub unsafe fn fn_801e8850(channel: u32, report: usize, out: usize) {
    let control = kpad_control(channel);
    let b1 = platform::read_u8(report + 1);
    let b2 = platform::read_u8(report + 2);

    let buttons = ((b2 as u16) << 8) | b1 as u16;
    platform::write_u16(out, buttons & 0x9F1F);
    platform::write_u8(
        out + 0x29,
        if platform::read_u32(control + 0x8B8) == 0x0C {
            0
        } else {
            0xFC
        },
    );
    platform::write_u8(out + 0x28, platform::read_u8(control + 0x8C1));
    platform::write_u32(control + 0x848, ((b1 >> 6) & 1) as u32);

    platform::call3(
        MEMCPY,
        KPAD_EXTENSION_SCRATCH as u32,
        (report + 3) as u32,
        19,
    );
    platform::call4(KPAD_XOR_DECODE, channel, (report + 3) as u32, 19, 0);

    if platform::read_u32(control + 0x840) != 0 {
        if platform::read_u8(control + 0x8C1) == 3 {
            for index in 0..4usize {
                let high = platform::read_u8(report + 3 + index * 2) as u16;
                let low = platform::read_u8(report + 4 + index * 2) as u16;
                platform::write_u16(out + 0x2A + index * 2, (high << 8) | low);
            }
            platform::write_u8(out + 0x32, platform::read_u8(report + 0x0B));
            platform::write_u8(out + 0x33, platform::read_u8(report + 0x0D));

            let code = (platform::read_u8(report + 0x0D) as u32) << 1;
            let kind = if code >= 260 {
                4
            } else if code >= 250 {
                3
            } else if code >= 240 {
                2
            } else if code >= 212 {
                1
            } else {
                0
            };
            platform::write_u8(control + 0x98F, kind);

            if platform::read_u8(control + 0x911) == 0 {
                platform::write_u8(control + 0x911, 1);
            }
        }

        let same = platform::call3(
            BT_NAME_MATCH,
            KPAD_EXTENSION_SCRATCH as u32,
            KPAD_EXTENSION_IDENTITY as u32,
            19,
        );
        if same == 0 && platform::read_u8(out + 0x29) == 0 {
            platform::write_u8(out + 0x29, 0xF9);
        }
    }
}

